QCU_T("es", "procedimiento1", {
  "0": ["¿Qué elemento constituye un indicador de alarma (bandera roja) en la exploración subjetiva?",["Un dolor nocturno intenso que no se modifica con los medicamentos ni con la postura","Un dolor mecánico que empeora con el movimiento y mejora con el reposo","Un dolor intermitente de intensidad leve aparecido tras un esfuerzo"],["El curso cita el dolor nocturno intenso y el dolor no modificado por medicamentos ni postura entre las banderas rojas.","Ese comportamiento es típicamente mecánico y tranquilizador, no una bandera roja según el curso.","Un dolor leve e intermitente no figura entre los indicadores de alarma del curso."]],
  "1": ["Según los grados de Maitland, ¿cuál es el objetivo de una movilización de grado I?",["Reducir el dolor y desensibilizar la articulación en los estados irritables","Ganar los últimos grados de movilidad capsular","Aumentar la movilidad cuando predomina la rigidez"],["El grado I (pequeña amplitud, inicio del recorrido) busca disminuir el dolor y desensibilizar.","Es el objetivo del grado IV (pequeña amplitud al final del recorrido).","Es el objetivo del grado III (gran amplitud hasta la barrera)."]],
  "2": ["¿Cuál es el principio de las técnicas de movilización neuromeníngea (neurodinámica)?",["Liberar los puntos de presión que dificultan el deslizamiento del nervio","Estirar el nervio hasta su límite elástico para alargarlo","Fortalecer los músculos inervados para compensar el déficit"],["El nervio atraviesa fascias, músculos y cápsulas que pueden rigidizarse y pinzarlo; esas técnicas liberan los puntos de presión a lo largo de su trayecto.","No se trata de alargar el nervio, sino de restaurar su movimiento allí donde su deslizamiento está impedido.","El fortalecimiento muscular no es el objeto de esas técnicas, que se dirigen al tejido nervioso y a su entorno."]],
  "3": ["¿Por qué se emplean también las técnicas neurodinámicas en dolores nociceptivos que no afectan al tejido nervioso?",["Porque mejoran el umbral del dolor del paciente","Porque aceleran la cicatrización del tejido lesionado","Porque suprimen la compresión del tejido nervioso"],["El curso indica que esas técnicas mejoran el umbral del dolor y reducen así el dolor percibido, incluso cuando el tejido nervioso no está afectado.","No se propone ningún efecto sobre la cicatrización tisular para justificar ese uso ampliado.","Precisamente no hay ninguna compresión nerviosa que levantar en esa situación, puesto que el tejido nervioso no está afectado."]],
  "4": ["¿Cuál es la utilidad del Slump Test?",["Es una prueba neurodinámica que pone en tensión exclusivamente el nervio ciático y sus raíces L4-S1, sin solicitar el resto del sistema nervioso.","Es una prueba neurodinámica que evalúa la mecanosensibilidad de los tejidos neurales puestos en tensión desde el neuroeje hasta los miembros inferiores.","Es una prueba neurodinámica específica de la hernia discal lumbar, cuya positividad confirma el conflicto discorradicular."],["Falso: el Slump Test no es exclusivo del nervio ciático; al movilizar el raquis y el miembro inferior, pone en tensión todo el sistema nervioso, desde el neuroeje hasta los miembros inferiores, y no sólo las raíces L4-S1.","Exacto: el Slump Test es una prueba neurodinámica global que, mediante la flexión cervicodorsolumbar asociada a la extensión de rodilla y la dorsiflexión, pone en tensión el tejido neural desde el neuroeje hasta los miembros inferiores y evalúa su mecanosensibilidad.","Falso: no es una prueba diagnóstica específica de hernia discal; su positividad traduce una mecanosensibilidad neural aumentada sin confirmar un conflicto discorradicular, que corresponde a la imagen."]],
  "5": ["La evaluación neurodinámica mediante una prueba de Lasègue positiva sugiere:",["Una mecanosensibilidad aumentada del nervio ciático","Una mecanosensibilidad aumentada del nervio femoral","Una mecanosensibilidad aumentada del nervio tibial posterior"],["El Lasègue (elevación pasiva de la pierna extendida, con dolor radicular por debajo de 60°) pone en tensión el nervio ciático: sugiere una hernia L4-L5 o L5-S1.","El nervio femoral se evalúa en decúbito prono, con la cadera en extensión (prueba de Léri/Wassermann), no mediante el Lasègue.","El tibial posterior se explora mediante dorsiflexión y eversión del tobillo al final del Lasègue (sensibilización distal), y no con el Lasègue básico."]],
  "6": ["¿Qué designa la « función muscular » cuyo nivel mejora el ejercicio terapéutico?",["La capacidad del músculo de producir tensión y de funcionar","La capacidad del músculo de alargarse sin dolor en reposo","La capacidad del músculo de almacenar glucógeno durante el esfuerzo"],["El curso define explícitamente la mejora de la función muscular como la de la capacidad del músculo de producir tensión.","El alargamiento corresponde a la flexibilidad y a la elasticidad musculotendinosas, y no a la definición recogida aquí.","Las reservas energéticas corresponden a los cambios metabólicos, descritos aparte de las cualidades musculares."]],
  "7": ["En electroterapia, ¿con qué finalidad se emplean las altas frecuencias (superiores a 50 Hz)?",["La analgesia","La electroestimulación muscular","La producción de una corriente galvánica continua"],["El curso precisa que las altas frecuencias (>50 Hz) se emplean para la analgesia.","El curso reserva las bajas frecuencias (<50 Hz) a la electroestimulación.","La corriente galvánica es una corriente continua a 0 Hz, sin relación con la elección de frecuencia."]],
  "8": ["¿En qué consiste la neuromodulación percutánea?",["En una aguja conectada a una corriente de baja frecuencia, aplicada al nervio periférico bajo ecografía","En una aguja introducida sin corriente en el punto gatillo muscular, sin inyección de sustancia","En una aguja conectada a una corriente galvánica aplicada al tendón degenerado bajo control ecográfico"],["El curso la define como un abordaje invasivo e indoloro dirigido al epineuro del nervio periférico con una corriente de baja frecuencia, bajo ecografía.","Es la definición de la punción seca, técnica distinta de la neuromodulación.","Esa descripción corresponde a la electrólisis percutánea, que apunta al foco lesional del tendón."]],
  "9": ["Entre las situaciones siguientes, ¿cuál figura entre las contraindicaciones generales de la electroterapia?",["Un proceso tumoral en evolución","Una cicatriz cerrada y antigua","Una amiotrofia tras una inmovilización"],["Los procesos tumorales forman parte de las contraindicaciones generales, al igual que las infecciones activas y los dispositivos implantados.","Son las heridas abiertas las que contraindican la aplicación, y no una cicatriz cerrada desde hace tiempo.","La amiotrofia consecutiva a una inmovilización constituye al contrario una indicación clásica de la contracción provocada."]],
  "10": ["¿Cuál es el mecanismo de acción de la electrólisis percutánea?",["Una corriente galvánica que provoca una reacción inflamatoria controlada que estimula la reparación","Una ablación térmica del tejido mediante corriente de alta frecuencia","La inyección de una sustancia analgésica a través de la aguja"],["El curso describe la aplicación de una corriente galvánica que induce una inflamación controlada reparadora.","El procedimiento es electroquímico mediante una corriente galvánica, no una ablación térmica.","No se inyecta ninguna sustancia; el efecto proviene de la corriente galvánica."]],
  "11": ["¿Con qué criterio se distingue la corriente pulsada de la corriente continua?",["Fluye por impulsos separados por tiempos sin corriente","Cambia el sentido del flujo en cada impulso emitido","Emite una intensidad creciente en cada impulso"],["Es la interrupción del flujo lo que define la corriente pulsada: impulsos sucesivos entrecortados por periodos de ausencia de corriente.","La inversión del sentido del flujo define la corriente alterna, y no el carácter pulsado, que depende únicamente de la interrupción de la corriente entre los impulsos.","La intensidad no interviene en esa clasificación, que se basa únicamente en la continuidad o no del flujo."]],
  "12": ["Cuando la frecuencia aplicada se vuelve demasiado elevada, muchos impulsos ya no desencadenan un potencial de acción. ¿Por qué?",["Porque la membrana no repolarizada permanece en periodo refractario","Porque la intensidad emitida disminuye cuando la frecuencia aumenta","Porque los impulsos próximos entre sí se anulan unos a otros"],["Mientras la repolarización no ha concluido, la membrana no acepta ningún nuevo estímulo: los impulsos demasiado próximos caen en ese periodo.","Frecuencia e intensidad son dos parámetros independientes: aumentar una no reduce la otra.","Los impulsos no se anulan mutuamente; es el estado de la membrana en el momento del estímulo el que decide la respuesta."]],
  "13": ["¿Cómo se define la terapia manual?",["Un tratamiento físico en el que el profesional utiliza sus manos para diagnosticar y tratar","Un tratamiento físico basado en agentes físicos aplicados al paciente","Un tratamiento activo en el que el paciente moviliza él mismo sus articulaciones"],["La terapia manual es un tratamiento físico en el que el profesional se sirve de sus manos, tanto para el diagnóstico como para el tratamiento de los trastornos musculoesqueléticos.","Los agentes físicos dependen de la electroterapia y de la termoterapia, no de la terapia manual.","La movilización activa por el paciente depende del ejercicio terapéutico."]],
  "14": ["¿Qué enfoque ha ido ocupando el lugar de la terapia manual en los últimos años?",["La electroterapia de baja frecuencia","El ejercicio terapéutico","El drenaje linfático manual"],["La electroterapia sigue siendo un coadyuvante, no el tratamiento que la ha sustituido.","Durante mucho tiempo la más utilizada en fisioterapia, la terapia manual ha cedido el lugar al ejercicio terapéutico.","El drenaje linfático es una disciplina de la propia terapia manual."]],
  "15": ["¿Cuál de estos elementos no es un objetivo principal de la terapia manual?",["Reducir el dolor del paciente","Mejorar la reparación tisular después de una lesión","Aumentar la fuerza máxima del músculo"],["La reducción del dolor es el primer objetivo citado.","La mejora de la reparación tisular es un objetivo reconocido.","La ganancia de fuerza máxima depende del ejercicio terapéutico, no de los objetivos de la terapia manual."]],
  "16": ["¿Qué finalidad persigue la terapia manual al recuperar las propiedades de los tejidos?",["Restaurar la funcionalidad","Prevenir la recidiva de la lesión inicial","Obtener una analgesia definitiva de la zona"],["Recuperar o mantener la elasticidad y la contractilidad de los tejidos busca la restauración de la funcionalidad.","La prevención de la recidiva no es la finalidad enunciada.","No se busca ninguna analgesia definitiva: el dolor se modula."]],
  "17": ["¿Cuál es el tejido diana del drenaje linfático?",["El tejido blando superficial","El sistema linfático","El tejido nervioso periférico"],["El tejido blando es la diana de la masoterapia, de los estiramientos y de la terapia miofascial.","Cada disciplina de la terapia manual tiene su tejido diana: el drenaje linfático se dirige al sistema linfático.","El tejido nervioso es la diana de la movilización neurodinámica."]],
  "18": ["¿Qué disciplina de la terapia manual se dirige al tejido ARTICULAR?",["La terapia miofascial y los estiramientos","La movilización neurodinámica global","La movilización y la manipulación articulares"],["Esas dos técnicas se dirigen al tejido blando.","La neurodinámica se dirige al tejido nervioso.","La movilización y la manipulación articulares son las dos disciplinas cuyo tejido diana es el tejido articular."]],
  "19": ["¿Cuál de estos elementos caracteriza el nivel de evidencia de la masoterapia?",["Una aceptación elevada de los pacientes pero un nivel de evidencia bajo","Un nivel de evidencia elevado y una buena aceptación de los pacientes","Una aceptación baja de los pacientes y un nivel de evidencia elevado"],["La masoterapia es muy bien aceptada por los pacientes, pero su nivel de evidencia es bajo, al ser los trabajos de baja calidad metodológica.","El nivel de evidencia es precisamente bajo, por falta de calidad metodológica.","La aceptación por los pacientes es al contrario elevada."]],
  "20": ["¿Cuál de estos tipos de masaje no figura entre los descritos?",["El masaje anestésico o sedante","El masaje descontracturante profundo","El masaje revulsivo"],["Ese tipo figura efectivamente entre los descritos.","Los tipos descritos son estimulante, de tonificación, eliminador, anestésico o sedante, y revulsivo.","El masaje revulsivo forma parte de los tipos descritos."]],
  "21": ["¿Qué efecto produce la masoterapia sobre la PIEL?",["Una vasoconstricción refleja con palidez local","Una reabsorción de los derrames articulares","Una vasodilatación activa con hiperemia local"],["El efecto es inverso: el enrojecimiento atestigua la vasodilatación.","La reabsorción de los derrames concierne al tejido celular subcutáneo.","Sobre la piel, el masaje produce una vasodilatación activa, una hiperemia, una eliminación de los desechos por transpiración aumentada y una mejora del trofismo."]],
  "22": ["¿Por qué mecanismo reduce la masoterapia los adipocitos?",["Por lisis mecánica de las células grasas","Por aumento del metabolismo basal","Por estimulación de la lipólisis hormonal"],["En el tejido celular subcutáneo, el masaje produce una reabsorción de los adipocitos por lisis mecánica.","No se describe ninguna acción metabólica general.","El mecanismo establecido es mecánico, no hormonal."]],
  "23": ["¿De qué depende el efecto relajante o excitante de la masoterapia sobre el músculo?",["Del tejido diana elegido por el profesional","De los parámetros de aplicación de la técnica","De la duración de la lesión a tratar"],["El tejido diana es el músculo en ambos casos: lo que cambia es el ajuste.","El masaje mejora tanto la relajación como la excitabilidad musculares, según los parámetros de aplicación establecidos.","La antigüedad de la lesión no es el factor determinante descrito."]],
  "24": ["¿Qué efecto produce la masoterapia sobre el tejido ARTICULAR?",["Un aumento de la producción de líquido sinovial por la membrana","Un aumento de la laxitud de la cápsula","Una reducción de la rigidez y un ablandamiento de las adherencias"],["La lubricación por el líquido sinovial es un efecto de la MOVILIZACIÓN articular.","El aumento de la laxitud es un efecto de la movilización articular.","Sobre el tejido articular, el masaje reduce la rigidez, ablanda las adherencias y favorece la resorción de los exudados."]],
  "25": ["¿Cómo actúa la masoterapia sobre el tejido visceral?",["Por una acción refleja a distancia","Por una acción mecánica directa sobre el órgano","Por una acción hormonal sobre la motilidad"],["La acción sobre el tejido visceral es refleja: el masaje de evacuación aumenta por ejemplo el peristaltismo intestinal.","La acción descrita es refleja, no una compresión directa del órgano.","No se describe ningún mecanismo hormonal."]],
  "26": ["¿Qué efecto produce la masoterapia sobre el tejido NERVIOSO?",["Una disminución de la excitabilidad de los nervios motores","Una analgesia por descenso de la sensibilidad de las terminaciones","Una disminución clara de la actividad parasimpática"],["Es lo contrario: la excitabilidad de los nervios motores aumenta.","Sobre el tejido nervioso, el masaje produce una analgesia por disminución de la sensibilidad de las terminaciones sensitivas, y un aumento de la excitabilidad de los nervios motores.","La actividad parasimpática aumenta, con un aumento de la variabilidad de la frecuencia cardiaca."]],
  "27": ["¿Qué efecto del masaje sobre el sistema nervioso autónomo se establece?",["Un aumento de la frecuencia cardiaca de reposo","Una elevación de la presión arterial sistólica","Un aumento de la variabilidad de la frecuencia cardiaca"],["El efecto parasimpático va en el sentido de una ralentización, no de una aceleración.","No se describe ninguna elevación tensional como efecto del masaje.","El aumento de la actividad parasimpática se traduce por un aumento de la variabilidad de la frecuencia cardiaca."]],
  "28": ["¿Qué caracteriza a la movilización SIMPLE?",["Sigue un movimiento fisiológico de la articulación","Se dirige a los movimientos accesorios de la articulación","Actúa simultáneamente sobre varias articulaciones"],["La movilización simple sigue los movimientos fisiológicos, flexoextensión, rotación, abducción-aducción, para mantener la amplitud y reducir la rigidez.","Los movimientos accesorios son la diana de la movilización ANALÍTICA.","La acción sobre varias articulaciones define la movilización GLOBAL."]],
  "29": ["¿Cuál es el objetivo de la movilización ANALÍTICA?",["Mantener un buen esquema motor en el paciente hospitalizado","Restaurar la biomecánica para recuperar la amplitud completa","Relajar la presión intracapsular de la articulación"],["El mantenimiento del esquema motor es el objetivo de la movilización global.","Más específica, la movilización analítica, dirigida a los movimientos accesorios, busca restaurar la biomecánica articular.","La relajación de la presión intracapsular es el principio de la tracción."]],
  "30": ["¿En qué tipo de paciente se utiliza principalmente la movilización GLOBAL?",["En el deportista en fase de reanudación","En el paciente portador de una rigidez articular aislada","En el paciente encamado y hospitalizado"],["La reanudación deportiva depende del trabajo activo y analítico.","Una rigidez aislada depende más bien de la movilización simple o analítica.","La movilización global, que actúa sobre varias articulaciones y mantiene el esquema motor, se emplea sobre todo en los pacientes encamados y hospitalizados."]],
  "31": ["¿Cuál es el principio de la tracción articular?",["Relajar la presión intracapsular y limitar los roces articulares","Desplazar la articulación más allá de su amplitud a gran velocidad","Movilizar varias articulaciones para mantener el esquema motor"],["La tracción, específica de una articulación, relaja la presión intracapsular y limita los roces entre las superficies, lo que reduce el dolor al movimiento.","Esa descripción es la de la manipulación articular.","Eso es el objeto de la movilización global."]],
  "32": ["¿Qué caracteriza a la manipulación articular?",["Un desplazamiento pasivo lento y sostenido dentro de la amplitud fisiológica media","Un desplazamiento pasivo más allá de la amplitud, realizado a gran velocidad","Una puesta en tensión progresiva del trayecto nervioso"],["El desplazamiento lento dentro de la amplitud define la movilización.","La manipulación desplaza pasivamente la articulación más allá de su amplitud de movimiento, a gran velocidad.","La puesta en tensión del nervio depende de la neurodinámica."]],
  "33": ["¿Qué se sabe del fenómeno de cavitación durante una manipulación articular?",["Condiciona enteramente el efecto analgésico obtenido","Traduce una lesión capsular a evitar absolutamente","No es necesario para producir los efectos analgésicos"],["El chasquido no es la condición de la analgesia.","No se asocia ninguna lesión capsular al fenómeno.","Los efectos fisiológicos de la manipulación siguen siendo poco conocidos, pero la cavitación no es necesaria para obtener la analgesia."]],
  "34": ["¿Cuál de estos efectos no pertenece a la movilización articular?",["La reducción de la presión intraneural","La activación del sistema top-down","La lubricación de las superficies articulares"],["El descenso de la presión intraneural es un efecto de la movilización NEURODINÁMICA.","La activación del sistema top-down figura entre los efectos de la movilización articular.","La producción de líquido sinovial forma parte de sus efectos."]],
  "35": ["¿Qué mecanismo medular se moviliza con la movilización articular?",["El transporte axoplásmico","El gate-control medular","La normalización de la mecanosensibilidad"],["El transporte axoplásmico es un efecto de la neurodinámica.","Los efectos de la movilización articular comprenden la activación del sistema top-down y el gate-control.","La normalización de la mecanosensibilidad depende igualmente de la neurodinámica."]],
  "36": ["¿Cómo se define la movilización neurodinámica?",["Una movilización analítica de las articulaciones atravesadas por el nervio","Una técnica de presión sostenida sobre el trayecto del nervio","Una movilización global dirigida a tensar el tejido nervioso en su trayecto"],["Se dirige al propio nervio, no a los movimientos accesorios de las articulaciones.","Pone en tensión y moviliza, no comprime el nervio.","La neurodinámica es una movilización global que pone en tensión y mejora la movilidad del tejido nervioso a lo largo de todo su trayecto en los miembros."]],
  "37": ["¿Qué estructuras pueden «pinzar» un nervio en su trayecto?",["Las fascias, los músculos y las cápsulas articulares","Los vasos linfáticos y los ganglios","Las superficies articulares y el cartílago hialino"],["El nervio atraviesa fascias, músculos y cápsulas articulares, que pueden rigidizarse o contraerse y comprimirlo.","El sistema linfático no se describe como fuente de compresión nerviosa.","Las superficies articulares no se citan como puntos de compresión del nervio."]],
  "38": ["¿Qué patología ilustra la liberación de un punto de presión nervioso?",["La capsulitis retráctil del hombro","El síndrome del túnel carpiano","La tendinopatía del manguito de los rotadores"],["La capsulitis es una afectación capsular, no un punto de compresión nerviosa.","El síndrome del túnel carpiano es el ejemplo dado de compresión que dificulta la conducción nerviosa, fuente de dolor, de pérdida de fuerza y de disestesia.","La tendinopatía es una afectación del tejido blando."]],
  "39": ["¿En qué otro marco se utiliza la neurodinámica, al margen de la afectación del nervio?",["En los edemas crónicos de los miembros inferiores de origen venoso","En las rigideces articulares postraumáticas","En los dolores nociceptivos, para elevar el umbral de dolor"],["El edema depende del drenaje linfático.","La rigidez articular depende de la movilización articular.","Sirve también en los dolores nociceptivos que no afectan al tejido nervioso, para mejorar el umbral de dolor y reducir el dolor percibido."]],
  "40": ["¿Cuál de estos efectos pertenece a la movilización neurodinámica?",["El aumento del transporte axoplásmico","El aumento de la laxitud articular","La resorción de los exudados articulares"],["Entre sus efectos figuran el descenso de la presión intraneural, el aumento del transporte axoplásmico y la normalización de la mecanosensibilidad.","El aumento de la laxitud es un efecto de la movilización articular.","La resorción de los exudados es un efecto de la masoterapia."]],
  "41": ["¿A qué niveles ejerce la movilización neurodinámica su efecto analgésico?",["A nivel periférico exclusivamente","A nivel espinal y supraespinal","A nivel del córtex somestésico solamente"],["El efecto supera el nivel periférico.","El efecto analgésico de la neurodinámica se describe como espinal y supraespinal.","El efecto no se limita a un relevo cortical único."]],
  "42": ["¿Qué efecto de la neurodinámica concierne directamente a la mecánica del nervio?",["Un aumento de la contractilidad muscular","Una disminución de la rigidez capsular","Una mejor adaptación biomecánica"],["La contractilidad muscular se mejora con la masoterapia.","La rigidez capsular depende de la movilización articular.","La mejora de la adaptación biomecánica del nervio figura entre los efectos, junto con el descenso de la presión intraneural."]],
  "43": ["¿Cómo se define la movilización articular?",["El desplazamiento pasivo de una articulación para mantener o restaurar la movilidad","El desplazamiento activo de una articulación contra una resistencia manual progresiva","El desplazamiento pasivo más allá de la amplitud fisiológica"],["La movilización articular desplaza pasivamente la articulación a fin de mantener o restaurar una movilidad completa y de prevenir las deformidades.","El trabajo activo contra resistencia depende del ejercicio terapéutico.","Superar la amplitud articular define la manipulación, no la movilización."]],
  "44": ["¿Cuál de estos sistemas puede estar en el origen de un dolor torácico?",["Los sistemas renal y cardiopulmonar","Los sistemas tiroideo y paratiroideo","Los sistemas hematopoyético y linfoide"],["El origen puede venir de las estructuras vertebrales y de la caja torácica, pero también de los sistemas gastrointestinal, cardiopulmonar y renal.","El tiroides no se cita entre los orígenes posibles.","La hematopoyesis no se cita como origen."]],
  "45": ["¿Qué movimientos aumentan el dolor facetario torácico?",["La flexión mantenida y la carga axial","La extensión, la rotación y la inclinación","Las respiraciones profundas y la tos"],["La flexión mantenida y la carga axial agravan el dolor discal.","El dolor facetario torácico aumenta con los movimientos de extensión, de rotación y de inclinación.","El dolor con la respiración profunda y la tos evoca una osteocondritis."]],
  "46": ["¿Qué alivia el dolor facetario torácico?",["El mantenimiento prolongado de la posición de pie","La flexión completa del tronco hacia delante","El cambio de posición"],["La posición de pie prolongada lo agrava al contrario.","La flexión no es la posición aliviadora descrita.","El dolor facetario mejora con el cambio de posición, mientras que aumenta en posición sentada o de pie prolongada."]],
  "47": ["¿A qué nivel son más frecuentes las hernias discales torácicas?",["En T11-T12","En T1-T2","En T6-T7"],["Las hernias discales torácicas más corrientes asientan en T11-T12 y son generalmente de origen traumático.","Ese nivel no es el más frecuentemente afectado.","El nivel más frecuente es más bajo."]],
  "48": ["¿Cuál es el origen habitual de una hernia discal torácica?",["Una degeneración discal progresiva","Un traumatismo del raquis torácico","Una inflamación autoinmune crónica"],["La degeneración progresiva no es el origen establecido.","La hernia discal torácica es generalmente de origen traumático.","No se describe ningún origen autoinmune."]],
  "49": ["¿Qué movimientos aumentan el dolor discal torácico?",["La extensión y la inclinación lateral","La palpación directa de las articulaciones costales","La flexión mantenida, la rotación y la carga axial"],["La extensión y la inclinación agravan el dolor facetario.","El dolor a la palpación costal evoca una osteocondritis.","El dolor discal torácico aumenta con la flexión mantenida, la rotación y la carga axial, y en la posición de pie prolongada."]],
  "50": ["¿Qué articulaciones afecta la osteocondritis?",["Las articulaciones esternocondral, condrocostal y esternoclavicular","Las articulaciones costovertebrales y costotransversas posteriores","Las articulaciones cigapofisarias torácicas y lumbares"],["La osteocondritis asienta en las articulaciones esternocondral, condrocostal y esternoclavicular, en los niveles costales del segundo al quinto.","Esas articulaciones posteriores no son las descritas.","Las cigapófisis dependen del dolor facetario."]],
  "51": ["¿En qué niveles costales asienta la osteocondritis?",["Del sexto al décimo","Del segundo al quinto","En las costillas undécima y duodécima"],["Esos niveles no son los descritos.","La osteocondritis asienta en los niveles costales del segundo al quinto.","Ese nivel corresponde al asiento de las hernias torácicas."]],
  "52": ["¿Con qué afección debe hacerse el diagnóstico diferencial de la osteocondritis?",["La espondilitis anquilosante","La hernia discal torácica traumática","El síndrome de Tietze y el dolor cardiaco"],["La espondilitis se detecta por la limitación de movilidad en la prueba de Ott.","La hernia discal da un dolor medio, no anterior y costal.","El diagnóstico diferencial se hace con el dolor cardiaco, el síndrome de Tietze y el dolor muscular pectoral o intercostal."]],
  "53": ["¿En qué posición agravan los movimientos del tronco una radiculopatía torácica?",["En decúbito, durante los movimientos del tronco","En posición de pie prolongada únicamente","En posición sentada sin apoyo dorsal"],["El dolor se agrava con los movimientos del tronco realizados en decúbito, y aumenta con el Valsalva.","La posición de pie prolongada agrava más bien el dolor discal.","Esa posición no es la descrita."]],
  "54": ["¿Qué alteraciones estructurales se buscan en la observación estática torácica?",["Una anteversión pélvica y una dismetría","Una hipercifosis, una escoliosis o un dorso plano","Una báscula escapular y un despegamiento aislado"],["Esos elementos dependen de la exploración lumbopélvica.","La observación estática busca las alteraciones estructurales como la hipercifosis, la escoliosis o el dorso plano, así como las alteraciones cutáneas, los nódulos y las cicatrices.","Esos elementos no son los citados."]],
  "55": ["¿Qué hace positiva la prueba de Adams?",["Una limitación de la separación entre los dos puntos marcados","Una reproducción del dolor con el empuje costal","La aparición de una giba torácica o de una deformidad lumbar"],["La medida de los puntos de referencia pertenece a la prueba de Ott.","El empuje costal pertenece a la prueba de la primera costilla.","La prueba es positiva si aparece una giba torácica o una deformidad lumbar en flexión."]],
  "56": ["¿Por qué se añade una inclinación homolateral en la prueba de la primera costilla?",["Para relajar el músculo trapecio superior","Para poner el escaleno en tensión","Para bloquear los segmentos cervicales"],["La inclinación homolateral relaja el trapecio, lo que hace la primera costilla más accesible.","La maniobra busca una relajación, no una puesta en tensión.","El bloqueo segmentario no es el objetivo descrito."]],
  "57": ["¿Qué patología permite sospechar la prueba de Ott?",["La escoliosis idiopática del adolescente","La espondilitis anquilosante","El síndrome de la salida torácica"],["La escoliosis se detecta con la prueba de Adams.","Las modificaciones degenerativas del raquis limitan su movilidad: la espondilitis anquilosante es el ejemplo dado.","Ese síndrome se explora con la prueba de la primera costilla."]],
  "58": ["¿Para qué sirven los grados 1 y 2 de Maitland en el raquis torácico?",["Para mejorar la amplitud de los movimientos","Para realizar una manipulación a alta velocidad","Para la modulación del dolor"],["La ganancia de amplitud depende de los grados 3 y 4.","El impulso manipulativo corresponde al grado 5.","Los grados 1 y 2 sirven para modular el dolor, los grados 3 y 4 para mejorar la amplitud de los movimientos."]],
  "59": ["¿Qué grados se utilizan en la región ANTERIOR del tórax?",["Los grados 1 y 2","Los grados 3 y 4","El grado 5 manipulativo"],["En la región anterior del tórax se utilizan los grados 1 y 2, con una atención particular en los pacientes osteoporóticos o tratados con corticoides.","Los grados altos no se establecen en la cara anterior.","La manipulación no se establece en la cara anterior."]],
  "60": ["¿En qué pacientes hay que ser cauteloso durante el trabajo torácico anterior?",["Los pacientes portadores de una hernia de hiato","Los pacientes osteoporóticos o tratados con corticoides","Los pacientes portadores de un marcapasos"],["La hernia de hiato impone la prudencia sobre la parte central del diafragma.","La vigilancia se impone en los pacientes con osteoporosis o que han recibido un tratamiento con corticosteroides.","El marcapasos contraindica la electroterapia, no la movilización anterior."]],
  "61": ["¿Qué músculo debe tenerse siempre en cuenta en un dolor dorsal?",["El pectoral mayor","El elevador de la escápula","El diafragma"],["El pectoral mayor forma parte de las dianas, pero no es el que el curso obliga a considerar sistemáticamente.","Ese músculo figura entre las dianas, sin ese lugar sistemático.","El diafragma debe tenerse siempre en cuenta en todo dolor dorsal, e incluso lumbar."]],
  "62": ["¿Qué precaución tomar durante el trabajo del diafragma?",["Ser cauteloso con su parte central en caso de hernia de hiato","Evitar todo trabajo en el paciente osteoporótico","Trabajar solo un hemidiafragma a la vez"],["La parte central del diafragma exige una atención particular en los pacientes diagnosticados de hernia de hiato.","La osteoporosis concierne al trabajo torácico anterior.","Hay que trabajar al contrario todos los hemisferios, salvo contraindicación."]],
  "63": ["¿Cuál es la posición fisiológica del diafragma y del suelo pélvico?",["Sus ejes son perpendiculares entre sí","Sus ejes son horizontales y paralelos entre sí","Sus ejes divergen hacia delante, en tijera abierta"],["La perpendicularidad no es la disposición fisiológica.","En posición fisiológica, los ejes del diafragma y del suelo pélvico son horizontales y paralelos entre sí.","La divergencia en tijera abierta es precisamente la situación patológica."]],
  "64": ["¿A qué nervios se dirige la neurodinámica torácica?",["Al nervio mediano y al nervio cubital","Al nervio ciático y al nervio femoral","A los nervios intercostales y a los nervios espinales"],["Esos nervios dependen de la neurodinámica del miembro superior.","Esos nervios dependen de la neurodinámica del miembro inferior.","La neurodinámica torácica se dirige a los nervios intercostales y a los nervios espinales."]],
  "65": ["¿Qué técnica neurodinámica es la más utilizada y la menos agresiva?",["El deslizamiento por dos extremos","El deslizamiento por un extremo","La técnica de tensión bilateral"],["El deslizamiento por dos extremos es el más utilizado, sin peligro para el paciente y el menos agresivo; conviene a las fases iniciales y medias.","El deslizamiento por un extremo corresponde a las fases intermedias.","La técnica de tensión es la más intensa, reservada a las fases finales."]],
  "66": ["¿Qué ejes de trabajo establece el ejercicio para el raquis torácico?",["Únicamente la movilidad y los estiramientos analíticos","Movilidad, control motor, ejercicios respiratorios y fuerza","Únicamente el fortalecimiento de los músculos paravertebrales"],["El programa es más amplio que la sola movilidad.","El tratamiento mediante ejercicio establece la movilidad, el control motor lumbar y cervical, los ejercicios respiratorios, los ejercicios de disociación y la fuerza.","El fortalecimiento aislado no resume el programa."]],
  "67": ["¿Qué busca la segunda fase del tratamiento mediante ejercicio torácico?",["Tomar conciencia de la posición neutra de la pelvis","Introducir el trabajo de fuerza máxima en carga","Mantener la posición neutra y disociar los segmentos"],["La toma de conciencia depende de la primera fase.","El trabajo de fuerza máxima no es el objeto de esa fase.","La segunda fase busca el control de la posición neutra y la disociación segmentaria, integrando en ella los movimientos de los miembros superiores e inferiores."]],
  "68": ["En el adolescente, el dolor torácico es más frecuente:",["En las chicas","En los chicos","Sin diferencia entre los sexos"],["En los adolescentes, el dolor torácico es más frecuente en las chicas, con una prevalencia del 13 al 35 %.","El curso establece un predominio femenino.","Se señala explícitamente una diferencia."]],
  "69": ["¿Qué movimientos accesorios se exploran en el raquis torácico?",["Únicamente las articulaciones cigapofisarias torácicas","Las articulaciones costotransversa y costovertebral","Las articulaciones sacroilíacas y coxofemorales"],["La exploración no se limita a las cigapófisis.","Los movimientos accesorios exploran las presiones central y unilateral y las articulaciones costotransversa, costovertebral, esternocondral y condrocostal.","Esas articulaciones no dependen de la exploración torácica."]],
  "70": ["¿Con qué fin se utilizan los movimientos transversales en el raquis torácico?",["Para ganar amplitud al final del recorrido","Para movilizar las articulaciones condrocostales anteriores","Únicamente para modular el dolor, del lado no doloroso"],["La ganancia de amplitud depende de los grados 3 y 4 en presión directa.","Las articulaciones anteriores se trabajan mediante sus propios movimientos accesorios.","Los movimientos transversales sirven únicamente para modular el dolor, y se aplican del lado no doloroso."]],
  "71": ["¿Cómo proceder en caso de hiperalgesia torácica anterior?",["Trabajar otros niveles costales o el lado opuesto","Aumentar el grado para franquear el umbral doloroso","Interrumpir definitivamente todo tratamiento manual"],["En caso de hiperalgesia anterior se puede trabajar otros niveles costales, el lado contralateral, o las articulaciones posteriores del mismo nivel.","Franquear el dolor es contrario a los principios del método.","La interrupción definitiva no es la conducta propuesta."]],
  "72": ["¿En qué fase están indicadas las técnicas de TENSIÓN neurodinámica?",["En las fases iniciales y medias","En las fases finales del tratamiento","En las fases intermedias únicamente"],["Las fases iniciales y medias dependen del deslizamiento por dos extremos.","Las técnicas de tensión, que movilizan los dos extremos neurales, están indicadas en las fases finales del tratamiento.","Las fases intermedias dependen del deslizamiento por un extremo."]],
  "73": ["¿Qué busca la primera fase del tratamiento mediante ejercicio torácico?",["Mantener la posición neutra disociando los segmentos","Integrar los movimientos de los miembros en carga","Reconocer la posición neutra y activar el transverso"],["El mantenimiento y la disociación segmentaria constituyen la segunda fase.","La integración de los miembros llega en la fase siguiente.","La primera fase busca la conciencia de la posición neutra de la pelvis y del raquis, la activación selectiva de la musculatura estabilizadora y el control respiratorio coordinado."]],
  "74": ["¿Cómo se realiza la prueba de Adams?",["El paciente de pie flexiona completamente el tronco hacia sus pies","El paciente sentado gira la cabeza del lado de la costilla evaluada","El paciente de pie flexiona y extiende el tronco alternativamente"],["El paciente de pie realiza una flexión completa del tronco hacia los pies, colocándose el fisioterapeuta detrás de él.","Esa maniobra pertenece a la prueba de la primera costilla.","Ese movimiento alterno corresponde a la prueba de Ott."]],
  "75": ["¿Qué puntos de referencia se marcan para realizar la prueba de Ott?",["La espinosa de T1 y un punto situado veinte centímetros más abajo","La espinosa de C7 y un punto situado treinta centímetros más abajo","Las dos espinas ilíacas posterosuperiores"],["Los puntos establecidos son C7 y treinta centímetros.","Se marca la apófisis espinosa de C7 y un punto situado treinta centímetros más abajo.","Esos puntos sirven para la colocación del estabilizador lumbar."]],
  "76": ["¿Hacia dónde puede referirse el dolor facetario torácico?",["Hacia el abdomen, la región inguinal y el pubis","Hacia los miembros inferiores, más allá de la rodilla","Hacia el raquis cervical o la cintura escapular"],["Esa proyección no es la descrita.","La irradiación al miembro inferior no pertenece a ese cuadro.","El dolor facetario torácico puede referirse hacia el raquis cervical, la cintura escapular o la región de las costillas."]],
  "77": ["¿Qué elemento falta en el dolor facetario torácico?",["Las parestesias y la debilidad","El dolor matinal","El dolor referido a la cintura escapular"],["El dolor facetario torácico no comporta parestesias ni debilidad, al contrario que las afectaciones radiculares.","El dolor matinal forma parte del cuadro facetario.","El dolor referido escapular forma parte del cuadro."]],
  "78": ["¿Cuál de estos signos puede acompañar a una hernia discal torácica?",["Un dolor exclusivamente matinal y recurrente","Una disfunción vesical o intestinal","Un dolor limitado a las articulaciones condrocostales"],["El dolor matinal recurrente evoca una afectación facetaria.","El cuadro puede comportar alteraciones sensoriales, cambios térmicos de los pies, debilidad, una opresión torácica o abdominal y una disfunción vesical o intestinal.","La localización condrocostal evoca una osteocondritis."]],
  "79": ["¿Qué despierta el dolor de la osteocondritis?",["La extensión, la rotación y la inclinación del raquis dorsal","La maniobra de Valsalva y la posición de pie prolongada","La palpación, las respiraciones profundas y la tos"],["Esos movimientos agravan el dolor facetario.","El Valsalva y la posición de pie prolongada agravan el dolor discal.","El dolor se despierta con la palpación, los movimientos torácicos, las respiraciones profundas y la tos."]],
  "80": ["¿Cuál de estos signos caracteriza una neuropatía torácica?",["Disestesias o una hipoestesia de la zona costal","Un dolor localizado en las articulaciones esternocondrales","Una ausencia total de trastorno sensitivo"],["La neuropatía torácica da parestesias, quemazón, disestesias o una hipoestesia en la zona costal.","Esa localización evoca una osteocondritis.","Los trastornos sensitivos están al contrario en primer plano."]],
  "81": ["¿Qué situación clínica justifica la prueba de la primera costilla?",["Una sospecha de escoliosis estructural torácica","Un dolor de la unión cervicotorácica","Una sospecha de espondilitis anquilosante"],["La escoliosis se detecta con la prueba de Adams.","La prueba de la primera costilla es útil ante síntomas de la salida torácica o un dolor de la unión cervicotorácica.","La espondilitis se detecta con la prueba de Ott."]],
  "82": ["¿En cuánto aumenta la distancia en flexión durante la prueba de Ott?",["De 1 a 2 centímetros","De 8 a 10 centímetros","De 2 a 4 centímetros"],["Uno a dos centímetros corresponde a la disminución en extensión.","Esa amplitud supera ampliamente los valores establecidos.","En flexión del tronco la distancia aumenta de 2 a 4 centímetros, y en extensión disminuye de 1 a 2 centímetros."]],
  "83": ["¿Qué beneficio aporta la coordinación de los diafragmas al suelo pélvico?",["Previene la incontinencia y el prolapso","Aumenta la fuerza máxima del periné","Suprime toda necesidad de rehabilitación perineal"],["Una coordinación adecuada entre los diafragmas ayuda a prevenir disfunciones como la incontinencia o el prolapso.","La ganancia de fuerza máxima no es el beneficio descrito.","No se plantea ninguna sustitución de ese tipo."]],
  "84": ["¿Por qué favorecer el plano de la escápula en el trabajo del hombro?",["Para aumentar la tensión del bíceps largo","Para reducir la compresión subacromial","Para bloquear la articulación acromioclavicular"],["El aumento de tensión no es el objetivo buscado.","Favorecer los movimientos en el plano de la escápula reduce la compresión subacromial.","El bloqueo acromioclavicular no es el objetivo."]],
  "85": ["¿Cuál es el signo clave que distingue la capsulitis adhesiva de una tendinopatía?",["El dolor nocturno del lado del hombro afectado","La debilidad de la abducción contra resistencia","La pérdida de amplitud activa igual a la pasiva"],["El dolor nocturno existe en ambas afecciones.","La debilidad resistida pertenece a las afectaciones tendinosas.","La pérdida de amplitud activa igual a la pasiva es la clave de la capsulitis, frente a las tendinopatías donde la pasiva se conserva."]],
  "86": ["¿Qué efecto se espera de un TENS de baja frecuencia?",["Una liberación de endorfinas","Un efecto analgésico inmediato","Una activación de los músculos inhibidos"],["La alta frecuencia da un efecto inmediato, la baja frecuencia una liberación de endorfinas.","El efecto inmediato se obtiene con la alta frecuencia.","La activación muscular depende de la electroestimulación."]],
  "87": ["¿Qué consecuencia funcional comparten las lesiones SLAP y de Bankart?",["La pérdida simétrica de las amplitudes pasivas","La inestabilidad glenohumeral","La crepitación con rigidez progresiva"],["La pérdida simétrica de las amplitudes caracteriza a la capsulitis.","Ambas lesiones tienen como consecuencia funcional una inestabilidad glenohumeral.","Crepitación y rigidez progresiva evocan la artrosis."]],
  "88": ["¿Qué precaución tomar con la diatermia después de una cirugía del hombro?",["La prohibición formal durante un año","La aplicación exclusiva en fase aguda","La prudencia en presencia de material quirúrgico"],["No se plantea ninguna prohibición de esa duración.","La diatermia conviene a las fases subagudas y crónicas.","La diatermia es utilizable en las fases subagudas y crónicas, con precaución en presencia de material quirúrgico."]],
  "89": ["¿Cuál es el interés de la diatermia en el síndrome miofascial?",["Actúa sobre los puntos gatillo profundos o crónicos","Activa los músculos inhibidos o debilitados","Modula las respuestas centrales sensibilizadas"],["La diatermia aporta un calor profundo, reduce la rigidez y resulta muy eficaz sobre los puntos gatillo profundos o crónicos.","La activación de los músculos inhibidos depende de la electroestimulación.","La modulación central depende de la corriente de tipo burst."]],
  "90": ["¿Por qué hay que tratar precozmente un dolor persistente del hombro?",["Porque el riesgo de necrosis ósea aumenta","Porque el pronóstico se agrava con la duración del dolor","Porque la movilidad pasiva del hombro se pierde primero"],["El riesgo de necrosis avascular no es el argumento planteado.","Cuanto más persiste el dolor, más desfavorable es el pronóstico funcional: hay que tratar por tanto rápidamente.","La pérdida de movilidad pasiva caracteriza a la capsulitis adhesiva."]],
  "91": ["¿Qué produce la nocicepción persistente procedente del manguito de los rotadores?",["Una degeneración acelerada del labrum","Una osificación progresiva de la cápsula","Una hiperalgesia local y generalizada"],["La afectación labral depende de las lesiones SLAP y Bankart.","La osificación capsular no se describe.","La nocicepción persistente puede sensibilizar el sistema nervioso central, con hiperalgesia local y generalizada y tolerancia reducida al ejercicio."]],
  "92": ["¿Qué grado de movilización elegir ante un hombro doloroso sin restricción?",["Los grados I o II","Los grados III o IV","El grado V manipulativo"],["La evaluación guía la elección: el dolor conduce a los grados I o II, la restricción o la resistencia a los grados III o IV.","Los grados altos se dirigen a la restricción, no al dolor.","La manipulación no es la opción establecida aquí."]],
  "93": ["¿Qué precaución sigue a la aplicación de una electrólisis percutánea?",["Una inmovilización estricta durante tres semanas","Un reposo relativo después de la aplicación","Una reanudación inmediata del trabajo excéntrico"],["No se exige ninguna inmovilización estricta.","La electrólisis percutánea es ecoguiada, indicada en las fases subagudas o crónicas, y necesita un reposo relativo después de su aplicación.","La reanudación inmediata contradice el reposo relativo."]],
  "94": ["¿Qué amplitud de rotación externa se encuentra a menudo en la capsulitis adhesiva?",["A menudo menos de 100°","A menudo menos de 45°","A menudo menos de 10°"],["Cien grados es el límite de la elevación, no de la rotación externa.","Ese valor es superior al establecido.","La rotación externa está limitada, a menudo inferior a 10°, y la elevación inferior a 100°."]],
  "95": ["¿Qué busca la fase 3 del tratamiento articular de la capsulitis adhesiva?",["Las técnicas de fin de amplitud en grados 3 y 4","Las movilizaciones accesorias del raquis cervical","Las movilizaciones pasivas dentro de la amplitud indolora"],["La fase 3 comporta las técnicas de fin de amplitud, con movilizaciones accesorias de grados 3 y 4 y movilizaciones fisiológicas sin compensación.","El trabajo del raquis pertenece a la fase 1.","Ese trabajo pertenece a la fase 1."]],
  "96": ["¿En qué fase de la capsulitis es ideal la diatermia?",["En la fase inflamatoria inicial","En las fases de congelación y de descongelación","Después de la resolución completa de los síntomas"],["La fase inicial depende sobre todo del TENS.","La diatermia es ideal en las fases de congelación y de descongelación, donde prepara la movilización.","Después de la resolución ya no hay indicación."]],
  "97": ["¿Qué parámetros de movilización se utilizan en fase funcional de una lesión labral?",["Una serie única de diez minutos a 5 Hz","Diez series de diez segundos a 0,5 Hz","Tres a cinco series de un minuto a 2 Hz"],["Una serie única larga a 5 Hz no es el protocolo descrito.","Series muy breves a 0,5 Hz no son el protocolo descrito.","La fase funcional emplea movilizaciones de grados III-IV, a razón de 3 a 5 series de 1 minuto a 2 Hz."]],
  "98": ["¿Por qué es útil la electroestimulación después de una cirugía labral?",["Activa los estabilizadores sin solicitar el labrum","Estimula la regeneración del rodete glenoideo lesionado","Aporta un calor profundo al tendón"],["La electroestimulación activa los deltoides y los estabilizadores escapulares sin solicitar el labrum, sobre todo después de una artroscopia.","No se atribuye ninguna regeneración labral a esa técnica.","El calor profundo es el efecto de la diatermia."]],
  "99": ["¿A partir de qué duración se dice que el dolor miofascial del hombro es crónico?",["Más allá de doce meses","Más allá de seis meses","Más allá de tres meses"],["Doce meses corresponde a la persistencia del síndrome subacromial.","El dolor puede volverse crónico si no se trata, con una persistencia superior a seis meses.","El umbral establecido es más tardío."]],
  "100": ["¿Qué traduce un desplome del brazo después de 2 o 3 segundos de prueba resistida?",["Una rotura completa del tendón explorado","Una irritación del nervio supraescapular","Una fatigabilidad precoz del músculo estirado"],["La rotura completa no se deduce de ese signo.","La afectación neural no se deduce de ese signo.","El desplome después de 2 a 3 segundos traduce un músculo estirado que presenta una fatigabilidad precoz."]],
  "101": ["¿Qué ejercicio conviene a la fase inicial, llamada analgésica, del síndrome miofascial?",["La movilidad activa asistida y el control escapular básico","Las elevaciones progresivas contra resistencia","Los isométricos de los rotadores con una banda elástica ligera"],["La fase inicial asocia movilidad activa asistida, automasajes con pelota, control escapular básico y estiramientos.","Las elevaciones resistidas pertenecen a la fase avanzada.","Ese trabajo pertenece a la fase intermedia."]],
  "102": ["¿Qué prueba principal evalúa la sensibilización en el dolor de hombro?",["El umbral de percepción vibratoria","El umbral de dolor a la presión","El umbral de detección térmica"],["La vibración no es la modalidad establecida.","El umbral de dolor a la presión es la prueba principal para objetivar la sensibilización.","La detección térmica no es la modalidad establecida."]],
  "103": ["¿Cuál es el comportamiento del dolor en la artrosis glenohumeral?",["Superficial e inflamatorio, agravado en reposo","Irradiado al brazo, con parestesias distales","Profundo y mecánico, agravado con el esfuerzo"],["Un dolor de reposo de entrada no es el perfil de la artrosis.","Las parestesias distales evocan una afectación neural.","El dolor es profundo y mecánico: se agrava con el esfuerzo y mejora en reposo, con dolor nocturno en el estadio avanzado."]],
  "104": ["¿Cómo se realiza la prueba de Jobe, llamada «Empty-Can»?",["Abducción a 90° asociada a una rotación interna","Abducción a 90° asociada a una rotación externa","Abducción a 160° con compresión axial"],["La prueba de Jobe asocia una abducción de 90° y una rotación interna; es positiva en caso de pérdida de fuerza o de dolor.","Esa posición corresponde a la prueba de Patte.","Esa posición corresponde a la prueba de Crank."]],
  "105": ["¿En qué situación son particularmente útiles las ondas de choque?",["En una capsulitis en fase inflamatoria","En una tendinopatía crónica calcificada","En una lesión labral posoperatoria reciente"],["Están al contrario poco indicadas en las fases inflamatorias.","Las ondas de choque son muy útiles en las tendinopatías crónicas, en particular en caso de calcificación o de engrosamiento.","La fase posoperatoria reciente depende del TENS y de la magnetoterapia."]],
  "106": ["¿Cómo se comporta el dolor de la necrosis avascular frente a la fisioterapia estándar?",["Cede desde las primeras sesiones","Solo reaparece al reanudar el deporte","No responde bien a ella"],["Una respuesta rápida no corresponde a ese cuadro.","Esa evolución no es la descrita.","El dolor, sordo y mal localizado, se intensifica progresivamente y no responde bien a la fisioterapia estándar."]],
  "107": ["¿Qué tejido destruye la necrosis avascular de la cabeza humeral?",["El hueso subcondral y el hueso trabecular","El cartílago hialino de la cavidad glenoidea","El labrum glenoideo y su inserción bicipital"],["La necrosis avascular es la muerte del tejido óseo subcondral y del hueso trabecular de la cabeza humeral.","El desgaste del cartílago glenoideo depende de la artrosis.","La afectación labral define las lesiones SLAP."]],
  "108": ["¿Cuál es la eficacia del tratamiento conservador del hombro congelado?",["Eficaz en cerca de la mitad de los pacientes","Eficaz en hasta el 90 % de los pacientes","Eficaz en menos de un tercio de los pacientes"],["La mitad de los pacientes subestima ampliamente el resultado esperado.","El tratamiento conservador del hombro congelado es eficaz en hasta el 90 % de los pacientes.","Menos de un tercio de los pacientes queda muy lejos del resultado esperado."]],
  "109": ["¿Qué actividad perpetúa los puntos gatillo del dorsal ancho?",["Las actividades que exigen una elevación de los hombros","Las actividades en rotación interna resistida","Las actividades que exigen un descenso escapular"],["La elevación de los hombros concierne al trapecio superior.","La rotación interna resistida concierne al redondo mayor.","El dorsal ancho se activa con las actividades que exigen un descenso escapular, como el soporte del peso."]],
  "110": ["¿Qué progresión sigue el entrenamiento del síndrome miofascial?",["Del dominio motor hacia la resistencia y después la funcionalidad","De la fuerza máxima hacia el control motor","De la carga pesada hacia los movimientos analíticos"],["La progresión va del dominio motor a la resistencia, y después a la funcionalidad.","Ese orden es el inverso del propuesto.","Ese orden no corresponde a la progresión descrita."]],
  "111": ["¿Qué síndrome es el más corriente entre los dolores del hombro?",["La capsulitis adhesiva del hombro","El síndrome de dolor subacromial","La artrosis glenohumeral primitiva"],["La capsulitis solo afecta al 2-5 % de la población general.","El síndrome de dolor subacromial es el más corriente, y con él las tendinopatías del manguito de los rotadores.","La artrosis glenohumeral solo representa el 3-5 % de las artrosis periféricas."]],
  "112": ["¿Cuál de estos síntomas forma parte del cuadro típico del dolor de hombro?",["Los trastornos de la deglución","Los trastornos del equilibrio de pie","Los trastornos del sueño"],["La deglución no pertenece a ese cuadro clínico.","El equilibrio de pie no pertenece a ese cuadro clínico.","Los síntomas típicos asocian el dolor, la dificultad para levantar el brazo, los trastornos del sueño y los trastornos funcionales."]],
  "113": ["¿Cuál de estos elementos evoca una sensibilización en un paciente con dolor de hombro?",["Una hipersensibilidad difusa y un dolor bilateral","Una crepitación articular y una rigidez progresiva","Un arco doloroso entre sesenta y ciento veinte grados"],["Los signos de sensibilización comportan un umbral de dolor reducido, un dolor bilateral y una hipersensibilidad difusa.","La crepitación y la rigidez progresiva orientan hacia la artrosis glenohumeral.","El arco doloroso evoca un conflicto subacromial."]],
  "114": ["¿Contra qué estructura roza el tendón en el síndrome subacromial?",["La cara anterior de la cavidad glenoidea","La superficie inferior del acromion","La escotadura espinoglenoidea de la escápula"],["La glena anterior está implicada en la lesión de Bankart.","El tendón roza contra la superficie inferior del acromion, el ligamento coracoacromial y la articulación acromioclavicular.","Esa escotadura es el lugar de sufrimiento del nervio supraescapular."]],
  "115": ["¿Cómo se realiza la prueba de Hawkins?",["Mediante una abducción del brazo mantenido en rotación interna","Mediante una abducción de hombro a 90° asociada a una rotación externa máxima","Mediante una rotación interna, con hombro en abducción y codo flexionados a 90°"],["Esa maniobra es la del signo de Neer.","Esa posición es la de la prueba de Patte.","La prueba de Hawkins asocia una rotación interna a una abducción de hombro de 90° y una flexión de codo de 90°."]],
  "116": ["¿Dónde asienta el punto doloroso a la palpación del supraespinoso?",["A 1 o 2 cm por debajo del acromion","En el surco bicipital, delante del brazo","En la escotadura espinoglenoidea"],["La palpación encuentra un punto doloroso situado 1 a 2 cm por debajo del acromion.","Ese punto de referencia corresponde a la porción larga del bíceps.","Esa escotadura corresponde al trayecto del nervio supraescapular."]],
  "117": ["¿Qué debilidad traduce una afectación del infraespinoso?",["La debilidad en abducción","La debilidad en rotación externa","La debilidad en supinación resistida"],["La abducción corresponde al supraespinoso.","La debilidad en abducción traduce una afectación del supraespinoso, la de la rotación externa una afectación del infraespinoso.","La supinación resistida explora la porción larga del bíceps."]],
  "118": ["¿Qué músculo explora la prueba de Jobe?",["El infraespinoso","La porción larga del bíceps","El supraespinoso"],["El infraespinoso se explora con la prueba de Patte.","La porción larga del bíceps se explora con la prueba de Yergason.","La prueba de Jobe, o Empty-Can, explora el supraespinoso."]],
  "119": ["¿Por qué tipo de contracción comienza el manejo de una tendinopatía del manguito?",["Por contracciones isométricas","Por contracciones excéntricas","Por contracciones pliométricas"],["Se comienza por contracciones isométricas para mejorar la tolerancia al dolor, antes de progresar hacia el excéntrico y el concéntrico.","El excéntrico llega en un segundo tiempo.","La pliometría no es el punto de partida."]],
  "120": ["¿En qué modo se aplican los ultrasonidos terapéuticos sobre un tendón?",["En modo continuo, en las fases agudas","En modo pulsado, en las fases subagudas","En modo pulsado, antes de toda movilización"],["El modo continuo en las fases agudas no es la indicación establecida.","Los ultrasonidos se aplican en modo pulsado en las fases subagudas, para favorecer la resorción de los microedemas y la vascularización.","El momento de aplicación no se define así."]],
  "121": ["¿Cuál es el efecto buscado de la diatermia sobre un tendón?",["Una neovascularización por estimulación mecánica","Una liberación de endorfinas por estimulación lenta","Un calor profundo que mejora la extensibilidad"],["La neovascularización por estimulación mecánica es el efecto de las ondas de choque.","La liberación de endorfinas caracteriza al TENS de baja frecuencia.","La diatermia aporta un calor profundo, mejora el metabolismo local y la extensibilidad del tendón."]],
  "122": ["¿Qué movimiento se afecta primero en la necrosis avascular glenohumeral?",["La rotación externa","La abducción activa","La rotación interna"],["La rotación externa, activa y pasiva, es el primer movimiento afectado, antes de la abducción activa y después de la flexión anterior.","La abducción activa llega después de la rotación externa.","La rotación interna solo se afecta en los estadios avanzados."]],
  "123": ["¿Qué estructura está engrosada en la capsulitis adhesiva?",["El ligamento coracoacromial","El ligamento coracohumeral","El labrum glenoideo superior"],["Ese ligamento interviene en el conflicto subacromial.","La capsulitis adhesiva comporta un engrosamiento del ligamento coracohumeral y de la cápsula glenohumeral.","El labrum superior está implicado en las lesiones SLAP."]],
  "124": ["¿En qué orden se restringen las amplitudes en la capsulitis adhesiva?",["Abducción, después rotación interna, después rotación externa","Rotación interna, después rotación externa, después flexión","Rotación externa, después abducción, después rotación interna"],["Ese orden inverso no es el descrito.","Ese orden no es el descrito.","La rotación externa se afecta primero, seguida de la abducción y después de la rotación interna."]],
  "125": ["¿Qué caracteriza la segunda fase, llamada de «congelación», de la capsulitis adhesiva?",["Una rigidez grave con un dolor mínimo","Un dolor intenso con una amplitud conservada","Una mejora de la amplitud y poco dolor"],["La fase de congelación, de 9 a 15 meses, asocia una rigidez grave a un dolor mínimo.","Ese cuadro no corresponde a ninguna fase descrita.","Esa descripción corresponde a la fase de descongelación."]],
  "126": ["¿Qué grados de movilización se utilizan en la fase 1 de la capsulitis adhesiva?",["Los grados 3 y 4","Los grados 1 y 2","El grado 5 manipulativo"],["Los grados 3 y 4 pertenecen a las fases 2 y 3.","La fase 1 asocia movilizaciones pasivas dentro de la amplitud indolora, movilizaciones accesorias de grados 1 y 2 y técnicas neurales.","La manipulación no se establece en ese protocolo."]],
  "127": ["¿Qué lugar ocupan las ondas de choque en la capsulitis adhesiva?",["Es la técnica de primera intención","Están formalmente contraindicadas","No es la técnica de primera elección"],["No son de primera intención en esa afección.","Pueden plantearse con prudencia en los casos crónicos.","Las ondas de choque están poco indicadas en las fases inflamatorias y no constituyen la técnica de primera elección."]],
  "128": ["¿Qué nervio hay que proteger en las lesiones labrales del hombro?",["El nervio supraescapular, en la escotadura espinoglenoidea","El nervio mediano, en el desfiladero subacromial","El plexo braquial, a su paso bajo el pectoral menor retraído"],["El objetivo es prevenir la irritación del nervio supraescapular en la escotadura espinoglenoidea.","El nervio mediano se moviliza en el estrechamiento subacromial.","Esa compresión se evoca en la capsulitis adhesiva."]],
  "129": ["¿Qué principio guía la interpretación de las pruebas en el síndrome miofascial?",["Solo una prueba positiva autoriza el tratamiento","Reproducir los síntomas importa más que la positividad de la prueba","Las pruebas de fuerza priman sobre la reproducción de los síntomas"],["Esa exigencia no corresponde al principio enunciado.","Es más importante reproducir los síntomas del paciente que obtener pruebas positivas.","Esa jerarquía es la inversa de la enunciada."]],
  "130": ["¿Qué factor perpetúa los puntos gatillo del pectoral menor?",["Los movimientos repetidos de rotación interna resistida","Las actividades que exigen un descenso escapular","Las compresiones por una mochila"],["La rotación interna resistida repetida activa el redondo mayor.","El descenso escapular activa el dorsal ancho.","La activación y el mantenimiento del pectoral menor se deben a la postura de los hombros, al latigazo cervical, a los problemas respiratorios, a las compresiones y a los traumatismos."]],
  "131": ["¿Qué gesto activa los puntos gatillo del infraespinoso?",["Un movimiento del brazo hacia atrás y hacia arriba","Un porte de carga prolongado a lo largo del cuerpo","Un movimiento vigoroso de abducción del brazo"],["El infraespinoso se activa por sobrecargas agudas durante el movimiento del brazo hacia atrás y hacia arriba.","El porte de carga a lo largo del cuerpo activa el subescapular.","La abducción vigorosa activa el deltoides medio."]],
  "132": ["¿Qué gesto activa los puntos gatillo del redondo mayor?",["Los movimientos repetidos en extensión y aducción","Los movimientos repetidos en rotación interna contra resistencia","Los levantamientos potentes por encima de la cabeza"],["La extensión con aducción repetida concierne al dorsal ancho.","El redondo mayor se activa por movimientos repetidos hacia la rotación interna contra resistencia.","Los levantamientos por encima de la cabeza conciernen al supraespinoso."]],
  "133": ["¿Qué nervio se sensibiliza a menudo en el síndrome miofascial del hombro?",["El nervio cubital en el codo","El nervio intercostal superior","El nervio supraescapular"],["El nervio cubital no se cita en ese síndrome.","Los nervios intercostales dependen del raquis torácico.","Se constata frecuentemente una disfunción mecánica o una sensibilidad aumentada de los nervios supraescapular, axilar o musculocutáneo."]],
  "134": ["¿Qué gestos despiertan el dolor de una epicondilalgia lateral?",["La prensión y la extensión de la muñeca","La prensión y la flexión de la muñeca","La prensión y la pronación del antebrazo"],["El dolor del epicóndilo lateral aparece durante la prensión y la extensión de la muñeca.","La flexión de la muñeca despierta la epicondilalgia medial.","La pronación del antebrazo despierta la epicondilalgia medial."]],
  "135": ["¿Qué gestos despiertan el dolor de una epicondilalgia medial?",["La extensión de la muñeca y la supinación del antebrazo","La flexión de la muñeca y la pronación del antebrazo","La hiperextensión del codo y la abducción de hombro"],["La extensión de la muñeca despierta la epicondilalgia lateral.","El dolor del epicóndilo medial aparece durante la prensión, la flexión de la muñeca y la pronación del antebrazo.","La hiperextensión del codo evoca una sobrecarga externa en valgo."]],
  "136": ["¿Qué tendón está engrosado en la epicondilalgia lateral?",["El tendón flexor común","El tendón del supinador largo","El tendón extensor común"],["El tendón flexor depende de la afectación medial.","Ese tendón no es el que se describe como engrosado.","El engrosamiento afecta al tendón extensor común, con afectación de su unión miotendinosa."]],
  "137": ["¿A qué tipo de actividad se asocian las epicondilalgias?",["A los movimientos repetitivos","A los traumatismos directos únicos","A las inmovilizaciones prolongadas"],["Las epicondilalgias se asocian a los movimientos repetitivos del miembro superior.","El traumatismo único no es el mecanismo establecido.","La inmovilización no es el mecanismo establecido."]],
  "138": ["¿Qué evoca una queja de dolor aislado durante la prensión?",["Una epicondilalgia medial o un síndrome del pronador","Una epicondilalgia lateral o un atrapamiento radial","Una inestabilidad rotatoria o una sobrecarga en valgo"],["El dolor medial aparece en flexión y pronación, no con la sola prensión.","Un dolor con la prensión hace evocar una epicondilalgia lateral o un posible atrapamiento radial.","La inestabilidad se acompaña de una sensación de inestabilidad al movimiento."]],
  "139": ["¿Qué evoca una sensación de pesadez y hormigueo en el trayecto del nervio cubital?",["Un síndrome del músculo pronador redondo","Un síndrome de la arcada de Frohse","Una compresión del nervio cubital"],["El síndrome del pronador concierne al nervio mediano.","La arcada de Frohse concierne al nervio radial.","Pesadez y hormigueo en el trayecto del nervio cubital hacen evocar una compresión cubital."]],
  "140": ["¿Qué evoca un dolor anterior del codo exacerbado por la flexión de la muñeca, la pronación y la flexión del codo?",["Un síndrome del músculo pronador redondo","Una compresión del nervio cubital en el codo","Una inestabilidad rotatoria del codo"],["Esa combinación de movimientos hace evocar un posible síndrome del pronador redondo.","La compresión cubital se traduce por pesadez y hormigueo distales.","La inestabilidad rotatoria asocia dolor al movimiento y sensación de inestabilidad."]],
  "141": ["¿Qué evoca un dolor del codo asociado a una sensación de inestabilidad?",["Una epicondilalgia lateral crónica","Una inestabilidad rotatoria","Un síndrome del canal retroepitroclear"],["La epicondilalgia no comporta sensación de inestabilidad.","Un dolor al movimiento asociado a una sensación de inestabilidad hace evocar una inestabilidad rotatoria.","Ese síndrome se manifiesta por síntomas neurales cubitales."]],
  "142": ["¿Qué evoca un dolor del codo que aparece en hiperextensión?",["Una epicondilalgia medial incipiente","Un atrapamiento del nervio radial proximal","Un síndrome de sobrecarga externa en valgo"],["La forma medial se despierta en flexión y pronación.","El atrapamiento radial se traduce por un dolor a la prensión.","Un dolor del codo en hiperextensión hace evocar un síndrome de sobrecarga externa asociado al valgo."]],
  "143": ["¿Qué hipótesis debe explorar la demostración funcional del codo?",["Las hipótesis neural, de hombro, cervical y de muñeca","Las hipótesis vascular, visceral y metabólica","Las hipótesis torácica, lumbar y pélvica"],["La demostración funcional explora las hipótesis neural, de hombro, cervical y de muñeca.","Esas hipótesis no son las establecidas para el codo.","Esas regiones no forman parte de las hipótesis establecidas."]],
  "144": ["¿Qué lesión evalúa la prueba de estrés en valgo móvil?",["Una afectación del ligamento colateral lateral","Una afectación del ligamento colateral medial","Una afectación del tendón extensor común"],["El ligamento lateral no es la estructura explorada.","La prueba de estrés en valgo móvil evalúa una rotura o una inestabilidad crónica del ligamento colateral medial.","El tendón extensor no es la estructura explorada."]],
  "145": ["¿Cuál es la posición de partida de la prueba de estrés en valgo móvil?",["Hombro en abducción a 90° y codo extendido a 0°","Hombro en rotación interna y codo flexionado a 90°","Hombro en abducción a 90° y codo flexionado a 120°"],["El codo parte en flexión máxima, no en extensión.","Esa posición no es la de la prueba.","El paciente está sentado, con el hombro en abducción a 90° y el codo en flexión máxima, cerca de 120°."]],
  "146": ["¿Qué fuerzas aplica el fisioterapeuta durante la prueba de estrés en valgo móvil?",["Una resistencia en el hombro con un impulso en valgo en el codo","Una tracción axial con un impulso en varo en el codo","Una compresión axial con rotaciones alternas"],["Aplica una resistencia máxima en el hombro manteniendo un impulso en valgo en el codo, y después extiende hasta 30°.","El impulso buscado es un valgo, no un varo.","Esa maniobra no es la de la prueba."]],
  "147": ["¿En qué sector debe aparecer el dolor durante la prueba de estrés en valgo móvil?",["Entre 70 y 30° de flexión","Entre 120 y 70° de flexión","Entre 30 y 0° de flexión"],["Ese sector está más cerca de la extensión que el establecido.","El dolor debe aparecer entre 120 y 70° de flexión del codo.","Ese sector corresponde al final del movimiento de la prueba."]],
  "148": ["¿Qué músculo se toma como diana prioritaria en la epicondilalgia lateral?",["El flexor radial del carpo","El músculo pronador redondo del codo","El extensor radial corto del carpo"],["El flexor radial del carpo es una diana de la forma medial.","El pronador redondo es una diana de la forma medial.","Las dianas laterales comportan el braquiorradial, el extensor común de los dedos, los extensores radiales, el ancóneo y el extensor cubital."]],
  "149": ["¿Cuál de estos músculos es una diana de la epicondilalgia medial?",["El flexor cubital del carpo","El extensor cubital del carpo","El músculo ancóneo del codo"],["Las dianas mediales comportan el pronador redondo, el flexor radial del carpo, los flexores de los dedos y el flexor cubital del carpo.","El extensor cubital del carpo es una diana de la forma lateral.","El ancóneo es una diana de la forma lateral."]],
  "150": ["¿Qué síndrome corresponde a la afectación del nervio radial en el codo?",["El síndrome del músculo pronador redondo","El síndrome de la arcada de Frohse","La compresión del canal retroepitroclear"],["Ese síndrome concierne al nervio mediano.","El nervio radial está implicado en el síndrome de la arcada de Frohse.","Esa compresión concierne al nervio cubital."]],
  "151": ["¿Qué síndrome corresponde a la afectación del nervio mediano en el codo?",["El síndrome de la arcada de Frohse","La compresión del canal retroepitroclear","El síndrome del músculo pronador redondo"],["La arcada de Frohse comprime el nervio radial.","El canal retroepitroclear comprime el nervio cubital.","El nervio mediano está implicado en el síndrome del pronador redondo."]],
  "152": ["¿Dónde se comprime el nervio cubital en el codo?",["En el canal retroepitroclear","Bajo la arcada de Frohse del supinador","Entre los vientres del músculo pronador redondo"],["El nervio cubital se comprime en el canal retroepitroclear.","La arcada de Frohse concierne al nervio radial.","El pronador redondo concierne al nervio mediano."]],
  "153": ["¿Por qué es siempre beneficiosa la movilización del tejido nervioso en el codo?",["Porque sustituye al trabajo manual de los tejidos blandos","Porque los nervios tienen relaciones estrechas con los músculos","Porque restaura por sí sola la fuerza de prensión"],["No sustituye al tratamiento de los tejidos blandos.","Los nervios mantienen relaciones estrechas con las estructuras musculoesqueléticas en todo su trayecto.","La restauración de la fuerza depende del ejercicio."]],
  "154": ["¿Cuál es el objetivo del ejercicio isométrico en el codo?",["La normalización del tono muscular","Las modificaciones estructurales del tendón","La activación muscular en las fases iniciales"],["La normalización del tono depende del ejercicio isocinético.","Las modificaciones tendinosas dependen del excéntrico.","El ejercicio isométrico sirve para la activación muscular en las fases iniciales."]],
  "155": ["¿Cuál es el objetivo del ejercicio isocinético en el codo?",["La normalización del tono muscular","La activación muscular de las fases iniciales","Las modificaciones estructurales del tendón"],["El ejercicio isocinético busca la normalización del tono muscular.","La activación inicial depende del isométrico.","Las modificaciones tendinosas dependen del excéntrico."]],
  "156": ["¿Qué técnica de estiramiento establece el tratamiento del codo?",["El estiramiento balístico repetido","El contraer-relajar, u hold-relax","El estiramiento pasivo prolongado solo"],["El estiramiento balístico no se establece.","El tratamiento establece estiramientos especiales de tipo contraer-relajar.","El estiramiento pasivo aislado no es la técnica citada."]],
  "157": ["¿Cuándo se prefiere el TENS de baja frecuencia en el codo?",["Cuando el tendón está calcificado","Cuando el nervio está comprimido","Cuando el dolor es profundo"],["La calcificación depende de las ondas de choque.","El componente neuropático depende de la neuromodulación.","El TENS se aplica en las fases dolorosas, en baja frecuencia si el dolor es profundo."]],
  "158": ["¿Qué técnica está indicada en caso de dolor persistente sin correlato ecográfico?",["La neuromodulación ecoguiada","Los ultrasonidos terapéuticos pulsados","La electrólisis percutánea ecoguiada"],["La neuromodulación ecoguiada se dirige al componente neuropático o al dolor persistente sin correlato ecográfico.","Los ultrasonidos pulsados buscan la resorción de los microedemas.","La electrólisis estimula la regeneración del tendón."]],
  "159": ["¿Qué zona del tendón extensor común se afecta en la epicondilalgia lateral?",["La inserción osteotendinosa distal","La unión miotendinosa","La vaina sinovial del tendón"],["La inserción distal no es la zona descrita.","La afectación alcanza la unión miotendinosa del tendón extensor común.","La vaina sinovial no es la zona descrita."]],
  "160": ["¿Hacia dónde puede irradiar el dolor de la epicondilalgia?",["Hacia la cara dorsal de la mano solamente","Hacia la región cervical baja solamente","Hacia arriba y hacia abajo del codo"],["La irradiación no se limita a la mano.","La región cervical corresponde a una hipótesis a descartar, no a la irradiación propia.","El dolor puede irradiar tanto en sentido craneal como en sentido caudal."]],
  "161": ["¿Qué se busca durante los movimientos activos y pasivos del codo?",["La amplitud, la calidad y las compensaciones","Únicamente la fuerza máxima contra resistencia","Únicamente la reproducción de un dolor medial"],["Se evalúan la amplitud y la calidad, los síntomas durante y al final del recorrido, y las compensaciones.","La fuerza máxima no es el objeto de esa exploración.","La reproducción del dolor no resume esa exploración."]],
  "162": ["¿Qué músculo del brazo se asocia a los puntos gatillo del dolor epicondíleo?",["El braquial anterior, o brachialis","El braquiorradial, o supinador largo","El tríceps braquial, vientre medial"],["El braquial anterior no figura entre las dianas citadas.","El braquiorradial porta puntos gatillo ligados al dolor del epicóndilo y del antebrazo.","El tríceps braquial no figura entre las dianas citadas."]],
  "163": ["¿Qué tipo de ejercicio produce modificaciones a nivel del tendón?",["El ejercicio isométrico","El ejercicio isocinético","El ejercicio excéntrico"],["El isométrico sirve para la activación muscular de las fases iniciales.","El isocinético sirve para normalizar el tono muscular.","El ejercicio excéntrico produce modificaciones a nivel del tendón."]],
  "164": ["¿Qué dificultad funcional traduce la afectación motora del túnel carpiano?",["La pérdida de precisión de la prensión fina","La pérdida de la fuerza de agarre global","La pérdida del bloqueo de la muñeca en carga"],["La pérdida de precisión de la prensión fina se traduce por una dificultad para abotonar o para sostener objetos pequeños.","La pérdida de fuerza global no es el signo característico.","El bloqueo de la muñeca no es el signo descrito."]],
  "165": ["¿Qué síntoma es el más característico del síndrome del túnel carpiano?",["La rigidez matinal duradera de la muñeca","El despertar nocturno por hormigueo o dolores","La crepitación durante las rotaciones de la muñeca"],["La rigidez matinal duradera no es el síntoma característico.","Los síntomas nocturnos son muy característicos: el paciente se despierta a causa de hormigueo o de dolores.","La crepitación evoca una afectación degenerativa."]],
  "166": ["¿Qué hace positiva la prueba de Phalen?",["Una pérdida de fuerza de la oposición del pulgar","Una crepitación a la movilización del carpo","Parestesias o un dolor del territorio mediano"],["La pérdida de fuerza no es el criterio de esa prueba.","La crepitación no es el criterio de esa prueba.","La prueba es positiva en caso de parestesias, de adormecimiento o de dolor en el territorio del nervio mediano."]],
  "167": ["¿A qué velocidad se aplican los movimientos accesorios en la muñeca?",["Lentamente y de forma rítmica, entre 0,5 y 2 Hz","Rápidamente, a más de 5 Hz","Lentamente y de forma sostenida, sin oscilación"],["Los movimientos accesorios se aplican a velocidad baja y rítmica, entre 0,5 y 2 Hz.","Esa frecuencia es muy superior a la establecida.","El modo lento sostenido caracteriza a las movilizaciones fisiológicas."]],
  "168": ["¿Qué busca una técnica de Mulligan en la muñeca?",["Reducir la rigidez capsular por mantenimiento prolongado","Eliminar un defecto de posición y obtener un cambio inmediato","Modular la nocicepción por oscilaciones de amplitud baja"],["La reducción de la rigidez capsular depende de las movilizaciones fisiológicas.","La técnica de Mulligan elimina el defecto de posición, produce cambios inmediatos sin dolor y reeduca el movimiento funcional.","La modulación por oscilaciones depende de los movimientos accesorios."]],
  "169": ["¿Qué consecuencia conlleva la compresión crónica del nervio mediano?",["Una desmielinización segmentaria pura y reversible","Una retracción fibrosa del retináculo de los flexores","Un edema intraneuronal con disminución del deslizamiento"],["La desmielinización segmentaria no es el mecanismo descrito.","La retracción del retináculo no es el mecanismo descrito.","La compresión crónica conlleva un edema intraneuronal, una mecanosensibilidad aumentada y una disminución del deslizamiento del nervio."]],
  "170": ["¿Qué grado de tracción se utiliza en el tratamiento articular de la rizartrosis?",["El grado III","El grado I","El grado V"],["El tratamiento articular recurre a una decoaptación y una tracción de grado III.","El grado I no corresponde a la intensidad establecida.","El grado V correspondería a una manipulación."]],
  "171": ["¿En qué estadio de Eaton es mejor el pronóstico del tratamiento conservador?",["En los estadios III y IV","En los estadios I y II","En el estadio IV solamente"],["Los estadios III y IV dependen más bien de la cirugía.","El tratamiento conservador mejora el pronóstico en las fases iniciales, es decir los estadios I y II.","El estadio IV es el más desfavorable."]],
  "172": ["¿Cuál es el objetivo del trabajo muscular en la rizartrosis?",["Aumentar la amplitud de la aducción del pulgar","Aumentar la laxitud capsular de la trapeciometacarpiana","Aumentar la estabilidad ligamentaria de la articulación"],["La aducción es precisamente la tendencia deformante a limitar.","El aumento de laxitud sería contraproducente.","El trabajo muscular busca aumentar la estabilidad ligamentaria, mediante la movilidad, el control del movimiento y la fuerza."]],
  "173": ["¿Qué signo indica un estadio avanzado de síndrome del túnel carpiano?",["La atrofia de la eminencia tenar","Las parestesias nocturnas del dedo medio","El dolor irradiado hacia el antebrazo"],["La atrofia de la eminencia tenar indica los casos avanzados, por lesión axonal prolongada del nervio mediano.","Las parestesias nocturnas son el signo más precoz.","La irradiación al antebrazo no traduce un estadio avanzado."]],
  "174": ["¿Cuánto tiempo se mantiene la posición de la prueba de Phalen?",["Treinta segundos","Sesenta segundos","Diez segundos"],["Treinta segundos corresponde a la duración de la prueba de Durkan.","La posición de la prueba de Phalen se mantiene durante 60 segundos.","Esa duración es demasiado breve para esa prueba."]],
  "175": ["¿Cuál es el objetivo de las movilizaciones fisiológicas de la muñeca?",["Producir una analgesia por oscilaciones rítmicas","Eliminar un defecto de posición articular","Restaurar la artrocinemática y las amplitudes funcionales"],["La analgesia por oscilaciones depende de los movimientos accesorios.","La eliminación del defecto de posición depende de Mulligan.","Las movilizaciones fisiológicas restauran la artrocinemática normal y las amplitudes funcionales."]],
  "176": ["¿Qué permite una técnica de deslizamiento neural en el túnel carpiano?",["Desplazar el nervio mediano sin aumentar su tensión","Poner el nervio mediano bajo tensión máxima","Inmovilizar el nervio mediano en el túnel"],["Las técnicas de deslizamiento desplazan el nervio mediano en el interior del túnel sin aumentar su tensión.","La puesta bajo tensión máxima depende de las técnicas de tensión.","La inmovilización no es el objetivo de la técnica."]],
  "177": ["¿Cuándo utilizar técnicas de tensión neural en el túnel carpiano?",["Desde la fase aguda muy irritable","En las fases finales del tratamiento","En presencia de parestesias nocturnas fluctuantes"],["La fase aguda irritable depende del deslizamiento.","Las técnicas de tensión, más agresivas para el nervio, son menos recomendables en caso de síntomas nerviosos pero pueden servir en las fases finales.","La sintomatología fluctuante depende del deslizamiento."]],
  "178": ["¿Cuál es el interés del ejercicio isométrico en el síndrome del túnel carpiano?",["Aumentar el deslizamiento de los tendones flexores","Restaurar la artrocinemática del carpo","Controlar el dolor sin modificar la tensión neural"],["La ganancia de deslizamiento tendinoso depende del excéntrico.","La restauración artrocinemática depende de las movilizaciones.","El ejercicio isométrico permite controlar el dolor y fortalecer el antebrazo sin modificar la tensión neural."]],
  "179": ["¿Qué efecto produce el ejercicio excéntrico en el túnel carpiano?",["Una reducción de la presión en el túnel carpiano","Un aumento de la mecanosensibilidad del nervio","Una disminución de la capacidad de carga de los tendones"],["El excéntrico reduce la presión en el túnel gracias a un mejor control de los flexores, aumenta el deslizamiento tendinoso y procura una analgesia mecánica aguda.","El aumento de la mecanosensibilidad sería un efecto indeseable.","El excéntrico mejora al contrario la capacidad de carga."]],
  "180": ["¿Qué técnica articular conviene a la fase activa con movimiento en la rizartrosis?",["La tracción y la descompresión articular","Las técnicas de Mulligan con movimiento activo","La corrección asistida de la abducción"],["La tracción y la descompresión corresponden a la fase pasiva.","La fase activa con movimiento recurre a Mulligan, para mejorar la movilidad activa sin dolor.","La corrección asistida corresponde a la fase activa."]],
  "181": ["¿Qué hay que evitar en la fase inflamatoria de la rizartrosis?",["El uso de una ortesis nocturna","La educación terapéutica del paciente","Las movilizaciones agresivas"],["La ortesis nocturna forma parte del tratamiento recomendado.","La educación forma parte del enfoque multimodal.","Es importante evitar las movilizaciones agresivas durante las fases inflamatorias."]],
  "182": ["¿Qué efecto produce el deslizamiento del nervio radial en la artrosis de la mano?",["Un efecto hipoalgésico en ambas manos","Un efecto hipoalgésico estrictamente local","Un efecto duradero más allá de varios meses"],["El deslizamiento del nervio radial en la mano sintomática produce efectos hipoalgésicos bilaterales, lo que apunta a un componente central.","El efecto no es estrictamente local, puesto que alcanza la mano opuesta.","Los efectos son sobre todo inmediatos y tienden a desaparecer con el tiempo."]],
  "183": ["¿Qué sugiere el efecto bilateral del deslizamiento neural en la artrosis de la mano?",["Una compresión bilateral del nervio radial","Un componente central de modulación del dolor","Una afectación degenerativa de ambas muñecas"],["No se invoca ninguna compresión bilateral.","El efecto bilateral refuerza la idea de un componente central de modulación del dolor, y no solo periférico.","El efecto obtenido no implica una afectación bilateral."]],
  "184": ["¿Cuál es el interés de la radioterapia a dosis baja en la artrosis de la mano?",["Restaurar de forma duradera el espacio articular pinzado","Sustituir la ortesis nocturna en el trabajador manual","Modular el dolor en el paciente mayor a corto plazo"],["No se atribuye ninguna restauración articular a esa técnica.","No sustituye a la ortesis nocturna.","La radioterapia a dosis baja es útil en los pacientes mayores o no candidatos a un tratamiento farmacológico o quirúrgico, para modular el dolor a corto plazo."]],
  "185": ["¿Cuándo está indicada la cirugía en la rizartrosis?",["En caso de fracaso del conservador o en los estadios avanzados","De entrada, en cuanto se establece el diagnóstico radiológico","Desde la aparición de un dolor nocturno aislado"],["La cirugía solo está indicada en caso de fracaso del tratamiento conservador o en los estadios avanzados III y IV.","La cirugía no se propone de entrada.","El dolor nocturno solo no basta para establecer la indicación."]],
  "186": ["¿Qué territorio sensitivo afecta el síndrome del túnel carpiano?",["El dedo quinto y la mitad cubital del anular","El pulgar, el índice, el dedo medio y la mitad del anular","La cara dorsal de la primera comisura de la mano"],["Ese territorio corresponde al nervio cubital.","La compresión del mediano en el túnel carpiano afecta a la conducción sensitiva del pulgar, del índice, del dedo medio y de la mitad radial del anular.","Ese territorio corresponde al nervio radial."]],
  "187": ["¿Cuál es la progresión típica de los síntomas del túnel carpiano?",["Diurna, después nocturna, después intermitente","Persistente de entrada, después fluctuante","Nocturna, después diurna, después persistente"],["Ese orden es el inverso de la progresión descrita.","Una forma persistente de entrada no es la progresión descrita.","La evolución típica va de los síntomas nocturnos a los síntomas diurnos, y después a una forma persistente."]],
  "188": ["¿Qué ejercicios constituyen la primera línea del tratamiento conservador del túnel carpiano?",["Los ejercicios de deslizamiento tendinoso","Los ejercicios excéntricos de los flexores","Los ejercicios de fortalecimiento máximo de la muñeca"],["Los ejercicios de deslizamiento tendinoso son los ejercicios de primera línea del tratamiento conservador.","El excéntrico completa el programa, no lo abre.","El fortalecimiento máximo no es la primera línea."]],
  "189": ["¿En qué condiciones se utiliza el ejercicio concéntrico en el túnel carpiano?",["En la amplitud completa, en carga máxima","En amplitudes reducidas, sin estrés mecánico del mediano","Únicamente en la fase de tensión neural terminal"],["La carga máxima en amplitud completa no se establece.","El ejercicio concéntrico sirve, en amplitudes reducidas, para fortalecer los flexores sin estrés mecánico del nervio mediano.","La tensión neural terminal no es el marco de ese ejercicio."]],
  "190": ["¿Qué caracteriza al estadio III de la clasificación de Eaton?",["Una afectación de la articulación escafotrapezoidea","Un espacio articular totalmente conservado","Una subluxación del primer metacarpiano sobre el trapecio"],["La afectación escafotrapezoidea define el estadio IV.","El espacio conservado corresponde al estadio I.","El estadio III asocia un estrechamiento marcado y una subluxación de la base del primer metacarpiano sobre el trapecio."]],
  "191": ["¿Qué gesto despierta más el dolor de la rizartrosis?",["El pinzamiento entre el pulgar y los dedos","La flexión mantenida de la muñeca durante un minuto","La extensión resistida de la muñeca en prensión"],["El dolor de la base del pulgar se despierta sobre todo durante los movimientos de pinzamiento, y en tareas como abrir un bote o escribir.","La flexión mantenida es la maniobra de la prueba de Phalen.","La extensión resistida despierta una epicondilalgia lateral."]],
  "192": ["¿Hacia qué posición se deforma el pulgar en la rizartrosis?",["Hacia la abducción y la extensión","Hacia la aducción y la flexión","Hacia la rotación externa y la retropulsión"],["La abducción y la extensión están al contrario limitadas.","El pulgar tiende hacia la aducción y la flexión, con a veces una hiperextensión compensatoria de la metacarpofalángica.","Esa deformidad no es la descrita."]],
  "193": ["¿Qué músculo hay que evaluar prioritariamente para la estabilidad del primer metacarpiano?",["El músculo flexor largo del pulgar","El músculo abductor corto del pulgar","El músculo interóseo del primer dedo"],["El flexor largo depende de las compensaciones a tratar, no de la estabilidad.","El abductor corto no es el músculo designado para esa función.","El músculo interóseo del primer dedo es esencial para evitar la subluxación radial del metacarpiano."]],
  "194": ["¿En qué posición mantiene una ortesis el pulgar en la rizartrosis?",["En abducción con una ligera flexión metacarpofalángica","En aducción con una extensión metacarpofalángica","En oposición completa con la muñeca flexionada"],["Las ortesis mantienen el pulgar en abducción y en ligera flexión de la metacarpofalángica.","Esa posición reproduciría la deformidad a evitar.","Esa posición no es la establecida."]],
  "195": ["¿Cuál de estos ejercicios trabaja la destreza en la rizartrosis?",["Abrir una goma elástica entre el pulgar y el quinto dedo","Trazar líneas con el pulgar y romper papel","Comprimir una pelota de silicona con toda la mano"],["La apertura contra goma elástica es un ejercicio de fuerza y de resistencia.","Los ejercicios de destreza comportan el trazado de líneas con el pulgar, el rasgado de papel y la manipulación de objetos ligeros.","La pelota de silicona es un ejercicio de fuerza."]],
  "196": ["¿Qué músculos debilita la compresión del nervio mediano en el túnel carpiano?",["El aductor del pulgar y los interóseos","El extensor largo y el extensor corto del pulgar","El abductor corto y el oponente del pulgar"],["Esos músculos dependen de la inervación cubital.","Esos músculos dependen de la inervación radial.","La debilidad del pulgar en abducción y en oposición se debe a la afectación del abductor corto y del oponente del pulgar."]],
  "197": ["¿Qué movimientos del pulgar están debilitados en el síndrome del túnel carpiano?",["La abducción y la oposición","La aducción y la flexión","La extensión y la retropulsión"],["La debilidad del pulgar afecta en particular a la abducción y a la oposición.","La aducción y la flexión no son los movimientos deficitarios descritos.","La extensión depende del nervio radial."]],
  "198": ["¿Cuál es el modo de inicio del síndrome del túnel carpiano?",["Brusco, después de un traumatismo de la muñeca","Insidioso, sin lesión inicial identificable","Progresivo, después de una inmovilización con yeso"],["El traumatismo inicial no se encuentra en ese cuadro.","El inicio es insidioso: el paciente no presenta ninguna lesión inicial identificable.","La inmovilización con yeso no es el punto de partida descrito."]],
  "199": ["¿Entre qué estructuras se percute en el signo de Tinel en la muñeca?",["Entre la eminencia tenar y la eminencia hipotenar","Entre el trapecio y la base del primer metacarpiano","Entre el palmar largo y el flexor radial del carpo"],["Ese punto de referencia es el de la prueba de compresión de Durkan.","Ese punto de referencia corresponde a la articulación trapeciometacarpiana.","El examinador percute suavemente el túnel carpiano, entre el palmar largo y el flexor radial del carpo."]],
  "200": ["¿Dónde se colocan los pulgares en la prueba de compresión de Durkan?",["Entre la eminencia tenar y la eminencia hipotenar","Entre el palmar largo y el flexor radial del carpo","Sobre la cara dorsal de la primera comisura"],["Los pulgares se colocan sobre el túnel carpiano, entre la eminencia tenar y la eminencia hipotenar.","Ese punto de referencia es el del signo de Tinel.","Ese punto de referencia no corresponde al túnel carpiano."]],
  "201": ["¿Cuál es el elemento clave del tratamiento nocturno del síndrome del túnel carpiano?",["La aplicación nocturna de ondas de choque","El uso de una ortesis de noche","La contención elástica nocturna del codo"],["Las ondas de choque no forman parte del tratamiento nocturno.","Los elementos clave del tratamiento comportan la amplitud de la muñeca, la movilización nerviosa, el hombro y el cuello, el ejercicio y la ortesis de noche.","La contención del codo no es la opción establecida."]],
  "202": ["¿Qué articulación contribuye principalmente a la flexión palmar de la muñeca?",["La articulación radiocarpiana, en cerca del 60 %","La articulación carpometacarpiana, en cerca del 60 %","Las articulaciones mediocarpianas, en cerca del 60 %"],["La radiocarpiana solo asegura cerca del 40 % de la flexión palmar.","La carpometacarpiana no interviene en esa distribución.","Las mediocarpianas aseguran la contribución principal a la flexión palmar, cerca del 60 % del total."]],
  "203": ["¿Qué músculo porta más a menudo puntos gatillo en el síndrome del túnel carpiano?",["El trapecio superior","El músculo subescapular","El músculo pectoral mayor"],["Una gran mayoría de los pacientes presenta puntos gatillo activos en el trapecio superior.","El subescapular no es el músculo designado aquí.","El pectoral mayor no es el músculo designado aquí."]],
  "204": ["¿Qué músculos del antebrazo portan puntos gatillo en el túnel carpiano leve a moderado?",["El flexor cubital del carpo y el ancóneo","El extensor radial del carpo y el braquiorradial","El pronador redondo y el supinador largo"],["Esos músculos no son los designados.","Los puntos gatillo del antebrazo asientan sobre todo en el extensor radial del carpo y el braquiorradial.","El pronador redondo no se designa para esa localización."]],
  "205": ["¿Qué papel podrían desempeñar los puntos gatillo tenares en el túnel carpiano?",["Bloquear la conducción motora del nervio cubital","Impedir el deslizamiento de los tendones extensores","Provocar un estrechamiento del túnel carpiano"],["El nervio cubital no está implicado en esa hipótesis.","Los tendones extensores no están implicados en esa hipótesis.","Los puntos gatillo de los músculos tenares podrían ser una causa de estrechamiento del túnel carpiano."]],
  "206": ["¿Sobre qué nervio se aplica la neuromodulación ecoguiada en la muñeca?",["El nervio mediano","El nervio cubital","El nervio radial superficial"],["En la muñeca, la neuromodulación ecoguiada se aplica generalmente sobre el nervio mediano.","El nervio cubital no es la diana establecida en la muñeca.","El nervio radial superficial no es la diana establecida."]],
  "207": ["¿Cuál es la artrosis más frecuente de la mano?",["La artrosis de las interfalángicas distales","La rizartrosis, en la base del pulgar","La artrosis de las interfalángicas proximales"],["La artrosis interfalángica distal es muy frecuente en la imagen, pero la rizartrosis se establece como la más frecuente.","La rizartrosis se considera la artrosis más frecuente de la mano.","La artrosis interfalángica proximal es menos frecuente."]],
  "208": ["¿Qué movimientos del pulgar están rígidos en la rizartrosis?",["La aducción y la flexión","La oposición y la retropulsión","La abducción y la extensión"],["La aducción y la flexión corresponden a la tendencia deformante, no a la rigidez.","Esos movimientos no son los descritos como rígidos.","La rigidez afecta en particular a la abducción y a la extensión del pulgar."]],
  "209": ["¿Cuál es la prueba más sensible y más específica de la articulación trapeciometacarpiana?",["La prueba de Lever","La prueba de Grind","La prueba de compresión de Durkan"],["La prueba de Lever, mediante movimientos radiales y cubitales, es la prueba más sensible y más específica de la trapeciometacarpiana.","La prueba de Grind es útil pero menos eficaz que la prueba de Lever.","La prueba de Durkan explora el túnel carpiano."]],
  "210": ["¿Qué subluxación previene el músculo interóseo del primer dedo?",["La subluxación palmar del trapecio","La subluxación radial del primer metacarpiano","La subluxación dorsal del escafoides del carpo"],["El trapecio no es la estructura implicada.","El interóseo del primer dedo previene la subluxación radial del metacarpiano.","El escafoides no es la estructura implicada."]],
  "211": ["¿Qué músculos toma como diana prioritaria el tratamiento manual de la rizartrosis?",["El abductor corto, el extensor corto y el extensor largo","Los interóseos dorsales y los lumbricales de la mano","El aductor, el flexor largo y el oponente del pulgar"],["Los abductores y extensores del pulgar no son las dianas designadas.","Los interóseos dorsales y los lumbricales no son las dianas designadas.","El tratamiento manual del aductor del pulgar, del flexor largo del pulgar y del oponente del pulgar es determinante."]],
  "212": ["¿Qué comporta el enfoque multimodal conservador de la rizartrosis?",["Ortesis nocturna, ejercicio, terapia manual y educación","Ondas de choque, ultrasonidos pulsados y estiramientos","Inmovilización estricta, analgésicos y reposo completo"],["El enfoque multimodal asocia ortesis nocturna, ejercicio, terapia manual y educación.","Esa asociación no es la descrita.","La inmovilización estricta con reposo completo no es el enfoque establecido."]],
  "213": ["¿Qué déficit de control motor se observa en la rizartrosis?",["La incapacidad de flexionar completamente las interfalángicas","La incapacidad de mantener la apertura de la primera comisura","La incapacidad de extender la muñeca contra resistencia"],["La flexión de las interfalángicas no es el déficit descrito.","El déficit se traduce por un desplome articular durante el pinzamiento y una incapacidad de mantener la apertura de la primera comisura.","La extensión de la muñeca no es el déficit descrito."]],
  "214": ["¿Qué consecuencia tiene la rigidez costal en el síndrome de la salida torácica?",["Suprime el paso del plexo braquial","Conlleva una trombosis venosa de esfuerzo","Altera la adaptación dinámica del tórax"],["No se describe ninguna supresión del paso.","La trombosis de esfuerzo depende de la forma venosa.","La rigidez costal o el descenso de la movilidad torácica altera la adaptación dinámica del tórax durante la respiración y la elevación del brazo."]],
  "215": ["¿Por qué se evita la neurodinámica en caso de compresión estructural fija?",["Porque corre el riesgo de agravar los síntomas","Porque puede alterar el flujo vascular","Porque conlleva una hiperalgesia periférica"],["Ante una compresión estructural fija, como una costilla cervical o una fibrosis, la neurodinámica corre el riesgo de agravar los síntomas.","La alteración del flujo vascular concierne a la forma vascular.","La hiperalgesia marcada impone una precaución, no una exclusión."]],
  "216": ["¿Qué técnica eléctrica conviene a una sensibilización central leve?",["La neuromodulación percutánea ecoguiada","La estimulación a alta frecuencia de tipo burst","La magnetoterapia superinductiva profunda"],["La neuromodulación ecoguiada se dirige a las parestesias bien delimitadas.","La estimulación transcutánea a alta frecuencia de tipo burst mejora el umbral de dolor y modula las respuestas centrales.","La magnetoterapia no es la técnica designada para esa indicación."]],
  "217": ["¿Qué muestra la exploración ecográfica de un nervio afectado en un estadio avanzado?",["Una atrofia de los músculos inervados por ese nervio","Una reducción de la velocidad de conducción nerviosa","Un engrosamiento con pérdida del patrón interno"],["La atrofia muscular se confirma con una exploración por resonancia magnética.","La conducción nerviosa se explora con el electromiograma.","En un estadio avanzado se observa un engrosamiento del nervio y una pérdida de su patrón interno."]],
  "218": ["¿Qué consecuencia tiene una protracción escapular sobre el plexo braquial?",["Una tracción continua del plexo y de los vasos","Una compresión intermitente de las raíces C8 y T1","Una fibrosis progresiva del pectoral menor"],["La protracción escapular o los hombros caídos ejercen una tracción continua del plexo braquial y de los vasos.","La compresión radicular no es el mecanismo descrito.","No se describe ninguna fibrosis del pectoral menor."]],
  "219": ["¿Por qué esperar unos segundos antes de interpretar la prueba de Wright?",["Porque las parestesias tardan en aparecer","Porque el pulso puede desaparecer por el solo hecho del movimiento","Porque la rotación externa debe ser progresiva"],["El plazo no se justifica por la latencia de las parestesias.","Se esperan unos segundos porque el pulso puede desaparecer a causa del movimiento de elevación del brazo.","La progresividad del movimiento no es la razón planteada."]],
  "220": ["¿Cuánto tiempo debe abrir y cerrar las manos el paciente en la prueba de Roos?",["Sesenta segundos","Treinta segundos","Tres minutos"],["Sesenta segundos corresponde a la prueba de Phalen.","Treinta segundos corresponde a la prueba de Durkan.","El paciente abre y cierra las manos repetidamente durante 3 minutos."]],
  "221": ["¿Está indicada la neurodinámica en un síndrome de la salida torácica leve?",["Sí, mediante deslizamientos suaves sin parestesias persistentes","Sí, pero únicamente mediante técnicas de tensión","No, siempre corre el riesgo de agravar los síntomas"],["En un síndrome leve o moderado, la neurodinámica está indicada en forma de deslizamientos suaves, sin provocar parestesias persistentes.","Las técnicas de tensión no son las recomendadas aquí.","El riesgo de agravamiento concierne a la compresión estructural fija."]],
  "222": ["¿En qué caso está formalmente contraindicada la neurodinámica en la salida torácica?",["En la forma aparecida después de un traumatismo cervical","En la forma vascular, arterial o venosa","En la forma leve acompañada de parestesias"],["La forma postraumática depende al contrario de la neurodinámica asociada al trabajo postural.","La neurodinámica está contraindicada en el síndrome de la salida torácica vascular, porque puede alterar el flujo vascular.","La forma leve es una indicación, con deslizamientos suaves."]],
  "223": ["¿Qué conducta mantener ante una hiperalgesia periférica marcada en la salida torácica?",["Renunciar definitivamente a toda neurodinámica","Comenzar de entrada por técnicas de tensión","Progresar muy progresivamente, o de forma indirecta"],["La renuncia concierne a la compresión estructural fija.","La tensión de entrada no está indicada en esa situación.","Ante un dolor intenso o una hiperalgesia marcada, la progresión debe ser muy progresiva o indirecta."]],
  "224": ["¿Cuándo está indicado el TENS en el síndrome de la salida torácica?",["En las fases muy agudas, sobre la zona de parestesia","En las fases subagudas, sobre una zona delimitada","En las fases crónicas, antes de la movilización"],["El TENS es útil en las fases muy agudas, colocado principalmente sobre la zona de parestesia más marcada.","Las fases subagudas con zona delimitada dependen de la neuromodulación ecoguiada.","La preparación para la movilización depende de la diatermia."]],
  "225": ["¿Por qué asociar la diatermia a las técnicas neurodinámicas?",["Porque modula directamente la conducción nerviosa","Porque reduce la rigidez y facilita la movilización","Porque sustituye al trabajo postural y respiratorio"],["No se describe ninguna acción directa sobre la conducción.","La diatermia mejora la circulación, reduce la rigidez y facilita la movilización: es muy eficaz asociada a las técnicas neurodinámicas.","No sustituye al trabajo postural y respiratorio."]],
  "226": ["¿Cuándo está indicada la neuromodulación ecoguiada en la salida torácica?",["En las fases muy agudas muy dolorosas","Antes de toda sesión de movilización articular","En las fases subagudas, ante parestesias delimitadas"],["Las fases muy agudas dependen del TENS.","No está concebida como una preparación sistemática.","La neuromodulación ecoguiada está particularmente indicada en las fases subagudas, en especial ante parestesias en una zona bien delimitada."]],
  "227": ["¿A qué nivel se sitúa la compresión del síndrome de la arcada de Frohse?",["A nivel del músculo supinador","A nivel del dorso de la muñeca","A nivel del canal retroepitroclear"],["La compresión asienta a nivel del músculo supinador del antebrazo.","El dorso de la muñeca corresponde al síndrome de Wartenberg.","Ese canal corresponde a la afectación cubital del codo."]],
  "228": ["¿Qué ocurre con la longitud del nervio durante un deslizamiento por los dos extremos?",["Está aumentada de forma controlada","No se modifica por el movimiento","Se modifica por el extremo distal"],["El aumento de longitud caracteriza a las técnicas de tensión.","Durante el deslizamiento por los dos extremos, la longitud de la estructura nerviosa no se modifica: origen e inserción acompañan al movimiento.","La modificación por el extremo distal caracteriza al deslizamiento por un extremo."]],
  "229": ["¿Cuál de estos signos evoca una forma venosa de síndrome de la salida torácica?",["Una palidez con disminución de los pulsos distales","Una debilidad de los músculos intrínsecos de la mano","Una cianosis con dilatación venosa superficial"],["La palidez y el descenso de los pulsos caracterizan a la forma arterial.","La debilidad intrínseca caracteriza a la forma neurógena.","La forma venosa comporta edema, cianosis, sensación de congestión del brazo y dilatación venosa superficial."]],
  "230": ["¿Qué variación ósea favorece el síndrome de la salida torácica?",["Una costilla cervical, o una apófisis de C7 alargada","Un gancho del ganchoso mal consolidado tras una fractura","Un valgo constitucional marcado del codo"],["Los factores anatómicos comportan una costilla cervical o una apófisis transversa alargada de C7.","Esa anomalía favorece la afectación del canal de Guyon.","El valgo del codo favorece la afectación del canal cubital."]],
  "231": ["¿Qué se pide al paciente en la prueba de Adson?",["Descender los hombros y sacar el pecho","Girar la cabeza del lado explorado e inspirar","Abrir y cerrar las manos repetidamente"],["Esa indicación pertenece a la prueba de Eden.","El paciente gira la cabeza hacia el lado explorado, estira el cuello e inspira profundamente manteniendo la posición.","Esa indicación pertenece a la prueba de Roos."]],
  "232": ["¿Qué espacio evalúa la prueba de Wright?",["El triángulo formado por los dos escalenos","El desfiladero situado entre clavícula y primera costilla","El espacio subcoracoideo, bajo el pectoral menor"],["Ese triángulo se evalúa con la prueba de Adson.","Ese desfiladero se evalúa con la prueba de Eden.","La prueba de Wright, o prueba del pectoral menor, evalúa el espacio subcoracoideo."]],
  "233": ["¿Cuál es la particularidad de la prueba de Roos?",["Es la más sensible, pero no la más específica","Es la más específica, pero poco sensible","Es a la vez la más sensible y la más específica"],["La prueba de Roos es la más sensible de las pruebas de la salida torácica, pero no la más específica.","Su especificidad no es su cualidad principal.","No es la más específica."]],
  "234": ["¿Dónde se sitúa el último punto de tensión en el síndrome de la arcada de Frohse?",["En la muñeca","En el codo","En el hombro"],["La muñeca es el último punto de tensión del síndrome de Wartenberg.","En el síndrome de la arcada de Frohse, el último punto de tensión es el codo.","El hombro no es el último punto de tensión descrito."]],
  "235": ["¿En qué localización se propone la electrólisis para el nervio radial?",["En el canal de Guyon","En el túnel carpiano","En la arcada de Frohse"],["El canal de Guyon concierne al nervio cubital.","El túnel carpiano concierne al nervio mediano.","La electrólisis se propone a nivel de la arcada de Frohse."]],
  "236": ["¿A qué afección del codo se vincula el síndrome del pronador redondo?",["A la epicondilopatía medial","A la epicondilopatía lateral","A la inestabilidad rotatoria del codo"],["El síndrome del pronador redondo se vincula a la epicondilopatía medial del codo.","La epicondilopatía lateral se vincula al síndrome de la arcada de Frohse.","La inestabilidad rotatoria no es la afección asociada."]],
  "237": ["¿Qué patología general se asocia al síndrome del túnel carpiano?",["El asma bronquial","El hipotiroidismo","La anemia falciforme hereditaria"],["El asma se cita en el marco de la salida torácica.","Las patologías asociadas comportan la diabetes, la obesidad, el hipotiroidismo y la artritis reumatoide.","La anemia falciforme no se cita para esa afección."]],
  "238": ["¿Dónde se sitúa el último punto de tensión en el síndrome del túnel carpiano?",["En el codo","En el hombro","En la muñeca"],["El codo es el último punto de tensión del síndrome del pronador redondo.","El hombro no es el último punto de tensión descrito.","En el síndrome del túnel carpiano, el último punto de tensión es la muñeca."]],
  "239": ["¿Cuál de estos espacios concierne al síndrome de la salida torácica?",["El espacio costoclavicular","El espacio retroepitroclear","El espacio de la arcada del supinador"],["Los tres espacios implicados son el triángulo interescalénico, el espacio costoclavicular y el espacio subcoracoideo.","Ese espacio concierne a la neuropatía cubital del codo.","Ese espacio concierne a la neuropatía radial."]],
  "240": ["¿En qué territorio asientan las parestesias del síndrome de la salida torácica neurógeno?",["En la cara dorsal y radial de la mano","En la cara medial del antebrazo y de la mano","En los tres primeros dedos de la mano"],["Ese territorio corresponde a la rama sensitiva del nervio radial.","Las parestesias asientan en la cara medial del antebrazo y de la mano, es decir el territorio cubital.","Ese territorio corresponde al nervio mediano."]],
  "241": ["¿Cuándo aparece la sensación de pesadez en el síndrome de la salida torácica?",["Cuando el codo permanece flexionado mucho tiempo","Cuando la muñeca está flexionada mucho tiempo","Cuando el brazo está levantado"],["La flexión prolongada del codo evoca una afectación cubital.","La flexión prolongada de la muñeca evoca un túnel carpiano.","La sensación de pesadez o de fatiga aparece cuando el brazo está levantado."]],
  "242": ["¿Cuál de estos signos evoca una forma arterial de síndrome de la salida torácica?",["Una mano fría y pálida con pulsos distales disminuidos","Un edema del brazo con sensación de congestión","Parestesias del borde medial del antebrazo"],["La forma arterial asocia frialdad, palidez, disminución de los pulsos distales, claudicación y dolor isquémico.","El edema y la congestión caracterizan a la forma venosa.","Las parestesias mediales caracterizan a la forma neurógena."]],
  "243": ["¿Qué trastorno postural estrecha el espacio costoclavicular?",["Una hiperlordosis lumbar marcada","Una cifosis torácica acentuada","Una inclinación cervical permanente"],["La lordosis lumbar no actúa sobre ese espacio.","La cifosis torácica acentuada desplaza la cintura escapular hacia delante y hacia abajo, estrechando el espacio costoclavicular.","La inclinación cervical no es el factor descrito."]],
  "244": ["¿Cómo se realiza la prueba de Roos?",["Brazos extendidos a lo largo del cuerpo, cabeza girada del lado explorado","Brazo en abducción pasiva con rotación externa máxima","Brazos a 90° de abducción y rotación externa, codos flexionados a 90°"],["Esa posición pertenece a la prueba de Adson.","Esa posición pertenece a la prueba de Wright.","El paciente levanta ambos brazos a 90° en abducción y rotación externa, codos flexionados a 90°, y abre y cierra las manos durante 3 minutos."]],
  "245": ["¿Qué grados de movilización cervical utilizar en fase aguda de salida torácica?",["Los grados I o II","Los grados III o IV","El grado V manipulativo"],["Las presiones central y unilateral de las cervicales y de las torácicas se hacen en grados I o II en los procesos agudos.","Los grados altos no convienen a la fase aguda.","La manipulación no se establece en ese protocolo."]],
  "246": ["¿Qué porción del bíceps braquial se toma como diana en la salida torácica?",["La porción larga","La porción corta","Las dos porciones indistintamente"],["La porción larga no es la diana designada.","La porción corta del bíceps braquial forma parte de las dianas, debido a su inserción coracoidea.","El curso designa específicamente la porción corta."]],
  "247": ["¿Qué puntos clave establece el ejercicio en el síndrome de la salida torácica?",["Únicamente la fuerza máxima de los músculos escalenos","Únicamente la flexibilidad de los flexores de la muñeca","El control cervical y la dinámica respiratoria"],["Fortalecer los escalenos al máximo sería contraproducente.","Los flexores de la muñeca no son la diana de ese programa.","El entrenamiento busca el control cervical, la normalización de la dinámica respiratoria, la movilidad neural y la estabilización torácica."]],
  "248": ["¿Dónde asienta la compresión del síndrome de Wartenberg?",["En el dorso del antebrazo o de la muñeca","En el espesor del músculo supinador","Entre las dos cabezas del pronador redondo"],["La compresión asienta generalmente a nivel del dorso del antebrazo o de la muñeca.","El músculo supinador corresponde a la arcada de Frohse.","El pronador redondo corresponde a la afectación del nervio mediano."]],
  "249": ["¿Qué articulación se moviliza en la neuropatía del nervio radial?",["La articulación cubitohumeral","La articulación radiohumeral","La articulación humeroulnar"],["La cubitohumeral se moviliza en la afectación del nervio mediano.","Las movilizaciones anteroposteriores y posteroanteriores radiohumerales se hacen en grados I-II en las fases agudas, III-IV después.","La humeroulnar se moviliza en la afectación del nervio cubital."]],
  "250": ["¿Cuál de estos músculos se toma como diana en la neuropatía del nervio radial?",["El músculo pronador redondo","El músculo palmar corto","El músculo supinador"],["El pronador redondo es una diana de la afectación mediana.","El palmar corto es una diana de la afectación cubital.","Las dianas comportan el braquiorradial, el supinador y los extensores radiales corto y largo."]],
  "251": ["¿Qué músculo se trabaja en isometría en la neuropatía del nervio radial?",["El músculo supinador","El músculo pronador redondo","El músculo flexor cubital del carpo"],["El ejercicio terapéutico comporta contracciones isométricas del músculo supinador.","El pronador redondo no es el músculo trabajado aquí.","Ese músculo no es el trabajado aquí."]],
  "252": ["¿Dónde asienta el dolor del síndrome del pronador redondo?",["En la cara dorsal del antebrazo distal","En la cara anteromedial del antebrazo proximal","En la cara medial del brazo y de la axila"],["Esa topografía evoca una afectación radial.","El dolor es anteromedial, en el antebrazo proximal, e irradia hacia la muñeca o la eminencia tenar.","Esa topografía evoca una afectación de la salida torácica."]],
  "253": ["¿Qué movimientos agravan el síndrome del pronador redondo?",["La supinación resistida y la extensión del codo","La flexión de la muñeca mantenida un minuto","La pronación resistida y la flexión del codo"],["Esa combinación no es la que agrava ese síndrome.","La flexión mantenida de la muñeca es la maniobra de la prueba de Phalen.","El dolor se agrava con la pronación resistida y la flexión del codo."]],
  "254": ["¿Cuál de estos factores se asocia al síndrome del túnel carpiano?",["Las vibraciones transmitidas a la mano","El apoyo prolongado sobre la cara medial del codo","La elevación prolongada de ambos brazos por encima de la cabeza"],["Los factores comportan los movimientos repetitivos de la muñeca, las posturas forzadas y las vibraciones.","El apoyo sobre el codo expone a la afectación cubital.","La elevación prolongada expone a la salida torácica."]],
  "255": ["¿Qué posición del hombro comporta la prueba neurodinámica del nervio mediano?",["Una abducción a 10° con rotación interna","Una abducción a 90° con rotación externa","Una aducción completa a lo largo del cuerpo"],["Esa posición pertenece a la prueba del nervio radial.","La prueba del nervio mediano asocia una abducción de hombro a 90° y una rotación externa, con supinación del antebrazo.","Esa posición no es la de la prueba."]],
  "256": ["¿Qué movimiento termina la prueba neurodinámica del nervio mediano?",["Una abducción lenta del hombro","Una pronación lenta del antebrazo","Una extensión lenta del codo"],["La abducción lenta del hombro termina la prueba del nervio radial.","La pronación pertenece a las pruebas radial y cubital.","La prueba termina con una extensión lenta del codo, seguida de la maniobra de diferenciación estructural."]],
  "257": ["¿Qué articulación se moviliza en la neuropatía del nervio mediano?",["La articulación cubitohumeral","La articulación radiohumeral","La articulación esternoclavicular"],["Las movilizaciones anteroposteriores cubitohumerales se hacen en grados I-II en las fases agudas, III-IV después.","La radiohumeral se moviliza en la afectación radial.","La esternoclavicular se moviliza en la salida torácica."]],
  "258": ["¿Cuál de estos músculos se toma como diana en la neuropatía del nervio mediano?",["El músculo braquiorradial","El músculo pronador redondo","El músculo palmar corto"],["El braquiorradial es una diana de la afectación radial.","Las dianas comportan el pronador redondo, los flexores de los dedos, el flexor radial y los músculos intrínsecos de la mano.","El palmar corto es una diana de la afectación cubital."]],
  "259": ["¿Qué músculos debilita la afectación del canal de Guyon?",["El abductor corto y el oponente del pulgar","El supinador y los extensores radiales del carpo","Los interóseos, el aductor del pulgar y los hipotenares"],["Esos músculos dependen de la afectación mediana.","Esos músculos dependen de la afectación radial.","La afectación debilita los músculos interóseos, el aductor del pulgar y los músculos hipotenares."]],
  "260": ["¿Qué deformidad provoca la afectación avanzada del canal de Guyon?",["Una mano en garra del cuarto y quinto dedos","Una atrofia aislada de la eminencia tenar","Una mano caída en flexión de la muñeca"],["Se puede observar una mano en garra del cuarto y quinto dedos.","La atrofia tenar depende de la afectación mediana.","La mano caída depende de una afectación radial alta."]],
  "261": ["¿Qué posición del antebrazo comporta la prueba neurodinámica del nervio cubital?",["Una supinación del antebrazo","Una pronación del antebrazo","Una posición neutra del antebrazo"],["La supinación pertenece a la prueba del nervio mediano.","La prueba del nervio cubital comporta una pronación del antebrazo, tras la rotación externa del hombro y la flexión del codo.","La posición neutra no es la de la prueba."]],
  "262": ["¿Dónde se sitúa el último punto de tensión en la afectación del canal de Guyon?",["En el codo","En el antebrazo proximal","En la muñeca"],["El codo es el último punto de tensión del síndrome del canal cubital.","El antebrazo proximal no es el punto descrito.","En el síndrome del canal de Guyon, el último punto de tensión es la muñeca."]],
  "263": ["¿Qué articulación se moviliza en la neuropatía del nervio cubital?",["La articulación humeroulnar","La articulación radiohumeral","La articulación radioulnar distal"],["Las presiones posteroanteriores humeroulnares y las transversales ulnares se hacen en grados I-II en las fases agudas, III-IV después.","La radiohumeral se moviliza en la afectación radial.","La radioulnar distal se moviliza en la afectación mediana."]],
  "264": ["¿A qué fase se reservan las movilizaciones en fin de recorrido?",["A la fase inicial muy dolorosa","A la última fase de recuperación","A la fase intermedia de reanudación del apoyo"],["La fase inicial depende de los grados bajos.","Esas técnicas agresivas pueden irritar la articulación: se reservan a la última fase de recuperación.","La fase intermedia no es la establecida."]],
  "265": ["¿Qué tratamiento del síndrome trocantéreo da los mejores resultados a corto plazo?",["Las ondas de choque radiales o focales","El entrenamiento domiciliario mediante ejercicio","La inyección de corticosteroides"],["Las ondas de choque se muestran superiores a medio plazo.","El ejercicio domiciliario se muestra superior a largo plazo.","A corto plazo, la inyección de corticosteroides da mejores resultados que el ejercicio domiciliario y las ondas de choque."]],
  "266": ["¿Qué valor de ángulo alfa define un conflicto de tipo cam?",["Un ángulo superior a 55 o 60°","Un ángulo superior a 40°","Un ángulo superior a 83°"],["El tipo cam corresponde a un ángulo alfa superior a 55-60°.","Cuarenta grados corresponde al umbral del ángulo de cobertura lateral.","Ochenta y tres grados corresponde al signo de Trendelenburg."]],
  "267": ["¿Qué ejercicios se privilegian primero en la necrosis avascular de la cadera?",["Las sentadillas progresivas en cadena cerrada","Los isométricos en cadena cinética abierta","Los saltos amortiguados sobre superficie blanda"],["La cadena cerrada debe evitarse en un primer momento.","Se privilegia la cadena cinética abierta, con isométricos del glúteo medio y de los cuádriceps.","El impacto debe evitarse formalmente."]],
  "268": ["¿Qué técnica neurodinámica conviene a los pacientes más afectados?",["El deslizamiento por un extremo","La técnica de tensión neural","El deslizamiento por dos extremos"],["El deslizamiento por un extremo conviene a las fases intermedias.","La técnica de tensión es la más exigente para el nervio.","El deslizamiento por dos extremos es la técnica menos agresiva y más segura, utilizada en los pacientes más afectados."]],
  "269": ["¿Qué posición hay que evitar en el conflicto femoroacetabular?",["Sentarse con las piernas cruzadas","Tumbarse sobre el lado afectado","Caminar con un bastón del lado opuesto"],["Hay que evitar sentarse con las piernas cruzadas, es decir flexión, aducción y rotación interna.","Esa posición es penosa en la tendinopatía glútea.","El bastón es un medio de descarga, no una posición a evitar."]],
  "270": ["¿Cuál es el objetivo del tratamiento articular en la necrosis avascular de la cadera?",["Comprimir la articulación para estimular el cartílago","Descomprimir mecánicamente para favorecer la perfusión restante","Aumentar la presión intraósea para consolidar"],["La compresión está al contrario contraindicada.","El objetivo es descomprimir mecánicamente la articulación a fin de favorecer la escasa perfusión restante.","El aumento de presión es el problema, no el objetivo."]],
  "271": ["¿Qué técnica está contraindicada en la necrosis avascular de la cadera?",["Las tracciones axiales suaves","Las movilizaciones pasivas","Las técnicas de alto impacto"],["Las tracciones suaves están al contrario recomendadas.","Las movilizaciones pasivas forman parte del tratamiento.","Las compresiones y las técnicas de alto impacto están contraindicadas."]],
  "272": ["¿Por qué tratar el psoas ilíaco en la necrosis avascular de la cadera?",["Porque su tensión aumenta la compresión anterior de la cápsula","Porque asegura la estabilidad lateral de la pelvis","Porque irriga la cabeza femoral por sus ramas"],["La tensión del psoas aumenta la compresión anterior de la cápsula: la terapia miofascial se concentra en él, el recto anterior y los aductores.","La estabilidad lateral la aseguran los abductores.","El psoas no tiene ningún papel vascular sobre la cabeza femoral."]],
  "273": ["¿Qué estructura hay que preservar durante el tratamiento manual de la cadera necrótica?",["El labrum acetabular anterior","El paquete vasculonervioso","La cintilla iliotibial lateral"],["El labrum no es la estructura objeto de esa precaución.","Hay que ser prudente con las maniobras que podrían comprometer el paquete vasculonervioso.","La cintilla iliotibial no es la estructura objeto de esa precaución."]],
  "274": ["¿Por qué es la prueba HEC la más fiable para la tendinopatía del psoas ilíaco?",["Porque aísla únicamente la función de flexión","Porque se realiza sin resistencia manual","Porque combina las dos funciones del músculo"],["El aislamiento de una sola función sería menos fiable.","La ausencia de resistencia no es el argumento establecido.","La prueba HEC combina las dos funciones del músculo, lo que aumenta su fiabilidad."]],
  "275": ["¿Qué técnica está en la base del tratamiento del dolor miofascial?",["La liberación miofascial","La punción seca de los puntos gatillo","La corriente interferencial analgésica"],["La liberación miofascial está en la base del tratamiento del dolor miofascial, en todos los estadios, y particularmente en los primeros.","La punción seca es una opción, pero no la base del tratamiento.","La corriente interferencial solo se utiliza como complemento."]],
  "276": ["¿En qué estadio es particularmente pertinente la liberación miofascial?",["En los estadios más crónicos solamente","En los primeros estadios de la evolución","Después del fracaso de todo enfoque conservador"],["Se aplica a todos los estadios, pero su interés es sobre todo precoz.","La liberación miofascial es particularmente pertinente en los primeros estadios de la evolución.","No se reserva a los fracasos."]],
  "277": ["¿Qué precaución tomar para prescribir el ejercicio en un síndrome miofascial?",["Comenzar de entrada por un trabajo de fuerza máxima","Esperar la desaparición total de todo punto gatillo","Evaluar al paciente antes de personalizar la prescripción"],["El trabajo de fuerza llega después de la disminución del dolor.","No se exige una desaparición total previa.","El ejercicio debe prescribirse con precaución: hay que evaluar al paciente antes, para personalizar el tratamiento y evitar toda lesión posterior."]],
  "278": ["¿Qué traduce una prueba de Ober positiva?",["Una tensión de la cintilla iliotibial","Una debilidad de los músculos abductores","Una retracción del músculo iliopsoas"],["Una prueba de Ober positiva indica una tensión de la cintilla iliotibial.","La debilidad de los abductores se explora con la abducción resistida.","La retracción del iliopsoas se explora con la prueba de Thomas."]],
  "279": ["¿Qué movimiento está más reducido en la necrosis avascular de la cabeza femoral?",["La abducción resistida de cadera","La rotación interna forzada","La extensión pasiva de cadera"],["La abducción resistida explora una tendinopatía glútea.","La amplitud está reducida, en particular durante la rotación interna forzada.","La extensión pasiva pertenece a la maniobra de aprehensión."]],
  "280": ["¿Qué movimientos deben preservar las movilizaciones pasivas en la necrosis avascular de la cadera?",["La aducción y la rotación externa","La extensión y la flexión de cadera","La abducción y la rotación interna"],["Esos movimientos no son los que hay que preservar prioritariamente.","La flexión y la extensión no son los primeros movimientos perdidos.","Las movilizaciones pasivas se centran en el mantenimiento de la abducción y de la rotación interna, primeros movimientos perdidos."]],
  "281": ["¿Qué músculos presentan una hipertonía defensiva en la necrosis avascular de la cadera?",["Los flexores y los aductores","Los abductores y los rotadores externos","Los extensores y los estabilizadores"],["La cadera necrótica genera una hipertonía defensiva de los flexores y de los aductores.","Esos músculos no son los descritos como hipertónicos.","Los estabilizadores están al contrario inhibidos."]],
  "282": ["¿Qué hace positiva la prueba de Thomas?",["La pierna permanece suspendida sin aducirse","El muslo de la pierna afectada supera los 90°","La rodilla no desciende hacia la mesa de exploración"],["Ese criterio pertenece a la prueba de Ober.","La prueba es positiva si el muslo de la pierna afectada supera los 90°.","Ese criterio pertenece a la prueba de FABER."]],
  "283": ["¿Con qué afección es esencial el diagnóstico diferencial del síndrome miofascial?",["La artritis reumatoide","La espondilitis anquilosante","La fibromialgia difusa"],["La artritis reumatoide se cita para el túnel carpiano.","La espondilitis se detecta con la prueba de Ott.","El diagnóstico diferencial con la fibromialgia es esencial; esos pacientes presentan puntos gatillo miofasciales secundarios."]],
  "284": ["¿Qué hace positiva la prueba del hula hoop?",["Un chasquido a nivel del trocánter mayor","Un dolor profundo de la ingle al final del recorrido","Una caída de la pelvis del lado opuesto"],["La prueba es positiva si la circunducción produce un chasquido a nivel del trocánter mayor.","El dolor inguinal profundo evoca una afectación intraarticular.","La caída de la pelvis pertenece al signo de Trendelenburg."]],
  "285": ["¿Qué hace positiva la prueba de Ober?",["La pierna se aduce más allá de la horizontal","La pierna permanece suspendida y no se aduce","El chasquido se reproduce en el trocánter mayor"],["Una aducción libre corresponde a una prueba negativa.","La prueba es positiva si la pierna permanece suspendida sin aducirse, lo que indica una tensión de la cintilla iliotibial.","El chasquido es el criterio de la prueba del hula hoop."]],
  "286": ["¿Qué se mide en la prueba de FABER?",["El ángulo entre la pelvis y el fémur en apoyo","La amplitud de aducción pasiva del muslo","La distancia vertical entre la rodilla y la mesa"],["Ese ángulo pertenece al signo de Trendelenburg.","La aducción pasiva pertenece a la prueba de Ober.","Se mide la distancia vertical entre la rodilla y la mesa de exploración, comparándola con el lado opuesto."]],
  "287": ["¿Qué hace positiva la prueba de FABER?",["Una distancia más corta del lado afectado","Una distancia mayor del lado afectado","Una ausencia de chasquido del lado afectado"],["La prueba es positiva cuando la distancia es más corta del lado afectado, o cuando aparece un dolor al forzar la abducción.","Una distancia mayor no corresponde al criterio establecido.","La ausencia de chasquido no es un criterio de esa prueba."]],
  "288": ["¿Qué dificultad cotidiana provoca la tendinopatía glútea?",["La dificultad para sentarse con las piernas cruzadas","La dificultad para acostarse de lado","La dificultad para llevar ropa apretada"],["Esa posición se evita en el conflicto femoroacetabular.","El paciente tiene dificultad para acostarse de lado, mantenerse de pie, caminar, subir escaleras y sentarse.","La ropa apretada favorece las neuropatías de cadera."]],
  "289": ["¿Qué prueba complementaria es la más adecuada en la tendinopatía glútea?",["La gammagrafía ósea","La ecografía dinámica","La resonancia magnética"],["La gammagrafía se cita como útil, pero no es la más adecuada.","La ecografía es útil, pero no aporta la misma visión de conjunto.","La exploración por resonancia magnética es la prueba más adecuada para obtener simultáneamente información sobre las estructuras adyacentes."]],
  "290": ["¿Qué hace positiva la prueba de abducción resistida?",["La reproducción de los síntomas del paciente","La aparición de un chasquido trocantéreo","La caída de la pelvis del lado en suspensión"],["La prueba es positiva si los síntomas del paciente se reproducen, o si existe una diferencia significativa de fuerza con la pierna opuesta.","El chasquido no es un criterio de esa prueba.","La caída de la pelvis pertenece al signo de Trendelenburg."]],
  "291": ["¿Qué hace positivo el signo de Trendelenburg?",["Una reproducción inmediata del dolor trocantéreo","Un ángulo pelvis-fémur inferior a 83° en 30 segundos","Una disminución clara de la fuerza en abducción resistida"],["La reproducción del dolor no es el criterio numérico establecido.","El resultado es positivo cuando el ángulo entre la pelvis y el fémur baja de 83° antes del final de los 30 segundos.","La fuerza en abducción se explora con otra prueba."]],
  "292": ["¿Dónde asienta precisamente el dolor de la bursitis trocantérea?",["En la región inguinal, en forma de C","En la cara anterolateral del muslo","Directamente por encima del trocánter mayor"],["El dolor inguinal en C evoca un conflicto femoroacetabular.","Esa topografía evoca una neuropatía femorocutánea.","El dolor es lateral, unilateral, directamente por encima del trocánter mayor del fémur proximal."]],
  "293": ["¿Dónde asientan los síntomas de las neuropatías de la región de la cadera?",["En la nalga superolateral y en el muslo anterolateral","En la cara medial del muslo y de la ingle, hacia la rodilla","En la cara posterior del muslo y de la pantorrilla, hacia el talón"],["Los síntomas asientan en la parte superolateral de la nalga y anterolateral del muslo.","Esa topografía corresponde a los aductores.","Esa topografía corresponde a los isquiotibiales."]],
  "294": ["¿Cuál de estos deportes se cita como factor de neuropatía de la cadera?",["La natación de competición","La gimnasia deportiva","El ciclismo en carretera"],["La natación se cita para la salida torácica.","Los deportes como la gimnasia, el béisbol, el fútbol y la musculación pueden favorecer esa patología.","El ciclismo se cita para el canal de Guyon."]],
  "295": ["¿Cómo se realiza la prueba de tensión del nervio femorocutáneo lateral?",["En decúbito supino, mediante una flexión de cadera y una rotación interna","De pie, mediante una circunducción de la cadera afectada","En decúbito lateral, mediante una extensión de cadera asociada a una aducción"],["Esa maniobra es la de la prueba FADIR.","Esa maniobra es la de la prueba del hula hoop.","El paciente está en decúbito lateral, con la cadera afectada hacia arriba y la pelvis fijada; se realiza una extensión de cadera asociada a una aducción."]],
  "296": ["¿Qué movimiento accesorio se explora primero en una movilización con movimiento?",["El que facilita biomecánicamente el movimiento doloroso","El que reproduce más claramente el dolor","El que ofrece la mayor amplitud disponible"],["Se explora siempre primero el movimiento accesorio que facilita biomecánicamente el movimiento fisiológico doloroso.","Reproducir el dolor es lo contrario del objetivo.","La amplitud no es el criterio de elección."]],
  "297": ["¿Cuál de estos músculos se toma como diana en el síndrome doloroso trocantéreo?",["El músculo sóleo de la pierna","El músculo cuadrado lumbar","El músculo flexor largo de los dedos"],["El sóleo no es una diana de ese síndrome.","Los tejidos diana comportan el glúteo menor y el glúteo mayor, el tensor de la fascia lata, el piramidal, el cuadrado lumbar y los vastos del cuádriceps.","Ese músculo no es una diana de ese síndrome."]],
  "298": ["¿Cómo se presenta el dolor del conflicto femoroacetabular?",["Lateral, directamente por encima del trocánter mayor","Anterolateral del muslo, con parestesias","Unilateral, en la cadera o en la ingle, en forma de C"],["Esa topografía es la de la bursitis trocantérea.","Esa topografía es la de una neuropatía femorocutánea.","El dolor es mecánico o posicional, unilateral, situado en la cadera o en la ingle, en C."]],
  "299": ["¿Qué define el conflicto femoroacetabular de tipo cam?",["Una protuberancia a nivel del cuello femoral","Una cobertura excesiva de la cabeza femoral","Una muerte del tejido óseo subcondral"],["El tipo cam asocia una cabeza femoral no perfectamente redonda y una protuberancia a nivel del cuello femoral.","La cobertura excesiva define el tipo pincer.","La necrosis ósea define la necrosis avascular."]],
  "300": ["¿Qué define el conflicto femoroacetabular de tipo pincer?",["Una cabeza femoral deformada, con un bulto en el cuello","Un acetábulo demasiado profundo, que cubre demasiado la cabeza","Una rotura aislada del labrum acetabular anterior"],["El bulto del cuello define el tipo cam.","El tipo pincer asocia un acetábulo de borde demasiado profundo y una cobertura excesiva de la cabeza femoral.","La rotura del labrum es una lesión asociada, no un tipo."]],
  "301": ["¿Qué anomalía de la pelvis puede provocar un conflicto femoroacetabular?",["Una dismetría de los miembros inferiores","Una hiperlaxitud ligamentaria generalizada","Una retroversión acetabular"],["La dismetría no se cita como causa.","La hiperlaxitud no se cita como causa.","El conflicto puede también provocarse por una retroversión acetabular o una inclinación pélvica anterior."]],
  "302": ["¿Qué prueba complementaria identifica una rotura del labrum asociada al conflicto femoroacetabular?",["La exploración por resonancia magnética","La exploración radiológica simple","La ecografía dinámica de la cadera"],["La exploración por resonancia magnética identifica una eventual rotura del labrum o una lesión del cartílago.","La radiología simple sirve para el diagnóstico del propio conflicto.","La ecografía dinámica sirve para la cadera en resorte."]],
  "303": ["¿Qué movimientos están limitados en las formas avanzadas de conflicto femoroacetabular?",["La extensión, la rotación externa y la abducción","La flexión, la rotación interna y la aducción","Únicamente la rotación interna forzada"],["Esos movimientos no son los descritos como limitados.","La amplitud está limitada, en particular la flexión, la rotación interna y la aducción en los casos avanzados.","La limitación no se reduce a la rotación interna."]],
  "304": ["¿En cuánto reducen los bastones la carga sobre la cabeza femoral necrosada?",["Del 10 al 20 %","Del 70 al 90 %","Del 30 al 50 %"],["Del diez al veinte por ciento corresponde a la carga residual en hidroterapia.","Esa reducción es superior a la establecida.","El uso de bastones o de muletas reduce la carga ponderal sobre la cabeza femoral del 30 al 50 %."]],
  "305": ["¿Es facultativo el uso de bastones en fase aguda de necrosis avascular?",["No, es imperativo para la articulación","Sí, depende de la comodidad del paciente","Sí, salvo si el dolor es intenso"],["El uso de bastones o de muletas es imperativo en las fases agudas: esa medida no es facultativa, busca proteger la articulación.","La comodidad no es el criterio establecido.","No se plantea ninguna condición de ese tipo."]],
  "306": ["¿Qué músculo sufre una inhibición refleja en la necrosis avascular de la cadera?",["El músculo iliopsoas","El glúteo mayor","Los músculos aductores"],["El iliopsoas presenta al contrario una hipertonía defensiva.","La cadera necrótica genera una inhibición refleja de los estabilizadores, entre ellos el glúteo mayor.","Los aductores presentan una hipertonía defensiva."]],
  "307": ["¿Cómo se distingue el dolor de la tendinopatía del psoas ilíaco de una afectación intraarticular?",["Es profundo y bien localizado en la ingle","Irradia siempre a la cara externa de la rodilla","Es difuso y superficial, no profundo y localizado"],["Ese es al contrario el perfil de la afectación intraarticular.","Esa irradiación evoca una neuropatía femorocutánea.","El dolor del psoas es difuso y superficial en la ingle, mientras que la patología intraarticular es profunda y bien localizada."]],
  "308": ["¿Qué gesto intensifica el dolor de la tendinopatía del psoas ilíaco?",["La flexión de cadera, para levantarse","La abducción resistida de lado","La rotación interna forzada"],["El dolor se intensifica durante la flexión de cadera, en particular para levantarse, acostarse o subir al coche.","La abducción resistida explora la tendinopatía glútea.","La rotación interna forzada evoca una necrosis avascular."]],
  "309": ["¿Qué muestra la ecografía de un punto gatillo miofascial?",["Una zona hiperecogénica homogénea","Una zona hipoecogénica focalizada","Un engrosamiento del tronco nervioso vecino"],["El aspecto descrito es hipoecogénico, no hiperecogénico.","La ecografía muestra una zona hipoecogénica focalizada, identificada como punto gatillo, con cambios de ecogenicidad.","El engrosamiento nervioso concierne a las neuropatías."]],
  "310": ["¿Cuándo introducir los ejercicios de fuerza en un síndrome miofascial?",["Desde la primera sesión, sea cual sea el estado","Solo después de una punción seca exitosa","Cuando el dolor disminuye y el movimiento está restablecido"],["Una introducción inmediata sería contraria al principio de prudencia.","La punción seca no es un requisito obligatorio.","Una vez que el dolor muscular disminuye y el movimiento está restablecido, se introducen ejercicios de fuerza y de resistencia."]],
  "311": ["¿Qué músculo puede referir un dolor lateral de muslo o de cadera?",["El tensor de la fascia lata","El músculo grácil del muslo","El músculo poplíteo del hueco poplíteo"],["El dolor lateral de muslo o de cadera puede provenir del glúteo mayor, del cuadrado lumbar, de los vastos, del piramidal, del glúteo menor o del tensor de la fascia lata.","El grácil refiere hacia la cara medial del muslo.","El poplíteo refiere hacia la cara posterior de la rodilla."]],
  "312": ["¿Qué músculo puede referir un dolor posterior de muslo?",["El músculo pectíneo de la ingle","El músculo obturador interno","El músculo vasto medial del cuádriceps"],["El pectíneo refiere hacia la cara anterior del muslo.","El dolor posterior de muslo puede venir del obturador interno, del piramidal, del glúteo menor y de los isquiotibiales.","El vasto medial refiere hacia la cara medial."]],
  "313": ["¿Qué músculo puede referir un dolor medial de muslo?",["El músculo vasto lateral","El músculo piramidal de la nalga","El músculo grácil del muslo"],["El vasto lateral refiere hacia la cara lateral.","El piramidal refiere hacia las caras posterior y lateral.","El dolor medial de muslo puede venir del sartorio, del grácil, del aductor mayor, del pectíneo y del vasto medial del cuádriceps."]],
  "314": ["¿Por qué asociar ejercicios de cadera al trabajo de la rodilla?",["Porque la asociación reduce el dolor mejor que la rodilla sola","Porque la rodilla no puede trabajarse de forma aislada","Porque la cadera sustituye a la propiocepción de la rodilla"],["Combinar los ejercicios para los glúteos y las caderas con la rodilla es más eficaz que trabajar la rodilla de forma aislada, tanto a corto como a largo plazo.","La rodilla puede trabajarse de forma aislada, pero con menos beneficio.","No se describe ninguna sustitución de ese tipo."]],
  "315": ["¿Qué intensidad de ejercicio privilegiar en las patologías de la rodilla?",["Una intensidad baja, para preservar el cartílago","Una intensidad alta, en progresión individualizada","Una intensidad máxima de entrada, sin progresión"],["La intensidad baja es menos eficaz.","Los programas de alta intensidad son superiores a los de baja intensidad, con una progresión gradual individualizada según la tolerancia.","La ausencia de progresión sería contraria al principio."]],
  "316": ["¿Por qué no se aconsejan los corticosteroides a largo plazo en la rodilla?",["Debido a una ineficacia total sobre el dolor","Debido a un riesgo elevado de infección articular","Debido al riesgo de lesiones tisulares"],["Alivian el dolor a muy corto plazo.","El riesgo infeccioso no es el argumento planteado.","No se aconsejan a largo plazo debido al riesgo de lesiones tisulares."]],
  "317": ["¿Para qué sirve la exploración por resonancia magnética en la tendinopatía de la pata de ganso?",["Para excluir una afectación intraarticular","Para confirmar la distensión de la bursa","Para estadificar la artrosis asociada"],["Se utiliza en los casos crónicos o complejos para excluir una afectación intraarticular.","La bursa se explora primero con ecografía.","La estadificación de la artrosis se hace con radiología."]],
  "318": ["¿Después de cuánto tiempo plantear opciones complementarias en la pata de ganso?",["Después de dos a tres semanas de tratamiento","Después de tres a seis meses de tratamiento conservador","Después de dos años de tratamiento conservador"],["Ese plazo es demasiado corto.","Se plantean opciones adicionales cuando la fisioterapia conservadora es insuficiente después de tres a seis meses.","Ese plazo es muy superior al establecido."]],
  "319": ["¿Qué hay que incluir imperativamente en el entrenamiento neuromuscular de la rodilla?",["La fuerza máxima concéntrica aislada","El estiramiento pasivo prolongado de la cadena posterior","El equilibrio y la propiocepción"],["La fuerza aislada no cubre ese objetivo.","El estiramiento pasivo no es el componente buscado.","Es esencial incluir el equilibrio y la propiocepción: el déficit propioceptivo postraumático se normaliza mediante un entrenamiento específico."]],
  "320": ["¿Cómo utilizar el vendaje neuromuscular en el síndrome femoropatelar?",["Como complemento del ejercicio, para la retroalimentación propioceptiva","Como tratamiento aislado de las formas dolorosas","En sustitución del fortalecimiento del cuádriceps"],["El vendaje se emplea como complemento del ejercicio, porque proporciona una retroalimentación propioceptiva.","El vendaje solo no reduce significativamente el dolor.","No sustituye al fortalecimiento muscular."]],
  "321": ["¿En qué caso sigue reservada la artroscopia en la rodilla?",["Ante toda crepitación palpable","Ante una lesión estructural documentada","Ante una atrofia del vasto medial"],["La crepitación no constituye una indicación.","Debe reservarse a los casos que presentan una lesión estructural documentada que no responde al tratamiento conservador.","La atrofia se trata con ejercicio."]],
  "322": ["¿Cuánto tiempo alivia el ácido hialurónico el dolor de la rodilla?",["Hasta tres meses","Hasta doce meses","Hasta tres semanas"],["Tres meses corresponde al plazo de evaluación de la electroacupuntura.","Esa duración es muy superior a la establecida.","El ácido hialurónico reduce el dolor y mejora la función a corto plazo, hasta tres semanas."]],
  "323": ["¿Cuánto tiempo alivia una inyección de corticosteroides la rodilla?",["De dos a tres semanas","De tres a seis meses","De veinticuatro a cuarenta y ocho horas"],["Los corticosteroides alivian a muy corto plazo, de dos a tres semanas, pero no se aconsejan a largo plazo.","Esa duración es muy superior a la establecida.","Ese plazo corresponde al dolor pospunción."]],
  "324": ["¿Por qué deben ser ecoguiadas las inyecciones de corticosteroides de la pata de ganso?",["Para apuntar con precisión al punto gatillo","Para evitar una inyección intratendinosa","Para controlar la neovascularización"],["La localización de los puntos gatillo depende de la punción seca.","Deben guiarse por ecografía a fin de evitar una inyección intratendinosa y el riesgo de rotura.","El control de la neovascularización no es el objetivo."]],
  "325": ["¿Cuál es la aportación de los antiinflamatorios en la tendinopatía de la pata de ganso?",["Una regeneración del tejido tendinoso","Una prevención duradera de las recidivas","Un alivio puramente sintomático"],["No se les atribuye ninguna regeneración.","No se les atribuye ninguna prevención de las recidivas.","Alivian el dolor y facilitan la participación en el ejercicio, dejando inalterada la evolución clínica de la tendinopatía."]],
  "326": ["¿Cuánto tiempo mantener el ejercicio antes de plantear opciones invasivas en la tendinopatía rotuliana?",["Al menos doce semanas","Al menos tres semanas","Al menos dos años"],["La terapia mediante ejercicio debe mantenerse al menos doce semanas antes de plantear opciones más invasivas.","Ese plazo es demasiado corto.","Ese plazo es muy superior al establecido."]],
  "327": ["¿Cuál es el objetivo de la fase isométrica en la tendinopatía rotuliana?",["Una adaptación estructural del tendón afectado","Una analgesia inmediata y una desinhibición","La recuperación de la capacidad reactiva"],["La adaptación estructural depende de la fase isotónica.","La fase isométrica busca una analgesia inmediata y la reducción de la inhibición cortical.","La capacidad reactiva depende de la fase de almacenamiento de energía."]],
  "328": ["¿Qué efecto indeseable pueden provocar los parches de nitroglicerina?",["Una rotura del tendón rotuliano","Un dolor transitorio después de la colocación","Dolores de cabeza en algunos pacientes"],["La rotura es el riesgo de los corticosteroides.","El dolor pospunción concierne a la punción seca.","Pueden provocar dolores de cabeza en algunos pacientes."]],
  "329": ["¿Cuál es el efecto indeseable más frecuente de la punción seca?",["Un dolor transitorio después de la punción","Una rotura parcial del tendón puncionado","Una atrofia muscular duradera del cuádriceps"],["El dolor pospunción transitorio es el efecto indeseable más frecuente; desaparece en 24 a 48 horas.","La rotura es el riesgo de la inyección intratendinosa de corticoides.","La atrofia no es un efecto de esa técnica."]],
  "330": ["¿Cuál es la eficacia de la electroacupuntura en la condromalacia rotuliana?",["Claramente superior a la fisioterapia convencional","Comparable a la fisioterapia convencional a tres meses","Sin efecto medible sobre el dolor y la discapacidad"],["No se demuestra ninguna superioridad.","La electroacupuntura se ha mostrado tan eficaz como la fisioterapia convencional para reducir el dolor y la discapacidad a tres meses.","Un efecto comparable está efectivamente demostrado."]],
  "331": ["¿Está recomendada la artroscopia en el síndrome femoropatelar crónico?",["Sí, en primera intención ante todo dolor","Sí, en cuanto fracasan seis semanas de rehabilitación","No, no aporta nada más que el ejercicio solo"],["No se propone en primera intención.","No se establece ningún plazo de ese tipo.","La artroscopia asociada al ejercicio da los mismos resultados que el ejercicio solo: queda fuera de las recomendaciones."]],
  "332": ["¿A qué afecciones se asocia a menudo la tendinopatía de la pata de ganso?",["A la artrosis de la rodilla y a la bursitis","A la tendinopatía rotuliana del deportista","A la inestabilidad femoropatelar crónica"],["Acompaña a menudo a la artrosis de la rodilla y a la bursitis.","La tendinopatía rotuliana no es la asociación descrita.","La inestabilidad femoropatelar no es la asociación descrita."]],
  "333": ["¿Cuál es el efecto de la crioterapia en la tendinopatía de la pata de ganso?",["Acelera la curación del tendón afectado","Alivia los síntomas sin modificar la evolución","Está formalmente contraindicada en fase aguda"],["No se demuestra ninguna acción sobre la curación.","El hielo puede aliviar los síntomas dolorosos, pero no está demostrado que modifique la evolución clínica de la tendinopatía.","No se plantea ninguna contraindicación."]],
  "334": ["¿Cuál es el nivel de evidencia del plasma rico en plaquetas en la tendinopatía rotuliana?",["Sólido, con una superioridad demostrada sobre el ejercicio","Ausente, al no haberse publicado nunca ningún estudio","Contradictorio, sin superioridad sobre el ejercicio en fase inicial"],["No se demuestra ninguna superioridad.","Existen estudios, pero sus resultados divergen.","La evidencia es contradictoria: se sugieren algunos beneficios a largo plazo en los casos crónicos, pero sin superioridad sobre el ejercicio en fase inicial."]],
  "335": ["¿Qué músculo se atrofia en el síndrome femoropatelar?",["El vasto medial oblicuo del cuádriceps","El músculo poplíteo del hueco poplíteo","El vientre medial del gastrocnemio"],["Se observa una atrofia leve pero visible del vasto medial oblicuo del cuádriceps.","El poplíteo no es el músculo descrito como atrofiado.","El gastrocnemio no es el músculo descrito como atrofiado."]],
  "336": ["¿Qué déficit de fuerza acompaña al síndrome femoropatelar?",["Una debilidad en flexión plantar del tobillo","Una debilidad en extensión de la rodilla y de la cadera","Una debilidad en rotación externa de la cadera"],["El tobillo no es la sede del déficit descrito.","Se documenta una debilidad en extensión de la rodilla y de la cadera, con reducción de la flexibilidad de la cadena posterior.","La rotación externa no es el déficit descrito."]],
  "337": ["¿Qué hace positiva la prueba de compresión de Clarke?",["Un desplazamiento rotuliano excesivo hacia fuera","Una crepitación audible al movimiento de la rodilla","La reproducción de un dolor retropatelar"],["El desplazamiento excesivo pertenece a la prueba de extrusión.","La crepitación no es el criterio de esa prueba.","La prueba es positiva si reproduce un dolor retropatelar, sugestivo de condromalacia o de síndrome femoropatelar."]],
  "338": ["¿Qué señala un dolor a la palpación de las facetas rotulianas?",["Una irritación condral o sinovial localizada","Una hiperlaxitud de la cápsula articular","Un déficit de fuerza del vasto medial oblicuo"],["Un dolor a la palpación indica una irritación condral o sinovial en ese lugar preciso.","La hiperlaxitud capsular se revela en la prueba de extrusión.","El déficit de fuerza se evalúa mediante una valoración muscular."]],
  "339": ["¿Qué clasificación permite estadificar la artrosis de la rodilla?",["La clasificación de Eaton","La clasificación de Kellgren","El cuestionario VISA-P"],["La clasificación de Eaton estadifica la artrosis del pulgar.","La clasificación de Kellgren y Lawrence, de 0 a 4, estadifica la artrosis en una radiografía simple.","El cuestionario VISA-P cuantifica la gravedad de una tendinopatía rotuliana."]],
  "340": ["¿Qué prueba complementaria explora las lesiones cartilaginosas de la rodilla?",["La exploración radiológica simple","La ecografía Doppler color","La exploración por resonancia magnética"],["La radiología simple sirve para la estadificación de la artrosis.","La ecografía Doppler explora las patologías tendinosas.","La exploración por resonancia magnética es útil para las lesiones cartilaginosas."]],
  "341": ["¿Cuál es el tratamiento de primera intención de las patologías de la rodilla?",["La terapia conservadora multimodal","La artroscopia asociada al ejercicio","La inyección intraarticular de corticosteroides"],["El consenso actual establece que la terapia conservadora multimodal es el tratamiento de primera intención.","La artroscopia no se recomienda en primera intención.","La inyección solo alivia a muy corto plazo."]],
  "342": ["¿Qué músculos toma como diana la punción seca en el síndrome femoropatelar?",["El poplíteo, los peroneos y el sóleo","Los cuádriceps, los glúteos y los isquiotibiales","Los aductores, el grácil y el sartorio"],["Esos músculos no son las dianas designadas.","Una evidencia baja a moderada respalda la punción seca de los puntos gatillo de los cuádriceps, de los glúteos y de los isquiotibiales.","Esos músculos dependen más bien de la pata de ganso."]],
  "343": ["¿Cuál de estos músculos toma como diana el tratamiento muscular de la rodilla?",["El músculo peroneo largo","El músculo tibial posterior","El músculo poplíteo de la rodilla"],["El peroneo largo no se cita entre esas dianas.","El tibial posterior no se cita entre esas dianas.","Los tejidos diana comportan el glúteo menor, el poplíteo, el tensor de la fascia lata, los isquiotibiales, los gastrocnemios y el cuádriceps."]],
  "344": ["¿Qué muestra la evidencia sobre el vendaje utilizado solo en la rodilla?",["No reduce significativamente el dolor","Reduce de forma duradera el dolor y la discapacidad","Agrava el dolor por compresión excesiva"],["La evidencia muestra que el vendaje solo no reduce significativamente el dolor.","No se demuestra ningún efecto duradero para el vendaje aislado.","No se refiere ningún agravamiento."]],
  "345": ["¿Qué muestra la comparación entre vendaje placebo asociado al ejercicio y ejercicio solo?",["El ejercicio solo superó a los otros dos enfoques","El vendaje placebo asociado al ejercicio superó al ejercicio solo","Los dos enfoques dieron resultados idénticos"],["Ese resultado es contrario al referido.","El vendaje placebo asociado al ejercicio superó al ejercicio solo en algunos estudios.","Se observó efectivamente una diferencia."]],
  "346": ["¿Dónde asienta el dolor de la tendinopatía de la pata de ganso?",["En el polo inferior de la rótula","Detrás y alrededor de la rótula","En la parte anteromedial de la rodilla"],["Esa localización evoca una tendinopatía rotuliana.","Esa localización evoca un síndrome femoropatelar.","El dolor es intenso y súbito, en la parte anteromedial de la rodilla."]],
  "347": ["¿Qué gesto agrava el dolor de la tendinopatía de la pata de ganso?",["La flexión de la rodilla contra resistencia","El salto vertical explosivo repetido","La posición sentada prolongada con las rodillas flexionadas"],["El dolor se intensifica en las escaleras, al levantarse de una posición sentada, al sentarse con las piernas cruzadas y durante una flexión resistida de la rodilla.","El salto explosivo agrava la tendinopatía rotuliana.","La posición sentada prolongada evoca el signo del cine."]],
  "348": ["¿Qué revela la ecografía en la tendinopatía de la pata de ganso?",["Una zona hipoecogénica del tendón","Una distensión de la bursa serosa","Un pinzamiento de la interlínea"],["Esa imagen corresponde a la tendinopatía rotuliana.","La ecografía revela una distensión de la bursa serosa, un engrosamiento del tendón y un aumento del flujo sanguíneo.","El pinzamiento de la interlínea se ve en radiología."]],
  "349": ["¿Qué amplitudes hay que evitar primero en la tendinopatía de la pata de ganso?",["Las amplitudes finales de extensión de la rodilla","Las amplitudes medias de flexión de la rodilla","Las amplitudes finales de flexión de la rodilla"],["La extensión final no es la posición compresiva descrita.","Las amplitudes medias no hay que evitarlas.","Hay que evitar primero las posiciones compresivas, es decir las amplitudes finales de flexión de la rodilla."]],
  "350": ["¿Qué técnicas de electroterapia dan los mejores resultados en la pata de ganso?",["La diatermia, las ondas de choque y la electrólisis percutánea","La electroacupuntura y la estimulación muscular","Los ultrasonidos pulsados y la magnetoterapia"],["La diatermia, las ondas de choque y la electrólisis percutánea constituyen las herramientas que ofrecen los mejores resultados clínicos.","La electroacupuntura depende del tratamiento femoropatelar.","Los ultrasonidos pulsados no figuran entre las herramientas designadas."]],
  "351": ["¿Qué estructura descarga la modificación de la zancada en la pata de ganso?",["El tendón rotuliano y el cuádriceps","Los isquiotibiales y los aductores","El tendón de Aquiles y el tríceps sural"],["El mecanismo extensor no es la diana de esa fase.","El objetivo es reducir la solicitación mecánica de los isquiotibiales y de los aductores durante la locomoción.","Esas estructuras no son la diana de esa fase."]],
  "352": ["¿Dónde asienta el dolor de la tendinopatía rotuliana?",["En la parte anteromedial de la rodilla","Alrededor y detrás de la rótula, de forma difusa","En la cara anterior, sobre el tendón profundo"],["Esa topografía evoca una tendinopatía de la pata de ganso.","Esa topografía evoca un síndrome femoropatelar.","El dolor es anterior, localizado en la rodilla y despertado a la palpación de la parte profunda del tendón."]],
  "353": ["¿Qué limitación del tobillo favorece la tendinopatía rotuliana?",["Una reducción de la flexión dorsal","Una reducción de la flexión plantar","Una reducción de la eversión del pie"],["La reducción de la dorsiflexión del tobillo figura entre los factores de riesgo, porque aumenta la carga sobre el mecanismo extensor.","La flexión plantar no es la limitación descrita.","La eversión no es la limitación descrita."]],
  "354": ["¿Qué revela la ecografía en la tendinopatía rotuliana?",["Una distensión de la bursa serosa medial","Una zona hipoecogénica, a veces con engrosamiento del tendón","Un pinzamiento de la interlínea femorotibial medial"],["La distensión de la bursa pertenece a la pata de ganso.","La ecografía revela una zona hipoecogénica, a veces asociada a un engrosamiento del tendón.","El pinzamiento de la interlínea se ve en radiología."]],
  "355": ["¿Qué muestra el modo Doppler en la tendinopatía rotuliana?",["Una ausencia total de flujo en el tendón","Un engrosamiento de la vaina sinovial sola","Una neovascularización con aumento del flujo"],["La ausencia de flujo no es la imagen descrita.","El engrosamiento sinovial aislado no es la imagen descrita.","El modo Doppler permite observar una neovascularización y un aumento del flujo sanguíneo."]],
  "356": ["¿En qué secuencias se ven mejor las desgarros parciales del tendón rotuliano?",["En las imágenes de señal intensa de tipo T2","En los cortes radiológicos de perfil en carga","En la ecografía en modo Doppler color"],["Los desgarros parciales se ponen mejor en evidencia en las imágenes T2 de señal intensa.","La radiología detecta sobre todo las anomalías óseas.","El Doppler muestra la neovascularización."]],
  "357": ["¿Qué mide el cuestionario VISA-P?",["El estadio radiológico de la afectación tendinosa","El dolor, la función y la capacidad deportiva","La fuerza isocinética del cuádriceps afectado"],["El estadio radiológico no forma parte de ese cuestionario.","El cuestionario VISA-P evalúa tres dimensiones: el dolor, la función y la capacidad deportiva.","La fuerza isocinética no se evalúa con ese cuestionario."]],
  "358": ["¿Qué muestran los metaanálisis sobre las ondas de choque en la tendinopatía rotuliana?",["Son claramente superiores al ejercicio excéntrico","Agravan el dolor y la función a corto plazo","No son superiores al placebo ni al excéntrico"],["No se demuestra ninguna superioridad.","No se refiere ningún agravamiento.","Los metaanálisis las sitúan al mismo nivel que el placebo o el ejercicio excéntrico sobre el dolor y la función a corto plazo."]],
  "359": ["¿Con qué frecuencia se introducen los saltos en la fase de almacenamiento de energía?",["Cada tres días","Todos los días sin interrupción","Una vez por semana solamente"],["La pliometría y los saltos se introducen progresivamente, cada tres días.","No se recomienda un trabajo diario.","Esa frecuencia es inferior a la establecida."]],
  "360": ["¿Qué hay que mantener en la reanudación del deporte después de una tendinopatía rotuliana?",["Una inmovilización parcial de la rodilla afectada","Ejercicios de mantenimiento, para prevenir las recaídas","Una inyección de corticosteroides preventiva"],["No se recomienda ninguna inmovilización.","La reanudación asocia un entrenamiento específico de la disciplina y el mantenimiento de ejercicios de mantenimiento para prevenir las recaídas.","Los corticosteroides no se aconsejan en esa patología."]],
  "361": ["¿Por qué no se aconsejan los corticosteroides en la tendinopatía rotuliana?",["Porque son totalmente ineficaces sobre el dolor","Porque provocan dolores de cabeza frecuentes","Porque aumentan el riesgo de rotura del tendón"],["Alivian el dolor a corto plazo.","Los dolores de cabeza conciernen a los parches de nitroglicerina.","Aunque alivian a corto plazo, aumentan considerablemente el riesgo de rotura del tendón y de atrofia a largo plazo."]],
  "362": ["¿En qué momento plantear las técnicas invasivas en la tendinopatía rotuliana?",["Entre la duodécima y la vigesimocuarta semana","En las doce primeras semanas de tratamiento","Más allá de seis meses de tratamiento conservador"],["Entre 12 y 24 semanas, ante una progresión insuficiente, se plantean las técnicas invasivas y se reevalúa mediante el cuestionario VISA-P.","Las doce primeras semanas se dedican al tratamiento conservador.","Más allá de seis meses, la cuestión planteada es la de la cirugía."]],
  "363": ["¿En qué momento se plantea la cirugía de la tendinopatía rotuliana?",["Más allá de doce semanas sin mejoría","Más allá de seis meses de un tratamiento conservador de calidad","Desde el diagnóstico en caso de desgarro parcial"],["Doce semanas corresponde al umbral de las técnicas invasivas.","La cirugía se reserva estrictamente a los casos que no responden después de seis meses de tratamiento conservador de alta calidad.","La cirugía no se propone de entrada."]],
  "364": ["¿En qué se basa el concepto Maitland?",["La corrección de un defecto de posición articular","El estudio, la exploración y la evaluación de los movimientos y del dolor","La búsqueda de una preferencia direccional durante los movimientos repetidos"],["La corrección posicional es la teoría del concepto Mulligan.","El concepto se basa en el estudio, la exploración y la evaluación de los movimientos y del dolor, y después la restauración de movimientos articulares específicos mediante movilización.","La preferencia direccional pertenece al concepto McKenzie."]],
  "365": ["¿Qué frecuencia corresponde a una oscilación LENTA de Maitland?",["Una oscilación cada segundo","Dos oscilaciones cada segundo","Una oscilación cada 2 segundos"],["Una oscilación por segundo define la frecuencia media.","Dos oscilaciones por segundo definen la frecuencia rápida.","La frecuencia lenta corresponde a una oscilación cada dos segundos, la media a una por segundo y la rápida a dos por segundo."]],
  "366": ["¿De qué depende la amplitud elegida para una movilización oscilatoria?",["De los objetivos terapéuticos de la movilización","De la frecuencia de oscilación establecida","Del tamaño de la articulación tratada"],["La amplitud es variable, alta o baja, según los objetivos terapéuticos perseguidos.","Frecuencia y amplitud se ajustan de forma independiente.","La dimensión articular no es el criterio enunciado."]],
  "367": ["¿Qué puede realizarse al final de la amplitud articular según Maitland?",["Impulsos de gran amplitud y gran velocidad","Técnicas de estiramiento con pequeñas oscilaciones","Movilizaciones de gran amplitud en zona neutra"],["Los impulsos rápidos de corta amplitud corresponden al grado V.","Al final de la amplitud pueden realizarse técnicas de estiramiento que comportan pequeñas oscilaciones.","La gran amplitud en zona neutra corresponde al grado II."]],
  "368": ["¿Cuáles son las dos vertientes de la evaluación de la movilidad articular?",["La velocidad y la amplitud del movimiento","La fuerza y la resistencia del movimiento","La cantidad y la calidad del movimiento"],["Velocidad y amplitud son parámetros de la técnica, no las vertientes de la evaluación.","Fuerza y resistencia dependen de la evaluación muscular.","La evaluación se centra en la cantidad de movilidad, limitada por una rigidez, un dolor o un espasmo, y en su calidad, es decir la sensación final."]],
  "369": ["¿A qué corresponde la calidad del movimiento en la evaluación de Maitland?",["A la sensación final percibida por el terapeuta","A la amplitud total medida en grados","A la intensidad del dolor referida por el paciente"],["La calidad del movimiento corresponde a la sensación final, percibida al final de la amplitud.","La amplitud medida depende de la cantidad.","La intensidad dolorosa depende de la evaluación del dolor."]],
  "370": ["¿Qué se busca al evaluar el dolor según Maitland?",["Una preferencia direccional que centralice el dolor","Un signo comparable, y el carácter conocido o desconocido del dolor","Un defecto de posición articular responsable del dolor"],["La centralización pertenece al concepto McKenzie.","La evaluación del dolor distingue el dolor conocido del dolor desconocido, y busca un signo comparable.","El fallo posicional pertenece al concepto Mulligan."]],
  "371": ["¿A qué corresponde una movilización de grado I?",["A movimientos de gran amplitud en la zona neutra","A movimientos de muy baja amplitud al final del recorrido","A movimientos de amplitud mínima, al inicio del recorrido"],["La gran amplitud en zona neutra corresponde al grado II.","La baja amplitud al final del recorrido corresponde al grado IV.","El grado I agrupa los movimientos de amplitud mínima, que reproducen el inicio del movimiento."]],
  "372": ["¿En qué zona se sitúan los movimientos de grado II?",["En la zona neutra, con una amplitud mayor","En el límite de la movilidad pasiva","Más allá de los límites anatómicos de la articulación"],["El grado II comporta movimientos de amplitud mayor, situados en la zona neutra.","El límite de la movilidad pasiva se alcanza con el grado III.","Ningún grado supera los límites anatómicos."]],
  "373": ["¿Qué caracteriza a una movilización de grado III?",["Una amplitud mínima que reproduce el inicio del movimiento","Una gran amplitud que alcanza el límite de la movilidad pasiva","Un impulso rápido de corta amplitud"],["La amplitud mínima define el grado I.","El grado III corresponde a movimientos de gran amplitud que alcanzan el límite de la movilidad pasiva.","El impulso rápido de corta amplitud define el grado V."]],
  "374": ["¿Qué distingue el grado IV del grado III?",["Su amplitud es mayor y se mantiene en zona neutra","Se ejecuta a gran velocidad en forma de impulso","Su amplitud es muy baja, pero se ejecuta al final de la amplitud"],["La zona neutra corresponde al grado II.","El impulso rápido define el grado V.","El grado IV comporta movimientos de muy baja amplitud, pero ejecutados al final de la amplitud, mientras que el grado III trabaja en gran amplitud."]],
  "375": ["¿En qué límites se ejecuta una movilización de grado V?",["En los límites anatómicos de la articulación","En la zona neutra de la articulación","Más allá de los límites anatómicos, por cavitación"],["El grado V consiste en impulsos rápidos de corta amplitud, ejecutados dentro de los límites anatómicos.","La zona neutra corresponde al grado II.","Ningún grado supera los límites anatómicos."]],
  "376": ["¿Cuáles son las tres direcciones de movimiento utilizadas como tratamiento?",["Activo, pasivo y contra resistencia manual","Fisiológico, accesorio y combinado","Rotación, deslizamiento y decoaptación axial"],["Esa clasificación no corresponde a las direcciones descritas.","Las direcciones de tratamiento son los movimientos fisiológicos pasivos, los movimientos accesorios, y la combinación de ambos.","Esos tres elementos son movimientos accesorios, no las tres direcciones."]],
  "377": ["¿Cuál es el papel de los movimientos accesorios en la mecánica articular?",["Sustituyen al movimiento fisiológico limitado","Protegen la articulación de las fuerzas de carga","Permiten la libertad total del movimiento fisiológico"],["No sustituyen al movimiento fisiológico: lo condicionan.","No se describe ningún papel de protección mecánica.","Los movimientos accesorios permiten una libertad total de movimiento fisiológico; su restricción conlleva trastornos del movimiento."]],
  "378": ["¿En qué orden se trabajan los movimientos según Maitland?",["El movimiento accesorio primero, y después el fisiológico","El movimiento fisiológico primero, y después el accesorio","Los dos simultáneamente, desde la primera sesión"],["El movimiento accesorio se trabaja generalmente primero, seguido del movimiento fisiológico.","El orden establecido es el inverso.","La combinación llega más tarde, según los objetivos."]],
  "379": ["¿En qué caso se asocia un movimiento accesorio a una DESCOMPRESIÓN?",["Para estimular la nutrición del cartílago","En caso de irritabilidad elevada","Para ganar amplitud al final del recorrido"],["La estimulación de la nutrición cartilaginosa pasa por la asociación de accesorio y compresión.","La asociación de accesorio y descompresión se establece cuando la irritabilidad es elevada.","La ganancia de amplitud terminal depende de los grados III y IV."]],
  "380": ["¿Con qué fin se asocia un movimiento accesorio a una COMPRESIÓN?",["Para reducir una irritabilidad articular elevada","Para provocar una cavitación articular","Para estimular la nutrición del cartílago"],["La irritabilidad elevada exige al contrario una descompresión.","La cavitación no es un objetivo buscado.","La asociación de accesorio y compresión busca estimular la nutrición del cartílago."]],
  "381": ["¿Qué movimiento fisiológico pasivo es el más funcional?",["El movimiento de tres ejes","El movimiento de un solo sentido","El movimiento de dos ejes"],["Los movimientos de tres ejes, por ejemplo flexión, aducción y rotación externa, son los más funcionales.","El movimiento de un solo sentido es el más analítico, no el más funcional.","El movimiento de dos ejes es intermedio."]],
  "382": ["¿Cuál de estos movimientos accesorios puede combinarse con una movilización fisiológica?",["Una contracción isométrica del músculo","Una decoaptación articular","Un impulso rápido de grado V"],["La contracción muscular no es un movimiento accesorio.","La movilización fisiológica puede asociarse a rotaciones, a deslizamientos anteriores, posteriores o laterales, y a decoaptaciones.","El grado V es un grado de amplitud, no un movimiento accesorio."]],
  "383": ["¿En qué se concentra el tratamiento cuando una dirección de movimiento está alterada?",["En el fortalecimiento de los músculos motores de esa dirección","En el estiramiento de las estructuras opuestas a esa dirección","En el restablecimiento del accesorio en esa dirección"],["El fortalecimiento muscular no es la respuesta descrita.","El estiramiento de los antagonistas no es la conducta establecida.","Cuando una dirección revela alteraciones clínicas o biomecánicas, el tratamiento se concentra en el restablecimiento del movimiento accesorio en ese movimiento preciso."]],
  "384": ["¿Qué representa R1 en un diagrama de movimiento?",["El punto donde comienza la resistencia","El punto de resistencia máxima","El punto donde el espasmo detiene el movimiento"],["R1 marca el inicio de la resistencia, R2 la resistencia máxima.","La resistencia máxima se anota R2.","La detención por el espasmo se anota E2."]],
  "385": ["En un paciente rígido, ¿cuál es el objetivo del tratamiento en el diagrama?",["Desplazar la resistencia hacia la izquierda","Desplazar la resistencia hacia la derecha","Acercar P1 al origen del diagrama"],["Un desplazamiento hacia la izquierda traduciría un agravamiento de la rigidez.","En el paciente rígido, en el que hay que dominar la resistencia, el objetivo del tratamiento es desplazar R hacia la derecha del diagrama.","Acercar el inicio del dolor al origen significaría una sensibilización."]],
  "386": ["¿Qué significa P2 en un diagrama del dolor?",["El punto preciso donde el dolor comienza a aparecer","El límite fisiológico del movimiento pasivo","El dolor máximo que se acepta infligir"],["El inicio del dolor se anota P1.","El límite del movimiento se representa con la línea L.","P2 es el dolor máximo que el paciente o el terapeuta está dispuesto a infligir, mientras que P1 marca el inicio del dolor."]],
  "387": ["¿Qué representan E1 y E2 en un diagrama integrado?",["El inicio del espasmo y su punto de detención del movimiento","El inicio y el máximo de la resistencia tisular","El inicio y el máximo del dolor percibido"],["E1 marca el inicio del espasmo muscular, E2 el punto donde el espasmo detiene el movimiento.","La resistencia se anota R1 y R2.","El dolor se anota P1 y P2."]],
  "388": ["¿Sobre qué sistemas actúa la estimulación mecánica de la terapia manual?",["Únicamente sobre el sistema nervioso periférico del miembro","Sobre los sistemas nerviosos central y periférico","Únicamente sobre el sistema nervioso autónomo"],["La acción supera el nivel periférico.","La terapia manual mediante estimulación mecánica produce respuestas neurofisiológicas en el sistema nervioso central y periférico, que modulan el dolor.","La acción no se limita al sistema autónomo."]],
  "389": ["¿Qué efecto periférico produce la terapia manual?",["Bloquea la conducción de las fibras nerviosas mielinizadas","Aumenta la permeabilidad capilar local","Actúa sobre los mediadores inflamatorios y los nociceptores"],["No se describe ningún bloqueo de conducción.","El aumento de la permeabilidad no es el efecto referido.","A nivel periférico, la terapia manual afecta directamente a los mediadores inflamatorios y a los nociceptores."]],
  "390": ["¿Qué sustancia ve DISMINUIR su tasa bajo el efecto de la terapia manual?",["La sustancia P local","Las betaendorfinas","Los cannabinoides endógenos"],["Las terapias manuales disminuyen la sustancia P, la serotonina, la anandamida, la N-palmitoiletanolamina y el TNF alfa en el lugar de la lesión.","Las betaendorfinas aumentan al contrario.","Los cannabinoides endógenos aumentan igualmente."]],
  "391": ["¿Qué sustancias ven AUMENTAR su tasa bajo el efecto de la terapia manual?",["La sustancia P y el TNF alfa del lugar lesionado","Las betaendorfinas y los cannabinoides","La serotonina y la anandamida periféricas"],["Esos dos mediadores disminuyen al contrario.","La terapia manual aumenta las betaendorfinas y los cannabinoides endógenos, al tiempo que baja las sustancias proinflamatorias.","Esas sustancias figuran entre las que disminuyen en el lugar lesional."]],
  "392": ["¿Qué efecto central ejerce la terapia manual sobre el dolor persistente?",["Aumenta la actividad de las regiones supramedulares","No tiene ningún efecto documentado sobre el dolor crónico","Puede inhibir la sensibilización central"],["Se observa al contrario una tendencia a la disminución de esas regiones.","Se refiere explícitamente un efecto sobre la sensibilización central.","La terapia manual puede inhibir la sensibilización central de los dolores musculoesqueléticos persistentes."]],
  "393": ["¿Cómo proceder cuando un movimiento accesorio provoca síntomas?",["Realizarlo en diferentes ángulos, menos sintomáticos","Abandonarlo definitivamente en favor del fisiológico","Ejecutarlo más rápido para franquear el dolor"],["Se pueden efectuar los movimientos accesorios en diferentes ángulos, menos sintomáticos, buscando mejorarlos.","Hay que intentar al contrario mejorarlo.","Franquear el dolor es contrario al principio del método."]],
  "394": ["¿Por qué puede estar limitada la cantidad de movilidad?",["Por una rigidez, una debilidad o una aprensión","Por una rigidez, un dolor o un espasmo","Por un dolor, un edema o una inestabilidad"],["La debilidad y la aprensión no figuran entre los tres factores.","Los tres factores que limitan la cantidad de movilidad son la rigidez, el dolor y el espasmo.","El edema y la inestabilidad no son los factores establecidos."]],
  "395": ["¿Cómo se caracteriza un diagrama de resistencia predominante?",["El dolor domina y limita por sí solo el movimiento","El espasmo detiene el movimiento antes de toda resistencia","La resistencia domina, con un dolor leve"],["Un cuadro dominado por el dolor daría un diagrama de dolor predominante.","La detención por el espasmo daría un diagrama de espasmo.","En ese diagrama integrado, la resistencia domina el cuadro mientras que el dolor se mantiene leve, en torno a 5 sobre 10."]],
  "396": ["¿Cuánto dura la rigidez matinal de la artrosis del tobillo?",["Más de una hora","Toda la mañana, sin mejoría","Menos de treinta minutos"],["Una rigidez prolongada evoca una afectación inflamatoria.","Una rigidez permanente no es la descrita.","La artrosis del tobillo da una rigidez matinal breve, de menos de treinta minutos."]],
  "397": ["¿Qué efecto puede tener un dolor de la rodilla o de la cadera sobre el tobillo?",["Aumenta la carga mecánica sobre el tobillo y el pie","Reduce la carga mecánica sobre el retropié en apoyo","No tiene ningún efecto medible sobre la marcha"],["El dolor del pie, de la rodilla o de la cadera modifica la marcha, lo que puede aumentar la carga mecánica sobre el tobillo y el pie.","La carga aumenta al contrario.","Se describe efectivamente un efecto sobre la zancada."]],
  "398": ["¿Por qué extender el tratamiento del hallux rigidus a la cadena posterior?",["Porque controla la dorsiflexión del dedo gordo","Porque su retracción sobrecarga el antepié en el despegue","Porque estabiliza la bóveda plantar transversal"],["La dorsiflexión del dedo gordo no depende de esa cadena.","La retracción de la cadena posterior aumenta la presión sobre el antepié durante la fase de despegue, lo que agrava el dolor articular.","La bóveda transversal depende de los intrínsecos."]],
  "399": ["¿Qué compensación antálgica hay que evitar en el hallux rigidus?",["El ataque exagerado con el talón","La flexión permanente de la rodilla en apoyo","La marcha en supinación del pie"],["El ataque con el talón no es la compensación descrita.","La flexión de la rodilla en apoyo no es la compensación descrita.","La reeducación de la marcha busca evitar las compensaciones antálgicas, como caminar supinando el pie."]],
  "400": ["¿Qué precaución tomar con las técnicas de tejidos blandos al inicio del manejo de la metatarsalgia?",["No ejercer un impacto excesivo en las primeras etapas","No asociarlas nunca a los ejercicios activos","Aplicarlas solo después de seis meses de tratamiento"],["Esas técnicas completan el ejercicio, pero conviene no ejercer un impacto excesivo en las primeras etapas.","Deben precisamente asociarse a los ejercicios.","No se plantea ningún plazo de ese tipo."]],
  "401": ["¿Cuál es el objetivo principal del tratamiento articular del hallux rigidus?",["Redistribuir la presión sobre el antepié","Restaurar la artrocinemática y romper las adherencias","Aumentar la tolerancia de la fascia a la carga"],["La redistribución de presión es el objetivo de la metatarsalgia.","El objetivo principal es restaurar la artrocinemática de la primera metatarsofalángica y romper las adherencias capsulares que limitan la extensión.","La tolerancia de la fascia es el objetivo de la fasciopatía plantar."]],
  "402": ["¿Qué técnica articular se utiliza en el hallux rigidus?",["Los deslizamientos posteriores talocrurales","Los deslizamientos laterales subastragalinos","La tracción con deslizamientos dorsal y plantar"],["Esos deslizamientos conciernen al tobillo.","Esos deslizamientos conciernen al retropié.","La movilización metatarsofalángica asocia tracción y deslizamientos dorsal y plantar para mejorar la amplitud y aliviar el dolor."]],
  "403": ["¿Qué ejercicio es la piedra angular del tratamiento del hallux rigidus?",["El fortalecimiento del flexor largo del hallux","El estiramiento pasivo de la fascia plantar medial","La movilización accesoria de la talocrural"],["El fortalecimiento del flexor largo del hallux es la piedra angular del ejercicio.","El estiramiento pasivo no es la piedra angular.","La movilización depende del tratamiento articular."]],
  "404": ["¿Cuál es el interés de un flexor largo del hallux fuerte?",["Aumenta la dorsiflexión pasiva del tobillo","Estabiliza la falange proximal y mejora la propulsión","Reduce la tensión del tendón de Aquiles en el despegue"],["La dorsiflexión del tobillo no es su función.","Un flexor largo del hallux fuerte estabiliza la falange proximal y mejora la propulsión, protegiendo la articulación dañada.","No se describe ninguna acción de ese tipo."]],
  "405": ["¿Qué hay que descartar antes de tratar una metatarsalgia?",["Una bursitis retrocalcánea asociada","Una retracción gastrosólea marcada","Una fractura de estrés y un edema óseo"],["La bursitis retrocalcánea concierne al retropié.","La retracción gastrosólea se trata, no se descarta.","Hay que descartar toda fractura de estrés y todo edema óseo."]],
  "406": ["¿Cuánto tiempo alivia el vendaje de Mulligan la talalgia aguda?",["De siete a diez días","De dos a tres semanas","De tres a seis meses"],["El vendaje puede reducir el dolor en las fases agudas, durante siete a diez días, el tiempo que tarda el ejercicio en hacer efecto.","Ese plazo corresponde al efecto de un corticoide.","Ese plazo es muy superior al establecido."]],
  "407": ["¿Cuál es el objetivo clave del tratamiento de la talalgia?",["Restaurar la artrocinemática del primer radio","Aumentar la tolerancia de la fascia a la carga","Redistribuir la presión sobre el antepié"],["Ese objetivo concierne al hallux rigidus.","La clave es aumentar la tolerancia de la fascia a la carga.","Ese objetivo concierne a la metatarsalgia."]],
  "408": ["¿Cuál es el mecanismo del síndrome de Haglund?",["Una degeneración entesopática de la fascia plantar","Un desequilibrio de las cargas sobre la bóveda transversal","Un roce mecánico de la exostosis con el tendón y la bursa"],["Esa degeneración caracteriza a la fasciopatía plantar.","Ese desequilibrio caracteriza a la metatarsalgia.","La prominencia ósea posterosuperior del calcáneo provoca un roce mecánico con el tendón de Aquiles y la bursa retrocalcánea."]],
  "409": ["¿Qué hueso afecta el desgaste cartilaginoso de la artrosis del tobillo?",["La tibia, el peroné y el astrágalo","El calcáneo y el cuboides","Los metatarsianos y las falanges"],["El desgaste progresivo afecta al cartílago articular de la tibia, del peroné y del astrágalo.","Esos huesos no son los descritos.","Esos huesos dependen de la artrosis del pie."]],
  "410": ["¿Dónde asienta el dolor del hallux rigidus?",["En la eminencia medial del primer metatarsiano","En la cara dorsal de la primera metatarsofalángica","Bajo las cabezas metatarsianas, en la planta"],["La eminencia medial es la sede del dolor del hallux valgus.","El dolor es dorsal, a nivel de la primera articulación metatarsofalángica.","Esa localización corresponde a la metatarsalgia."]],
  "411": ["¿Qué factor morfológico expone a la tendinopatía del tibial posterior?",["Una bóveda plantar sobredesarrollada","Un primer metatarsiano largo o elevado","Una diferencia de longitud de las piernas"],["El pie cavo se cita para el síndrome de Haglund.","Esa anatomía se cita para el hallux rigidus.","Las personas con sobrepeso y que presentan una diferencia de longitud de las piernas están más expuestas."]],
  "412": ["¿Qué mide el cuestionario VISA-A?",["El dolor, la función y la actividad física","El estadio degenerativo del tendón en la imagen","La fuerza isométrica del tríceps sural"],["El cuestionario VISA-A evalúa el dolor, la función y la capacidad de practicar una actividad física en las tendinopatías de Aquiles.","El estadio en la imagen no forma parte de ese cuestionario.","La fuerza no forma parte de ese cuestionario."]],
  "413": ["¿Dónde asienta el punto doloroso de la palpación localizada del tendón de Aquiles?",["Directamente sobre la tuberosidad medial del calcáneo","De 2 a 6 cm por encima de la inserción calcánea","Sobre el borde posterosuperior del calcáneo"],["Esa localización corresponde a la fasciopatía plantar.","El dolor a la presión asienta generalmente 2 a 6 cm por encima de la inserción calcánea.","Esa localización corresponde al síndrome de Haglund."]],
  "414": ["¿Qué limitación del tobillo aumenta las cargas sobre la fascia plantar?",["La limitación de la flexión plantar","La limitación de la eversión del pie","La limitación de la dorsiflexión"],["La flexión plantar no es la limitación descrita.","La eversión no es la limitación descrita.","Una dorsiflexión limitada del tobillo aumenta las cargas sobre la fascia y la entesis."]],
  "415": ["¿Qué articulación afecta principalmente la artrosis del pie?",["La metatarsofalángica del dedo gordo","La articulación subastragalina","La articulación talocrural"],["La artrosis del pie afecta principalmente a la metatarsofalángica del dedo gordo y a las articulaciones metatarsianas.","La subastragalina no es la diana principal.","La talocrural depende de la artrosis del tobillo."]],
  "416": ["¿Qué dificultad provoca la rigidez del dedo gordo al caminar?",["Una dificultad de ataque del talón","Una dificultad de propulsión","Una dificultad de equilibrio monopodal"],["El ataque del talón no es el tiempo alterado.","La rigidez del dedo gordo dificulta la propulsión durante la marcha.","El equilibrio monopodal no es la dificultad descrita."]],
  "417": ["¿Qué muestra la reducción del dolor de la rodilla o de la cadera sobre la marcha?",["Solo mejora el dolor, sin efecto funcional","Alarga la zancada y aumenta la carga distal","Modifica la zancada y reduce el estrés articular"],["Se describe efectivamente un efecto funcional.","Ese efecto es contrario al descrito.","Modificar o reducir el dolor del paciente modifica su zancada, lo que contribuye a la mejora funcional y a la reducción del estrés articular."]],
  "418": ["¿Qué busca la prueba de impingement dorsal del dedo gordo?",["Un dolor por choque óseo en dorsiflexión máxima","Una hipermovilidad del primer metatarsiano","Una tensión aumentada de la fascia plantar medial"],["La prueba de impingement dorsal reproduce el dolor durante un intento de dorsiflexión máxima, por choque óseo.","La hipermovilidad se explora con la prueba de movilidad del primer radio.","La tensión fascial se explora con la prueba de Windlass."]],
  "419": ["¿Cómo se distingue el hallux limitus del hallux rigidus?",["El hallux limitus afecta a la mujer, el hallux rigidus al hombre","El hallux limitus es el estadio inicial, el hallux rigidus el estadio final","El hallux limitus es doloroso, el hallux rigidus indoloro"],["La distinción no se basa en el sexo.","Los resultados de la exploración permiten diferenciar el hallux limitus, estadio inicial, del hallux rigidus, estadio final.","La distinción no se basa en el dolor."]],
  "420": ["¿Qué muestra la terapia manual articular comparada con la termoterapia sola en el hallux rigidus?",["Resultados estrictamente idénticos sobre el dolor","Un agravamiento de la rigidez capsular","Una mejora mayor de la dorsiflexión activa"],["Se describe efectivamente una diferencia significativa.","No se refiere ningún agravamiento.","Los pacientes tratados con terapia manual articular mostraron una mejora significativamente mayor de la dorsiflexión activa y una reducción del dolor."]],
  "421": ["¿Qué deformidad define el hallux valgus?",["Una desviación lateral del dedo gordo con prominencia medial","Una rigidez progresiva en dorsiflexión del dedo gordo","Una exostosis posterosuperior del calcáneo"],["El hallux valgus asocia una desviación lateral del dedo gordo y una prominencia medial de la cabeza del primer metatarsiano.","La rigidez en dorsiflexión caracteriza al hallux rigidus.","Esa exostosis caracteriza al síndrome de Haglund."]],
  "422": ["¿Qué complicación secundaria acompaña a menudo al hallux valgus?",["Una bursitis retrocalcánea posterior","Una metatarsalgia por transferencia de carga","Una tendinopatía aquílea insercional"],["La bursitis retrocalcánea depende de la talalgia posterior.","El hallux valgus comporta a menudo una metatarsalgia secundaria, debida a la transferencia de carga.","Esa tendinopatía depende del síndrome de Haglund."]],
  "423": ["¿Qué busca la prueba de movilidad del primer radio?",["Una limitación de la dorsiflexión del dedo gordo","Una tensión anormal de la fascia plantar","Una hipermovilidad del primer metatarsiano"],["Esa limitación se explora con la prueba de dorsiflexión.","La tensión fascial se explora con la prueba de Windlass.","La prueba de movilidad del primer radio evalúa la hipermovilidad del primer metatarsiano, factor predisponente."]],
  "424": ["¿Qué detecta la prueba de pronación del hallux?",["El componente rotacional de la deformidad","La hipermovilidad del primer metatarsiano","El bloqueo óseo dorsal al final del recorrido"],["La prueba de pronación del hallux detecta el componente rotacional de la deformidad.","La hipermovilidad se explora con la prueba del primer radio.","El bloqueo dorsal se explora en el hallux rigidus."]],
  "425": ["¿Cuál de estos músculos es una diana del tratamiento del hallux valgus?",["El músculo poplíteo del hueco poplíteo","El aductor del dedo gordo","El músculo cuadrado lumbar"],["El poplíteo es una diana del tratamiento de la rodilla.","Los tejidos diana comportan el tríceps sural, los tibiales, los extensores de los dedos, el flexor corto y el aductor del dedo gordo.","El cuadrado lumbar es una diana del tratamiento de la cadera."]],
  "426": ["¿Qué síntoma puede acompañar a un neuroma de Morton?",["Una rigidez matinal del dedo gordo","Un dolor posterior en el talón con el esfuerzo","Parestesias del antepié"],["La rigidez matinal del dedo gordo evoca el hallux rigidus.","Ese dolor evoca una afectación aquílea.","La metatarsalgia puede coexistir con parestesias, en el marco de un neuroma de Morton."]],
  "427": ["¿Qué alteración de la bóveda participa en el desequilibrio de las cargas del antepié?",["La alteración de la bóveda transversal","La alteración de la bóveda longitudinal medial","La alteración de la alineación del retropié"],["El desequilibrio de las cargas del antepié se debe a alteraciones del primer radio y de la bóveda transversal.","La bóveda longitudinal la mantienen los intrínsecos.","La alineación del retropié se cita para la fasciopatía."]],
  "428": ["¿Dónde asienta el dolor de la tendinopatía del tibial posterior?",["Bajo las cabezas metatarsianas, en la planta","En la cara medial del mediopié hasta el tobillo","En la parte posterior del talón, sobre la inserción del tendón de Aquiles"],["Esa localización corresponde a la metatarsalgia.","El dolor asienta en la cara medial del mediopié hasta el retropié o el tobillo, y se intensifica a la palpación.","Esa localización corresponde a la afectación aquílea."]],
  "429": ["¿Qué movimientos están debilitados en la tendinopatía del tibial posterior?",["La eversión y la flexión dorsal","La dorsiflexión del dedo gordo","La inversión y la flexión plantar"],["Esos movimientos no son los debilitados.","La dorsiflexión del dedo gordo depende del hallux rigidus.","El paciente presenta una disminución de la fuerza de inversión y de flexión plantar."]],
  "430": ["¿Qué dificultad funcional caracteriza la tendinopatía del tibial posterior?",["La dificultad para levantar el talón sobre una sola pierna","La dificultad para despegar el dedo gordo del suelo","La dificultad para apoyar el talón al iniciar el paso"],["El paciente tiene dificultades para levantar el talón sobre una sola pierna.","Esa dificultad depende del hallux rigidus.","El ataque del talón no es el tiempo alterado."]],
  "431": ["¿Qué hace positiva la prueba de elevación del talón sobre una pierna?",["Una hiperqueratosis plantar del lado afectado","Una diferencia de altura de despegue entre los dos lados","Un engrosamiento palpable de la fascia plantar"],["La hiperqueratosis depende de la metatarsalgia.","La prueba es positiva en caso de diferencia significativa de altura de despegue del talón entre el lado sintomático y el lado sano, con reproducción de los síntomas.","El engrosamiento fascial depende de la fasciopatía."]],
  "432": ["¿Qué evoca un dolor en el talón que sobreviene con poca carga, de forma difusa?",["Una paratendinitis aquílea","Un impingement calcáneo posterior","Una bursitis retrocalcánea"],["La paratendinitis da un dolor inflamatorio durante un movimiento suave.","El impingement calcáneo se revela en flexión plantar pasiva máxima.","El diagnóstico diferencial establece la bursitis retrocalcánea ante un dolor difuso con poca carga."]],
  "433": ["¿Qué evoca un dolor del talón reproducido en flexión plantar pasiva máxima?",["Un impingement calcáneo","Un engrosamiento de la fascia plantar","Una compresión del nervio sural"],["El impingement calcáneo da un dolor durante la flexión plantar pasiva máxima.","El engrosamiento fascial da un dolor al final de la dorsiflexión.","La compresión del nervio sural da un dolor lateral de tipo neurológico."]],
  "434": ["¿Qué evoca un dolor lateral del talón de tipo neurológico?",["Una bursitis retrocalcánea difusa","Una compresión del nervio sural","Una afectación de la grasa de Kager"],["La bursitis da un dolor difuso con poca carga.","La compresión del nervio sural da un dolor lateral de tipo neurológico.","La grasa de Kager da un dolor a la dorsiflexión por compresión."]],
  "435": ["¿Qué evoca un dolor del talón al final de la dorsiflexión?",["Una paratendinitis del tendón de Aquiles","Un impingement calcáneo posterior","Un engrosamiento de la fascia plantar"],["La paratendinitis se despierta con el movimiento suave.","El impingement se revela en flexión plantar máxima.","El engrosamiento de la fascia plantar da un dolor al final de la dorsiflexión."]],
  "436": ["¿Cuál es el signo clínico más corriente de la tendinopatía aquílea?",["El dolor a la presión del tendón","La incapacidad de realizar elevaciones de talón","El enrojecimiento de la cara posterior del calcáneo"],["El dolor a la presión del tendón, a veces acompañado de un engrosamiento fusiforme, es el signo clínico más corriente.","La incapacidad para las elevaciones es una prueba, no el signo más corriente.","El enrojecimiento posterior evoca el síndrome de Haglund."]],
  "437": ["¿Dónde asienta el dolor de la fasciopatía plantar?",["Bajo las cabezas metatarsianas, en la planta","En la inserción calcánea, en la planta medial","Sobre el borde posterosuperior del calcáneo"],["Esa localización corresponde a la metatarsalgia.","El dolor es plantar medial, a nivel de la inserción calcánea, sobre todo en los primeros pasos al levantarse.","Esa localización corresponde al síndrome de Haglund."]],
  "438": ["¿Qué mecanismo pone en juego la prueba de Windlass?",["La compresión del nervio interdigital entre los metatarsianos","El roce de la exostosis contra el tendón de Aquiles","La puesta en tensión de la fascia por dorsiflexión del hallux"],["Esa compresión se explora con la prueba de Mulder.","Ese roce caracteriza al síndrome de Haglund.","El mecanismo de Windlass aumenta la tensión de la fascia durante la dorsiflexión del hallux."]],
  "439": ["¿Qué músculo, retraído, limita la dorsiflexión en la fasciopatía plantar?",["El complejo gastrosóleo","El músculo tibial anterior","El músculo flexor largo del hallux"],["La limitación de la dorsiflexión por retracción gastrosólea figura entre los factores de riesgo.","El tibial anterior es un dorsiflexor, no un freno.","Ese músculo no es el descrito como retraído."]],
  "440": ["¿Qué explica la naturaleza degenerativa de la fasciopatía plantar?",["La curación espontánea en unas semanas","La evolución crónica y la respuesta variable","La eficacia constante de los corticosteroides"],["No se describe ninguna curación espontánea rápida.","La naturaleza degenerativa explica la evolución crónica y la respuesta variable a los tratamientos antiinflamatorios.","No se describe ninguna eficacia constante."]],
  "441": ["¿A partir de qué espesor se considera engrosada la fascia plantar?",["Por encima de 2 mm","Por encima de 10 mm","Por encima de 4 mm"],["Dos milímetros corresponde al tamaño de los osteofitos del pulgar en el estadio II.","Ese espesor es muy superior al umbral establecido.","La imagen establece un engrosamiento de la fascia por encima de 4 mm."]],
  "442": ["¿Para qué sirve la medida de la dorsiflexión con y sin flexión de la rodilla?",["Para estimar la retracción gastrosólea","Para medir el ángulo intermetatarsiano","Para cuantificar la tensión del tendón de Aquiles en reposo"],["Esa medida estima la retracción gastrosólea, que aumenta la tensión sobre la fascia.","Ese ángulo se mide en radiografía del antepié.","La tensión en reposo no es el objeto de esa medida."]],
  "443": ["¿Qué técnica mejora la inversión y la eversión en la fasciopatía plantar?",["Los deslizamientos posteriores talocrurales","La tracción y los deslizamientos laterales subastragalinos","Los deslizamientos anteroposteriores tibioperoneos"],["Esos deslizamientos mejoran la dorsiflexión.","La subastragalina se trabaja mediante tracción y deslizamientos laterales, para mejorar la eversión y la inversión.","Esos deslizamientos conciernen a la articulación proximal de la pierna."]],
  "444": ["¿Qué muestra la adición de movilizaciones vertebrales al tratamiento del pie?",["Resultados estrictamente idénticos","Un agravamiento del dolor plantar","Mejores resultados que un tratamiento local"],["Se describe efectivamente una diferencia favorable.","No se refiere ningún agravamiento.","La adición de manipulaciones o movilizaciones vertebrales al tratamiento del pie dio mejores resultados que el tratamiento del pie solo."]],
  "445": ["¿Cuál es el objetivo del tratamiento de los tejidos blandos en la fasciopatía plantar?",["Reducir la tensión de la aponeurosis y tratar los puntos gatillo","Corregir la exostosis posterosuperior del calcáneo","Redistribuir la presión bajo las cabezas metatarsianas"],["El objetivo es reducir la tensión en la aponeurosis y tratar los puntos gatillo miofasciales que provocan los dolores del talón.","La exostosis no se corrige mediante los tejidos blandos.","Esa redistribución concierne a la metatarsalgia."]],
  "446": ["¿En qué tres pilares se basa el tratamiento articular según Mulligan?",["El fallo posicional, la biomecánica y la neurofisiología","El dolor, la rigidez articular y la debilidad muscular","La evaluación, el tratamiento y la reevaluación del paciente"],["Los fundamentos del concepto son la teoría del fallo posicional, los principios biomecánicos y los principios neurofisiológicos.","Esos tres elementos son síntomas, no los fundamentos teóricos del concepto.","Esa secuencia describe el proceso clínico, no los fundamentos del concepto."]],
  "447": ["¿Qué postula la teoría del fallo posicional?",["Las técnicas alargan las estructuras capsulares acortadas","Las técnicas corrigen un defecto de posición articular","Las técnicas inhiben los receptores nociceptivos locales"],["El alargamiento capsular no es el mecanismo invocado.","La teoría postula que las técnicas corrigen los defectos de posición articular derivados de un desequilibrio muscular o de un traumatismo.","La inhibición local de los nociceptores no es la teoría planteada."]],
  "448": ["¿Cuáles son los dos orígenes del defecto de posición articular según Mulligan?",["Una artrosis evolucionada o una malformación congénita","Una inmovilización prolongada o una denervación","Un desequilibrio muscular o un traumatismo"],["Esas causas estructurales no son las descritas por la teoría.","La inmovilización y la denervación no se invocan.","El defecto de posición resulta de un desequilibrio muscular o de un traumatismo."]],
  "449": ["¿Cuál de estos elementos podría participar en el fallo posicional?",["La orientación de las fibras y la forma de los tejidos blandos","La densidad mineral del hueso subcondral adyacente","La viscosidad del líquido sinovial articular"],["Pueden estar implicadas la forma de las superficies articulares, el espesor del cartílago, la orientación de las fibras y la forma de los tejidos blandos capsulares.","La densidad ósea no figura entre los elementos citados.","La viscosidad sinovial no se menciona en esa teoría."]],
  "450": ["¿Qué puede conllevar una alteración de la posición articular?",["Una inestabilidad ligamentaria con episodios repetidos de luxación articular","Dolores, rigideces o modificaciones del tejido muscular","Una degeneración rápida del cartílago articular"],["La inestabilidad y la luxación no se describen como consecuencias.","Esas alteraciones pueden acompañarse de dolores, de rigideces o de modificaciones de los tejidos musculares.","No se evoca ninguna degeneración cartilaginosa acelerada."]],
  "451": ["¿Qué significa el hecho de que la analgesia obtenida no sea inhibida por la naloxona?",["Depende enteramente de la liberación de endorfinas","Solo es un efecto placebo ligado a la expectativa del paciente","Sigue una vía no opioide, más allá del simple efecto placebo"],["Si las endorfinas estuvieran implicadas, la naloxona bloquearía el efecto.","Es precisamente la conclusión inversa la que se extrae.","La ausencia de inhibición por la naloxona indica una vía no opioide: el efecto supera por tanto el simple placebo."]],
  "452": ["¿Por qué sistema está mediada la hipoalgesia mecánica de las técnicas de Mulligan?",["Por el sistema nervioso central, a través de sus vías descendentes","Por los receptores articulares periféricos solos","Por la liberación local de mediadores antiinflamatorios"],["La hipoalgesia mecánica está mediada por el sistema nervioso central, por modulación de las vías descendentes.","El efecto supera el nivel periférico.","No se invoca ningún mecanismo inflamatorio local."]],
  "453": ["¿Cuál de estos parámetros atestigua un efecto mediado por el sistema nervioso AUTÓNOMO?",["La actividad electromiográfica","La conductancia cutánea del paciente","El umbral de dolor medido por algometría"],["Las modificaciones electromiográficas se refieren aparte, como efecto muscular.","Los efectos autónomos se traducen por modificaciones de la frecuencia cardiaca, de la presión arterial y de la conductancia cutánea.","La algometría mide la respuesta dolorosa, no la actividad autónoma."]],
  "454": ["¿Qué secuencia describe el efecto de las movilizaciones con movimiento?",["Estiramiento capsular, y después ganancia de amplitud mecánica duradera","Inhibición refleja del músculo, y después alivio del dolor","Cambio de posición articular, y después modulación central del dolor"],["El efecto descrito no es una simple ganancia mecánica por estiramiento.","La inhibición muscular refleja no es la vía descrita.","Las MWM modifican la posición articular, lo que provoca cambios centrales que activan el sistema de modulación endógena del dolor, y mejora síntomas y función."]],
  "455": ["¿Qué requiere la movilización accesoria pasiva asociada al movimiento activo del paciente?",["Cooperación, comunicación y conocimientos","Fuerza, resistencia y velocidad de ejecución","Inmovilización previa y anestesia local"],["Esa asociación exige la cooperación del paciente, la comunicación y los conocimientos del profesional.","Esas cualidades físicas no son los requisitos enunciados.","No se requiere nada de eso: la técnica debe permanecer asintomática."]],
  "456": ["¿Cómo debe ser sentida la técnica por el paciente?",["Debe reproducir el dolor para ser eficaz","Debe ser segura y asintomática","Debe provocar una fatiga muscular franca"],["Reproducir el dolor es contrario al principio de una técnica asintomática.","Los puntos clave establecen una técnica segura y asintomática, es decir que no despierte el dolor.","No se busca ninguna fatiga muscular."]],
  "457": ["¿Qué tipo de resultado producen las técnicas de Mulligan?",["Resultados diferidos, que aparecen solo después de varias sesiones de tratamiento","Resultados definitivos desde la primera aplicación","Resultados inmediatos, cuya durabilidad se aprecia en la reevaluación"],["La inmediatez del resultado es precisamente característica.","La durabilidad no está garantizada: exige una reevaluación.","Los puntos clave establecen resultados inmediatos, quedando la durabilidad por verificar mediante la reevaluación."]],
  "458": ["¿Cuál es la indicación principal de las técnicas de Mulligan?",["El tratamiento del dolor, en particular ligado al movimiento","El tratamiento de la rigidez articular instaurada","El tratamiento del déficit de fuerza muscular"],["La indicación clínica se centra en el tratamiento del dolor y del dolor ligado al movimiento.","La eficacia es precisamente baja en los cuadros dominados por la rigidez.","El déficit de fuerza depende del ejercicio terapéutico."]],
  "459": ["¿En qué caso una limitación de movimiento es objeto de una técnica de Mulligan?",["Cuando está causada por una rigidez capsular","Cuando está causada por el dolor","Cuando está causada por una retracción muscular"],["Ante una rigidez, la eficacia del concepto es baja.","La limitación de movimiento es una indicación si el dolor es su causa; la eficacia es baja ante una rigidez verdadera.","La retracción muscular depende de los estiramientos y del trabajo del tejido blando."]],
  "460": ["¿Qué significa el acrónimo SNAG en el concepto Mulligan?",["Un deslizamiento apofisario sin movimiento activo del paciente","Una movilización pasiva de las articulaciones periféricas","Un deslizamiento apofisario natural sostenido, con movimiento activo"],["La ausencia de movimiento activo caracteriza a los NAG, no a los SNAG.","Las articulaciones periféricas dependen de las MWM.","Los SNAG son movilizaciones con movimiento de las articulaciones vertebrales, basadas en la orientación de las facetas, manteniéndose el movimiento accesorio durante la movilidad activa."]],
  "461": ["¿En qué se basa la dirección de la movilización accesoria de un SNAG?",["En la orientación de las facetas articulares","En la dirección del movimiento doloroso del paciente","En el eje de tracción longitudinal del segmento"],["La movilización accesoria del SNAG se basa en la orientación de las facetas articulares del segmento tratado.","El movimiento activo del paciente acompaña a la técnica, no dicta la dirección del deslizamiento.","No se establece ninguna tracción longitudinal como referencia."]],
  "462": ["¿Cuál es la particularidad de los NAG entre las técnicas de Mulligan?",["Es la única técnica reservada a las articulaciones periféricas","Es la única técnica descrita sin movilidad activa del paciente","Es la única técnica autorizada en caso de fractura"],["Las articulaciones periféricas son el dominio de las MWM.","Los NAG son un movimiento accesorio sostenido sin movimiento activo: es la única técnica del concepto en ese caso.","La fractura es una contraindicación de todas esas técnicas."]],
  "463": ["¿En qué región son particularmente útiles los NAG?",["En el raquis lumbar y la pelvis","En las articulaciones del miembro inferior","En el raquis cervical y torácico superior"],["Esa región no es la citada para los NAG.","El miembro inferior depende de las MWM.","Los NAG son muy útiles en el tratamiento del raquis cervical o torácico superior."]],
  "464": ["¿Qué asocia una movilización con movimiento, o MWM?",["Una movilización accesoria pasiva y una movilidad fisiológica activa","Una movilización accesoria pasiva y una tracción sostenida","Una movilización fisiológica pasiva y un estiramiento final"],["Las MWM asocian una movilización accesoria pasiva a una movilidad fisiológica activa del paciente.","Ninguna tracción entra en la definición de las MWM.","La movilidad fisiológica es ACTIVA, y no se asocia ningún estiramiento."]],
  "465": ["¿Cuál es el campo de aplicación de las MWM?",["Las articulaciones vertebrales cervicales","Las articulaciones periféricas de los miembros","Las articulaciones sacroilíacas exclusivamente"],["El raquis depende de los SNAG y de los NAG.","Las MWM están indicadas para las articulaciones periféricas, y para el dolor y los trastornos funcionales de los miembros superiores e inferiores.","No se describe ninguna restricción de ese tipo."]],
  "466": ["¿Cuál de estas situaciones es una contraindicación de las técnicas de Mulligan?",["Un dolor ligado al movimiento","Una limitación de movimiento dolorosa","Una fractura reciente no consolidada"],["El dolor ligado al movimiento es al contrario la indicación principal.","Esa limitación es una indicación posible.","Las precauciones y contraindicaciones establecen las fracturas y las lesiones intraarticulares graves."]],
  "467": ["¿Qué lesión intraarticular constituye una precaución en el concepto Mulligan?",["Una lesión grave o que hace temer el movimiento","Una condropatía incipiente asintomática","Un derrame articular mínimo y antiguo, sin dolor"],["Las lesiones intraarticulares de gravedad elevada, o que provocan una aprensión del movimiento, constituyen una precaución.","Una lesión incipiente y muda no es una precaución establecida.","Un derrame mínimo no se cita como precaución."]],
  "468": ["¿Con qué enfoques se combina el concepto Mulligan en la práctica?",["La electroterapia de alta frecuencia y el láser","El concepto Maitland, el taping y la actividad física","El drenaje linfático y la presoterapia"],["Esos agentes físicos no se citan como asociaciones establecidas.","La literatura establece la combinación clínica y científica con el Maitland, el taping o la actividad física.","El drenaje linfático no se menciona como asociación."]],
  "469": ["¿Qué se establece sobre el nivel de evidencia del concepto Mulligan?",["Su eficacia se basa únicamente en opiniones de expertos","Su eficacia no se ha evaluado nunca en ensayo controlado","Su eficacia está clínicamente probada"],["El nivel de evidencia supera la opinión de experto.","Los trabajos publicados incluyen revistas de alto impacto.","Con más de 380 artículos publicados en revistas con revisión por pares, la eficacia del concepto está clínicamente probada."]],
  "470": ["¿En qué se inscribe el concepto Mulligan en el modelo biopsicosocial?",["Preserva el movimiento pese al dolor y da un papel activo al paciente","Privilegia la corrección estructural de la lesión antes de toda reanudación del movimiento","Reserva la decisión terapéutica únicamente al profesional"],["Terapia centrada en el paciente, preserva los movimientos pese al dolor, da un papel activo al paciente y favorece la autoeficacia.","La corrección posicional sirve a la función: el movimiento no se aplaza.","El concepto está centrado en el paciente, cuya cooperación se requiere."]],
  "471": ["¿Qué noción psicológica busca promover el concepto Mulligan?",["La aceptación del dolor crónico","La autoeficacia del paciente","La dependencia del seguimiento del profesional"],["La aceptación del dolor no es el objetivo buscado.","La promoción de la autoeficacia y del funcionamiento forma parte del interés del concepto en el modelo biopsicosocial.","El concepto busca al contrario la autonomía del paciente."]],
  "472": ["¿Qué resultado obtiene el concepto Mulligan sobre la discapacidad?",["Una mejora de la discapacidad limitada a las formas agudas","Una mejora de la discapacidad sin efecto sobre el dolor","Puntuaciones altas de mejora de la discapacidad"],["No se describe ninguna restricción de ese tipo.","El tratamiento del dolor es su indicación principal.","El concepto obtiene puntuaciones altas de mejora de la discapacidad, y se combina fácilmente con otras estrategias."]],
  "473": ["¿Por qué mecanismo central actúan los movimientos repetitivos del concepto McKenzie?",["Activan los mecanismos inhibidores descendentes","Bloquean la conducción de las fibras nociceptivas","Saturan los receptores opioides medulares"],["Los movimientos repetitivos efectuados en dirección hipoalgésica activan los mecanismos inhibidores descendentes.","El concepto no invoca ningún bloqueo de conducción.","La saturación de los receptores opioides no es el mecanismo descrito."]],
  "474": ["¿En qué dirección deben realizarse los movimientos repetitivos?",["En dirección del dolor, para desensibilizar","En dirección hipoalgésica, la que alivia","En todas las direcciones, de forma alterna"],["Reproducir el dolor es contrario al principio asintomático del método.","Los movimientos repetitivos se realizan en la dirección que disminuye el dolor, llamada hipoalgésica.","El concepto se basa en una dirección precisa, propia de cada paciente."]],
  "475": ["¿Qué efecto produce el movimiento activo indoloro sobre el sistema nervioso central?",["Una inhibición duradera del córtex motor","Un aumento de la sensibilización central","Una reorganización cortical adaptativa"],["No se busca ninguna inhibición cortical.","El concepto busca al contrario reducir la sensibilización.","El aprendizaje motor indoloro y el movimiento activo facilitan una reorganización cortical adaptativa."]],
  "476": ["¿Qué beneficio psicológico procura el enfoque activo e hipoalgésico?",["Una disminución de la kinesiofobia","Una aceptación del dolor crónico","Una dependencia tranquilizadora del terapeuta"],["El enfoque activo e hipoalgésico disminuye la kinesiofobia, lo que mejora la autoeficacia y la funcionalidad.","La aceptación del dolor no es el objetivo perseguido.","El concepto busca al contrario la autonomía del paciente."]],
  "477": ["En los síndromes discogénicos, ¿qué aportan los movimientos repetitivos indoloros?",["Una rehidratación medible del disco","Una mejora del comportamiento discal y facetario","Una cicatrización definitiva del anillo fibroso"],["No se reivindica ninguna rehidratación discal.","Los movimientos repetitivos indoloros mejoran el comportamiento de las articulaciones discales y facetarias.","El concepto no pretende cicatrizar el anillo fibroso."]],
  "478": ["¿Por qué mecanismo biomecánico mejora la amplitud indolora?",["Por el estiramiento de los músculos paravertebrales","Por el aumento de la presión intradiscal","Por la descompresión de los forámenes"],["El estiramiento muscular no es el mecanismo establecido.","Aumentar la presión intradiscal iría en contra del objetivo.","La mejora de la amplitud indolora y sin periferización se atribuye a la descompresión de los forámenes."]],
  "479": ["¿En qué interfaces mecánicas reduce la carga el concepto McKenzie?",["Las del plexo lumbosacro","Las del plexo braquial","Las de las articulaciones sacroilíacas"],["El concepto reduce la carga mecánica sobre las interfaces mecánicas del plexo lumbosacro.","El plexo implicado es lumbosacro, al dirigirse el método al raquis lumbar.","Las sacroilíacas no son las interfaces citadas."]],
  "480": ["¿En qué músculos se han observado las modificaciones electromiográficas?",["El cuadrado lumbar y el psoas ilíaco","Los multífidos y los erectores del raquis","El glúteo mayor y los isquiotibiales"],["Esos músculos no son los citados por los trabajos.","Las modificaciones de la actividad electromiográfica se han observado a nivel de los multífidos y de los erectores del raquis.","Esos músculos no forman parte de las observaciones referidas."]],
  "481": ["¿Qué modificación se describe durante la extensión lumbar?",["Una inhibición completa de los multífidos","Una contracción aislada del transverso abdominal","Una modificación de la coactivación paravertebral"],["No se refiere ninguna inhibición completa.","El transverso abdominal no está implicado en esas observaciones.","Se describen modificaciones de la coactivación paravertebral durante la extensión lumbar."]],
  "482": ["¿Cuál es la indicación clínica del concepto McKenzie?",["La lumbalgia aguda o subaguda no específica","La lumbalgia crónica de más de un año","La lumbalgia de origen inflamatorio específico"],["La indicación establecida es la lumbalgia aguda o subaguda no específica.","La indicación se centra en los dolores recientes, no en la cronicidad instaurada.","Una lumbalgia específica es objeto de un diagnóstico y un tratamiento propios."]],
  "483": ["¿Desde cuánto tiempo evoluciona habitualmente el dolor en esa indicación?",["Menos de tres semanas","Menos de doce semanas","Más de seis meses"],["Tres semanas es un plazo más corto que el establecido.","En general el dolor está presente desde menos de doce semanas, lo que define el marco agudo o subagudo.","Seis meses corresponde a un dolor crónico instaurado."]],
  "484": ["¿Cuáles son los tres síndromes de la clasificación mecánica de McKenzie?",["Discogénico, facetario y muscular puro","Agudo, subagudo y crónico instaurado","Desarreglo, disfunción y postura"],["Esa clasificación anatómica no es la del concepto.","Esa clasificación cronológica no es la clasificación mecánica.","La clasificación mecánica distingue el síndrome de desarreglo, el síndrome de disfunción postural y el síndrome postural."]],
  "485": ["¿Qué síndrome representa el principal subtipo de la clasificación?",["El síndrome de desarreglo","El síndrome de disfunción postural","El síndrome postural"],["El síndrome de desarreglo es el principal subtipo: representa el 75-80 % de las lumbalgias mecánicas.","La disfunción postural es menos frecuente que el desarreglo.","El síndrome postural concierne sobre todo al sujeto joven y sigue siendo minoritario."]],
  "486": ["¿A qué corresponde el síndrome de desarreglo en el plano mecánico?",["Un acortamiento definitivo de los tejidos blandos periarticulares","Una alteración de posición con obstrucción reversible","Una sobrecarga tisular ligada a una postura prolongada"],["El acortamiento tisular caracteriza a la disfunción postural.","El desarreglo responde a una alteración de la posición normal de una estructura articular, que genera una obstrucción mecánica reversible del movimiento.","La sobrecarga postural define el síndrome postural."]],
  "487": ["¿Qué indica clínicamente un síndrome de desarreglo?",["Un dolor reproducible al final del movimiento","Un dolor intermitente aliviado por el cambio de posición","Una preferencia direccional que centraliza los síntomas"],["El dolor de final de movimiento reproducible caracteriza a la disfunción postural.","Ese perfil corresponde al síndrome postural.","El desarreglo se manifiesta por una preferencia direccional, es decir un movimiento que centraliza los síntomas."]],
  "488": ["¿Cómo se presenta el dolor del síndrome de disfunción postural?",["Mecánico, localizado y no irradiado","Brusco e irradiado al miembro inferior","Presente únicamente en las posturas mantenidas"],["La disfunción postural da un dolor mecánico localizado y no irradiado, que sobreviene al final del movimiento.","La irradiación brusca evoca un desarreglo.","Esa presentación es la del síndrome postural."]],
  "489": ["¿A qué se asocia la disfunción postural?",["A una obstrucción mecánica reversible","A tejidos acortados o cicatriciales","A una sobrecarga tisular por posición prolongada"],["La obstrucción reversible define el desarreglo.","Se asocia a tejidos acortados y cicatriciales o a inadaptaciones al movimiento, que modifican las propiedades mecánicas de los tejidos blandos.","La sobrecarga postural define el síndrome postural."]],
  "490": ["¿En qué momento del movimiento sobreviene el dolor de la disfunción postural?",["Desde el mismo inicio del movimiento","Solo después del movimiento, a distancia","Al final mismo del movimiento"],["El inicio del movimiento no es el momento descrito.","El dolor es reproducible durante la exploración, no diferido.","El dolor sobreviene generalmente al final del movimiento, no cambia de localización y sigue siendo reproducible en la exploración."]],
  "491": ["¿Qué evolución presenta el dolor de la disfunción postural después de haber sido reproducido?",["Desaparece generalmente","Persiste varias horas","Se desplaza hacia la periferia del miembro"],["El dolor conserva la misma localización, sigue siendo reproducible en la exploración y desaparece generalmente después de haberse reproducido.","La persistencia prolongada no se describe.","El desplazamiento periférico sería una periferización, propia del desarreglo."]],
  "492": ["¿Qué causas pueden estar en el origen de una disfunción postural?",["Una hernia discal aguda con conflicto radicular claro","Un traumatismo, una inflamación o una degeneración","Una sobrecarga postural en un sujeto joven"],["El conflicto discorradicular agudo depende del desarreglo.","Puede deberse a un traumatismo anterior, a afecciones inflamatorias o a procesos degenerativos.","La sobrecarga postural del sujeto joven define el síndrome postural."]],
  "493": ["¿Cuándo presenta síntomas el paciente con un síndrome postural?",["Únicamente al final de la amplitud articular","Desde los primeros grados de movimiento activo","Únicamente en posturas prolongadas"],["El dolor de final de movimiento caracteriza a la disfunción postural.","El movimiento no es el factor desencadenante de ese síndrome.","El síndrome postural solo da síntomas en las posturas mantenidas durante mucho tiempo."]],
  "494": ["¿Cómo se comporta el dolor del síndrome postural?",["Intermitente, aliviado al cambiar de posición","Permanente y agravado por todos los movimientos","Irradiado hacia el miembro inferior"],["Es intermitente y localizado, sin irradiación, y se atenúa al cambiar de posición, manteniéndose preservada la movilidad.","El dolor es intermitente, no permanente.","Es localizado y no irradiado."]],
  "495": ["¿Cuál es el estado de la movilidad en el síndrome postural?",["Está limitada en una dirección precisa","Está generalmente preservada","Está limitada al final de la amplitud solamente"],["Una limitación direccional evoca un desarreglo.","La movilidad del paciente está generalmente preservada en el síndrome postural.","La limitación de final de amplitud evoca la disfunción postural."]],
  "496": ["¿Cómo se determina la preferencia direccional de un paciente?",["Estableciendo la dirección del movimiento más álgico","Aplicando el protocolo de extensión a todos los pacientes","Buscando el movimiento repetido que centraliza los síntomas"],["El movimiento doloroso hay que evitarlo, no establecerlo.","El movimiento seleccionado es individual, no protocolario.","Se determina qué posición sostenida o qué movimiento repetitivo centraliza los síntomas: ese movimiento, individual, fundamenta el tratamiento."]],
  "497": ["¿Qué significa la centralización de los síntomas?",["El dolor asciende de la periferia hacia la región lumbar","El dolor desciende del raquis hacia el miembro inferior","El dolor se concentra en un punto gatillo único"],["La centralización es el movimiento del dolor desde la periferia hacia la región lumbar; traduce una mejora de la mecánica raquídea.","Ese trayecto define la periferización.","El punto gatillo depende del síndrome miofascial."]],
  "498": ["¿Qué valor pronóstico posee la centralización?",["Anuncia una evolución hacia la cronicidad","Se asocia a un mejor pronóstico","No tiene ningún valor pronóstico establecido"],["Es la conclusión inversa la que se extrae.","La centralización de los síntomas se asocia a un mejor pronóstico.","Su valor pronóstico favorable se establece explícitamente."]],
  "499": ["¿Qué abarca la noción de autotratamiento en el concepto McKenzie?",["Dejar que el paciente elija solo todos sus ejercicios","Limitar el número de sesiones por razones de coste","Informar y educar al paciente para que gestione su proceso"],["La autonomía se construye sobre una educación, no sobre una libre elección no guiada.","La motivación es la autonomización del paciente, no económica.","El autotratamiento supone informar y educar al paciente para que comprenda y gestione su proceso solo, y para que prosiga el tratamiento en casa."]],
  "500": ["¿Cómo se presenta habitualmente el síndrome de desarreglo?",["Bruscamente, con irradiación posible al miembro inferior","Progresivamente, sin irradiar nunca hacia el miembro","Únicamente después de una postura mantenida mucho tiempo"],["El desarreglo aparece generalmente de forma brusca, con una irradiación posible hacia los miembros inferiores.","La instauración brusca y la irradiación posible lo caracterizan.","Las posturas prolongadas caracterizan al síndrome postural."]],
  "501": ["¿Qué sostenía el modelo estructuralista del tratamiento de los tejidos blandos?",["La fuerza mecánica desencadena una cascada neurofisiológica","La técnica corrige una alteración tisular localizada","El efecto clínico depende de las expectativas del paciente"],["Esa lectura es la del modelo neurofisiológico, que ha sustituido al modelo estructuralista.","El modelo mecanicista consideraba que la técnica corregía una alteración localizada, fascia restringida o fibra acortada, derivándose el efecto clínico directamente de ese cambio estructural.","Las expectativas del paciente pertenecen al modelo neurofisiológico integral."]],
  "502": ["¿Qué papel desempeña la fuerza mecánica en el modelo neurofisiológico?",["El de un corrector de la restricción fascial","El de un inhibidor directo de los nociceptores","El de un estímulo de entrada"],["La corrección de la restricción es la lectura mecanicista.","El efecto no es una inhibición directa del nociceptor por la fuerza aplicada.","La fuerza mecánica actúa como un estímulo de entrada que desencadena la cascada de respuestas neurofisiológicas."]],
  "503": ["¿Qué muestra la síntesis de las revisiones sobre los mecanismos de la terapia manual?",["Una calidad moderada en neurología, muy baja en biomecánica","Una calidad alta para las modificaciones biomecánicas específicas","Una ausencia total de datos científicos aprovechables"],["La síntesis pone en evidencia una calidad moderada de los datos neurovasculares y neurológicos, pero extremadamente baja para las modificaciones biomecánicas específicas.","Es lo contrario: la calidad es extremadamente baja en ese punto.","Existen datos de calidad moderada en la vertiente neurológica."]],
  "504": ["¿Qué estatus dan las recomendaciones actuales al tratamiento de los tejidos blandos?",["El del mecanismo principal del cambio a largo plazo","El de un facilitador, que abre la vía al trabajo activo","El de un tratamiento sustitutivo del ejercicio"],["No constituye en sí el mecanismo de cambio a medio y largo plazo.","El tratamiento de los tejidos blandos es un facilitador: reduce temporalmente el dolor y la protección muscular, lo que permite el trabajo activo posterior.","Prepara el ejercicio, no lo sustituye."]],
  "505": ["¿Cuál de estos elementos es un mecanosensor celular?",["Los receptores opioides del sistema nervioso central","Las interneuronas inhibidoras del asta dorsal","Los canales iónicos mecanosensibles de tipo Piezo"],["Los receptores opioides pertenecen al sistema analgésico endógeno.","Esas interneuronas dependen del control de la puerta medular.","Los mecanosensores comprenden las integrinas, los canales iónicos mecanosensibles de tipo TRP y Piezo, y el citoesqueleto."]],
  "506": ["¿Qué respuesta celular adaptativa sigue a la mecanotransducción?",["Un remodelado tisular por los fibroblastos","Una proliferación de las terminaciones nerviosas libres","Una multiplicación de las fibras musculares del territorio"],["Los cambios bioquímicos conducen a un remodelado tisular por los fibroblastos, a modificaciones de la expresión génica y a la modulación de la nocicepción.","Las terminaciones libres ven su nocicepción modulada, no proliferan.","No se describe ninguna multiplicación de las fibras musculares."]],
  "507": ["¿Qué fibras activan las interneuronas inhibidoras en la teoría de la puerta?",["Las fibras de pequeño diámetro de conducción lenta","Las fibras de gran diámetro de conducción rápida","Las fibras simpáticas posganglionares"],["Las fibras pequeñas transmiten precisamente la información nociceptiva cuya transmisión se reduce.","Las aferencias de gran diámetro, que transmiten la información táctil y propioceptiva no nociceptiva, activan las interneuronas inhibidoras.","Las fibras autónomas no intervienen en ese mecanismo medular."]],
  "508": ["¿Qué neurotransmisores liberan las vías descendentes de modulación?",["Las endorfinas y las dinorfinas","La acetilcolina y el glutamato","La serotonina y la noradrenalina"],["Esos péptidos pertenecen al sistema opioide endógeno.","Esos neurotransmisores no son los citados para la modulación descendente.","Las vías descendentes del tronco cerebral hacia la médula liberan serotonina y noradrenalina."]],
  "509": ["¿A qué se asocia la disfunción del sistema opioide endógeno?",["A la cronificación del dolor","A una hipersensibilidad cutánea localizada","A una pérdida definitiva de la fuerza muscular"],["La disfunción del sistema opioide endógeno se asocia a la cronificación del dolor.","La hipersensibilidad cutánea no es la consecuencia descrita.","No se asocia ninguna repercusión de fuerza a esa disfunción."]],
  "510": ["¿Qué es la desfacilitación neuronal aguda?",["Una inhibición refleja duradera del músculo que ha sido tratado","Un descenso temporal de la excitabilidad central","Una facilitación del reclutamiento de las unidades motoras"],["El efecto es temporal, no duradero.","Es una reducción temporal de la excitabilidad del sistema nervioso central necesaria para la activación de los músculos, que compromete la capacidad de generar fuerza.","Es al contrario una disminución del reclutamiento de las unidades motoras."]],
  "511": ["¿Qué consecuencia práctica conlleva la desfacilitación neuronal aguda?",["Una mejora inmediata de la fuerza máxima","Un aumento duradero de la amplitud articular","Una capacidad de generar fuerza momentáneamente comprometida"],["El efecto es inverso: la fuerza está momentáneamente disminuida.","El efecto descrito se centra en la excitabilidad, no en la amplitud.","El descenso del reclutamiento de las unidades motoras y de la tasa de descarga compromete momentáneamente la producción de fuerza."]],
  "512": ["¿Cuál es el tamaño habitual de un punto gatillo miofascial?",["De 5 a 10 milímetros","De 2 a 3 centímetros","Menos de un milímetro"],["El nódulo palpable hipersensible mide 5 a 10 milímetros, con la consistencia de un grano de arroz.","Ese tamaño supera ampliamente el del nódulo descrito.","Un nódulo de ese tamaño no sería palpable."]],
  "513": ["¿Dónde se sitúa exactamente el punto gatillo miofascial?",["En la fascia que envuelve el músculo","En el músculo, a nivel de la placa motora","En la unión entre el tendón y el hueso"],["El curso precisa explícitamente que el punto gatillo no está en la fascia.","El punto gatillo se produce a nivel de la placa motora, unión entre la motoneurona y la fibra: asienta por tanto en el músculo, y no en la fascia.","La unión osteotendinosa no es la sede descrita."]],
  "514": ["¿Qué relación existe entre un punto gatillo y una contractura?",["El punto gatillo es una forma localizada de contractura muscular","Los dos términos designan la misma realidad clínica","No es una contractura, pero puede encontrarse en ella"],["El curso distingue explícitamente las dos entidades.","Son dos entidades distintas.","El punto gatillo se distingue de la contractura, aunque pueda asentar dentro de una contractura."]],
  "515": ["¿Cómo se obtiene una respuesta de espasmo local?",["Mediante una palpación rápida o una percusión transversal","Mediante una presión sostenida y progresiva sobre el nódulo","Mediante un estiramiento pasivo lento del músculo entero"],["La respuesta de espasmo local se provoca mediante una palpación rápida de la banda tensa, mediante una punción o mediante una percusión transversal de las fibras.","La presión sostenida reproduce el dolor, no provoca la sacudida.","El estiramiento lento no desencadena esa respuesta."]],
  "516": ["¿Qué vínculo existe entre el tamaño de un punto gatillo y el dolor que provoca?",["Un vínculo proporcional directo","No existe ningún vínculo entre ambos","Un vínculo inverso entre ambos"],["No existe ninguna proporcionalidad entre ambos.","La irritabilidad no depende del tamaño: no existe ningún vínculo entre el tamaño del punto gatillo y el dolor que provoca.","No se establece ninguna relación, ni siquiera inversa."]],
  "517": ["¿Qué caracteriza al dolor referido de un punto gatillo?",["Sigue estrictamente el trayecto de un dermatoma","Queda estrictamente limitado al nódulo palpado","No sigue el trayecto de un nervio"],["No sigue ni trayecto nervioso ni dermatoma.","Por definición se percibe a distancia del punto de origen.","El dolor referido es una sensación de presión o de quemazón que NO sigue el trayecto nervioso, con un patrón reproducible propio de cada músculo."]],
  "518": ["¿Qué alteración neuromuscular acompaña a un punto gatillo?",["Una fatiga precoz con recuperación tardía","Una hipertrofia compensadora del músculo","Un aumento de la fuerza máxima voluntaria"],["La disfunción se traduce por una fatiga precoz y una recuperación tardía, y el músculo puede estar inhibido.","No se describe ninguna hipertrofia.","El músculo está al contrario debilitado o inhibido."]],
  "519": ["¿Cuáles son los tres criterios considerados esenciales para el diagnóstico de un punto gatillo?",["Respuesta de espasmo local, signo del salto y dolor referido","Banda tensa, punto hipersensible y reproducción de los síntomas","Dolor al estiramiento, dolor a la contracción y pérdida de amplitud"],["Esos signos están asociados, pero no figuran entre los tres criterios esenciales.","El setenta por ciento de los expertos considera esenciales la banda tensa, el punto hipersensible y la reproducción de los síntomas del paciente.","Esos signos clínicos están asociados, no son esenciales."]],
  "520": ["¿Qué distingue un punto gatillo ACTIVO de un punto latente?",["La capacidad de provocar un dolor referido a distancia del nódulo","La presencia de una banda tensa palpable","La reproducibilidad de los síntomas habituales del paciente"],["Los dos tipos pueden dar un dolor referido.","La banda tensa existe en ambos casos.","Los dos pueden provocar un dolor referido: la diferencia principal reside en la reproducibilidad de los síntomas del paciente."]],
  "521": ["¿Cómo se comporta un punto gatillo LATENTE?",["Solo duele a la presión y evoluciona a menudo hacia el estado activo","Provoca un dolor espontáneo reconocido por el paciente","Desaparece espontáneamente sin volverse nunca activo"],["El punto latente permanece silencioso en reposo, se vuelve doloroso a la presión, limita la amplitud por su banda tensa y evoluciona hacia el estado activo.","El dolor espontáneo reconocido caracteriza al punto activo.","Evoluciona al contrario generalmente hacia el estado activo."]],
  "522": ["¿Qué caracteriza a la palpación en pinza?",["Se desliza el dedo perpendicularmente a las fibras superficiales","Se toma el cuerpo del músculo y se ejercen tracciones","Se asciende de la inserción del músculo hacia el nódulo que se sospecha"],["Ese gesto describe la palpación plana.","Se toma el cuerpo del músculo entre el pulgar y los demás dedos, se efectúan tracciones para identificar la banda tensa, y después fricciones transversales para encontrar el nódulo.","Ese trayecto define la palpación profunda."]],
  "523": ["¿En qué situación hay que buscar un factor de perpetuación?",["Cuando el dolor desaparece desde la primera sesión","Cuando el paciente presenta un punto gatillo latente aislado","Cuando el dolor reaparece al cabo de unos días"],["La resolución rápida no exige ninguna búsqueda de ese tipo.","Un punto latente aislado no impone esa búsqueda.","Se buscan si no se observa ningún cambio, si la mejoría es incompleta, o si el dolor reaparece al cabo de unos días."]],
  "524": ["¿Cuál de estos elementos no es un objetivo de la movilización de los tejidos blandos?",["Aumentar la fuerza máxima del músculo tratado","Estimular los mecanorreceptores para modular el dolor","Preparar los tejidos para una actividad posterior"],["Los objetivos son optimizar la reparación, restablecer la función, evitar las recidivas, estimular los mecanorreceptores y preparar los tejidos para la actividad posterior.","Ese objetivo figura explícitamente entre los establecidos.","La preparación para el ejercicio y el control motor es un objetivo central."]],
  "525": ["¿Cuál de estas técnicas pertenece al trabajo de los tejidos blandos?",["La manipulación articular de alta velocidad","La fibrólisis diacutánea instrumental","La movilización neurodinámica"],["La manipulación se dirige al tejido articular.","Las técnicas citadas son el masaje transversal profundo, la masoterapia, la liberación miofascial y la fibrólisis diacutánea.","La neurodinámica se dirige al tejido nervioso."]],
  "526": ["¿Qué precaución tomar para interpretar una sensación de final de recorrido?",["Repetir la prueba tres veces seguidas","Medir la amplitud con el goniómetro","Comparar con el lado contralateral"],["La repetición no es la precaución recomendada.","La medida goniométrica se centra en la cantidad, no en la sensación final.","Conviene proceder a una evaluación contralateral, a fin de detectar eventuales diferencias interindividuales."]],
  "527": ["En el modelo neurofisiológico, ¿qué explica el resultado clínico?",["La cascada de respuestas espinales y supraespinales","El cambio estructural obtenido sobre el tejido tratado","El alargamiento duradero de las fibras acortadas"],["Es la cascada neurofisiológica desencadenada por el estímulo mecánico, y no el cambio estructural, la que explica el resultado clínico.","Es precisamente lo que el modelo neurofisiológico descarta.","El alargamiento tisular duradero depende del antiguo modelo mecanicista."]],
  "528": ["¿Qué desencadena la activación de los mecanosensores celulares?",["Una despolarización directa de las fibras nociceptivas periféricas","Una liberación de calcio y la activación de proteínas quinasas","Una liberación inmediata de betaendorfinas"],["La cascada descrita es bioquímica intracelular, no una despolarización nerviosa.","La activación de los mecanosensores desencadena la liberación de calcio, la activación de proteínas quinasas como MAPK y FAK, y modificaciones de los factores de transcripción.","La liberación de endorfinas depende del sistema opioide endógeno."]],
  "529": ["¿Qué valor diagnóstico posee la respuesta de espasmo local?",["Un criterio indispensable para establecer el diagnóstico","Un criterio de exclusión del síndrome miofascial","Un criterio de confirmación no esencial"],["No es esencial para el diagnóstico.","Su presencia confirma más que excluye.","Su fiabilidad es limitada: puede servir de criterio de confirmación, pero no es esencial para el diagnóstico."]],
  "530": ["¿Qué traduce una sensación de final de recorrido inesperada durante una prueba pasiva?",["Una posible disfunción","Una variación normal entre individuos","Una contractura muscular aislada"],["Una sensación de final de recorrido inesperada, por ejemplo firme donde se esperaba elástica, hace sospechar una disfunción.","La variabilidad interindividual justifica precisamente la comparación contralateral, pero la anomalía queda por interpretar.","La contractura no es la conclusión que se extrae de esa prueba."]],
  "531": ["¿Cómo se realiza una palpación plana?",["Tomando el cuerpo del músculo entre el pulgar y los demás dedos de la mano","Con el dedo, perpendicularmente a las fibras, sobre un músculo superficial","Partiendo de la inserción hacia el punto sospechado"],["Esa toma define la palpación en pinza.","La palpación plana se efectúa sobre los músculos superficiales, con el dedo perpendicular a las fibras, separando la piel y deslizando después a lo largo de las fibras.","Ese trayecto caracteriza a la palpación profunda."]],
  "532": ["¿Qué es un factor de perpetuación?",["El factor que desencadenó la aparición del punto gatillo","Un factor que agrava transitoriamente el dolor con el esfuerzo","Un factor que impide la resolución pese a un tratamiento correcto"],["El factor desencadenante es el factor de activación, distinto del factor de perpetuación.","No se trata de un simple factor de agravamiento pasajero.","Los factores de perpetuación impiden la resolución del trastorno aunque haya sido correctamente diagnosticado y tratado; no se confunden con el factor de activación."]],
  "533": ["¿Cómo se consideran las expectativas del paciente en el modelo actual?",["Como una parte del mecanismo de acción","Como factores de confusión a neutralizar","Como un elemento sin influencia sobre el resultado"],["Los estímulos contextuales, entre ellos las expectativas del paciente y la alianza terapéutica, forman parte del mecanismo de acción y no de los factores de confusión.","Es precisamente la lectura que el modelo actual abandona.","Su influencia está al contrario integrada en el mecanismo."]],
  "534": ["¿Qué información transmiten las fibras de pequeño diámetro?",["La información táctil y propioceptiva","La información nociceptiva","La información térmica exclusivamente"],["El tacto y la propiocepción siguen las fibras de gran diámetro.","Las fibras de pequeño diámetro transmiten la información nociceptiva, cuya transmisión se reduce por la activación de las fibras grandes.","La modalidad térmica no es la establecida en esa descripción."]],
  "535": ["¿Qué péptidos componen el sistema opioide endógeno?",["La serotonina, la noradrenalina y la dopamina","La sustancia P, el TNF alfa y la anandamida","Las endorfinas, las encefalinas y las dinorfinas"],["Esas monoaminas intervienen en la modulación descendente, pero no son péptidos opioides.","Esos mediadores son proinflamatorios o cannabinoides.","El organismo produce sus propios analgésicos: endorfinas, encefalinas y dinorfinas, que se unen a los receptores opioides del sistema nervioso central."]],
  "536": ["¿Hacia qué equilibrio autónomo se acompaña la reducción del dolor después del tratamiento?",["Hacia un predominio parasimpático","Hacia un predominio simpático","Hacia un bloqueo completo del sistema autónomo"],["El descenso del dolor y de la tensión muscular se acompaña de un desplazamiento hacia un predominio parasimpático, objetivado por la frecuencia cardiaca y la conductancia cutánea.","El desplazamiento descrito va en el sentido inverso.","No se describe ningún bloqueo autónomo: se trata de un reequilibrio."]],
  "537": ["¿Cómo se define el síndrome de dolor miofascial?",["Un dolor difuso y generalizado, sin punto preciso","Un dolor regional procedente de puntos hipersensibles","Un dolor articular reproducido al final de la amplitud"],["El dolor es regional y se refiere a puntos precisos.","Es una afección neuromuscular caracterizada por un dolor regional persistente, procedente de puntos hipersensibles situados en bandas tensas palpables del músculo esquelético.","El dolor de final de amplitud evoca una disfunción articular."]],
  "538": ["¿Qué caracteriza a los sarcómeros a nivel de un punto gatillo?",["Están estirados más allá de su longitud de reposo","Están despolarizados permanentemente por una descarga motora continua","Están contraídos sin que un potencial de acción los haya alcanzado"],["La anomalía descrita es una contracción, no un estiramiento.","La ausencia de potencial de acción es precisamente la particularidad.","El punto gatillo se caracteriza por una hipertonía de los sarcómeros, contraídos cuando ningún potencial de acción los ha alcanzado."]],
  "539": ["¿Cómo se pone en evidencia una dermalgia refleja?",["Haciendo rodar una pinza sobre el punto gatillo","Percutiendo transversalmente las fibras del músculo","Manteniendo una contracción isométrica prolongada"],["La dermalgia refleja aparece cuando se hace rodar una pinza cutánea sobre el punto gatillo.","La percusión transversal provoca la respuesta de espasmo local.","La contracción mantenida despierta el dolor, sin definir la dermalgia."]],
  "540": ["¿Cuántos criterios esenciales hay que reunir para establecer el diagnóstico?",["Los tres obligatoriamente","Al menos dos de los tres","Uno solo basta"],["Dos criterios de tres bastan.","Se recomienda que al menos dos de los tres criterios esenciales estén presentes para establecer el diagnóstico.","Un criterio aislado no basta."]],
  "541": ["¿Dónde se sitúa un punto gatillo llamado «de inserción»?",["En el centro del cuerpo muscular","En la aponeurosis superficial del músculo","En la unión miotendinosa"],["El cuerpo del músculo es la sede del punto central.","La aponeurosis no es la sede descrita.","La clasificación por lugar distingue el punto central, en el cuerpo del músculo, y el punto de inserción, en la unión miotendinosa."]],
  "542": ["¿A qué tipo de dolor se asocia el punto gatillo activo?",["A los dolores crónicos instaurados","A los dolores agudos postraumáticos","A los dolores de origen articular"],["El punto activo, responsable de los síntomas actuales o pasados, se asocia a los dolores crónicos.","Su asociación se describe con el dolor crónico.","Se trata de un dolor muscular, no articular."]],
  "543": ["¿Cuándo se recurre a la palpación profunda?",["Sistemáticamente, antes de toda otra palpación","Cuando las demás técnicas son inaplicables","Únicamente en los músculos más superficiales"],["Llega como último recurso, no en primera intención.","La palpación profunda se reserva a los casos en que las técnicas anteriores son inaplicables; se hace de la inserción hacia el punto sospechado.","Los músculos superficiales dependen de la palpación plana."]],
  "544": ["¿Cuál de estos elementos es un factor de perpetuación reconocido?",["Una sobrecarga muscular aguda reciente","Un traumatismo directo sobre el músculo","Una carencia de vitamina D"],["La sobrecarga aguda es un factor de ACTIVACIÓN, no de perpetuación.","El traumatismo directo es igualmente un factor desencadenante.","Los ejemplos citados comprenden los problemas endocrinos y las carencias de vitaminas D, E y ácido fólico, las parasitosis, las asimetrías y las radiculopatías."]],
  "545": ["¿Cuál es el objetivo de la neurodinámica?",["Restablecer la homeostasis dentro y alrededor del sistema nervioso","Fortalecer los músculos inervados por el nervio afectado","Corregir un defecto de posición de la articulación vecina"],["La neurodinámica busca restablecer la homeostasis en el sistema nervioso y a su alrededor, movilizando el propio nervio o las estructuras que lo rodean.","El fortalecimiento muscular no es el objeto de la neurodinámica.","La corrección posicional pertenece al concepto Mulligan."]],
  "546": ["¿Qué facilita la movilización neuronal?",["El deslizamiento de las superficies articulares entre sí","El movimiento entre las estructuras nerviosas y su interfaz","La difusión de los fármacos en el tejido nervioso"],["El deslizamiento articular depende de la movilización articular.","La movilización facilita el movimiento entre el nervio y las estructuras que lo rodean, su interfaz, mediante técnicas manuales o ejercicios.","No se describe ningún efecto de difusión farmacológica."]],
  "547": ["¿Cuál de estos efectos no pertenece a la neurodinámica?",["La evacuación del edema intraneural","La dispersión de los mediadores inflamatorios","El aumento de la presión extraneural"],["La evacuación del edema intraneural es un efecto reconocido.","La dispersión de los mediadores inflamatorios forma parte de los efectos.","Es lo contrario: la neurodinámica reduce el edema y la presión extraneural."]],
  "548": ["¿Qué secuencia describe la evolución de una compresión nerviosa no aliviada?",["Hipoxia, edema, inflamación y después fibrosis","Edema, hipoxia, desmielinización y después regeneración","Inflamación, fibrosis y después recuperación espontánea"],["La secuencia descrita es la hipoxia local, el edema, la inflamación y a la larga la fibrosis.","El orden propuesto no corresponde a la secuencia descrita.","No se describe ninguna recuperación espontánea en caso de compresión persistente."]],
  "549": ["¿Qué células se dañan cuando la hipoxia nerviosa persiste?",["Las células de Schwann de la vaina de mielina","Las células endoteliales de los capilares del nervio","Los cuerpos celulares del ganglio raquídeo"],["Las células de Schwann no son las citadas en ese mecanismo.","La hipoxia persistente daña las células endoteliales capilares del nervio, lo que agrava el edema y la disfunción.","El ganglio está implicado en la hiperexcitabilidad, no en esa lesión endotelial."]],
  "550": ["¿Cómo se comporta un nervio inflamado frente a las fuerzas mecánicas?",["Se vuelve insensible debido al bloqueo de conducción","Solo reacciona una vez que la velocidad de conducción ha bajado claramente en el trayecto","Se vuelve muy sensible, aunque la velocidad de conducción siga siendo normal"],["Se vuelve al contrario hipersensible.","La sensibilidad precede a toda alteración de la conducción.","Un nervio inflamado se vuelve muy sensible a las presiones y a los estiramientos, mientras que la velocidad de conducción puede seguir siendo globalmente normal."]],
  "551": ["¿Qué explica la aparición de potenciales de acción ectópicos?",["Un aumento de los canales iónicos en las zonas desmielinizadas","Una disminución del número de canales iónicos membranarios","Una rotura completa del axón en el punto de compresión"],["Los potenciales ectópicos se explican por la multiplicación de los canales iónicos en las zonas desmielinizadas e inflamadas, y por la presencia de mediadores inflamatorios.","Es un aumento, no una disminución, lo que se describe.","No se requiere ninguna sección axonal para ese fenómeno."]],
  "552": ["¿Cuál de estos mediadores activa las zonas nerviosas anormales?",["El factor de crecimiento nervioso","La interleucina 6 inflamatoria","La serotonina de las vías descendentes"],["El NGF interviene en la respuesta neuroinmunitaria, descrita aparte.","Los mediadores citados son el TNF alfa, la interleucina 6 y la sustancia P.","La serotonina pertenece a la modulación descendente, no a los mediadores locales citados."]],
  "553": ["¿Qué hiperalgesia disminuye la movilización nerviosa?",["La hiperalgesia química exclusivamente","La hiperalgesia visceral referida","La hiperalgesia térmica y mecánica"],["La modalidad química no es la citada.","La hiperalgesia visceral no entra en ese marco.","La movilización disminuye la hiperalgesia térmica y mecánica, es decir el dolor al calor, al frío y a la presión."]],
  "554": ["¿Cómo se comporta el factor de crecimiento nervioso en un tejido inflamado?",["Está generalmente sobreexpresado","Está fuertemente disminuido","Se mantiene en un nivel estrictamente normal"],["El NGF está generalmente sobreexpresado en los tejidos inflamados, se trate de músculo, de nervio o de articulación.","Es una sobreexpresión, no un descenso, lo que se describe.","Su expresión está precisamente modificada por la inflamación."]],
  "555": ["¿Qué efecto produce el factor de crecimiento nervioso sobre los nociceptores?",["Los desensibiliza de forma duradera","Los sensibiliza más","Bloquea su transducción mecánica"],["Su efecto es sensibilizador, no lo contrario.","El NGF sensibiliza los nociceptores y estimula la expresión de otros mediadores proinflamatorios.","No se describe ningún bloqueo de transducción."]],
  "556": ["¿Por qué el rebrote de las fibras nerviosas favorecido por el NGF puede mantener el dolor?",["Porque se acompaña siempre de una desmielinización","Porque conlleva una compresión de los fascículos vecinos","Porque a veces es desorganizado en contexto patológico"],["No se describe ninguna desmielinización sistemática.","La compresión de los fascículos no es el mecanismo invocado.","El NGF favorece el rebrote de las fibras, pero a veces de forma desorganizada en los contextos patológicos, lo que contribuye a la persistencia del dolor."]],
  "557": ["¿Qué estructura central interviene en la modulación descendente movilizada por la neurodinámica?",["La sustancia gris periacueductal","El ganglio de la raíz dorsal","El córtex somestésico primario"],["Los mecanismos centrales citados comprenden la sustancia gris periacueductal y el gate control.","El ganglio raquídeo es una estructura periférica.","El córtex somestésico no es la estructura citada."]],
  "558": ["¿Qué efecto produce la movilización neurodinámica sobre la sumación temporal?",["La aumenta claramente","La disminuye","La deja inalterada"],["El efecto descrito es una disminución.","La movilización neurodinámica conlleva una disminución de la sumación temporal y una modulación de los opioides endógenos.","Se refiere explícitamente una modificación."]],
  "559": ["¿Qué compromete una deformación nerviosa superior a la tolerancia fisiológica?",["La continuidad anatómica del axón","La producción de mielina por las células de Schwann","El flujo sanguíneo intraneural"],["La rotura axonal no es la consecuencia descrita.","La mielinización no es el mecanismo implicado.","Más allá de la tolerancia, la deformación compromete el flujo sanguíneo intraneural y conlleva una disfunción."]],
  "560": ["¿Sobre qué nos informa la mecanosensibilidad de un nervio?",["Sobre su tolerancia a la deformación mecánica","Sobre su velocidad de conducción nerviosa","Sobre el grado de desmielinización de sus fibras"],["La mecanosensibilidad informa sobre la tolerancia del nervio a la deformación mecánica: un nervio sensible reacciona con dolor a las fuerzas aplicadas.","La velocidad de conducción se evalúa mediante la electrofisiología.","El grado de desmielinización no se evalúa mediante esas pruebas clínicas."]],
  "561": ["¿Cómo aplican las pruebas neurodinámicas una fuerza al nervio?",["Aplicando una presión directa sobre el trayecto del nervio","Combinando movimientos del raquis y de los miembros","Estimulando eléctricamente el nervio a distancia"],["La presión directa no es el principio de esas pruebas.","Las pruebas combinan movimientos específicos de la columna y de los miembros para aplicar fuerzas mecánicas dirigidas, que aumentan tensión, deslizamiento y compresión.","No interviene ninguna estimulación eléctrica."]],
  "562": ["¿Qué es el principio de diferenciación estructural?",["Comparar la amplitud obtenida con la del lado contralateral","Repetir la prueba modificando la velocidad de ejecución","Modificar los síntomas mediante un movimiento de otra región"],["La comparación contralateral es una etapa del procedimiento, no la diferenciación estructural.","La velocidad de ejecución no interviene en ese principio.","La diferenciación estructural consiste en modificar los síntomas mediante un movimiento en otra región del cuerpo que implique también al sistema nervioso, por ejemplo una inclinación cervical contralateral."]],
  "563": ["¿Cuál es la primera etapa de una prueba neurodinámica estandarizada?",["Evaluar los síntomas en reposo, en posición de partida","Añadir de entrada todos los parámetros de carga","Realizar directamente la maniobra de diferenciación"],["Se evalúan primero los síntomas en reposo en posición de partida, y después se explora el miembro contralateral antes de añadir los parámetros de carga uno por uno.","Los parámetros se añaden uno por uno, para detectar la aparición de los síntomas.","La diferenciación llega después de la aparición de los signos o síntomas."]],
  "564": ["¿Qué lado se explora primero en una prueba neurodinámica?",["El miembro sintomático","El miembro contralateral","Los dos simultáneamente"],["El lado afectado se explora después del lado sano.","Se evalúa primero el miembro contralateral, lo que proporciona la referencia de comparación.","Las pruebas se realizan sucesivamente, según una secuencia siempre idéntica."]],
  "565": ["¿Cuál de estas situaciones contraindica una prueba neurodinámica?",["Un dolor reproducido por un movimiento activo","Una mecanosensibilidad aumentada conocida del nervio","Síntomas de la cola de caballo"],["La reproducción del dolor al movimiento es al contrario el motivo de la exploración.","La mecanosensibilidad aumentada es lo que la prueba busca confirmar.","Las contraindicaciones comprenden los síntomas de la cola de caballo, los estados discogénicos inestables y los trastornos neurológicos evolutivos."]],
  "566": ["¿Qué prueba neurodinámica explora el nervio MEDIANO?",["La prueba de tensión del miembro superior 1","La prueba de tensión del miembro superior 3","La prueba de flexión de la rodilla en prono"],["La primera prueba de tensión del miembro superior explora el nervio mediano, la segunda variante el radial y la tercera el cubital.","La tercera prueba explora el nervio cubital.","Esa prueba explora los dolores lumbares y la cara anterior del muslo."]],
  "567": ["¿Qué prueba explora el nervio CUBITAL?",["La prueba de tensión del miembro superior 1","La prueba de tensión del miembro superior 3","La prueba del Slump en posición sentada"],["La primera prueba explora el nervio mediano.","La tercera prueba de tensión del miembro superior es la exploración neurodinámica del nervio cubital.","El Slump explora el neuroeje y los miembros inferiores."]],
  "568": ["¿Cuál es la indicación de la prueba de elevación de la pierna extendida?",["Una afectación del nervio radial en el codo","Una afectación del neuroeje cervical alto","Una afectación lumbar o del miembro inferior"],["El nervio radial se explora con la segunda prueba del miembro superior.","El neuroeje se explora con el Slump.","La prueba de elevación de la pierna extendida se dirige a las afectaciones lumbares o de los miembros inferiores, en especial la hernia discal."]],
  "569": ["¿Cuál es la indicación de la prueba de flexión de la rodilla en prono?",["Los dolores lumbares y de la cara anterior del muslo","Los dolores posteriores de la pierna por hernia discal","Los dolores del antebrazo y de la mano del paciente"],["Esa prueba se dirige a los dolores lumbares y a los dolores anteriores de cadera, de muslo o de rodilla.","La hernia lumbar con ciatalgia se explora con la elevación de la pierna extendida.","El miembro superior se explora con las pruebas de tensión del miembro superior."]],
  "570": ["¿En qué situación es apropiada la técnica de deslizamiento?",["En los estadios avanzados de la rehabilitación","Cuando el sistema nervioso es muy irritable","Cuando el nervio ha perdido toda mecanosensibilidad"],["Los estadios avanzados dependen de las técnicas de tensión, más intensas.","Más suave, la técnica de deslizamiento conviene a las situaciones en que el sistema nervioso es muy irritable.","La ausencia de mecanosensibilidad no justificaría la técnica."]],
  "571": ["¿Qué distingue una técnica de TENSIÓN de una técnica de deslizamiento?",["Equilibra la tensión mediante un movimiento de sentido opuesto","Se aplica a una sola articulación del miembro","No utiliza ningún movimiento compensatorio"],["El equilibrado mediante un movimiento opuesto caracteriza al deslizamiento.","Puede movilizar una o varias articulaciones.","La técnica de tensión aplica una tracción en los dos extremos del nervio, sin movimiento compensatorio, para obtener una elongación máxima."]],
  "572": ["¿A qué momento de la rehabilitación se reservan las técnicas de tensión?",["A los estadios avanzados de la rehabilitación","A la fase aguda muy irritable","Antes de toda prueba neurodinámica"],["Más intenso, el enfoque en tensión se reserva generalmente a los estadios avanzados de la rehabilitación.","La fase muy irritable depende del deslizamiento, más suave.","El tratamiento sigue a la evaluación, no la precede."]],
  "573": ["¿Cuál es la primera consecuencia de una compresión nerviosa prolongada?",["Una fibrosis del tejido conjuntivo perinervioso","Una alteración del flujo sanguíneo intraneural","Una desmielinización segmentaria inmediata"],["La fibrosis es el término de la evolución, no su inicio.","La compresión prolongada altera primero el flujo sanguíneo intraneural, lo que conlleva una hipoxia local, después un edema, una inflamación y finalmente una fibrosis.","La desmielinización no es la primera etapa descrita."]],
  "574": ["¿Qué efecto produce la movilización nerviosa sobre el ganglio de la raíz dorsal?",["Un aumento del número de sus neuronas","Un bloqueo completo de su conducción aferente","Una reducción de la hiperexcitabilidad de sus neuronas"],["No se describe ningún aumento del número de neuronas.","No se busca ningún bloqueo de conducción.","La movilización reduce la hiperexcitabilidad de las neuronas del ganglio de la raíz dorsal y mejora su vascularización y su nutrición."]],
  "575": ["¿Qué es una prueba neurodinámica SIGNIFICATIVA?",["Una asimetría de amplitud o la aparición de síntomas desconocidos","La reproducción de los síntomas habituales, ya bien conocidos por el paciente","La ausencia de todo síntoma y de toda asimetría"],["Una prueba es significativa ante una asimetría significativa de amplitud o la aparición de síntomas desconocidos por el paciente.","La reproducción de los síntomas conocidos define una prueba positiva.","La ausencia de síntoma y de asimetría define una prueba negativa."]],
  "576": ["¿Qué elongación tolera un nervio periférico sin lesión ni síntoma?",["Del 15 al 20 %","Del 6 al 8 %","Menos del 1 %"],["Una deformación así comprometería el flujo sanguíneo intraneural.","En condiciones normales, los nervios toleran un 6-8 % de elongación sin lesión estructural ni síntoma.","Esa tolerancia sería muy inferior a la descrita."]],
  "577": ["¿Qué define una prueba neurodinámica POSITIVA?",["Una asimetría significativa de la amplitud de movimiento","La aparición de síntomas desconocidos en el paciente","Los síntomas conocidos y una diferenciación positiva"],["La asimetría de amplitud define una prueba significativa, no positiva.","Unos síntomas desconocidos hacen la prueba significativa, no positiva.","Una prueba es positiva cuando provoca los síntomas conocidos del paciente y la maniobra de diferenciación estructural es positiva."]],
  "578": ["¿Qué caracteriza a una técnica de DESLIZAMIENTO nervioso?",["Un movimiento aumenta la tensión mientras otro la disminuye","Los dos extremos del nervio se someten a tracción simultáneamente","Se aplica un solo parámetro de carga al nervio"],["El deslizamiento moviliza dos articulaciones o más para alargar el trayecto del nervio equilibrando la tensión: un movimiento la aumenta mientras el otro la relaja, es decir dos parámetros de carga.","La tracción en los dos extremos caracteriza a la técnica de tensión.","Un solo parámetro de carga caracteriza a la técnica de tensión."]],
  "579": ["¿Cuáles son los tres tipos de factores de intervención del ejercicio?",["Mecánicos, térmicos y químicos","Estructurales, nerviosos y hormonales","Articulares, musculares y tendinosos"],["Esa clasificación no corresponde a los factores descritos.","Los factores de intervención son estructurales, nerviosos y hormonales: hipertrofia y tipo de fibra, coordinación y reclutamiento, equilibrio anabólico.","Esa clasificación anatómica no es la establecida."]],
  "580": ["¿Qué factor NERVIOSO interviene en la adaptación al ejercicio?",["La hipertrofia de las fibras musculares","El equilibrio entre cortisol y testosterona","La sincronización de las unidades motoras"],["La hipertrofia es un factor estructural.","El equilibrio anabólico es un factor hormonal.","Los factores nerviosos comprenden la coordinación intermuscular e intramuscular, el reclutamiento, la frecuencia de estimulación y la sincronización."]],
  "581": ["¿Qué adaptación cardiovascular produce el ejercicio regular?",["Una disminución de la frecuencia cardiaca en reposo","Un aumento duradero de la presión arterial","Un aumento permanente de la acidosis sanguínea"],["Practicado de forma sistemática, el ejercicio produce adaptaciones que bajan la frecuencia cardiaca basal y la tensión arterial, y mejoran el aclaramiento del lactato.","La tensión arterial disminuye al contrario con el entrenamiento.","La acidosis es una respuesta aguda al esfuerzo, no una adaptación."]],
  "582": ["¿Por qué mecanismo participa el ejercicio en el control del dolor?",["Bloqueando la conducción de las fibras nociceptivas finas","Activando los mecanismos centrales y periféricos del control","Aumentando el umbral de sensibilidad de los mecanorreceptores"],["No se describe ningún bloqueo de conducción.","El ejercicio reduce el dolor mejorando la circulación, reduciendo la inflamación y activando los mecanismos centrales y periféricos de control, entre ellos la liberación de endorfinas.","No es el mecanismo enunciado para el ejercicio."]],
  "583": ["¿Cuál es el objetivo del trabajo de control motor?",["Un movimiento potente y rápido en toda circunstancia","Un movimiento estrictamente idéntico en cada repetición","Un movimiento eficaz, adaptativo y económico"],["La potencia sin control se considera inútil.","La variabilidad contextual mejora precisamente la transferencia.","El objetivo es obtener un movimiento eficaz, adaptativo y económico."]],
  "584": ["¿Por qué conviene el trabajo CONCÉNTRICO a las fases iniciales de rehabilitación?",["Porque permite la rehabilitación con poca carga mecánica","Porque no provoca ninguna fatiga muscular notable","Porque genera las ganancias de fuerza más elevadas"],["El concéntrico mejora la potencia y el trofismo y facilita la rehabilitación motora con una carga mecánica baja, lo que lo hace más seguro al inicio.","Aumenta al contrario la demanda muscular y la fatiga.","Las ganancias de fuerza más importantes vienen del trabajo excéntrico."]],
  "585": ["¿En qué momento del día es más marcada la rigidez?",["Al final de la tarde","Por la mañana, al despertar","Indistintamente, sin influencia"],["La flexibilidad es mejor al final de la tarde.","El ritmo circadiano hace que la rigidez sea mayor por la mañana que al final de la tarde.","La hora del día se cita explícitamente como factor extrínseco."]],
  "586": ["¿En qué mecanismo se basa la facilitación neuromuscular propioceptiva de tipo mantener-relajar?",["En el reflejo miotático del huso neuromuscular","Únicamente en la viscoelasticidad del tejido conjuntivo","En la inhibición autógena por el órgano tendinoso de Golgi"],["El reflejo miotático se opone al estiramiento, no se aprovecha así.","El mecanismo invocado es neurofisiológico, no puramente tisular.","La contracción voluntaria seguida de una relajación aprovecha la inhibición autógena mediada por el órgano tendinoso de Golgi."]],
  "587": ["¿Qué duración requiere habitualmente el estiramiento estático pasivo?",["De quince a sesenta segundos","De uno a dos segundos","De cinco a diez minutos seguidos"],["El estiramiento estático pasivo se mantiene de quince a sesenta segundos, sin contracción muscular.","Esa duración sería muy insuficiente.","Los estiramientos estáticos muy prolongados son objeto de precauciones."]],
  "588": ["¿En qué situación se privilegia el estiramiento estático PASIVO?",["En fase final de rehabilitación, para el control motor","En fase posoperatoria aguda y en el paciente neurológico","En el calentamiento, antes de una competición"],["La fase final depende más bien del estiramiento estático activo.","Ampliamente utilizado en rehabilitación inicial o guiada, conviene a la fase posoperatoria aguda, al dolor y al paciente neurológico.","El calentamiento depende de los estiramientos dinámicos."]],
  "589": ["¿Qué dosis semanal se establece para un efecto crónico sobre la amplitud?",["Al menos cuatro minutos por semana y por grupo muscular","Al menos sesenta minutos por semana y por grupo muscular","Al menos diez minutos por semana y por grupo muscular"],["Cuatro minutos corresponden a la dosis de una sesión única.","Esa dosis supera ampliamente el mínimo establecido.","Para un efecto crónico a lo largo de al menos cuatro semanas, hace falta un mínimo de diez minutos por semana y por grupo muscular, en dos a tres sesiones."]],
  "590": ["¿Qué duración mínima debe alcanzar un bloque de movilidad activa de calentamiento?",["De cuatro a ocho minutos","De treinta a sesenta segundos","De quince a veinte minutos"],["El bloque de movilidad activa, con o sin estiramientos dinámicos, debe durar al menos cuatro a ocho minutos.","Esa duración sería insuficiente para cumplir las funciones del calentamiento.","Esa duración supera la establecida."]],
  "591": ["¿Qué efecto metabólico produce el ejercicio sobre la glucemia?",["Aumenta la resistencia a la insulina de los tejidos","Mejora la sensibilidad a la insulina y la glucemia","Baja el metabolismo basal de forma duradera"],["El efecto es inverso: la sensibilidad a la insulina mejora.","El ejercicio mejora la sensibilidad a la insulina y contribuye a la regulación de la glucemia.","El metabolismo basal mejora, no baja."]],
  "592": ["¿Qué efecto produce el ejercicio sobre el sistema inmunitario?",["Baja de forma duradera las defensas inmunitarias del organismo","No tiene ningún efecto documentado sobre la inmunidad","Aumenta la actividad inmunitaria y regula la inflamación"],["El efecto descrito es al contrario una estimulación.","Se refiere explícitamente un efecto inmunitario.","El ejercicio aumenta la actividad inmunitaria, favoreciendo la producción de células que combaten las infecciones y regulan la inflamación."]],
  "593": ["¿Por qué asegura la musculatura profunda la estabilidad?",["Porque su brazo de palanca corto actúa a un nivel preciso","Porque se extiende sobre múltiples segmentos vertebrales","Porque contiene sobre todo fibras de tipo II"],["Insertada en la columna con un brazo de palanca corto, actúa a un nivel preciso y de forma específica: asegura la estabilidad.","La extensión sobre varios segmentos caracteriza a la musculatura superficial.","La composición en fibras no es el argumento establecido."]],
  "594": ["¿Qué distingue el feedforward del feedback en control motor?",["El feedforward corrige, el feedback anticipa","El feedforward anticipa, el feedback corrige","Los dos designan el mismo bucle sensitivomotor"],["Las dos nociones están invertidas.","El feedforward corresponde a la anticipación y el feedback a la corrección del movimiento.","Son dos mecanismos distintos y complementarios."]],
  "595": ["¿Qué mide el consumo máximo de oxígeno?",["La cantidad de oxígeno transportada por la hemoglobina en reposo","La diferencia arteriovenosa de oxígeno medida en reposo","La cantidad máxima de oxígeno captada, transportada y consumida"],["No se trata de una medida de reposo.","La diferencia arteriovenosa es una adaptación periférica, no la definición.","El consumo máximo de oxígeno es la cantidad máxima de oxígeno que el organismo puede captar, transportar y consumir en un tiempo dado: es la mejor medida de la capacidad cardiovascular."]],
  "596": ["¿Qué duración semanal de actividad reduce ya significativamente la mortalidad?",["Setenta y cinco minutos por semana","Trescientos minutos por semana","Diez minutos por semana"],["El riesgo de mortalidad, de enfermedad cardiovascular y de cáncer es significativamente menor ya con el equivalente de 75 minutos por semana.","Los niveles más altos aportan más, pero el umbral citado es más bajo.","Esa duración es muy inferior al umbral establecido."]],
  "597": ["¿Por qué produce el trabajo EXCÉNTRICO ganancias de fuerza superiores?",["Por una carga mecánica claramente menor sobre el músculo solicitado","Por una activación mayor de los puentes de actina-miosina","Por una menor solicitación propioceptiva"],["La carga es ahí al contrario más elevada.","El trabajo excéntrico activa más los puentes de actina-miosina, de ahí ganancias de fuerza superiores a las del concéntrico.","Su carga propioceptiva es precisamente elevada."]],
  "598": ["Según el modelo articulación por articulación, ¿qué provoca la hipomovilidad de una articulación?",["Una hipomovilidad idéntica de las articulaciones vecinas","Una ausencia de repercusión sobre los segmentos vecinos","Una hipermovilidad compensadora de las articulaciones adyacentes"],["La compensación va en el sentido de una hipermovilidad adyacente.","El modelo describe precisamente esa repercusión.","Al ser el cuerpo una cadena, la incapacidad de una articulación de cumplir su función impone una compensación a las articulaciones situadas por encima y por debajo."]],
  "599": ["¿Qué efecto fisiológico produce el estiramiento estático ACTIVO?",["Una inhibición recíproca y un mejor control motor","Una reducción del tono muscular por relajación pasiva","Una activación cardiorrespiratoria progresiva"],["El estiramiento estático activo, en el que el paciente contrae el antagonista, produce una inhibición recíproca y mejora el control neuromotor y la propiocepción.","El descenso del tono caracteriza al estiramiento estático pasivo.","La activación cardiorrespiratoria depende del calentamiento."]],
  "600": ["¿Qué duración acumulada hay que alcanzar en una sesión para mejorar la flexibilidad?",["Al menos treinta segundos por grupo muscular","Al menos cuatro minutos por grupo muscular","Al menos quince minutos por grupo muscular"],["Treinta segundos corresponden a una repetición, no a la dosis acumulada.","Para un efecto agudo, hacen falta al menos cuatro minutos acumulados por grupo muscular para obtener una mejora medible.","Quince minutos corresponden a los protocolos crónicos de hipertrofia."]],
  "601": ["¿Qué protocolo se establece para los estiramientos dinámicos antes de una competición?",["Tres a cuatro repeticiones mantenidas de treinta a sesenta segundos por grupo","Tres a cinco ciclos de contracción y relajación","Una a dos series de diez a quince repeticiones controladas por grupo"],["Ese formato corresponde a los estiramientos estáticos crónicos.","Ese formato corresponde a la facilitación neuromuscular propioceptiva.","En efecto agudo, se establecen una a dos series de diez a quince repeticiones controladas por grupo muscular, es decir cerca de sesenta a noventa segundos."]],
  "602": ["¿Por qué son ideales los estiramientos dinámicos en el calentamiento?",["Por su activación neuromuscular","Por su efecto analgésico inmediato","Por su ganancia de amplitud superior a las demás técnicas"],["Los estiramientos dinámicos son ideales en el calentamiento debido a su activación neuromuscular.","El efecto analgésico no es la razón invocada.","Ninguna técnica es superior en la ganancia de amplitud."]],
  "603": ["¿Cuál de estos signos traduce una pérdida de control motor?",["Una hipertrofia muscular compensadora","Un acortamiento adaptativo","Una mejora de la coordinación intermuscular"],["La hipertrofia no se cita entre las consecuencias.","La alteración de la reactividad se manifiesta por la incapacidad de moverse, la debilidad, la incoordinación, el acortamiento adaptativo, la inmovilidad articular, la espasticidad, la hipertonía y el espasmo.","La coordinación está al contrario alterada."]],
  "604": ["¿Qué elementos conducen a la consolidación de un aprendizaje motor?",["La repetición sola, en cantidad suficiente","La variabilidad contextual exclusivamente","La repetición, el sentido y la motivación"],["La repetición aislada no basta para consolidar.","La variabilidad mejora la transferencia, no consolida por sí sola.","La consolidación resulta de la asociación entre repetición, sentido y motivación."]],
  "605": ["¿Cuál de estos efectos produce el trabajo de fuerza?",["Una prevención de la sarcopenia por ganancia de densidad","Un aumento claro de la masa grasa corporal","Un descenso de la sensibilidad de los receptores a la insulina"],["La musculación aumenta la densidad muscular, lo que previene la sarcopenia, aumenta la densidad ósea y el metabolismo basal, y disminuye la masa grasa.","La masa grasa disminuye al contrario.","La sensibilidad a la insulina aumenta."]],
  "606": ["¿Qué se arriesga en ausencia de aumento progresivo de la carga?",["Una hipertrofia excesiva del músculo","El estancamiento o la lesión","Una pérdida definitiva de la coordinación"],["La hipertrofia excesiva no es el riesgo descrito.","Sin progresión de la carga, se expone al estancamiento o a la lesión.","La pérdida de coordinación no es la consecuencia citada."]],
  "607": ["¿En qué indicación es particularmente útil el trabajo excéntrico?",["El tratamiento de la hipertensión arterial grave","La rehabilitación después de una inmovilización prolongada","La prevención de las lesiones y de las tendinopatías"],["La hipertensión contraindica más bien el trabajo isométrico.","La atrofia después de una inmovilización depende más bien del trabajo concéntrico.","El trabajo excéntrico es muy útil en la prevención de las lesiones musculares y de las tendinopatías."]],
  "608": ["¿Qué relación mantiene la flexibilidad con la movilidad?",["La flexibilidad es un componente de la movilidad, sin garantizarla","La flexibilidad y la movilidad son dos términos sinónimos","La movilidad es un simple componente de la flexibilidad"],["La flexibilidad es un componente de la movilidad; por sí sola no garantiza una movilidad funcional o activa.","Las dos nociones se distinguen explícitamente.","La relación es inversa según los datos del curso."]],
  "609": ["¿A qué patología se asocia un déficit de movilidad del raquis torácico?",["A la lesión muscular de los isquiotibiales","Al dolor cervical y al hombro","A la fascitis plantar crónica"],["La lesión de los isquiotibiales se vincula al déficit de flexibilidad de esos músculos.","La falta de movilidad torácica se asocia al dolor cervical y a la patología del hombro.","La fascitis plantar se vincula al déficit de flexión dorsal del tobillo."]],
  "610": ["¿Cuál es el estímulo primario del órgano tendinoso de Golgi?",["Un estiramiento rápido y súbito del músculo","Una variación de temperatura del tejido","Una tensión muscular elevada, activa o pasiva"],["El estiramiento rápido es el estímulo del huso neuromuscular.","La temperatura no es un estímulo de ese receptor.","El órgano tendinoso de Golgi responde a una tensión muscular elevada, sea activa o pasiva, con una inhibición autógena."]],
  "611": ["¿Qué hormonas intervienen en el equilibrio anabólico del ejercicio?",["El cortisol, la hormona del crecimiento y la testosterona","La insulina, el glucagón y la adrenalina","Las hormonas tiroideas, la parathormona y la insulina"],["El equilibrio anabólico depende del cortisol, de la hormona del crecimiento y de la testosterona.","Esas hormonas no son las citadas para el equilibrio anabólico.","Esas hormonas no figuran entre los factores hormonales descritos."]],
  "612": ["¿Qué beneficio óseo aporta el ejercicio terapéutico?",["Un aumento del espesor del cartílago articular","Un aumento de la masa ósea, que previene la osteoporosis","Un aumento de la densidad del líquido sinovial"],["El engrosamiento cartilaginoso no es el efecto descrito.","El ejercicio aumenta la masa ósea, lo que previene la osteoporosis y por tanto la dependencia física.","No se refiere ningún efecto de ese tipo."]],
  "613": ["¿Cuál es la respuesta cardiovascular a CORTO plazo del ejercicio?",["Una disminución de la frecuencia cardiaca en reposo","Una mejora del aclaramiento del lactato","Un aumento de la frecuencia cardiaca y de la presión"],["El descenso de la frecuencia de reposo es una adaptación a LARGO plazo.","La mejora del aclaramiento del lactato es una adaptación crónica.","A corto plazo, el ejercicio aumenta la frecuencia cardiaca, la presión arterial sistólica y la acidosis durante el esfuerzo."]],
  "614": ["¿Cuál es el principal factor de riesgo de accidente cerebrovascular que recuerda el curso?",["La hipertensión arterial","El sedentarismo aislado","El exceso de masa grasa abdominal"],["La hipertensión arterial es el principal factor de riesgo de accidente cerebrovascular.","El sedentarismo es un factor de riesgo, pero no es el designado como principal.","La adiposidad abdominal es un factor de riesgo metabólico, no el primer factor citado."]],
  "615": ["¿Qué facilita la práctica DISTRIBUIDA en el aprendizaje motor?",["La transferencia hacia otros contextos","La adquisición inicial del gesto","La consolidación del aprendizaje"],["La transferencia se favorece por la variabilidad contextual.","La práctica distribuida facilita la adquisición inicial, mientras que la variabilidad contextual mejora la transferencia.","La consolidación resulta de la repetición asociada al sentido y a la motivación."]],
  "616": ["¿Cómo se define el ejercicio aerobio?",["Una actividad breve e intensa contra resistencia elevada","Una actividad dirigida al alargamiento de los tejidos blandos","Una actividad que aumenta la demanda de oxígeno de los músculos"],["La actividad contra resistencia depende del trabajo de fuerza.","El alargamiento tisular depende de los estiramientos.","El ejercicio aerobio es una actividad física sistemática que aumenta la función cardiorrespiratoria aumentando la demanda de oxígeno de la musculatura esquelética que lo ejecuta."]],
  "617": ["¿La pérdida de qué fibras explica numerosos problemas de salud ligados a la debilidad muscular?",["Las fibras de tipo II","Las fibras de tipo I","Las fibras intermedias de tipo IIa solas"],["Numerosos problemas de salud asociados a la pérdida de fuerza muscular se deben a la pérdida de fibras de tipo II.","Las fibras de tipo I sirven a la resistencia, pero su pérdida no es la implicada.","La distinción establecida se centra en el tipo II en su conjunto."]],
  "618": ["¿De qué formas puede aumentarse la carga de un programa de fuerza?",["Únicamente aumentando el peso de la resistencia","Mediante el peso, el volumen, la velocidad o las pausas","Únicamente aumentando el número de sesiones"],["Existen varias palancas, entre ellas el volumen y la densidad.","La carga se aumenta jugando con el peso, el número de series y de repeticiones, la velocidad gestual o la duración de las pausas.","El número de sesiones no se cita entre esas palancas."]],
  "619": ["¿En qué situación es particularmente útil el trabajo ISOMÉTRICO?",["Cuando se busca una ganancia de coordinación","Cuando el paciente presenta una hipertensión arterial","Cuando el movimiento está contraindicado"],["Es precisamente su inconveniente: trabaja poco la coordinación.","La hipertensión es al contrario una contraindicación del trabajo isométrico.","El isométrico permite trabajar la fuerza cuando el movimiento está contraindicado, previene la atrofia y resulta muy útil en la artrosis."]],
  "620": ["¿Cuál es el principal límite del trabajo isométrico?",["Trabaja poco la coordinación","Expone a un riesgo elevado de lesión muscular","Provoca una inflamación importante después de la sesión"],["Su inconveniente es solicitar poco la coordinación, aunque permita una ganancia de fuerza en ángulos específicos.","El riesgo de lesión concierne sobre todo al trabajo excéntrico mal ejecutado.","La inflamación posesfuerzo caracteriza al trabajo excéntrico."]],
  "621": ["¿Cómo se define la movilidad articular?",["La capacidad pasiva de un músculo de estirarse libremente y sin dolor","La capacidad de moverse activamente de forma controlada e indolora","La amplitud máxima medida con el goniómetro en plano"],["La capacidad pasiva de estiramiento define la flexibilidad.","La movilidad articular es la capacidad de movilizar activamente una articulación en una amplitud funcional, controlada e indolora, con componentes articulares y neuromusculares.","La amplitud medida solo es una parte de la movilidad."]],
  "622": ["¿Cómo se define la distensibilidad de un tejido?",["La capacidad de volver a su posición inicial","La capacidad de generar activamente una tensión","La capacidad de ser deformado por una fuerza exterior"],["El retorno a la posición inicial define la elasticidad.","La generación activa de tensión define la contractilidad.","La distensibilidad es la capacidad de un cuerpo de ser deformado por una fuerza exterior."]],
  "623": ["¿Qué sensación final corresponde a la extensión del codo?",["Una sensación dura, por contacto óseo","Una sensación blanda, por contacto muscular","Una sensación firme, por estiramiento capsular"],["La extensión del codo da una sensación dura, por contacto del olécranon con la fosa olecraniana.","La sensación blanda se observa en la flexión del codo o de la rodilla.","La sensación firme se observa en la rotación de hombro o en la abducción de cadera."]],
  "624": ["¿Qué receptor está situado en la unión entre el músculo y el tendón?",["El huso neuromuscular","El órgano tendinoso de Golgi","El corpúsculo de Ruffini capsular"],["El huso neuromuscular asienta en el interior del músculo, paralelamente a las fibras.","El órgano tendinoso de Golgi asienta en la unión músculo-tendón; responde a una tensión elevada con una inhibición refleja del músculo.","Ese mecanorreceptor no es el descrito aquí."]],
  "625": ["¿Qué respuesta desencadena el huso neuromuscular?",["Una inhibición refleja del músculo estirado","Una relajación del músculo antagonista","Una contracción refleja del músculo estirado"],["La inhibición refleja, llamada autógena, es la respuesta del órgano tendinoso de Golgi.","La inhibición recíproca concierne al antagonista, pero no es la respuesta del huso.","El huso neuromuscular responde a un estiramiento rápido con una contracción refleja del músculo estirado: es el reflejo miotático."]],
  "626": ["¿Cómo se define el estiramiento ESTÁTICO?",["El mantenimiento de una posición en la que se siente una resistencia pasiva","La aplicación cíclica de movimientos sin carga","La asociación de un estiramiento y de una contracción submáxima"],["El estiramiento estático alarga los tejidos más allá de su longitud de reposo manteniendo una posición articular en la que se siente una resistencia pasiva, una sensación de estiramiento o una incomodidad.","La aplicación cíclica define el estiramiento dinámico.","Esa asociación define la facilitación neuromuscular propioceptiva."]],
  "627": ["¿Qué caracteriza a la técnica de mantener-relajar?",["Una contracción isotónica contra resistencia del músculo diana","Una contracción isométrica del músculo diana antes de un nuevo estiramiento","Una contracción del músculo antagonista durante el estiramiento"],["La contracción isotónica contra resistencia caracteriza a la técnica contraer-relajar.","En el mantener-relajar, el músculo se estira pasivamente y después se contrae de forma isométrica, antes de un nuevo estiramiento en relajación.","La contracción del antagonista caracteriza al estiramiento estático activo."]],
  "628": ["¿Qué concluye la literatura sobre la superioridad de una técnica de estiramiento?",["La facilitación neuromuscular propioceptiva es la más eficaz","El estiramiento balístico da los mejores resultados","Ninguna técnica es superior para ganar amplitud"],["No se demuestra ninguna superioridad.","Ninguna técnica destaca en la ganancia de amplitud.","No se ha observado ninguna diferencia significativa entre las técnicas en cuanto a la ganancia de amplitud: no existe una técnica superior."]],
  "629": ["¿Qué signos caracterizan una cervicalgia con restricción de los movimientos?",["Un dolor central o unilateral con limitación de amplitud","Parestesias que siguen el trayecto de los dermatomas del brazo","Vértigos y trastornos de la concentración"],["El cuadro asocia un dolor central o unilateral y una limitación de amplitud que reproduce los síntomas, con a veces un dolor referido al miembro superior.","Las parestesias dermatómicas pertenecen a la cervicalgia con dolor irradiado.","Esos signos caracterizan a la cervicalgia con trastornos de la coordinación."]],
  "630": ["¿Qué resultado de exploración se espera en una cervicalgia con restricción de movimiento?",["Una prueba de Spurling francamente positiva en el brazo","Una restricción segmentaria cervical y torácica","Una algometría de presión francamente positiva"],["La prueba de Spurling pertenece al estudio de la radiculopatía.","Se espera una amplitud cervical limitada, un dolor al final del recorrido activo y pasivo, y una restricción segmentaria cervical y torácica.","La algometría positiva pertenece al cuadro de los trastornos de la coordinación."]],
  "631": ["¿Qué técnica articular se establece para la cervicalgia con restricción de movimiento?",["Únicamente la movilización neurodinámica en tensión","Únicamente la punción seca de los puntos gatillo","Las técnicas torácicas y cervicales de alta velocidad"],["La neurodinámica se dirige a los dolores irradiados.","La punción seca es una técnica de tejido blando, no articular.","Las estrategias comprenden las técnicas torácicas y cervicales de alta velocidad y las técnicas de baja velocidad por movilización accesoria."]],
  "632": ["¿Qué prueba es positiva en una cervicalgia con cefalea?",["La prueba de flexión-rotación cervical","La prueba de distracción cervical","La prueba de flexión craneocervical"],["El cuadro comporta una prueba de flexión-rotación cervical positiva y una cefalea reproducida por la provocación segmentaria.","La distracción cervical pertenece al grupo de pruebas de la radiculopatía.","Esa prueba pertenece al cuadro de los trastornos de la coordinación."]],
  "633": ["¿Por qué estructura pasa la conexión entre raíces cervicales y trigémino?",["El ganglio de la raíz dorsal","El núcleo trigeminocervical","La sustancia gris periacueductal"],["El ganglio raquídeo no es el lugar de esa convergencia.","La conexión anatómica entre las raíces cervicales superiores y las raíces del trigémino pasa por el núcleo trigeminocervical, en la médula espinal.","Esa estructura interviene en la modulación descendente."]],
  "634": ["¿Qué caracteriza al dolor de la migraña?",["Un dolor no pulsátil que mejora con el ejercicio","Una sensación de banda frontal bilateral","Un dolor lancinante unilateral que se agrava con el esfuerzo"],["La mejoría con el ejercicio caracteriza a la cefalea tensional y a la cefalea cervicogénica.","La sensación de banda frontal caracteriza a la cefalea tensional.","La migraña da un dolor lancinante unilateral, de intensidad moderada a grave, que se agrava con el esfuerzo, con o sin aura."]],
  "635": ["¿A qué se asocia la cefalea tensional en el plano muscular?",["A una hipersensibilidad de los músculos craneocervicales","A una debilidad aislada de los flexores profundos","A una retracción de los músculos suboccipitales"],["Se asocia a una hipersensibilidad de los músculos craneocervicales, ligada a una activación aumentada de los receptores del dolor.","La debilidad de los flexores profundos depende de los trastornos de la coordinación.","La retracción suboccipital no es el mecanismo descrito."]],
  "636": ["¿Qué desencadena típicamente una cefalea cervicogénica?",["Las variaciones hormonales y la falta de sueño","Posiciones cervicales no fisiológicas sostenidas","El esfuerzo físico intenso y prolongado"],["Esos desencadenantes pertenecen a la migraña.","Se causa por posiciones cervicales no fisiológicas y sostenidas, o por una presión externa en región occipital o cervical.","El agravamiento con el esfuerzo caracteriza a la migraña."]],
  "637": ["¿Qué antecedente domina en la cervicalgia con trastornos de la coordinación?",["Una hernia discal cervical documentada","Una artrosis facetaria evolucionada","Un traumatismo de tipo latigazo cervical"],["La hernia discal pertenece al cuadro de dolor irradiado.","La artrosis facetaria depende del dolor facetario.","El cuadro sigue a un traumatismo o latigazo cervical, con dolor referido al miembro superior, vértigos y náuseas."]],
  "638": ["¿Qué prueba positiva orienta hacia trastornos de la coordinación cervical?",["La prueba de flexión craneocervical","La prueba de Spurling","La prueba de flexión-rotación cervical"],["El cuadro comporta una prueba de flexión craneocervical positiva, una prueba de resistencia de los flexores positiva y una algometría de presión positiva.","El Spurling pertenece al grupo de pruebas de la radiculopatía.","Esa prueba pertenece al cuadro de la cefalea cervicogénica."]],
  "639": ["¿Cómo se presenta el dolor en los trastornos de la coordinación cervical?",["Sobreviene únicamente al final de la amplitud","Sobreviene en amplitud media y se agrava al mantenerla","Irradia según un dermatoma bien preciso del miembro superior"],["El dolor de final de amplitud caracteriza a la restricción de movimiento.","El dolor aparece en los movimientos de amplitud media y se agrava en las posiciones sostenidas.","La irradiación dermatómica indica una afectación radicular."]],
  "640": ["¿Qué límite de rotación cervical entra en el grupo de pruebas de la radiculopatía?",["Menos de 80 grados del lado afectado","Menos de 30 grados del lado afectado","Menos de 60 grados del lado afectado"],["El umbral establecido es más restrictivo.","Ese umbral es más severo que el establecido.","Una rotación cervical del lado afectado inferior a 60 grados forma parte del grupo de pruebas."]],
  "641": ["¿Cuál es el perfil del dolor facetario cervical en la exploración física?",["Una movilidad reducida y una sensibilidad paravertebral","Una debilidad y un adormecimiento del miembro superior","Una sensibilidad de la línea media con signos vestibulares"],["El dolor facetario da una reducción de movilidad del cuello y una sensibilidad paravertebral, sin déficit neurológico.","La debilidad y el adormecimiento indican una compresión radicular.","Ese perfil evoca una afectación discal."]],
  "642": ["¿Qué valor tiene la imagen en el dolor facetario cervical?",["Alto: la radiografía confirma el diagnóstico","Bajo: la asociación radioclínica es baja","Decisivo: el electrodiagnóstico es indispensable"],["La asociación radioclínica es precisamente baja.","La asociación entre el dolor y la artrosis de las facetas en las radiografías simples es baja, y el electrodiagnóstico no está indicado.","El electrodiagnóstico no está indicado en ese cuadro."]],
  "643": ["¿Cuál de estos elementos es un factor de riesgo de dolor discal cervical?",["Los deportes de alto impacto","Un latigazo cervical aislado","El tabaquismo crónico"],["Los deportes de alto impacto son un factor de riesgo de dolor de los tejidos blandos.","El latigazo cervical orienta hacia el dolor facetario o de los tejidos blandos.","Los factores de riesgo de dolor discal son el tabaquismo, la edad avanzada, los movimientos repetitivos del cuello y el traumatismo."]],
  "644": ["¿Qué signo clínico inesperado puede acompañar a un dolor discal cervical?",["Signos vestibulares","Una debilidad motora de un territorio radicular","Una cefalea en banda frontal"],["El dolor discal cervical puede comportar un dolor axial, un dolor del hombro, un dolor del brazo no radicular y signos vestibulares.","La debilidad radicular indica una compresión de raíz.","La banda frontal evoca la cefalea tensional."]],
  "645": ["¿Qué factor de riesgo domina en la compresión radicular por hernia discal?",["La edad avanzada del paciente","La edad media de la vida","La adolescencia deportiva"],["La edad avanzada es el terreno de la estenosis foraminal.","La hernia discal concierne sobre todo a la edad media, mientras que la estenosis foraminal concierne a la edad avanzada.","Ese terreno no es el descrito."]],
  "646": ["¿En qué grados se utilizan las técnicas accesorias de Maitland en el raquis cervical?",["En los grados 1 y 2","En el grado 5 exclusivamente","En los grados 3 y 4"],["Los grados 1 y 2 trabajan en amplitud mínima o neutra.","El grado 5 corresponde al impulso manipulativo.","Las técnicas accesorias se emplean en los grados 3 y 4, en forma de presiones posteroanteriores centrales o unilaterales."]],
  "647": ["¿Qué técnica de Mulligan se utiliza para la cervicalgia con restricción de movimiento?",["La técnica de alta velocidad de la charnela C7-T1","La movilización con movimiento de las articulaciones periféricas","La técnica de tensión neurodinámica por dos extremos"],["La técnica de alta velocidad de C7-T1 se establece para la cervicalgia con restricción de movimiento.","Las articulaciones periféricas dependen de las movilizaciones con movimiento.","La tensión neurodinámica se dirige al tejido nervioso."]],
  "648": ["¿Cuál de estos músculos es una diana del tratamiento de los tejidos blandos en el raquis cervical?",["El dorsal ancho","El masetero","El cuadrado lumbar"],["El dorsal ancho no se cita entre las dianas.","Los tejidos diana son el trapecio superior, los suboccipitales, el esternocleidooccipitomastoideo, el temporal y el masetero.","El cuadrado lumbar no forma parte de las dianas cervicales."]],
  "649": ["¿Qué duración de mantenimiento valida la prueba de resistencia de los extensores cervicales?",["Diez segundos en posición neutra","Sesenta segundos en posición neutra","Veinte segundos en posición neutra"],["Diez segundos corresponden a una repetición de la prueba de los flexores.","Esa duración supera el criterio establecido.","La prueba de resistencia de los extensores cervicales es satisfactoria a los veinte segundos en posición neutra."]],
  "650": ["¿Qué traduce una flexión del cuello por incapacidad de mantener la cabeza recta?",["Una debilidad de los extensores profundos y superficiales","Una debilidad aislada de los extensores profundos","Una debilidad aislada de los flexores profundos"],["La incapacidad de mantener la cabeza recta indica una debilidad tanto de los extensores profundos como de los superficiales.","La debilidad aislada de los profundos da una pérdida de retracción del mentón.","Los flexores profundos se evalúan con otra prueba."]],
  "651": ["¿Cuántas repeticiones como mínimo comporta la prueba de reposicionamiento de la cabeza?",["Diez repeticiones","Seis repeticiones","Tres repeticiones"],["Diez repeticiones corresponden a la prueba de resistencia de los flexores.","La evaluación de la precisión del reposicionamiento de la cabeza en posición neutra comporta como mínimo seis repeticiones.","El mínimo establecido es más alto."]],
  "652": ["¿Qué muestra la resonancia magnética en una afectación discal cervical?",["Una artrosis de las facetas articulares","Una estenosis foraminal aislada","Desgarros o fisuras anulares"],["La artrosis facetaria depende de la radiografía, con un valor bajo.","La estenosis foraminal es un factor de compresión radicular.","La resonancia magnética muestra desgarros o fisuras anulares, mientras que la radiografía muestra una reducción de la altura discal."]],
  "653": ["¿Sobre qué estructura se aplica una presión posteroanterior CENTRAL?",["Sobre las apófisis espinosas","Sobre las apófisis cigapofisarias","Sobre las apófisis transversas"],["La presión central se aplica sobre las apófisis espinosas y se dirige a los dolores centrales, discogénicos o facetarios.","Las cigapófisis reciben la presión unilateral.","Las apófisis transversas no son la diana descrita."]],
  "654": ["¿Qué se establece sobre la especificidad de la manipulación articular cervical?",["Es muy elevada","Es más bien baja","Es máxima en la región torácica"],["Su especificidad se describe precisamente como baja.","La manipulación articular tiene una especificidad baja: la vértebra a manipular debe colocarse en posición articular adecuada.","No se describe ninguna superioridad de especificidad torácica."]],
  "655": ["¿En qué caso es la neurodinámica una técnica clave en el raquis cervical?",["Ante una cefalea tensional aislada","Ante un dolor facetario estrictamente axial, sin irradiación","Ante una cervicalgia irradiada al miembro superior"],["La cefalea tensional depende del trabajo de los tejidos blandos craneocervicales.","El dolor facetario axial depende de las técnicas articulares.","La neurodinámica es clave ante una cervicalgia irradiada al miembro superior, sea radicular o debida al atrapamiento de una interfaz mecánica."]],
  "656": ["¿Qué signo traduce una debilidad de los extensores cervicales PROFUNDOS?",["Un alargamiento del mentón o una pérdida de retracción","Una flexión del cuello por incapacidad de mantener la cabeza recta","Una pérdida de la zona neutra del raquis lumbar"],["Una debilidad de los extensores profundos se traduce por un alargamiento del mentón o una pérdida de la retracción, indicando un dominio de los extensores superficiales.","Esa flexión traduce una debilidad de los extensores profundos Y superficiales.","El raquis lumbar no está implicado en esa prueba."]],
  "657": ["¿Por encima de qué error se considera anormal el reposicionamiento de la cabeza?",["Por encima de 10 grados","Por encima de 4,5 grados","Por encima de 1 grado"],["El umbral establecido es más fino.","Los errores de posicionamiento son mayores en los pacientes con dolor, por encima de 4,5 grados.","Ese umbral sería inferior a la variabilidad normal."]],
  "658": ["¿Qué se privilegia en los primeros estadios del tratamiento mediante ejercicio cervical?",["El trabajo funcional en carga y en velocidad gestual","Las técnicas manipulativas de alta velocidad","El control motor, la fuerza y la resistencia sin dolor"],["El trabajo funcional llega más tarde en la progresión.","Las manipulaciones no dependen de la terapia mediante ejercicio.","En los primeros estadios se trabaja el control motor, la fuerza y la resistencia, sin dolor y sin fatiga, adaptándose a la irritabilidad."]],
  "659": ["¿Cómo se define la cefalea cervicogénica?",["Una cefalea secundaria a una disfunción de la columna cervical","Una cefalea primaria de origen neurovascular","Una cefalea ligada a la hipersensibilidad de los músculos pericraneales y de la mandíbula"],["Es una cefalea secundaria, cuyo origen se asocia a una patología o a una disfunción de la columna cervical.","La cefalea neurovascular primaria corresponde a la migraña.","La hipersensibilidad craneocervical caracteriza a la cefalea tensional."]],
  "660": ["¿A qué tipo de dolor se dirige la presión posteroanterior UNILATERAL?",["A los dolores centrales discogénicos","A los dolores unilaterales de origen facetario","A los dolores irradiados al miembro superior"],["Los dolores centrales dependen de la presión central.","La presión unilateral, aplicada sobre las cigapófisis, se dirige a los dolores unilaterales de origen facetario.","Los dolores irradiados dependen de la neurodinámica."]],
  "661": ["¿Qué opciones de tratamiento neurodinámico se establecen en el miembro superior?",["La punción seca y la fibrólisis diacutánea","Las presiones posteroanteriores centrales y unilaterales","El deslizamiento por uno o dos extremos y la técnica de tensión"],["Esas técnicas se dirigen al tejido blando.","Esas presiones son técnicas articulares.","Las opciones son el deslizamiento por dos extremos, el deslizamiento por un extremo y la técnica de tensión."]],
  "662": ["¿Qué tareas evalúan la cinestesia cervical?",["Trazar un ocho o seguir el contorno de un dibujo","Mantener una presión constante en el estabilizador","Realizar una rotación máxima de ambos lados"],["La cinestesia se evalúa pidiendo al paciente que haga un ocho o que siga el contorno de un dibujo.","El estabilizador sirve para el trabajo y la prueba del control de los flexores profundos.","La rotación máxima mide la amplitud, no la cinestesia."]],
  "663": ["¿Cuál de estos medios de electroterapia se establece en el raquis cervical?",["Las corrientes de Kotz excitomotoras","El láser de alta potencia","La iontoforesis con fines analgésicos"],["Las corrientes de Kotz no figuran entre los medios citados aquí.","Los medios establecidos son la diatermia o radiofrecuencia, el TENS analgésico, el láser de alta potencia y la electropunción.","La iontoforesis no se cita en ese capítulo."]],
  "664": ["¿Cuál de estos trastornos es una comorbilidad asociada a la cervicalgia?",["El reflujo ácido","La hipertensión arterial esencial","La cefalea asociada"],["El reflujo no se cita entre las comorbilidades asociadas.","La hipertensión no es una comorbilidad descrita aquí.","La cervicalgia se asocia a varias comorbilidades, entre ellas las cefaleas, las dorsalgias y las artralgias."]],
  "665": ["¿Cuándo se esperan déficits de fuerza y de control motor en una cervicalgia?",["En caso de dolor subagudo o crónico","Desde la fase aguda, sistemáticamente","Únicamente en presencia de un déficit neurológico"],["Los déficits de fuerza y de control motor se esperan cuando el dolor es subagudo o crónico.","Esos déficits no se esperan de entrada en fase aguda.","No dependen de la existencia de un déficit neurológico."]],
  "666": ["¿Qué segmentos están restringidos en la cervicalgia con cefalea?",["Los segmentos cervicales inferiores y C7-T1","Los segmentos cervicales superiores","Los segmentos torácicos medios"],["La restricción descrita asienta en el nivel superior.","La movilidad está restringida a nivel de los segmentos cervicales superiores, con déficits de fuerza, de resistencia y de coordinación.","El raquis torácico medio no es la sede descrita."]],
  "667": ["¿Qué teoría explica la cefalea cervicogénica?",["La teoría del control de la puerta medular","La teoría de la sensibilización central difusa","La convergencia trigeminocervical"],["El gate control explica la modulación del dolor, no esa localización.","La sensibilización central no es la teoría invocada aquí.","La teoría de la convergencia trigeminocervical explica la doble localización del dolor, por conexión entre las raíces cervicales altas y el trigémino."]],
  "668": ["¿Cuál es la cefalea más extendida en el mundo?",["La cefalea tensional","La migraña con aura","La cefalea cervicogénica"],["La cefalea tensional es el tipo más extendido: afecta a cerca de una persona de cada dos, y sigue siendo más frecuente que la migraña.","La migraña es menos frecuente que la cefalea tensional.","La cefalea cervicogénica es una cefalea secundaria, mucho menos frecuente."]],
  "669": ["¿Cómo se propaga el dolor de la cefalea cervicogénica?",["De un inicio frontal hacia atrás","De un inicio posterior hacia delante","De forma difusa y bilateral de entrada"],["El sentido de propagación descrito es inverso.","La cefalea cervicogénica comienza en la parte posterior y se propaga hacia delante; puede irradiar al hombro o al brazo.","Es unilateral y no pulsátil."]],
  "670": ["¿Cuál es la particularidad vegetativa de la cefalea cervicogénica?",["Los síntomas vegetativos son ahí constantes","Se acompaña siempre de un aura visual","Los episodios son raramente vegetativos"],["Son al contrario raros.","La cefalea cervicogénica sobreviene sin aura.","Los episodios de cefalea cervicogénica se asocian raramente a síntomas vegetativos."]],
  "671": ["¿Cuál de estos signos pertenece a la cervicalgia con trastornos de la coordinación?",["Dificultades de concentración y de memoria","Parestesias de distribución dermatómica","Un dolor referido a la mitad de la espalda"],["El cuadro comporta cefaleas, dificultades de concentración y de memoria, hipersensibilidad y trastornos emocionales aumentados.","Las parestesias dermatómicas indican una afectación radicular.","El dolor referido dorsal evoca una afectación facetaria."]],
  "672": ["¿Qué pruebas componen el grupo diagnóstico de la radiculopatía cervical?",["Flexión-rotación, algometría y resistencia de los flexores","Spurling, distracción, tensión del miembro y rotación limitada","Flexión craneocervical, reposicionamiento y cinestesia"],["Esas pruebas dependen de la cefalea y de los trastornos de la coordinación.","El grupo asocia la prueba de Spurling, la distracción cervical, la primera prueba de tensión del miembro superior y una rotación cervical del lado afectado inferior a 60 grados.","Esas pruebas evalúan el control motor cervical."]],
  "673": ["¿Cuántas pruebas positivas del grupo aumentan fuertemente la probabilidad de radiculopatía?",["Una sola basta","Las cinco pruebas son necesarias","Tres o cuatro"],["Una prueba aislada no tiene ese valor.","El grupo comporta cuatro ítems, y tres ya bastan.","Tres o cuatro pruebas positivas en ese grupo aumentan considerablemente la probabilidad de una radiculopatía cervical."]],
  "674": ["¿Hacia dónde se proyecta el dolor facetario cervical?",["Hacia el occipucio, el hombro y la mitad de la espalda","Hacia el antebrazo y la mano, según un dermatoma","Hacia la región frontal, en banda"],["El dolor facetario es axial, con un dolor referido al occipucio, al hombro y a la mitad de la espalda.","Esa proyección distal evoca una afectación radicular.","La banda frontal evoca una cefalea tensional."]],
  "675": ["¿Qué perfil de limitación de amplitud evoca una afectación discal cervical?",["La flexión más limitada que la extensión, la rotación más que la inclinación","La extensión más limitada que la flexión, la inclinación más que la rotación","Una limitación idéntica en todas las direcciones"],["El perfil descrito es inverso.","En la afectación discal, la extensión está más limitada que la flexión, y la inclinación más que la rotación.","La limitación no es homogénea."]],
  "676": ["¿Cuál es la sensibilidad de la prueba de Spurling?",["Superior al 90 %","Inferior al 10 %","Del 40 al 60 %"],["Su sensibilidad es modesta, de ahí su uso dentro de un grupo de pruebas.","Su sensibilidad es baja pero no tanto.","La prueba de Spurling tiene una sensibilidad del 40-60 %, lo que explica el interés de un conjunto de pruebas."]],
  "677": ["¿Cómo se desarrolla la prueba de resistencia de los flexores cervicales profundos?",["Diez repeticiones de diez segundos, con diez segundos de descanso","Veinte segundos de mantenimiento activo en posición neutra","Seis repeticiones de reposicionamiento de la cabeza"],["Se piden diez repeticiones de diez segundos de activación, separadas por diez segundos de descanso en cada nivel, y se anota la repetición que falla y por qué.","Veinte segundos en posición neutra corresponden a la prueba de los extensores cervicales.","El reposicionamiento evalúa la precisión, no la resistencia."]],
  "678": ["¿Cómo se comporta la lumbalgia en la gran mayoría de los casos?",["Como la manifestación de una patología estructural grave y evolutiva","Como un problema mecánico benigno, a veces ligado al estrés psicosocial","Como un dolor neuropático de entrada crónico"],["Solo el 1-2 % de los pacientes tiene una patología grave.","En la gran mayoría de los casos la lumbalgia es benigna: depende de un comportamiento mecánico, o se asocia a un estrés psicosocial o a malos hábitos de vida.","La naturaleza neuropática no es la regla."]],
  "679": ["¿Hasta dónde se proyecta el dolor facetario lumbar?",["Supera la rodilla según un metámero","Permanece estrictamente medio y central","No supera la rodilla"],["La irradiación más allá de la rodilla indica un dolor radicular.","El dolor central medio evoca un origen discogénico.","El dolor facetario puede referirse a la nalga, a la ingle, a la cresta ilíaca, a la cara anterior del muslo y al trocánter, pero no supera la rodilla."]],
  "680": ["¿En qué momento del día es más marcado el dolor facetario?",["Por la mañana, al levantarse","Más bien al final del día","Por la noche, en posición acostada"],["El dolor facetario es más pronunciado por la mañana; se instaura rápidamente y desaparece en unos días, de forma recurrente.","El curso establece un predominio matinal.","El dolor nocturno de reposo es un signo de alerta, no el perfil facetario."]],
  "681": ["¿Qué movimiento aumenta el dolor discogénico?",["La extensión lumbar","La flexión lumbar","El apoyo monopodal prolongado"],["La extensión disminuye al contrario el dolor discogénico.","El dolor discogénico aumenta con la flexión lumbar y al pasar de la posición sentada a la posición de pie.","El apoyo monopodal desencadena el dolor sacroilíaco."]],
  "682": ["¿Qué maniobra aumenta el dolor discogénico por elevación de la presión intraabdominal?",["La prueba de Thomas en decúbito","La prueba de Patrick-Fabere","La maniobra de Valsalva repetida"],["La prueba de Thomas evalúa la asimetría de tono del psoas.","Esa prueba explora la articulación sacroilíaca.","El dolor aumenta con la elevación de la presión intraabdominal, por tanto durante la maniobra de Valsalva."]],
  "683": ["¿Qué caracteriza el reposo del paciente con dolor discogénico?",["Le cuesta encontrar una posición que lo alivie","Queda totalmente aliviado en cuanto se sienta","Solo se alivia en apoyo monopodal"],["El paciente tiene dificultad para encontrar una posición de reposo en la que el dolor disminuya.","La posición sentada aumenta más bien su dolor.","El apoyo monopodal no tiene aquí ningún papel analgésico."]],
  "684": ["¿Qué gesto desencadena habitualmente el dolor sacroilíaco?",["La extensión repetida del tronco en carga","El apoyo monopodal, al caminar","La maniobra de Valsalva repetida"],["La extensión del tronco agrava el dolor facetario.","El apoyo monopodal desencadena normalmente el dolor, por ejemplo al caminar o al subir y bajar escaleras.","El Valsalva aumenta el dolor discogénico y radicular."]],
  "685": ["¿Cuántas pruebas positivas afirman una alta fiabilidad de afectación sacroilíaca?",["Una sola prueba positiva","Las seis pruebas de la batería","Tres pruebas positivas"],["Una prueba aislada no basta.","Tres pruebas positivas ya bastan.","Tres pruebas positivas dan una alta fiabilidad para un problema de la articulación sacroilíaca."]],
  "686": ["¿En qué posición disminuye el dolor de estenosis?",["En reposo, en flexión del tronco","En extensión del tronco hacia atrás","En decúbito con las piernas extendidas"],["El dolor de estenosis disminuye en reposo con una flexión del tronco: el paciente camina típicamente inclinado hacia delante.","La inclinación del tronco hacia atrás agrava al contrario los síntomas.","Esa posición no es la que alivia."]],
  "687": ["¿Qué caracteriza la irradiación del dolor radicular lumbar?",["Una irradiación que se detiene por encima de la rodilla","Una irradiación metamérica que supera la rodilla","Una irradiación inguinal y posterolateral del muslo"],["La irradiación que no supera la rodilla evoca un origen facetario.","El dolor radicular da una irradiación metamérica que va más allá de la rodilla, condicionada por el movimiento o la posición del raquis.","Esa proyección evoca una afectación sacroilíaca."]],
  "688": ["¿Cuánto tiempo evoluciona habitualmente el dolor radicular lumbar?",["Solo unos días","Unas horas, de forma intermitente","Semanas o meses"],["La resolución en unos días caracteriza al dolor facetario.","La intermitencia breve evoca más bien la claudicación de estenosis.","El dolor radicular dura semanas o meses, a diferencia del dolor facetario que desaparece en unos días."]],
  "689": ["¿Cuándo se realiza un movimiento fisiológico con SOBREPRESIÓN?",["Solo si el movimiento fisiológico no reproduce nada","Sistemáticamente, en cada movimiento que se explora","Únicamente en presencia de un déficit neurológico"],["La sobrepresión solo se hace cuando el movimiento fisiológico no reproduce la sintomatología; busca reproducir los síntomas del paciente.","No es sistemática.","El déficit neurológico no es el criterio de realización."]],
  "690": ["¿Cuántas repeticiones activas se piden en cada dirección?",["Tres repeticiones","Diez repeticiones","Veinte repeticiones"],["Tres repeticiones serían insuficientes para juzgar la respuesta.","Se piden diez repeticiones activas en cada una de las direcciones, llevándose el movimiento hasta el inicio del dolor.","El protocolo establece diez repeticiones."]],
  "691": ["¿Qué dosis se establece para la movilidad pasiva de la articulación sacroilíaca?",["Tres series de diez repeticiones, con sesenta segundos de descanso","Diez repeticiones de diez segundos, con diez segundos de descanso","Tres series de dos minutos a un hercio, con un minuto de descanso"],["Esa dosificación corresponde a la técnica de Mulligan.","Esa dosificación corresponde a la prueba de los flexores cervicales.","La movilidad articular pasiva se hace en tres series de dos minutos de trabajo a un hercio, con un minuto de descanso entre las series."]],
  "692": ["¿Por qué modifica el embarazo la solicitación del psoas ilíaco?",["Adelanta el centro de gravedad y la anteversión pélvica","Reduce claramente la lordosis lumbar fisiológica","Provoca una dismetría pélvica duradera"],["El embarazo conlleva un adelantamiento del centro de gravedad y una mayor anteversión pélvica, lo que modifica las curvaturas.","La modificación va en el sentido de una anteversión, no de un borramiento.","La dismetría pélvica concierne más bien al cuadrado lumbar."]],
  "693": ["¿A qué fase de tratamiento corresponde el deslizamiento por UN extremo?",["A las fases más agudas e irritables","A las fases intermedias","A las fases finales, en plena carga"],["Las fases más afectadas dependen del deslizamiento por dos extremos.","El deslizamiento por un extremo se emplea en las fases intermedias del tratamiento: un extremo está fijo y la longitud del nervio se modifica.","Las fases avanzadas dependen de la técnica de tensión."]],
  "694": ["¿En qué fases está indicado el TENS en la lumbalgia?",["En las fases subagudas y crónicas","En la fase aguda exclusivamente","En todas las fases del tratamiento"],["Son la diatermia y la tecarterapia las que se dirigen sobre todo a las fases subagudas y crónicas.","Su indicación no se limita a la fase aguda.","El TENS analgésico está indicado en todas las fases; se aplica sobre la zona dolorosa o a lo largo de las raíces lumbares, de L3 a S1."]],
  "695": ["¿En qué fase es particularmente útil la diatermia en la lumbalgia?",["En las fases subagudas o crónicas","En la fase aguda inflamatoria","Únicamente en prevención de las recidivas"],["La diatermia genera un calor profundo, mejora la vascularización y disminuye la rigidez: es particularmente útil en las fases subagudas o crónicas.","La fase aguda depende más bien del modo atérmico y de la analgesia.","Su indicación no es preventiva."]],
  "696": ["¿Qué se establece sobre el nivel de evidencia del estabilizador en el raquis lumbar?",["Es alto y superior a la ecografía","Es bajo, en comparación con la ecografía","Es equivalente al de la electromiografía"],["Es lo contrario lo que se establece.","La evidencia científica del estabilizador en el raquis lumbar es baja, en comparación con la ecografía.","La electromiografía no es el comparador citado."]],
  "697": ["¿Qué ejercicio de control motor se cita para el raquis lumbar?",["La plancha lateral mantenida el mayor tiempo posible","La extensión activa del tronco contra resistencia","El balanceo alterno de los brazos y las piernas en cuadrupedia"],["La plancha depende de los isométricos de estabilización.","La extensión activa depende de las contracciones concéntricas y excéntricas.","El ejercicio de control motor citado es el balanceo alterno de los brazos y las piernas en posición cuadrúpeda."]],
  "698": ["¿Qué movimiento agrava el dolor facetario lumbar?",["La extensión del tronco","La flexión lumbar","El apoyo monopodal repetido"],["El dolor facetario se agrava con la extensión del tronco, la posición de pie prolongada y el paso de una posición sentada prolongada a de pie.","La flexión lumbar agrava el dolor discogénico.","El apoyo monopodal desencadena el dolor sacroilíaco."]],
  "699": ["¿Dónde asienta el dolor discogénico lumbar?",["De forma unilateral, por debajo del nivel de L5","En el centro, sobre la línea media","En barra, de un lado a otro del raquis"],["El dolor unilateral por debajo de L5 evoca una afectación sacroilíaca.","El dolor discogénico es central, sobre la línea media, con una irradiación posible a lo largo de la pierna.","El dolor en barra evoca un origen facetario."]],
  "700": ["¿Dónde asienta el dolor sacroilíaco?",["En el centro, sobre la línea media lumbar","En barra bilateral por encima de L5","De forma unilateral, por debajo del nivel de L5"],["El dolor medio evoca un origen discogénico.","El dolor en barra evoca un origen facetario.","El dolor sacroilíaco es unilateral y asienta por debajo de L5, con un dolor inguinal posible y una referencia posterolateral del muslo."]],
  "701": ["¿Qué se busca con la exploración de los movimientos fisiológicos ACTIVOS?",["La calidad del movimiento realizado","La cantidad de movimiento","La reproducción de los síntomas por sobrepresión"],["Los movimientos activos informan sobre la calidad del movimiento, los movimientos pasivos sobre la cantidad.","La cantidad se aprecia mediante los movimientos pasivos.","La sobrepresión es una maniobra distinta, realizada al final de la amplitud."]],
  "702": ["¿Qué busca la visualización DINÁMICA en la exploración lumbar?",["La diferencia descalzo y con calzado","El ritmo lumbopélvico del paciente","La calidad de la contracción del transverso"],["Esa comparación depende de la visualización estática.","La visualización dinámica se centra en el ritmo lumbopélvico, tras la inspección estática de pie y sentado.","La contracción del transverso se evalúa mediante el estabilizador."]],
  "703": ["¿Qué dosificación se establece para la técnica de Mulligan aplicada a la sacroilíaca?",["Tres series de dos minutos de trabajo a un hercio","Una serie única de diez repeticiones sin descanso","Tres series de diez repeticiones, descanso de 60 a 90 segundos"],["Esa dosificación corresponde a la movilidad articular pasiva.","El protocolo prevé tres series y tiempos de descanso.","La dosificación es de tres series de diez repeticiones a presión constante, con sesenta a noventa segundos de descanso entre las series."]],
  "704": ["¿A partir de qué dismetría pélvica está implicado el cuadrado lumbar?",["De 1,5 a 1,7 centímetros","Desde 0,2 centímetros","Por encima de 5 centímetros"],["El cuadrado lumbar es diana ante una dismetría pélvica de 1,5 a 1,7 centímetros, una marcha de Trendelenburg o cargas en flexoextensión con rotación.","Una diferencia así es inferior al umbral establecido.","El umbral establecido es mucho más bajo."]],
  "705": ["¿Qué músculos toma como diana la electroestimulación en la lumbalgia?",["El glúteo mayor y los isquiotibiales","Los multífidos y el transverso del abdomen","El cuadrado lumbar y el psoas ilíaco"],["Esos músculos superficiales no son la diana descrita.","La electroestimulación estimula los músculos estabilizadores profundos, multífidos y transverso del abdomen, en caso de déficit.","Esos músculos dependen del tratamiento de los tejidos blandos."]],
  "706": ["¿Qué músculos locales toma como diana el reentrenamiento de la estabilidad segmentaria?",["El recto mayor, los oblicuos y el glúteo mayor superficial","El cuadrado lumbar, el psoas y el piramidal","El transverso, el multífido y el suelo pélvico"],["Esos músculos superficiales no son los músculos locales buscados.","Esos músculos dependen del tratamiento de los tejidos blandos.","El trabajo de los músculos locales se dirige al transverso del abdomen, al multífido lumbar y al suelo pélvico."]],
  "707": ["¿Qué prueba explora la inestabilidad o la hipermovilidad lumbar?",["La prueba de inestabilidad en prono","La prueba de Gaenslen","La prueba de Slump en posición sentada"],["La prueba de inestabilidad en prono explora la inestabilidad o la hipermovilidad, mientras que el Slump y la elevación de la pierna extendida exploran la afectación nerviosa.","La prueba de Gaenslen explora la articulación sacroilíaca.","El Slump explora la afectación nerviosa."]],
  "708": ["En el tratamiento facetario, ¿cuándo se utilizan los movimientos transversales?",["Para tratar un dolor estrictamente medio y central","Cuando la presión unilateral no se tolera","Para movilizar la articulación sacroilíaca"],["El dolor central depende de la presión posteroanterior central.","Los movimientos transversales, aplicados transversalmente a la apófisis espinosa, sirven para mejorar el dolor y cuando el paciente no tolera la presión posteroanterior unilateral.","La sacroilíaca depende de otras técnicas."]],
  "709": ["¿Cómo mejorar la precisión de una manipulación lumbar?",["Aumentando la velocidad del impulso","Colocando la vértebra diana al final de la amplitud","Poniendo los segmentos adyacentes en tensión"],["La velocidad no determina la especificidad segmentaria.","La vértebra a manipular debe estar en posición articular neutra.","La manipulación tiene una especificidad baja: la vértebra diana debe estar en posición neutra y los segmentos adyacentes puestos en tensión para ganar precisión."]],
  "710": ["¿Cómo se trabaja la cápsula de la articulación sacroilíaca?",["Mediante pequeños círculos cíclicos, con la cadera flexionada","Mediante un impulso de alta velocidad único","Mediante una tracción longitudinal mantenida"],["La técnica capsular consiste en pequeños círculos cíclicos realizados con la cadera flexionada.","El impulso de alta velocidad es una técnica distinta.","La tracción mantenida no es la técnica descrita."]],
  "711": ["¿Qué indicación impone la técnica de Mulligan al terapeuta?",["Aumentar progresivamente la presión en cada repetición","Mantener la presión constante durante todo el tratamiento","Relajar la presión al final de cada movimiento"],["La presión debe permanecer constante.","El fisioterapeuta ejerce una presión pasiva constante mientras el paciente va hacia el movimiento doloroso.","La relajación durante la serie no está prevista."]],
  "712": ["¿Cuál de estas técnicas pertenece al tratamiento de los tejidos blandos lumbares?",["La presión posteroanterior","El deslizamiento neurodinámico por dos extremos","La inhibición por presión sostenida"],["Esa presión es una técnica articular.","El deslizamiento es una técnica de tejido neural.","Las técnicas establecidas son la inhibición por presión, la movilización dinámica de los tejidos blandos, la inhibición con estiramiento y las técnicas posisométricas."]],
  "713": ["¿Qué define la técnica de TENSIÓN neurodinámica?",["Los dos extremos son móviles, en direcciones opuestas","Un solo extremo es móvil, el otro está fijo","Los dos extremos se acompañan en el mismo sentido"],["En la técnica de tensión, los dos extremos son móviles pero se desplazan en direcciones opuestas, lo que aleja el origen de la inserción.","Un solo extremo móvil define el deslizamiento por un extremo.","El acompañamiento en el mismo sentido define el deslizamiento por dos extremos."]],
  "714": ["¿Con qué ejercicios comienza el enfoque de carga progresiva lumbar?",["Contracciones concéntricas y excéntricas controladas","Isométricos de estabilización, plancha y puente glúteo","Estiramientos suaves de los isquiotibiales y del psoas"],["Constituyen la etapa siguiente de la progresión.","Se comienza por ejercicios isométricos de estabilización, plancha y puente glúteo, para activar la musculatura profunda sin movimiento doloroso.","Los estiramientos dependen del apartado de movilidad y flexibilidad."]],
  "715": ["¿En qué situación disminuye el dolor discogénico?",["En flexión del tronco, durante el reposo sentado","En posición de pie prolongada en el trabajo","En extensión o tumbado, sin carga axial"],["La flexión aumenta el dolor discogénico.","La posición de pie prolongada agrava el dolor facetario.","Disminuye con los movimientos de extensión o en posición tumbada, cuando se suprime la carga axial."]],
  "716": ["¿A qué problema muscular puede asociarse el dolor sacroilíaco?",["Un problema del piramidal, fuente de seudociática","Una asimetría de tono entre los dos psoas","Una debilidad del transverso del abdomen"],["Puede asociarse a un problema del piramidal, que genera una seudociática.","La asimetría de los psoas se evalúa con la prueba de Thomas, en otro marco.","La debilidad del transverso depende del déficit de estabilidad segmentaria."]],
  "717": ["¿Qué caracteriza al dolor de estenosis lumbar?",["Un dolor constante bajo la nalga, con signos claros de radiculopatía aguda","Un dolor radicular intermitente bajo la nalga, desencadenado por la marcha","Un dolor medio aumentado por la flexión lumbar"],["El dolor constante con signos de radiculopatía caracteriza al dolor radicular.","El dolor de estenosis es radicular e intermitente bajo la nalga, comienza desde los muslos hacia distal y se desencadena con la actividad, en particular al caminar.","Ese perfil evoca un dolor discogénico."]],
  "718": ["¿Cómo se reconoce la presentación típica de la estenosis lumbar al caminar?",["El paciente camina evitando el apoyo monopodal","El paciente camina en extensión lumbar marcada","El paciente camina inclinado hacia delante"],["La evitación del apoyo monopodal evoca una afectación sacroilíaca.","La extensión agrava precisamente sus síntomas.","La presentación típica es la de un paciente que camina inclinado hacia delante, agravado cuando inclina el tronco hacia atrás."]],
  "719": ["¿Cuál de estos signos acompaña a un dolor radicular lumbar?",["Una pérdida de fuerza de los dedos del pie o de los talones","Un dolor más marcado por la mañana al despertar","Un alivio completo en posición sentada"],["El dolor radicular se acompaña de parestesias de la pierna o del pie y de una pérdida de fuerza de los dedos del pie o de los talones.","El predominio matinal evoca un dolor facetario.","La posición sentada no alivia el dolor radicular."]],
  "720": ["¿Qué es una respuesta SINTOMÁTICA favorable en la prueba de McKenzie?",["La amplitud aumenta después de las diez repeticiones","El dolor disminuye o se centraliza","El dolor se desplaza hacia el pie del paciente"],["La ganancia de amplitud es una respuesta MECÁNICA.","Una respuesta sintomática favorable es un dolor que disminuye o que se centraliza en el curso de las diez repeticiones.","El desplazamiento distal es una periferización, desfavorable."]],
  "721": ["¿En qué dirección se moviliza el hueso ilíaco en el tratamiento sacroilíaco?",["En traslación lateral pura","En distracción longitudinal axial","En rotación anterior o posterior"],["La traslación lateral no es la dirección descrita.","La distracción axial no es la técnica establecida.","El ilíaco se moviliza en rotación anterior o posterior, recibiendo el sacro una presión posteroanterior."]],
  "722": ["¿Qué prueba evalúa la asimetría de tono entre los dos psoas?",["La prueba de Thomas en decúbito","La prueba de Patrick-Fabere","La prueba de inestabilidad en prono"],["La asimetría de tono entre los dos psoas se evalúa con la prueba de Thomas.","Esa prueba explora la articulación sacroilíaca.","Esa prueba explora la inestabilidad segmentaria."]],
  "723": ["¿Qué situación orienta hacia un trabajo de la musculatura paravertebral?",["Una posición sentada prolongada en el puesto de trabajo","Una aceleración-desaceleración rápida, tipo accidente","Una asimetría de tono entre los psoas"],["La posición sentada prolongada debilita sobre todo los glúteos.","La musculatura paravertebral es diana después de una aceleración-desaceleración rápida, un accidente de coche o una inmovilidad prolongada.","La asimetría de los psoas se explora con la prueba de Thomas."]],
  "724": ["¿Qué caracteriza al deslizamiento neurodinámico por DOS extremos?",["La longitud del nervio está claramente aumentada","Los dos extremos se desplazan en sentidos opuestos","La longitud del nervio no se modifica"],["El alargamiento del nervio caracteriza al deslizamiento por un extremo y a la técnica de tensión.","El desplazamiento en sentidos opuestos define la técnica de tensión.","Es la técnica menos agresiva y más segura, reservada a los pacientes más afectados: el origen y la inserción se acompañan, por lo que la longitud del nervio no se modifica."]],
  "725": ["¿Qué extremo debe ser móvil en un deslizamiento por un extremo?",["El más distal respecto a la zona dolorosa","El más proximal respecto a la zona dolorosa","Indistintamente uno u otro"],["El extremo móvil debe ser el más distal respecto a la zona dolorosa, permaneciendo el otro fijo.","Es el extremo distal el que debe ser móvil.","La elección la precisa el curso."]],
  "726": ["¿Sobre qué dermatomas se aplica el TENS en la lumbalgia?",["De C5 a T1","De L3 a S1","De T6 a T12"],["Esos dermatomas corresponden al miembro superior.","El TENS se aplica sobre la zona dolorosa o a lo largo de las raíces nerviosas lumbares, de los dermatomas L3 a S1.","Esos dermatomas torácicos no son los buscados."]],
  "727": ["¿Dónde hay que colocar el borde inferior del estabilizador en el raquis lumbar?",["Justo por debajo de las últimas costillas flotantes","A nivel de la charnela toracolumbar","Justo por encima de las espinas ilíacas posteriores"],["Ese punto de referencia no es el establecido.","Ese punto de referencia es demasiado alto, según el curso.","El borde inferior del estabilizador se coloca justo por encima de las espinas ilíacas posterosuperiores, pasando la línea de las espinosas por el medio."]],
  "728": ["¿Qué designa el punto B en un diagrama de movimiento?",["El punto donde comienza la resistencia","El punto de dolor máximo admitido","El final de la movilidad pasiva media"],["El inicio de la resistencia se anota R1.","El dolor máximo admitido se anota P2.","El punto B marca el final de la movilidad pasiva media; en un movimiento normal, el límite coincide con B."]],
  "729": ["¿Cómo se califica el concepto Mulligan desde el punto de vista de la participación del paciente?",["Es una terapia activa","Es una terapia enteramente pasiva","Es una terapia instrumental asistida"],["El concepto es una terapia activa: la movilización accesoria pasiva se acompaña de un movimiento activo del paciente.","La participación activa del paciente está en el corazón del concepto.","El concepto no requiere ningún instrumento."]],
  "730": ["¿Qué población está principalmente afectada por el síndrome postural?",["Los sujetos mayores portadores de lesiones degenerativas","Los sujetos jóvenes, por sobrecarga tisular prolongada","Los deportistas después de un traumatismo agudo"],["Las lesiones degenerativas orientan hacia la disfunción postural.","El síndrome postural sobreviene generalmente en los jóvenes, debido a una sobrecarga tisular prolongada.","El traumatismo agudo no es el marco de ese síndrome."]],
  "731": ["¿Cómo se denomina la irradiación del dolor del raquis hacia el miembro inferior?",["Una centralización de los síntomas","Una preferencia direccional","Una periferización de los síntomas"],["La centralización es el fenómeno inverso: el dolor asciende hacia la región lumbar.","La preferencia direccional designa el movimiento que alivia, no el trayecto del dolor.","Cuando el dolor irradia de la región lumbar hacia los miembros inferiores, se habla de periferización."]],
  "732": ["¿Qué proporción de las lumbalgias mecánicas representa el síndrome de desarreglo?",["Del 25 al 30 %","Menos del 10 %","Del 75 al 80 %"],["Esa proporción subestima ampliamente su frecuencia.","Esa proporción no corresponde al principal subtipo.","El desarreglo representa el 75-80 % de los casos de lumbalgia mecánica."]],
  "733": ["¿Qué particularidad presentan las vías descendentes de modulación del dolor?",["Pueden amplificar tanto como reducir la señal dolorosa","Solo pueden reducir la señal dolorosa","Escapan a toda influencia emocional"],["Esas vías pueden amplificar la señal, se habla de facilitación, o reducirla, se habla de inhibición.","La facilitación también existe: el efecto no es unívoco.","Están al contrario influidas por la ansiedad y las expectativas."]],
  "734": ["¿Qué designa el signo del salto en la palpación?",["Una reacción involuntaria del paciente a la palpación","Una contracción refleja transitoria de las fibras del músculo","Una irradiación dolorosa a distancia del nódulo"],["El signo del salto es la reacción involuntaria del paciente durante la palpación del punto gatillo.","La contracción refleja transitoria es la respuesta de espasmo local.","La irradiación a distancia es el dolor referido."]],
  "735": ["¿Cómo se denomina el fenómeno de presión entre los fascículos de un nervio comprimido?",["Un mini síndrome compartimental","Un síndrome del desfiladero toracobraquial","Un síndrome de la cola de caballo"],["El mecanismo se describe como un mini síndrome compartimental entre los fascículos del nervio.","Ese síndrome designa una compresión anatómica precisa, no ese mecanismo intraneural.","Los síntomas de la cola de caballo son una contraindicación de las pruebas, no ese fenómeno."]],
  "736": ["¿De qué resulta el control motor?",["Únicamente de la fuerza desarrollada por los músculos agonistas","De la movilidad pasiva disponible en la articulación","De la integración de la información sensorial y motora"],["La potencia sin el control es inútil: la fuerza sola no basta.","La amplitud pasiva solo es un componente entre otros.","El control motor resulta de la integración de la información sensorial y motora, controlada por el sistema nervioso central."]],
  "737": ["¿Qué función asegura esencialmente la musculatura SUPERFICIAL?",["La movilidad de los segmentos","La estabilidad","La propiocepción articular fina"],["Al extenderse sobre varios segmentos y controlar la orientación espacial, la musculatura superficial asegura esencialmente la movilidad.","La estabilidad la asegura la musculatura profunda, de brazo de palanca corto.","La propiocepción no es la función atribuida a ese grupo."]],
  "738": ["¿Qué traduce una sensación final BLANDA en una prueba pasiva?",["Un estiramiento del tejido capsular y ligamentario","El contacto entre dos masas musculares","Un contacto directo entre dos superficies óseas"],["La tensión firme y progresiva traduce un estiramiento capsuloligamentario.","La sensación blanda, elástica o de compresión, resulta del contacto entre las masas musculares, por ejemplo en la flexión del codo o de la rodilla.","El contacto óseo da una detención brusca, sin elasticidad."]],
  "739": ["¿Cuál de estos elementos es un objetivo general del control motor?",["Evitar los defectos de movilidad, tanto por exceso como por defecto","Aumentar la fuerza máxima voluntaria del paciente","Mejorar la capacidad aerobia general del paciente"],["Los objetivos generales son restaurar la función musculoesquelética, reducir la percepción del dolor y evitar los defectos de movilidad.","La fuerza máxima depende del trabajo de fuerza, no del control motor.","La capacidad aerobia depende del ejercicio aerobio."]],
  "740": ["¿Qué músculos componen la sinergia de estabilidad segmentaria?",["Los erectores del raquis, el cuadrado lumbar, el psoas y los oblicuos","Los rectos mayores, los oblicuos y el glúteo mayor","Los multífidos, el transverso, el diafragma y el suelo pélvico"],["Esos músculos no componen la sinergia descrita.","Esos músculos superficiales no forman esa sinergia.","La estabilidad segmentaria se basa en la sinergia multífidos, transverso, diafragma y suelo pélvico."]],
  "741": ["¿Qué distingue el estiramiento BALÍSTICO del estiramiento dinámico?",["El mantenimiento de una fase estática al final de la amplitud","La utilización de una resistencia externa elástica","Acciones más rápidas, menos controladas y con rebote"],["El estiramiento dinámico precisamente no tiene fase estática.","La resistencia externa caracteriza al estiramiento asistido.","El estiramiento balístico se distingue del dinámico por acciones más rápidas, menos controladas y con rebote, llevadas hasta el final de la amplitud."]],
  "742": ["¿A cuántos mililitros de oxígeno por kilo y por minuto corresponde un equivalente metabólico?",["A 3,5 mililitros","A 10 mililitros","A 1 mililitro"],["Un equivalente metabólico corresponde a 3,5 mililitros de oxígeno por kilogramo y por minuto.","Ese valor no corresponde a la equivalencia establecida.","Ese valor subestima claramente la equivalencia."]],
  "743": ["¿Cuál de estos elementos es una adaptación PERIFÉRICA al ejercicio aerobio?",["La disminución de las resistencias periféricas totales","El aumento de la diferencia arteriovenosa de oxígeno","El aumento del volumen sistólico de eyección"],["El descenso de las resistencias es un cambio central.","Los cambios periféricos, que conciernen a la capacidad del músculo de extraer el oxígeno, comprenden las mitocondrias, las enzimas oxidativas, la mioglobina, la capilarización y la diferencia arteriovenosa.","El volumen sistólico es una adaptación central."]],
  "744": ["¿Qué fibras musculares tienen el umbral de activación más bajo?",["Las fibras de tipo II","Los dos tipos tienen el mismo umbral","Las fibras de tipo I"],["Las fibras de tipo II tienen un umbral más elevado y sirven a la fuerza máxima.","Los umbrales difieren claramente entre los dos tipos.","Las fibras de tipo I tienen un umbral de activación más bajo y sirven a los movimientos de baja intensidad, por tanto a la fuerza-resistencia."]],
  "745": ["¿Qué combina un estiramiento en facilitación neuromuscular propioceptiva?",["Un estiramiento estático y contracciones submáximas","Un estiramiento dinámico asociado a rebotes controlados","Un estiramiento pasivo prolongado sin ninguna contracción"],["Esos estiramientos combinan un estiramiento estático con contracciones musculares de intensidad submáxima a máxima.","Los rebotes pertenecen al estiramiento balístico.","La ausencia de contracción define el estiramiento estático pasivo."]],
  "746": ["¿Cuál es el principal determinante del efecto de un estiramiento sobre la amplitud?",["La técnica establecida, más que la dosis acumulada","La dosis de estiramiento, más que la técnica empleada","La posición articular de partida elegida"],["Es la conclusión inversa la que se establece.","Los datos actuales indican que la dosis de estiramiento, más que la técnica empleada, es el principal determinante del efecto sobre la amplitud.","La posición de partida no es el determinante citado."]],
  "747": ["¿Qué conclusión imponen los datos recientes sobre los estiramientos?",["Deben ser sistemáticos antes de todo ejercicio físico","Son superiores a cualquier otra intervención sobre la movilidad","No son obligatorios en ningún contexto terapéutico"],["Su carácter obligatorio se cuestiona precisamente.","Otras soluciones son igual de eficaces, o más.","Los estiramientos siguen siendo una opción facultativa, de eficacia comparable a otras intervenciones sobre la movilidad: su uso se evalúa caso por caso."]],
  "748": ["¿Cuál de estos elementos es una adaptación CENTRAL al ejercicio aerobio?",["La hipertrofia del ventrículo izquierdo","El aumento del número de mitocondrias","El aumento de la mioglobina muscular"],["Los cambios centrales, que conciernen a la capacidad de suministrar el oxígeno, comprenden el aumento del volumen sistólico, la hipertrofia ventricular izquierda y el descenso de las resistencias periféricas.","La multiplicación de las mitocondrias es un cambio PERIFÉRICO.","La mioglobina depende de las adaptaciones periféricas."]],
  "749": ["¿Cómo se define la fuerza MÁXIMA?",["La capacidad de mantener contracciones en el tiempo","La capacidad neuromuscular de superar una carga","La capacidad de superar una carga a velocidad máxima"],["El mantenimiento en el tiempo define la fuerza-resistencia.","La fuerza máxima es la capacidad del sistema neuromuscular de superar una carga mediante la contracción muscular.","La velocidad máxima define la fuerza explosiva."]],
  "750": ["¿Cuál de estos factores que influyen en la flexibilidad es INTRÍNSECO?",["La temperatura ambiente","La hora del día","La edad del paciente"],["La temperatura ambiental es un factor extrínseco.","El ritmo circadiano es un factor extrínseco.","Los factores intrínsecos comprenden la edad, el sexo y las modificaciones del embarazo, la genética y la morfología ósea."]],
  "751": ["¿A qué patología se asocia un déficit de flexión dorsal del tobillo?",["A la tendinopatía de Aquiles","Al conflicto femoroacetabular de cadera","Al síndrome subacromial del hombro"],["La falta de flexión dorsal del tobillo se asocia a la tendinopatía de Aquiles, a la fascitis plantar y a la tendinopatía rotuliana.","El conflicto femoroacetabular se asocia al déficit de rotación interna de cadera.","El síndrome subacromial se vincula al déficit de rotación interna de hombro."]],
  "752": ["¿Con qué instrumento se mide la amplitud articular?",["Un dinamómetro isocinético","Un goniómetro o un inclinómetro","Un algómetro de presión"],["El dinamómetro mide la fuerza, no la amplitud.","La movilidad articular se mide con instrumentos que cuantifican la amplitud angular: goniómetro, inclinómetro, fotogrametría.","El algómetro mide el umbral de dolor a la presión."]],
  "753": ["¿En qué debe basarse la elección del tipo de estiramiento?",["En la técnica mejor respaldada por la literatura","Únicamente en la disponibilidad del material de asistencia","En el contexto, las preferencias y los objetivos"],["Al no ser ninguna técnica superior, ese criterio no decide.","El material no es el criterio establecido.","La elección se basa en el contexto clínico o deportivo, las preferencias del paciente o del atleta y los objetivos del programa."]],
  "754": ["¿Cuál de estos efectos no produce el calentamiento por movilidad activa?",["Una ganancia duradera de fuerza máxima","Una preparación neuromuscular y propioceptiva","Una activación cardiorrespiratoria progresiva"],["El calentamiento prepara la carga y mejora la amplitud; no produce ganancia duradera de fuerza.","Esa preparación forma parte de las funciones del calentamiento.","La activación cardiorrespiratoria progresiva es una función del calentamiento."]],
  "755": ["¿Qué designa la viscosidad de un tejido?",["La resistencia de los tejidos que contienen fluidos a ser deformados","La capacidad de un tejido de volver a su forma inicial después de la deformación","La capacidad de deformarse bajo una fuerza externa"],["La viscosidad es la propiedad de los tejidos que contienen fluidos, caracterizada por su resistencia al estiramiento y al retorno a su tamaño inicial.","El retorno a la forma inicial define la elasticidad.","La deformación bajo fuerza define la distensibilidad."]],
  "756": ["¿Qué particularidad presenta el trabajo excéntrico después de la sesión?",["No provoca ninguna reacción inflamatoria después del esfuerzo","Provoca más inflamación, por tanto más adaptaciones","Disminuye las adaptaciones musculares a largo plazo"],["La inflamación posesfuerzo es precisamente característica.","El trabajo excéntrico provoca más inflamación después del entrenamiento, y es esa reacción la que genera más adaptaciones.","Las adaptaciones son al contrario mayores."]],
  "757": ["¿Cuál es la prevalencia anual media de la cervicalgia?",["Cerca del 15 %","Cerca del 37 %","Cerca del 50 %"],["El quince por ciento corresponde al límite bajo del intervalo.","Los estudios epidemiológicos refieren una prevalencia anual del 15 al 50 %, con una tasa media del 37,2 %.","El cincuenta por ciento corresponde al límite alto del intervalo."]],
  "758": ["¿Cómo evoluciona la prevalencia de la cervicalgia?",["Disminuye regularmente con la edad","Es idéntica a todas las edades de la vida","Aumenta con la edad y culmina en la edad media"],["La evolución descrita es inversa.","La edad influye claramente en la prevalencia.","La prevalencia aumenta con la edad, es más elevada en la mujer y alcanza su máximo en la edad media."]],
  "759": ["¿Qué proporción de la población tendrá un episodio de cervicalgia significativo?",["Cerca de una décima parte","Cerca de la mitad","La casi totalidad"],["Esa proporción subestima ampliamente la frecuencia del problema.","Cerca de la mitad de las personas tendrán un episodio de cervicalgia clínicamente significativo a lo largo de su vida.","La proporción establecida es del orden de la mitad, no de la totalidad."]],
  "760": ["¿Cómo se califica el enfoque terapéutico de la cervicalgia?",["Monomodal, centrado en la manipulación","Pasivo, esperando la resolución espontánea","Multimodal, adaptado a las necesidades del paciente"],["El manejo no se limita a una sola modalidad.","El consejo de mantenerse activo forma parte del manejo.","El enfoque es multimodal y se adapta a las necesidades del paciente: técnicas articulares, ejercicio, consejos para mantenerse activo y fisioterapia invasiva."]],
  "761": ["¿Qué movimientos se evalúan en un paciente con dolor discogénico según McKenzie?",["La flexión, la extensión y las traslaciones laterales","La flexión, la rotación y la inclinación lateral","La extensión y únicamente la traslación del lado doloroso"],["Se evalúan tres movimientos: flexión, extensión y traslación izquierda y derecha, dejando un minuto de descanso entre cada dirección.","La rotación no entra en las tres direcciones evaluadas.","Se evalúan ambas traslaciones."]],
  "762": ["¿Qué situación favorece una debilidad del glúteo medio y del glúteo menor?",["Un accidente de coche con latigazo cervical","La posición sentada prolongada","Una dismetría pélvica de 1,5 centímetros"],["La aceleración-desaceleración rápida concierne a la musculatura paravertebral.","El glúteo medio y el glúteo menor están implicados en los gestos deportivos, las marchas largas y la posición sentada prolongada, fuente de debilidad.","La dismetría pélvica concierne al cuadrado lumbar."]],
  "763": ["¿Cuál de estas pruebas explora la articulación sacroilíaca?",["La prueba de elevación de la pierna extendida","La prueba de empuje femoral","La prueba de inestabilidad en prono"],["Esa prueba explora la afectación nerviosa.","Las pruebas sacroilíacas comprenden el empuje femoral, la distracción, la compresión, el Gaenslen, el empuje sacro y el Patrick-Fabere.","Esa prueba explora la inestabilidad segmentaria."]],
  "764": ["¿Qué proporción de los dolores crónicos de espalda representan las afectaciones discogénica, facetaria y sacroilíaca?",["Cerca del 45 %","Cerca del 68 %","Cerca del 20 %"],["El cuarenta y cinco por ciento es la parte del dolor discogénico solo.","Los pacientes que presentan síntomas discogénicos, facetarios y sacroilíacos representan el 68 % de los dolores crónicos de espalda.","El veinte por ciento es la parte del dolor facetario solo."]],
  "765": ["¿Qué proporción de pacientes con lumbalgia presenta una patología grave?",["Del 10 al 20 %","Del 1 al 2 %","Cerca del 62 %"],["Esa proporción sobrestima muy ampliamente el riesgo.","Solo el 1-2 % de los pacientes con lumbalgia puede presentar una patología grave.","El sesenta y dos por ciento es la proporción que evoluciona hacia síntomas crónicos."]],
  "766": ["¿Qué proporción de las lumbalgias representa el dolor FACETARIO?",["Cerca del 20 %","Cerca del 45 %","Cerca del 15 %"],["El dolor facetario representa el 20 % de los dolores lumbares, frente al 45 % del discogénico y al 15 % del sacroilíaco.","El cuarenta y cinco por ciento corresponde al dolor discogénico.","El quince por ciento corresponde al dolor sacroilíaco."]],
  "767": ["¿Cuál es la prevalencia del dolor torácico en el adulto?",["Del 13 al 35 %","Del 4 al 15 %","Del 40 al 50 %"],["Ese intervalo es el del adolescente.","La prevalencia en el adulto varía del 4 al 15 %, frente al 13-35 % en el adolescente, donde es más frecuente en las chicas.","Esa prevalencia es muy superior a la descrita."]],
  "768": ["¿Qué proporción de los dolores dorsales representa el dolor facetario torácico?",["Cerca del 50 %","Cerca del 30 %","Cerca del 2 %"],["El dolor facetario representa el 50 % de los dolores dorsales.","El treinta por ciento corresponde a la osteocondritis entre los dolores no cardiacos.","Menos del 2 % corresponde a la radiculopatía torácica."]],
  "769": ["¿Qué proporción de los dolores torácicos NO cardiacos representa la osteocondritis?",["Cerca del 30 %","Cerca del 50 %","Menos del 2 %"],["La osteocondritis representa el 30 % de los dolores torácicos no cardiacos.","El cincuenta por ciento corresponde a la parte facetaria de los dolores dorsales.","Menos del 2 % corresponde a la radiculopatía torácica."]],
  "770": ["¿Cuál es la prevalencia de las radiculopatías torácicas?",["Del 4 al 15 %","Menos del 2 %","Cerca del 30 %"],["Ese intervalo es el del dolor torácico en general en el adulto.","La prevalencia de las radiculopatías y neuropatías torácicas es baja, inferior al 2 %.","El treinta por ciento corresponde a la osteocondritis entre los dolores no cardiacos."]],
  "771": ["¿A qué población afecta principalmente la osteocondritis?",["Los hombres de más de 60 años","Las mujeres de 20 a 50 años","Los adolescentes en periodo de crecimiento"],["Esa población no es la descrita.","La osteocondritis es más frecuente en la mujer entre los 20 y los 50 años.","La adolescencia no es el terreno de esa afección."]],
  "772": ["¿Qué músculo presenta más a menudo un punto gatillo en el síndrome subacromial?",["El infraespinoso","El subescapular","El supraespinoso"],["El infraespinoso está afectado en el 42 % de los casos, menos a menudo.","El subescapular está afectado en el 42 % de los casos, menos a menudo.","El supraespinoso está afectado en el 67 % de los casos, por delante del infraespinoso y del subescapular con un 42 %."]],
  "773": ["¿Sobre qué nervio se aplica la neuromodulación ecoguiada en el síndrome subacromial?",["El nervio supraescapular","El nervio musculocutáneo","El nervio torácico largo"],["La neuromodulación ecoguiada se aplica sobre el nervio supraescapular.","Ese nervio se cita en el síndrome miofascial, no aquí.","Ese nervio no es la diana establecida en ese síndrome."]],
  "774": ["¿Qué músculo explora la prueba de Patte?",["El supraespinoso","El infraespinoso","El subescapular"],["El supraespinoso se explora con la prueba de Jobe.","La prueba de Patte, abducción a 90° mantenida con rotación externa, explora el infraespinoso.","El subescapular se explora con el despegamiento de la mano de la espalda."]],
  "775": ["¿Qué hace positiva la prueba de Crank?",["Un dolor o un chasquido","Una pérdida de fuerza en rotación externa","Una aprensión sin dolor asociado"],["La prueba de Crank es positiva en caso de dolor o de chasquido durante las rotaciones bajo compresión axial.","La pérdida de fuerza orienta hacia una afectación tendinosa.","La aprensión aislada no es el criterio establecido aquí."]],
  "776": ["¿Cuál es el objetivo del trabajo del control motor en el síndrome subacromial?",["Alinear las superficies articulares para liberar el espacio subacromial","Alargar la cápsula retraída para ganar en rotación","Descargar el labrum glenoideo para limitar la inestabilidad glenohumeral"],["Mejorar el control motor y la propiocepción busca una mejor alineación de las superficies articulares a fin de liberar el espacio subacromial.","La ganancia capsular en rotación es el objetivo de la capsulitis adhesiva.","La protección labral concierne a las lesiones SLAP y Bankart."]],
  "777": ["¿Qué técnica de electroterapia se dirige a la bursitis subacromial?",["La magnetoterapia superinductiva","La electrólisis percutánea ecoguiada","La corriente interferencial analgésica"],["La magnetoterapia tiene un efecto antiinflamatorio general, no dirigido a la bursa.","La electrólisis percutánea ecoguiada es la opción establecida para la bursitis subacromial.","La corriente interferencial tiene un objetivo analgésico."]],
  "778": ["¿Por qué tratar el raquis cervical y torácico en una tendinopatía del manguito?",["Para desensibilizar los receptores capsulares","Para prevenir la irritación del nervio supraescapular","Para mejorar la postura y el espacio subacromial"],["La desensibilización de los receptores depende de los balanceos controlados.","La protección de ese nervio concierne a las lesiones labrales.","El trabajo del raquis cervical y torácico mejora la postura y por tanto el espacio subacromial."]],
  "779": ["¿Qué umbral de dolor respetar durante el ejercicio de una tendinopatía?",["Un dolor moderado inferior o igual a 3 sobre 10","Un dolor inferior o igual a 6 sobre 10","La ausencia total de toda sensación dolorosa"],["Hay que respetar un umbral de dolor moderado, inferior o igual a 3 sobre 10 durante el ejercicio, sin dolor persistente después.","Ese umbral es demasiado elevado respecto a la indicación.","No se exige la ausencia total de dolor."]],
  "780": ["¿Qué elemento debe hacer sospechar una necrosis avascular de la cabeza humeral?",["Un arco doloroso con signo de Neer claramente positivo","Una limitación activa aislada, con la pasiva totalmente conservada","Un dolor profundo con pérdida de rotación externa"],["Un signo de Neer positivo orientaría hacia un conflicto subacromial.","Ese perfil evoca una tendinopatía del manguito.","Ante pruebas de manguito y subacromiales negativas, un dolor profundo, una rigidez y una pérdida de rotación externa deben hacer sospechar una necrosis avascular."]],
  "781": ["¿Qué muestra la prueba de Apley, llamada «scratching test»?",["El sufrimiento del labrum glenoideo superior","La pérdida global de las rotaciones y de la abducción activas","La fatigabilidad precoz del músculo supraespinoso"],["El labrum superior se explora con la prueba de palma hacia arriba.","La prueba de Apley evalúa globalmente la pérdida de movimiento activo de rotación externa, de rotación interna y de abducción.","La fatigabilidad precoz se observa en la prueba resistida del supraespinoso."]],
  "782": ["¿Cuál es el mecanismo habitual de una lesión SLAP?",["Un traumatismo único, deportivo o profesional","Microtraumatismos repetidos por encima de 90°","Una interrupción del flujo sanguíneo circunflejo"],["El traumatismo único es el mecanismo de la lesión de Bankart.","La lesión SLAP resulta de microtraumatismos repetidos, generalmente en movimientos superiores a 90°.","La interrupción vascular conduce a una necrosis avascular."]],
  "783": ["¿Cómo se interpreta una prueba de O'Brien positiva?",["El dolor aumenta en rotación externa y disminuye en rotación interna","El dolor aparece solo con la compresión axial","El dolor aumenta en rotación interna y disminuye en rotación externa"],["Esa interpretación es la inversa de la establecida.","La compresión axial pertenece a la prueba de Crank.","La prueba es positiva si el dolor aumenta en rotación interna y disminuye en rotación externa."]],
  "784": ["¿Qué modificación ósea acompaña a la artrosis glenohumeral?",["Una muerte del tejido óseo subcondral","Una esclerosis subcondral con osteofitos","Un engrosamiento del ligamento coracohumeral"],["La necrosis del tejido subcondral define la necrosis avascular.","Las modificaciones óseas secundarias asocian esclerosis subcondral, osteofitos y estrechamiento del espacio articular.","El engrosamiento coracohumeral caracteriza a la capsulitis adhesiva."]],
  "785": ["¿En qué combinación de movimientos sobreviene principalmente el conflicto subacromial?",["La abducción asociada a la rotación externa","La aducción asociada a la extensión","La elevación asociada a la rotación interna"],["La abducción con rotación externa es la posición de la prueba de Patte.","Esa combinación no es la del conflicto.","El conflicto se produce principalmente en la elevación asociada a la rotación interna."]],
  "786": ["¿Cómo se realiza el signo de Neer?",["Mediante una abducción con el brazo en rotación interna","Mediante una rotación interna en abducción a 90° con el codo flexionado","Mediante una elevación resistida, con la mano sobre el hombro opuesto"],["El signo de pinzamiento o de Neer se realiza en abducción, con el brazo colocado en rotación interna.","Esa maniobra es la de la prueba de Hawkins.","Esa maniobra es la de la prueba de Yocum."]],
  "787": ["¿Qué enfermedad general constituye un factor de riesgo de tendinopatía del manguito?",["La anemia falciforme","La diabetes mellitus","La enfermedad de Gaucher"],["La anemia falciforme es un factor de necrosis avascular.","Los factores de riesgo comportan la edad, las alteraciones de la escápula, los desequilibrios musculares y la diabetes.","La enfermedad de Gaucher es un factor de necrosis avascular."]],
  "788": ["¿Qué limita la amplitud articular en el síndrome miofascial del hombro?",["La retracción de la cápsula articular","El dolor, y no una rigidez articular","El estrechamiento del espacio subacromial"],["La retracción capsular caracteriza a la capsulitis adhesiva.","El bloqueo en rotación y en abducción se debe al dolor, no a una rigidez articular.","Ese estrechamiento pertenece al síndrome subacromial."]],
  "789": ["¿Qué tipo de debilidad se observa en el síndrome miofascial del hombro?",["Una debilidad selectiva de los rotadores externos","Una debilidad proporcional a la atrofia visible","Una debilidad refleja sin esquema neuromotor definido"],["La debilidad selectiva de los rotadores orienta hacia una afectación tendinosa.","La debilidad no se vincula a una atrofia en ese cuadro.","Se observa una debilidad refleja, sin esquema neuromotor definido."]],
  "790": ["¿Qué situación perpetúa los puntos gatillo del supraespinoso?",["Una inmovilización en aducción y rotación interna","Una actividad prolongada a la altura de los hombros","Inyecciones intramusculares repetidas en el brazo"],["El supraespinoso se activa por los esfuerzos repetitivos de rotación interna, los levantamientos por encima de la cabeza y las inmovilizaciones prolongadas en aducción y rotación interna.","El trabajo prolongado a la altura de los hombros concierne al deltoides anterior.","Las inyecciones intramusculares conciernen al deltoides posterior."]],
  "791": ["¿Qué desequilibrio muscular acompaña a la artrosis glenohumeral?",["El de los rotadores externos y de los estabilizadores escapulares","El de los flexores y de los extensores del codo y de la muñeca","El de los depresores y de los elevadores de la laringe"],["El desequilibrio muscular progresivo afecta a los rotadores externos y a los estabilizadores escapulares.","El codo no está implicado en ese desequilibrio.","Esa región no guarda ninguna relación con la articulación."]],
  "792": ["¿Cuándo aparece el dolor del síndrome subacromial?",["Desde los primeros grados de rotación externa","En los últimos grados de elevación y de abducción","Únicamente en la supinación resistida"],["La rotación externa limitada de entrada evoca una capsulitis o una necrosis.","El dolor sobreviene en los últimos grados de elevación y de abducción del brazo.","La supinación resistida explora la porción larga del bíceps."]],
  "793": ["¿Qué exposición favorece el síndrome subacromial?",["Los portes de carga a lo largo del cuerpo","Los movimientos repetidos de rotación interna resistida","Los trabajos repetitivos por encima de la cabeza"],["El porte de carga a lo largo del cuerpo activa más bien el subescapular.","La rotación interna resistida repetida activa el redondo mayor.","El síndrome subacromial es más frecuente en los trabajos repetitivos por encima de la cabeza."]],
  "794": ["¿Entre qué estructuras se comprimen los elementos subacromiales?",["Entre el arco coracoacromial y el húmero","Entre el acromion y la espina de la escápula","Entre la clavícula y la primera costilla"],["La compresión mecánica se produce entre el arco coracoacromial y el húmero durante la elevación activa del brazo.","Esa relación anatómica no es la del conflicto.","Ese espacio corresponde a la travesía cervicotorácica."]],
  "795": ["¿Cómo se realiza la prueba de Yocum?",["Mediante una elevación resistida, con la mano apoyada sobre el hombro opuesto","Mediante una rotación interna resistida, con la mano despegada de la espalda","Mediante una supinación resistida, con el codo flexionado a 90°"],["La prueba de Yocum consiste en una elevación resistida, con la mano del paciente apoyada sobre el hombro contralateral.","El despegamiento de la mano de la espalda explora el subescapular.","La supinación resistida es la prueba de Yergason."]],
  "796": ["¿Qué característica tiene el dolor nocturno de las tendinopatías del manguito?",["Sobreviene en reposo ya desde el estadio inicial","Despierta al paciente acostado sobre el lado afectado","Se acompaña de una alodinia segmentaria"],["Un dolor de reposo precoz evoca más bien una necrosis avascular.","El dolor nocturno es frecuente y despierta al paciente cuando se acuesta sobre el lado afectado.","La alodinia segmentaria pertenece al síndrome miofascial."]],
  "797": ["¿Cuál es el perfil de amplitud en una tendinopatía del manguito?",["Activa limitada y dolorosa, pasiva conservada","Activa y pasiva igualmente limitadas y dolorosas","Activa conservada y pasiva limitada"],["La amplitud activa está limitada y es dolorosa en abducción y rotación externa, mientras que la pasiva está generalmente conservada o es poco dolorosa.","La igualdad de las amplitudes activa y pasiva caracteriza a la capsulitis adhesiva.","Ese perfil invertido no se describe."]],
  "798": ["¿Cómo se realiza la prueba de Yergason?",["Codo flexionado a 90°, supinación resistida","Codo flexionado a 90°, pronación resistida","Codo extendido, abducción resistida"],["La prueba de Yergason se realiza con el codo flexionado a 90° con una supinación resistida; explora la porción larga del bíceps.","Es la supinación, y no la pronación, la que se resiste.","Esa posición no es la de la prueba."]],
  "799": ["¿De qué lesión es una complicación la necrosis avascular del hombro?",["De una luxación acromioclavicular","De una fractura proximal del húmero","De una rotura completa del supraespinoso"],["La luxación acromioclavicular no se cita como causa.","La necrosis avascular del hombro es una complicación de las fracturas proximales del húmero.","La rotura tendinosa no se cita como causa."]],
  "800": ["¿Qué arteria está implicada en la necrosis avascular traumática de la cabeza humeral?",["La arteria subclavia","La arteria torácica interna","La arteria circunfleja"],["La arteria subclavia no participa en la vascularización de la cabeza humeral.","La arteria torácica interna irriga la pared anterior del tórax.","La forma traumática procede de una interrupción del flujo sanguíneo de la arteria circunfleja."]],
  "801": ["¿Qué causa no traumática puede provocar una necrosis avascular de la cabeza humeral?",["El uso prolongado de corticoides","Los trabajos repetitivos por encima de la cabeza","Los microtraumatismos repetidos por encima de 90°"],["Las causas no traumáticas comportan el uso prolongado de corticoides, las enfermedades hematológicas y las secuelas de quimioterapia o de radioterapia.","Esa exposición favorece el síndrome subacromial.","Ese mecanismo provoca las lesiones SLAP."]],
  "802": ["¿Qué brazo afecta con mayor frecuencia la capsulitis adhesiva?",["El brazo no dominante, en el 70 % de los casos","El brazo dominante, en el 70 % de los casos","Los dos brazos simultáneamente, en el 70 % de los casos"],["La capsulitis es más frecuente en el brazo no dominante, en el 70 % de los casos.","Es el brazo no dominante el más afectado.","La afectación simultánea bilateral no es la regla."]],
  "803": ["¿Cuál es la indicación de la electroestimulación en la capsulitis adhesiva?",["El dolor agudo de la fase de precongelación","La rigidez capsular persistente","La pérdida de masa muscular debida a la inactividad"],["El dolor agudo depende del TENS.","La rigidez capsular depende de la diatermia y de las movilizaciones.","La electroestimulación está indicada en caso de pérdida de masa muscular debida a la inactividad, útil en fase de descongelación."]],
  "804": ["¿Cuál es la posición de partida de la prueba de Crank?",["Abducción a 160° y codo flexionado","Flexión a 90° con 10° de aducción","Abducción a 90° con antebrazo en supinación"],["La prueba de Crank se realiza con el hombro en abducción a 160°, codo flexionado, con compresión axial y después rotaciones.","Esa posición es la de la prueba de O'Brien.","Esa posición es la de la prueba de tensión del bíceps."]],
  "805": ["¿Cómo se realiza la prueba de palma hacia arriba?",["Mano en la cintura y empuje superomedial resistido","Flexión a 90°, rotación externa y supinación resistida","Abducción a 90° y rotación externa mantenidas contra resistencia"],["Esa maniobra es la del anterior slide.","La prueba de palma hacia arriba asocia flexión a 90°, rotación externa y supinación, contra una fuerza caudal resistida.","Esa posición es la de la prueba de Patte."]],
  "806": ["¿Qué alteración sensorial acompaña al síndrome miofascial del hombro?",["Una alodinia segmentaria en la zona de referencia","Una hipoestesia en banda del miembro superior","Una anestesia completa del territorio axilar"],["Se encuentra una hipersensibilidad cutánea y una alodinia segmentaria en la zona de dolor referido.","La hipoestesia en banda evoca una afectación radicular.","La anestesia completa no pertenece a ese cuadro."]],
  "807": ["¿Qué factor perpetúa los puntos gatillo del deltoides posterior?",["Los traumatismos directos y las caídas","Los movimientos vigorosos en abducción","Las inyecciones intramusculares"],["Los traumatismos directos conciernen al deltoides anterior.","La abducción vigorosa concierne al deltoides medio.","El deltoides posterior se activa por un ejercicio excesivo y por las inyecciones intramusculares."]],
  "808": ["¿Qué factor perpetúa los puntos gatillo del trapecio superior?",["El mantenimiento de los hombros o de los brazos levantados","El acortamiento de la cadena anterior","Los esfuerzos excesivos después de un infarto"],["El trapecio superior se activa por los hombros o brazos levantados, los traumatismos agudos y las compresiones.","El acortamiento de la cadena anterior concierne a los trapecios medio e inferior.","Las secuelas de infarto conciernen al pectoral mayor."]],
  "809": ["¿Cuál es la indicación de la electrólisis percutánea en el síndrome miofascial?",["Los músculos debilitados por la inactividad prolongada","La hipersensibilidad con sensibilización central leve","Los nódulos miofasciales resistentes al tratamiento conservador"],["Los músculos debilitados dependen de la electroestimulación.","Esa situación depende de la corriente de tipo burst.","La electrólisis percutánea se dirige a los puntos gatillo persistentes o nódulos miofasciales resistentes al tratamiento conservador, bajo guía ecográfica."]],
  "810": ["¿Qué lugar ocupa el dolor del hombro entre los motivos de consulta musculoesquelética?",["El primer motivo más frecuente","El tercer motivo más frecuente","El sexto motivo más frecuente"],["El hombro no llega en cabeza de las consultas musculoesqueléticas.","El dolor del hombro es la tercera causa más frecuente de consulta musculoesquelética, con una incidencia cercana al 30 %.","El lugar establecido es claramente más alto que el sexto."]],
  "811": ["¿En qué grupo de edad es más frecuente el síndrome subacromial?",["Entre los 50 y los 60 años","Entre los 20 y los 30 años","Entre los 40 y los 60 años"],["Ese grupo corresponde a la capsulitis adhesiva.","Ese grupo no corresponde a la afección.","El síndrome subacromial es más frecuente entre los 40 y los 60 años."]],
  "812": ["¿Cuál es la prevalencia de la capsulitis adhesiva en población general?",["Del 5 al 7 %","Del 16 al 20 %","Del 2 al 5 %"],["Del cinco al siete por ciento corresponde a las tendinopatías del manguito.","El dieciséis por ciento corresponde a la artrosis glenohumeral después de los 65 años.","La capsulitis adhesiva afecta al 2-5 % de la población general, más a las mujeres, entre los 50 y los 60 años."]],
  "813": ["¿Qué parte del labrum afecta la lesión SLAP?",["El labrum glenoideo superior","El labrum glenoideo inferior","El labrum glenoideo posterior aislado"],["La lesión SLAP afecta al labrum glenoideo superior, generalmente alrededor de la inserción del bíceps largo en la glena.","El labrum inferior corresponde a la lesión de Bankart.","La afectación posterior aislada no es la definición."]],
  "814": ["¿Cuál es la prevalencia de la artrosis glenohumeral después de los 65 años?",["Cerca del 44 %","Cerca del 2 %","Cerca del 16 %"],["El cuarenta y cuatro por ciento corresponde a la parte del síndrome subacromial.","Del dos al cinco por ciento corresponde a la capsulitis adhesiva.","La artrosis glenohumeral afecta a cerca del 16 % de las personas de más de 65 años, más a las mujeres."]],
  "815": ["¿Qué parte de las artrosis periféricas representa la artrosis glenohumeral?",["Del 3 al 5 %","Del 16 al 20 %","Del 30 al 40 %"],["La artrosis glenohumeral representa el 3-5 % de todos los casos de artrosis periférica.","El dieciséis por ciento es su prevalencia en los mayores de 65 años, no su parte relativa.","Esa parte es muy superior a la establecida."]],
  "816": ["¿Qué parte de los dolores de hombro representa el síndrome subacromial?",["Del 16 al 20 %","Del 44 al 46 %","Del 5 al 7 %"],["El dieciséis por ciento es la prevalencia de la artrosis glenohumeral después de los 65 años.","El síndrome subacromial representa el 44-46 % de los dolores del hombro.","Del cinco al siete por ciento es la prevalencia de las tendinopatías del manguito."]],
  "817": ["¿Cómo se denomina el dolor anterolateral que se intensifica al elevar el brazo?",["El signo del salto palpatorio","El arco doloroso del hombro","El signo del desplome"],["La reacción de salto pertenece a la palpación de los puntos gatillo.","El dolor anterolateral que se intensifica cuando el hombro choca con el arco coracoacromial define el arco doloroso.","El desplome después de unos segundos traduce una fatigabilidad precoz."]],
  "818": ["¿Cuál es la prevalencia de las tendinopatías del manguito en población general?",["Del 2 al 5 %","Del 44 al 46 %","Del 5 al 7 %"],["Del dos al cinco por ciento corresponde a la capsulitis adhesiva.","Esa parte corresponde al síndrome subacromial entre los dolores de hombro.","La prevalencia estimada es del 5-7 % en población general, y alcanza el 30 % después de los 60 años."]],
  "819": ["¿Qué parte del labrum afecta la lesión de Bankart?",["El labrum glenoideo superior","El labrum glenoideo inferior","El rodete acromioclavicular"],["El labrum superior corresponde a la lesión SLAP.","La lesión de Bankart afecta al labrum glenoideo inferior y predispone a una degeneración glenohumeral.","Esa estructura no es la implicada."]],
  "820": ["¿Qué proporción de los dolores crónicos del hombro comporta un punto gatillo?",["Cerca del 45 %","Cerca del 25 %","Hasta el 85 %"],["El cuarenta y cinco por ciento subestima claramente la frecuencia de los puntos gatillo.","El veinticinco por ciento subestima muy ampliamente esa frecuencia.","Hasta el 85 % de los pacientes con dolores crónicos del hombro presenta un punto gatillo miofascial."]],
  "821": ["¿Cuál es la prevalencia de la epicondilalgia lateral?",["Del 0,3 al 0,6 % de la población general","Del 1 al 3 % de la población general","Del 10 al 15 % de la población general"],["Ese intervalo corresponde a la forma medial.","La epicondilalgia lateral afecta al 1-3 % de la población general, frente al 0,3-0,6 % de la forma medial.","Esa prevalencia es muy superior a la establecida."]],
  "822": ["¿Cuál es la prevalencia de la epicondilalgia medial?",["Del 1 al 3 % de la población general","Del 5 al 8 % de la población general","Del 0,3 al 0,6 % de la población general"],["Ese intervalo corresponde a la forma lateral.","Esa prevalencia es muy superior a la establecida.","La epicondilalgia medial solo afecta al 0,3-0,6 % de la población general."]],
  "823": ["¿A qué edad sobreviene con mayor frecuencia la epicondilalgia lateral?",["Entre los 35 y los 55 años","Entre los 50 y los 60 años","Entre los 20 y los 30 años"],["La forma lateral sobreviene entre los 35 y los 55 años, la forma medial entre los 50 y los 60 años.","Ese grupo corresponde a la forma medial.","Ese grupo no corresponde a la afección."]],
  "824": ["¿A qué edad sobreviene con mayor frecuencia la epicondilalgia medial?",["Entre los 35 y los 55 años","Entre los 50 y los 60 años","Entre los 60 y los 70 años"],["Ese grupo corresponde a la forma lateral.","La forma medial sobreviene más tardíamente, entre los 50 y los 60 años.","Ese grupo es más tardío que el establecido."]],
  "825": ["¿Qué proporción de las epicondilalgias evoluciona hacia síntomas persistentes?",["Cerca del 20 al 30 %","Cerca del 50 al 60 %","Cerca del 5 al 10 %"],["Cerca del 20-30 % de los pacientes desarrolla síntomas persistentes.","Esa proporción es muy superior a la establecida.","Esa proporción es inferior a la establecida."]],
  "826": ["¿Qué manifestación del síndrome del túnel carpiano es la más precoz?",["La manifestación motora","La manifestación autonómica","La manifestación sensitiva"],["La manifestación motora indica en general una compresión ya crónica.","La manifestación autonómica es la menos frecuente.","La manifestación sensitiva, con parestesias nocturnas, dolor irradiado e hipoestesia, es la más precoz y la más frecuente."]],
  "827": ["¿Qué articulación contribuye principalmente a la flexión dorsal de la muñeca?",["Las articulaciones mediocarpianas, en cerca del 67 %","La articulación radiocarpiana, en cerca del 67 %","La articulación radioulnar distal, en cerca del 67 %"],["Las mediocarpianas solo aseguran cerca del 33 % de la flexión dorsal.","La radiocarpiana asegura la contribución principal a la flexión dorsal, cerca del 67 % del total.","La radioulnar distal no interviene en esa distribución."]],
  "828": ["¿Qué músculo del hombro hay que plantear como causa posible de síntomas que evocan un túnel carpiano?",["El supraespinoso","El infraespinoso","El deltoides medio"],["El supraespinoso no se designa para ese diagnóstico diferencial.","Ante una sospecha de síndrome del túnel carpiano, conviene tener en cuenta los puntos gatillo del infraespinoso como causa posible de los síntomas.","El deltoides medio no se designa para ese diagnóstico diferencial."]],
  "829": ["¿Qué traduce la aparición de una debilidad con atrofia tenar?",["Una compresión aguda y reversible","Una compresión ya crónica","Una afectación puramente autonómica"],["Una afectación aguda no da atrofia muscular.","La debilidad acompañada de una atrofia tenar indica generalmente una compresión crónica.","Los signos autonómicos son distintos de la afectación motora."]],
  "830": ["¿Qué hace positivo el signo de Tinel en la muñeca?",["Una sensación de descarga eléctrica u hormigueo distal","Un dolor profundo que aparece después de 60 segundos","Una reproducción del dolor por compresión sostenida"],["El signo de Tinel es positivo en caso de sensación de descarga eléctrica o de hormigueo distal.","El plazo de un minuto pertenece a la prueba de Phalen.","La compresión sostenida pertenece a la prueba de Durkan."]],
  "831": ["¿Qué efecto tienen los ejercicios neurodinámicos sobre el nervio mediano?",["Aumentan la tensión del nervio en el túnel carpiano","Engrosan la vaina de mielina del nervio mediano","Aumentan su deslizamiento y reducen su edema"],["El aumento de tensión no es el efecto buscado.","No se describe ningún engrosamiento de la mielina.","Los ejercicios neurodinámicos aumentan el deslizamiento del nervio mediano, favorecen la difusión de los fluidos y reducen el edema intraneuronal."]],
  "832": ["¿Qué muestra el estadio I de la clasificación de Eaton?",["Un estrechamiento focal del espacio articular","Una ligera laxitud o un pequeño osteofito, sin pinzamiento","Una subluxación de la base del primer metacarpiano"],["El estrechamiento focal define el estadio II.","En el estadio I, la exploración es normal sin estrechamiento del espacio ni subluxación; son posibles una ligera laxitud o un pequeño osteofito.","La subluxación define el estadio III."]],
  "833": ["¿Para qué sirve la palpación palmar en la exploración de la base del pulgar?",["Para confirmar la subluxación del primer metacarpiano","Para cuantificar la fuerza de pinzamiento lateral","Para diferenciar una tenosinovitis de De Quervain"],["La subluxación no se confirma con esa palpación.","La fuerza de pinzamiento se evalúa con pruebas de prensión.","La palpación palmar es importante para diferenciar la rizartrosis de la tenosinovitis de De Quervain."]],
  "834": ["¿Cómo se realiza la prueba de compresión de Durkan?",["Un dedo percute suavemente el túnel repetidas veces","Las dos muñecas permanecen flexionadas durante 60 segundos","Los dos pulgares presionan firmemente sobre el túnel durante 30 segundos"],["La percusión pertenece al signo de Tinel.","La flexión mantenida pertenece a la prueba de Phalen.","El examinador coloca sus dos pulgares sobre el túnel carpiano y presiona firmemente durante 30 segundos."]],
  "835": ["¿Qué puede esperarse de la fisioterapia en el síndrome del túnel carpiano de la mujer?",["Resultados comparables a los de la cirugía","Un beneficio limitado únicamente al dolor nocturno de la muñeca","Un beneficio inferior al de la abstención terapéutica"],["En la mujer con síndrome del túnel carpiano, la fisioterapia puede dar resultados similares a los de la cirugía en términos de dolor y de función.","El beneficio no se limita al dolor nocturno.","No se refiere ningún resultado de ese orden."]],
  "836": ["¿Cuál es la indicación de las técnicas de deslizamiento neural en la muñeca?",["Una fase final de tratamiento bien tolerada","Una fase aguda o una irritabilidad elevada","Una atrofia tenar ya instaurada"],["La fase final puede depender de las técnicas de tensión.","El deslizamiento neural está indicado en fase aguda o en caso de irritabilidad elevada, y ante una sintomatología fluctuante.","La atrofia instaurada no es la indicación establecida."]],
  "837": ["¿Cómo se realiza la prueba de Grind?",["Mediante movimientos radiales y cubitales alternos","Mediante una compresión asociada a una rotación","Mediante una palpación palmar firme de la base del pulgar"],["Los movimientos radiales y cubitales pertenecen a la prueba de Lever.","La prueba de Grind asocia compresión y rotación; despierta generalmente dolor y crepitaciones.","La palpación palmar sirve para el diagnóstico diferencial."]],
  "838": ["¿Qué compresión hay que descartar ante una rizartrosis?",["La del nervio mediano, cuya coexistencia es frecuente","La del nervio cubital en el canal retroepitroclear","La del plexo braquial en la travesía torácica"],["Hay que descartar una compresión del nervio mediano, cuya coexistencia con la rizartrosis es frecuente.","El nervio cubital no es el que hay que descartar prioritariamente.","La travesía torácica no está implicada aquí."]],
  "839": ["¿En qué modo se aplica la diatermia en la artrosis de la mano?",["En modo capacitivo, a alta temperatura","En modo resistivo, a baja temperatura","En modo pulsado, en fase subaguda"],["El modo capacitivo a alta temperatura no es el establecido.","La diatermia se utiliza por su efecto antiinflamatorio a baja temperatura, en modo resistivo.","El modo pulsado concierne a los ultrasonidos terapéuticos."]],
  "840": ["¿Qué actividades desencadenan los síntomas diurnos del túnel carpiano?",["Las que exigen un pinzamiento lateral repetido","Las que exigen una flexión o una extensión de la muñeca","Las que exigen una prensión con el codo extendido"],["El pinzamiento lateral despierta el dolor de la rizartrosis.","Los síntomas diurnos se desencadenan por las actividades que requieren la flexión o la extensión de la muñeca, como el teclado o la conducción.","Esa combinación evoca una epicondilalgia lateral."]],
  "841": ["¿Cuál de estos signos depende de la afectación autonómica del túnel carpiano?",["La hipoestesia distal de los tres primeros dedos","La debilidad de la oposición del pulgar","La sequedad de la piel y el edema aparente"],["La hipoestesia distal es un signo sensitivo.","La debilidad de la oposición es un signo motor.","Los signos autonómicos asocian cambios de color, piel seca y edema aparente; son menos frecuentes."]],
  "842": ["¿Cómo se realiza la prueba de Phalen?",["Las dos muñecas flexionadas a 90°, dorso de las manos enfrentado","Las dos muñecas en extensión, palmas enfrentadas","El antebrazo en supinación, muñeca relajada"],["El paciente flexiona las dos muñecas a 90°, con el dorso de las manos enfrentado, y mantiene la posición 60 segundos.","La extensión no es la posición de la prueba de Phalen.","Esa posición es la del signo de Tinel."]],
  "843": ["¿Cuál es la amplitud de la flexión palmar de la muñeca?",["De 60 a 75°","De 70 a 85°","De 40 a 55°"],["Ese intervalo corresponde a la flexión dorsal.","La flexión palmar alcanza 70 a 85°, frente a 60-75° de la flexión dorsal.","Ese intervalo es inferior a los valores establecidos."]],
  "844": ["¿Cómo se describe la movilidad de las articulaciones carpometacarpianas?",["En pilares fijo, móvil y semimóvil","En columnas radial, central y cubital","En arcos transversal, longitudinal y oblicuo"],["La movilidad carpometacarpiana se describe en pilar fijo, pilar móvil y pilar semimóvil.","La descripción en columnas no es la establecida por el curso.","La descripción en arcos no es la establecida por el curso."]],
  "845": ["¿Cuál es el efecto principal de los movimientos accesorios en la muñeca?",["Una mejora del rodamiento-deslizamiento articular","Una modulación nociceptiva con mejora capsular","Un reprocesamiento sensitivomotor inmediato"],["La mejora del rodamiento-deslizamiento depende de las movilizaciones fisiológicas.","Los movimientos accesorios producen una modulación nociceptiva y una mejora capsular.","El reprocesamiento sensitivomotor depende de las técnicas de Mulligan."]],
  "846": ["¿Cómo se realiza una técnica de Mulligan en la muñeca?",["Mediante un movimiento pasivo lento y sostenido al final del recorrido","Mediante oscilaciones pasivas rítmicas de baja amplitud","Mediante un movimiento activo asociado a un deslizamiento accesorio mantenido"],["Ese modo corresponde a las movilizaciones fisiológicas.","Ese modo corresponde a los movimientos accesorios.","La técnica asocia un movimiento activo del paciente a un deslizamiento accesorio mantenido."]],
  "847": ["¿Cuál es el tamaño de los osteofitos en el estadio II de Eaton?",["Más de 2 mm","Más de 5 mm","Menos de 2 mm"],["Unos osteofitos de más de 2 mm caracterizan el estadio III.","Ese tamaño corresponde a los grandes osteofitos del estadio IV.","En el estadio II los osteofitos u osículos miden menos de 2 mm, con un estrechamiento focal del espacio."]],
  "848": ["¿Qué afectación define el estadio IV de la clasificación de Eaton?",["La de la articulación escafotrapezoidea adyacente","La de la articulación trapeciometacarpiana únicamente","La de las articulaciones interfalángicas distales"],["El estadio IV extiende las lesiones a la articulación escafotrapezoidea: es la artrosis pantrapecial.","La afectación aislada de la trapeciometacarpiana corresponde a los estadios anteriores.","Las interfalángicas no forman parte de esa clasificación."]],
  "849": ["¿Cómo evoluciona el dolor de la rizartrosis?",["De un dolor nocturno hacia un dolor únicamente diurno","De un dolor en carga hacia un dolor constante, incluso nocturno","De un dolor constante hacia un dolor puramente mecánico"],["Esa progresión es la del síndrome del túnel carpiano, en sentido inverso.","La evolución es progresiva: el dolor solo aparece primero en carga, y después se vuelve constante, incluso de noche.","Esa evolución es la inversa de la descrita."]],
  "850": ["¿Qué compensación se observa a nivel de la metacarpofalángica del pulgar?",["Una hiperextensión compensatoria","Una flexión compensatoria irreductible","Una desviación cubital progresiva"],["Puede observarse una hiperextensión compensatoria de la primera metacarpofalángica.","La flexión irreductible no es la compensación descrita.","La desviación cubital no es la compensación descrita."]],
  "851": ["¿Se acompaña la rizartrosis de dolores neuropáticos?",["Sí, con trastornos de la sensibilidad constantes","Sí, por compresión asociada del nervio cubital","No, pero la neurodinamia puede servir para controlar el dolor"],["Los trastornos de la sensibilidad no forman parte del cuadro.","El nervio cubital no está implicado en esa afección.","La rizartrosis evoluciona sin dolor neuropático ni trastorno de la sensibilidad, pero la neurodinamia puede servir para controlar el dolor."]],
  "852": ["¿Cuál es la duración del alivio que aporta una inyección de corticosteroides en la rizartrosis?",["De uno a tres meses","De seis a doce meses","De unas horas solamente"],["Los corticosteroides procuran un alivio rápido, pero generalmente de corta duración, de uno a tres meses.","Esa duración es muy superior a la establecida.","Esa duración es muy inferior a la establecida."]],
  "853": ["¿Qué indicación acompaña al trabajo de fuerza de la pinza en la rizartrosis?",["Buscar la amplitud máxima de la oposición","Evitar el desplome articular durante la pinza","Mantener la muñeca en flexión palmar sostenida"],["La amplitud máxima de oposición no es la indicación.","El trabajo de fuerza y el entrenamiento propioceptivo de la pinza se hacen sin desplome articular.","La flexión palmar sostenida no es la indicación."]],
  "854": ["¿Cuál es la prevalencia de la rizartrosis después de los 30 años?",["Cerca del 15 % en el hombre y del 7 % en la mujer","Cerca del 25 % en ambos sexos","Cerca del 7 % en el hombre y del 15 % en la mujer"],["La distribución establecida es inversa: la mujer está más afectada.","Esa prevalencia es muy superior a la establecida.","La rizartrosis afecta a cerca del 7 % de los hombres y al 15 % de las mujeres a partir de los 30 años."]],
  "855": ["¿Qué particularidad presenta la artrosis de las interfalángicas distales?",["Numerosos casos visibles sin ningún síntoma","Un dolor constantemente presente desde el inicio","Una afectación limitada a los sujetos de menos de 40 años"],["El porcentaje de afectación es elevado, pero numerosos casos visibles permanecen asintomáticos.","El dolor no está constantemente presente.","La afectación concierne a sujetos de más edad."]],
  "856": ["¿Cómo se denominan los nódulos de la artrosis interfalángica distal?",["Los nódulos de Bouchard","Los nódulos de Heberden","Los nódulos de Dupuytren"],["Los nódulos de Bouchard corresponden a las interfalángicas proximales.","Los nódulos de Heberden corresponden a la artrosis de las interfalángicas distales.","Esa denominación no corresponde a una artrosis digital."]],
  "857": ["¿Cómo se denominan los nódulos de la artrosis interfalángica proximal?",["Los nódulos de Heberden","Los nódulos de Garrod","Los nódulos de Bouchard"],["Los nódulos de Heberden corresponden a las interfalángicas distales.","Esa denominación no corresponde a una artrosis digital.","Los nódulos de Bouchard corresponden a la artrosis de las interfalángicas proximales."]],
  "858": ["¿Cómo se denomina la afectación degenerativa extendida del estadio IV de Eaton?",["La artrosis escafolunar avanzada","La artrosis radiocarpiana global","La artrosis pantrapecial"],["La afectación escafolunar no corresponde al estadio descrito.","La afectación radiocarpiana global no corresponde al estadio descrito.","La extensión a la articulación escafotrapezoidea define la artrosis pantrapecial."]],
  "859": ["¿Cómo se presenta el dolor del síndrome de la arcada de Frohse?",["Profundo y sordo, extendido a la cara dorsal del antebrazo","Superficial y eléctrico, en el dorso de la mano","Anteromedial, irradiado hacia la eminencia tenar"],["El dolor es profundo y sordo, y se extiende a la región dorsal del antebrazo.","El dolor superficial del dorso de la mano evoca un síndrome de Wartenberg.","Esa topografía evoca un síndrome del pronador redondo."]],
  "860": ["¿Qué deformidad ósea favorece el síndrome del canal cubital?",["Una costilla cervical","Un gancho del ganchoso fracturado","Un valgo marcado del codo"],["La costilla cervical favorece la salida torácica.","Esa lesión favorece la afectación del canal de Guyon.","El valgo del codo, la artrosis, los osteofitos, los quistes y la fibrosis postraumática predisponen a ello."]],
  "861": ["¿Cuál de estos músculos se toma como diana en la neuropatía del nervio cubital?",["El músculo palmar corto","El músculo supinador del antebrazo","El músculo pronador redondo del codo"],["Las dianas comportan el flexor cubital, la eminencia hipotenar, el palmar corto, el tríceps braquial y los flexores de los dedos.","El supinador es una diana de la afectación radial.","El pronador redondo es una diana de la afectación mediana."]],
  "862": ["¿Qué debilidad acompaña al síndrome de la salida torácica neurógeno?",["La del músculo supinador del antebrazo","La de los músculos intrínsecos de la mano","La de los músculos de la eminencia tenar"],["La debilidad del supinador depende de la afectación radial.","El cuadro neurógeno comporta una debilidad de los músculos intrínsecos de la mano.","La debilidad tenar depende de la afectación mediana."]],
  "863": ["¿Qué complicación vascular puede provocar el síndrome de la salida torácica venoso?",["Una isquemia aguda del antebrazo","Una fibrosis del triángulo interescalénico","Una trombosis venosa de esfuerzo"],["La isquemia depende de la forma arterial.","La fibrosis es un factor anatómico, no una complicación.","La forma venosa puede complicarse con una trombosis venosa de esfuerzo."]],
  "864": ["¿Qué músculo, hipertrofiado o contracturado, favorece el síndrome de la salida torácica?",["El escaleno anterior o el escaleno medio","El músculo supinador del antebrazo","El músculo pronador redondo del codo"],["La hipertrofia o la contractura del escaleno anterior o medio es un factor anatómico.","El supinador interviene en la afectación radial.","El pronador redondo interviene en la afectación mediana."]],
  "865": ["¿Qué músculos vuelve hiperactivos el patrón respiratorio superior?",["El diafragma y los intercostales internos","El dorsal ancho y los romboides","Los escalenos y el pectoral menor"],["El diafragma está al contrario subutilizado en ese patrón.","El dorsal ancho y los romboides no son músculos accesorios de la inspiración.","El uso excesivo de los músculos accesorios vuelve hiperactivos los escalenos y el pectoral menor."]],
  "866": ["¿Qué mide la prueba de Roos?",["La compresión en el triángulo interescalénico únicamente","La permeabilidad global de la salida torácica","La compresión bajo el músculo pectoral menor únicamente"],["El triángulo interescalénico se evalúa con la prueba de Adson.","La prueba de Roos evalúa la permeabilidad global de la salida torácica.","El espacio bajo el pectoral menor se evalúa con la prueba de Wright."]],
  "867": ["¿Qué hace positiva la prueba de Roos?",["La incapacidad de mantener la posición más de uno a dos minutos","La desaparición del pulso radial en la inspiración","La reproducción de un chasquido escapular audible"],["La prueba es positiva en caso de dolor, pesadez, parestesias o debilidad, o de incapacidad de mantener la posición más de 1 a 2 minutos.","La desaparición del pulso pertenece a las pruebas de Adson, de Eden y de Wright.","No se busca ningún chasquido en esa prueba."]],
  "868": ["¿Qué articulación se moviliza como complemento en la salida torácica?",["La articulación radioulnar distal","La articulación esternoclavicular","La articulación humeroulnar del codo"],["Esa articulación concierne a la afectación del nervio mediano.","Las movilizaciones accesorias se centran en las presiones vertebrales, las costotransversas y la esternoclavicular.","Esa articulación concierne a la afectación del nervio cubital."]],
  "869": ["¿Cuál de estos músculos es una diana del tratamiento de los tejidos blandos en la salida torácica?",["El músculo supinador del antebrazo","El músculo palmar corto de la mano","El músculo subclavio"],["El supinador es una diana de la afectación radial.","El palmar corto es una diana de la afectación cubital.","Las dianas comportan los escalenos, el subclavio, el pectoral menor, el trapecio superior, la porción corta del bíceps y los romboides."]],
  "870": ["¿Qué nervio comprime el síndrome de la arcada de Frohse?",["El nervio interóseo posterior","La rama sensitiva superficial del radial","El nervio mediano entre las cabezas del pronador"],["El síndrome de la arcada de Frohse comprime el nervio interóseo posterior a nivel del músculo supinador.","Esa rama está implicada en el síndrome de Wartenberg.","Esa compresión define el síndrome del pronador redondo."]],
  "871": ["¿Qué signo motor acompaña al síndrome de la arcada de Frohse?",["Una ausencia total de déficit motor","Una mano en garra de los dos últimos dedos","Una debilidad con atrofia muscular"],["La ausencia de déficit motor caracteriza al síndrome de Wartenberg.","La mano en garra depende de la afectación cubital.","El síndrome de la arcada de Frohse comporta una debilidad y una atrofia musculares."]],
  "872": ["¿Qué significa una sensibilidad aumentada a la palpación de un tronco nervioso?",["Es una información adicional, no concluyente","Es un criterio suficiente para establecer el diagnóstico","Es un criterio de exclusión formal del diagnóstico"],["Una sensibilidad aumentada a la palpación constituye una información adicional, que no es exclusiva ni concluyente.","No basta para concluir.","No excluye el diagnóstico."]],
  "873": ["¿Qué maniobra de diferenciación estructural acompaña a la prueba del nervio mediano?",["Una rotación cervical homolateral","Una inclinación cervical contralateral","Un descenso complementario del hombro"],["La rotación homolateral no es la maniobra citada.","La diferenciación estructural puede consistir en una inclinación cervical contralateral.","El descenso del hombro es el primer tiempo de la prueba."]],
  "874": ["¿Qué estructuras comprime el síndrome de la salida torácica?",["El plexo braquial y los vasos subclavios","Las raíces cervicales en sus forámenes óseos","El nervio cubital en el canal retroepitroclear"],["El síndrome de la salida torácica comprime el plexo braquial y los vasos subclavios y axilares.","La compresión foraminal depende de una radiculopatía cervical.","El canal retroepitroclear concierne únicamente al nervio cubital."]],
  "875": ["¿Qué exposición profesional favorece el síndrome de la salida torácica?",["Los apoyos prolongados sobre el codo","Los trabajos repetitivos por encima de la cabeza","Las compresiones repetidas de la eminencia hipotenar"],["El apoyo prolongado sobre el codo favorece la neuropatía cubital.","El síndrome se favorece por los trabajos repetitivos por encima de la cabeza, y afecta al 8 % de los atletas lanzadores.","Esa compresión favorece la afectación del canal de Guyon."]],
  "876": ["¿Qué raíces afecta principalmente el síndrome de la salida torácica neurógeno?",["Las ramas C5 y C6","Las ramas C8 y T1","Las ramas C6 y C7"],["Las raíces altas del plexo no son las principalmente afectadas.","El síndrome neurógeno afecta principalmente a las ramas C8 y T1.","Las raíces medias del plexo no son las principalmente afectadas."]],
  "877": ["¿En qué tiempos respiratorios se moviliza la caja torácica en la salida torácica?",["En la espiración forzada únicamente","En apnea inspiratoria únicamente","En la inspiración y en la espiración"],["La movilización no se limita a la espiración.","La apnea no es el tiempo establecido.","La movilización de la caja torácica se hace en la inspiración y en la espiración."]],
  "878": ["¿Qué raíces dan el nervio radial?",["Las raíces de C5 a T1","Las raíces C8 y T1","Las raíces C5 y C6"],["El nervio radial proviene de las raíces C5, C6, C7, C8 y T1.","C8 y T1 corresponden al nervio cubital.","Esas dos raíces no bastan para describir su origen."]],
  "879": ["¿Qué causa iatrogénica puede provocar un síndrome de Wartenberg?",["Un apoyo prolongado sobre el codo","Un yeso mal ajustado","Una vibración transmitida por una herramienta"],["El apoyo sobre el codo favorece la afectación cubital.","Las causas pueden ser mecánicas, posturales, traumáticas o iatrogénicas, como las pulseras, los relojes o un yeso mal ajustado.","Las vibraciones favorecen el síndrome del túnel carpiano."]],
  "880": ["¿Qué define una prueba neurodinámica negativa?",["La provocación de síntomas desconocidos por el paciente","Una diferenciación estructural positiva aislada","La ausencia de síntomas conocidos y de asimetría"],["Los síntomas desconocidos hacen la prueba significativa.","La diferenciación positiva aislada no define una prueba negativa.","Una prueba es negativa en ausencia de síntomas conocidos y de asimetría."]],
  "881": ["¿Qué raíces dan el nervio cubital?",["C5 y C6","De C5 a T1","C8 y T1"],["Esas raíces no son las del nervio cubital.","Ese origen extendido corresponde a los nervios radial y mediano.","El nervio cubital proviene de las raíces C8 y T1."]],
  "882": ["¿Qué dedos vuelve parestésicos la afectación del canal de Guyon?",["El quinto dedo y la mitad del cuarto","El pulgar, el índice y el dedo medio de la mano","La cara radial del dorso de la mano"],["Las parestesias afectan al quinto dedo y a la mitad cubital del cuarto.","Ese territorio corresponde al nervio mediano.","Ese territorio corresponde a la rama sensitiva del radial."]],
  "883": ["¿Qué posición de la muñeca comporta la prueba neurodinámica del nervio cubital?",["Una flexión palmar de la muñeca con flexión de los dedos","Una flexión dorsal de la muñeca con extensión de los dedos","Una inclinación cubital mantenida de la muñeca"],["La flexión palmar pertenece a la prueba del nervio radial.","La prueba comporta una flexión dorsal de la muñeca y una extensión de los dedos.","Esa posición no es la de la prueba."]],
  "884": ["¿Qué combinación realiza un deslizamiento por un extremo del nervio mediano?",["Cervicales neutras, flexión del codo, extensión de la muñeca y de los dedos","Cervicales neutras, extensión del codo, flexión de la muñeca y de los dedos","Cervicales neutras, extensión del codo, extensión de la muñeca y de los dedos"],["Esa combinación corresponde al nervio cubital.","Esa combinación corresponde al nervio radial.","El deslizamiento por un extremo del nervio mediano asocia cervicales neutras, extensión del codo y extensión de la muñeca y de los dedos."]],
  "885": ["¿Qué combinación realiza una técnica de tensión del nervio cubital?",["Inclinación cervical contralateral, flexión del codo, extensión de la muñeca","Inclinación cervical contralateral, extensión del codo, flexión de la muñeca","Inclinación cervical homolateral, flexión del codo, flexión de la muñeca"],["La tensión del nervio cubital asocia una inclinación cervical contralateral, una flexión del codo y una extensión de la muñeca y de los dedos.","Esa combinación corresponde a la tensión del nervio radial.","La inclinación homolateral pertenece al deslizamiento, no a la tensión."]],
  "886": ["¿Qué patrón respiratorio agrava el síndrome de la salida torácica?",["Un patrón de predominio superior","Un patrón de predominio diafragmático","Un patrón de predominio abdominal bajo"],["Un patrón respiratorio de predominio superior, con uso excesivo de los músculos accesorios, conlleva una hiperactividad de los escalenos y del pectoral menor.","La respiración diafragmática se busca al contrario.","Ese patrón no es el descrito como agravante."]],
  "887": ["¿Qué espacio evalúa la prueba de Adson?",["El espacio costoclavicular","El triángulo interescalénico","El espacio subcoracoideo"],["El espacio costoclavicular se evalúa con la prueba de Eden.","La prueba de Adson evalúa la compresión en el triángulo interescalénico, entre los escalenos anterior y medio.","El espacio subcoracoideo se evalúa con la prueba de Wright."]],
  "888": ["¿Qué se observa en la prueba de Adson?",["La incapacidad de mantener la posición dos minutos","La aparición de un chasquido articular audible","La disminución o la desaparición del pulso radial"],["La prueba de resistencia pertenece a la prueba de Roos.","No se busca ningún chasquido en esa prueba.","Se observa si el pulso radial disminuye o desaparece, y si los síntomas se reproducen."]],
  "889": ["¿Qué espacio evalúa la prueba de Eden?",["El espacio entre la clavícula y la primera costilla","El espacio entre los escalenos anterior y medio","El espacio situado bajo el músculo pectoral menor"],["La prueba de Eden, o prueba del cuello clavicular, comprime el espacio entre la clavícula y la primera costilla.","Ese espacio se evalúa con la prueba de Adson.","Ese espacio se evalúa con la prueba de Wright."]],
  "890": ["¿Qué maniobra realiza el terapeuta en la prueba de Eden?",["Una abducción pasiva del brazo a 90°","Un descenso del hombro del paciente","Una extensión del cuello hacia el lado explorado"],["La abducción pasiva pertenece a la prueba de Wright.","El terapeuta toma el hombro y efectúa un movimiento hacia abajo, mientras el paciente inspira y lleva los hombros hacia atrás.","La extensión del cuello pertenece a la prueba de Adson."]],
  "891": ["¿Qué posición adopta el brazo en la prueba de Wright?",["Una abducción a 90° con el codo flexionado a 90°","Una posición relajada a lo largo del cuerpo","Una abducción a 90° y después una rotación externa máxima"],["Esa posición pertenece a la prueba de Roos.","La posición relajada pertenece a las pruebas de Adson y de Eden.","El fisioterapeuta eleva pasivamente el brazo en abducción a 90°, y después realiza una rotación externa máxima."]],
  "892": ["¿Qué rama comprime el síndrome de Wartenberg?",["El nervio interóseo posterior del radial","La rama superficial sensitiva del nervio radial","La rama profunda motora del nervio cubital"],["El nervio interóseo posterior depende del síndrome de la arcada de Frohse.","El síndrome de Wartenberg comprime la rama superficial sensitiva del nervio radial.","Esa rama depende de la afectación del canal de Guyon."]],
  "893": ["¿Cuál es el perfil clínico del síndrome de Wartenberg?",["Una afectación sensitiva, sin debilidad o con debilidad mínima","Una afectación motora pura con atrofia marcada","Una afectación mixta con déficit sensitivo y motor por igual"],["El síndrome de Wartenberg da dolor y parestesias en el dorso de la mano, cara radial, sin debilidad motora o con una debilidad mínima.","La afectación motora con atrofia depende de la arcada de Frohse.","El perfil descrito es ante todo sensitivo."]],
  "894": ["¿Qué confirma la exploración por resonancia magnética en una neuropatía del miembro superior?",["El engrosamiento del tronco nervioso","La atrofia de los músculos inervados","La ralentización de la conducción"],["El engrosamiento del tronco se ve en ecografía.","La exploración por resonancia magnética confirma la atrofia muscular.","La ralentización de la conducción se objetiva con el electromiograma."]],
  "895": ["¿Qué define una prueba neurodinámica significativa?",["La provocación de síntomas ya conocidos por el paciente","La ausencia de síntoma y de toda asimetría medible","Una asimetría de amplitud o síntomas desconocidos"],["La provocación de síntomas conocidos define una prueba positiva.","Esa situación define una prueba negativa.","Una prueba es significativa en caso de asimetría importante de amplitud o de aparición de síntomas desconocidos, con diferenciación estructural positiva."]],
  "896": ["¿Qué posición del codo comporta la prueba neurodinámica del nervio radial?",["Una extensión completa del codo","Una flexión del codo a 90°","Una flexión máxima del codo a 120°"],["La prueba del nervio radial comporta una extensión del codo a 0°.","La flexión del codo a 90° pertenece a las pruebas de los nervios mediano y cubital.","Esa posición pertenece a la prueba de estrés en valgo."]],
  "897": ["¿Qué posición del hombro comporta la prueba neurodinámica del nervio radial?",["Una abducción de 90° con rotación externa","Una abducción de 10° con rotación interna","Una abducción de 90° con rotación interna"],["Esa posición pertenece a la prueba del nervio mediano.","La prueba del nervio radial asocia una abducción de 10° y una rotación interna del hombro.","Esa posición no es la de la prueba del radial."]],
  "898": ["¿Qué posición de la muñeca comporta la prueba neurodinámica del nervio radial?",["Una extensión de la muñeca y de los dedos","Una posición neutra mantenida de la muñeca","Una flexión de la muñeca y de los dedos"],["La extensión de la muñeca pertenece a las pruebas de los nervios mediano y cubital.","La posición neutra no es la de la prueba.","La prueba del nervio radial comporta una flexión de los dedos y de la muñeca, con pronación del antebrazo."]],
  "899": ["¿Dónde se sitúa el último punto de tensión en el síndrome de Wartenberg?",["En la muñeca","En el codo","En el antebrazo medio"],["En el síndrome de Wartenberg, el último punto de tensión es la muñeca.","El codo es el último punto de tensión del síndrome de la arcada de Frohse.","El antebrazo medio no es el punto descrito."]],
  "900": ["¿Entre qué estructuras comprime el síndrome del pronador redondo el nervio mediano?",["Entre las dos cabezas del músculo supinador","Entre las dos cabezas del músculo pronador redondo","Bajo el retináculo de los flexores del carpo"],["El supinador concierne al nervio interóseo posterior.","El síndrome del pronador redondo comprime el nervio mediano entre las dos cabezas de ese músculo.","El retináculo de los flexores corresponde al túnel carpiano."]],
  "901": ["¿Cuál es la consecuencia de la compresión del nervio mediano en el pronador redondo?",["Una sección axonal completa e irreversible","Una desmielinización extensa de los troncos del plexo braquial","Una irritación o una isquemia nerviosa leve a moderada"],["No se describe ninguna sección axonal completa.","El plexo braquial no está implicado aquí.","La compresión provoca una irritación o una isquemia nerviosa leve a moderada."]],
  "902": ["¿Qué profesión está expuesta al síndrome del pronador redondo?",["Los mecánicos y los fisioterapeutas","Los ciclistas de larga distancia","Los atletas lanzadores de alto nivel"],["Los movimientos repetidos de pronosupinación o de flexión del codo exponen a los deportistas de raqueta, a los mecánicos y a los fisioterapeutas.","El ciclismo expone a la afectación del canal de Guyon.","Los lanzadores están expuestos al síndrome de la salida torácica."]],
  "903": ["¿Qué movilizaciones accesorias completan el tratamiento del nervio mediano?",["Las de las articulaciones costotransversas torácicas","Las de las dos líneas del carpo y de la radioulnar distal","Las de los transversales ulnares del codo"],["Las costotransversas dependen de la salida torácica.","El tratamiento comporta movilizaciones accesorias de la primera y la segunda línea del carpo y de la radioulnar distal.","Los transversales ulnares dependen de la afectación cubital."]],
  "904": ["¿Entre qué estructuras comprime el síndrome del canal cubital el nervio?",["Entre las dos cabezas del flexor ulnar del carpo","Entre las dos cabezas del músculo pronador redondo","Bajo la arcada fibrosa del músculo supinador"],["El curso sitúa la compresión entre las dos cabezas del músculo flexor ulnar del carpo.","El pronador redondo comprime el nervio mediano.","La arcada del supinador comprime el nervio interóseo posterior."]],
  "905": ["¿Qué actividad expone al síndrome del canal cubital?",["La compresión repetida de la eminencia hipotenar","El apoyo prolongado sobre el codo","El uso repetido de un teclado y de un teléfono"],["Esa compresión expone a la afectación del canal de Guyon.","Las actividades repetitivas de flexoextensión del codo y el apoyo prolongado sobre el codo exponen a ello.","Esos gestos exponen al síndrome del túnel carpiano."]],
  "906": ["¿Qué masa puede comprimir el nervio cubital en el canal de Guyon?",["Un osteofito del cóndilo humeral medial","Una banda fibrosa del triángulo interescalénico","Un quiste ganglionar o un lipoma"],["El osteofito del codo depende del canal cubital.","Las bandas fibrosas interescalénicas dependen de la salida torácica.","Una masa ocupante, como un quiste ganglionar o un lipoma, puede comprimir el nervio."]],
  "907": ["¿Qué lesión ósea puede provocar una afectación del canal de Guyon?",["Una fractura mal consolidada del ganchoso","Una fractura proximal del húmero","Una apófisis transversa alargada de C7"],["Una fractura o una mala consolidación del gancho del ganchoso o del pisiforme puede ser su causa.","Esa fractura no está implicada en la muñeca.","Esa variación concierne a la salida torácica."]],
  "908": ["¿Cómo se desplazan los dos extremos en una técnica de tensión?",["Son móviles, en sentidos opuestos","Son móviles, en el mismo sentido","Solo uno es móvil, el otro permanece fijo"],["En la técnica de tensión, los dos extremos son móviles pero en sentidos opuestos: se alejan el origen y la inserción.","El desplazamiento en el mismo sentido caracteriza al deslizamiento por los dos extremos.","Un solo extremo móvil caracteriza al deslizamiento por un extremo."]],
  "909": ["¿Qué límite respetar en una técnica de tensión neural?",["No superar diez segundos de mantenimiento","No reproducir el dolor del paciente","No asociar componente cervical"],["No se plantea ningún límite de duración de ese tipo.","Se alejan el origen y la inserción sin reproducir el dolor.","El componente cervical forma al contrario parte de la técnica."]],
  "910": ["¿Qué combinación realiza un deslizamiento por un extremo del nervio cubital?",["Cervicales neutras, extensión del codo, extensión de la muñeca y de los dedos","Cervicales neutras, extensión del codo, flexión de la muñeca y de los dedos","Cervicales neutras, flexión del codo, extensión de la muñeca y de los dedos"],["Esa combinación corresponde al nervio mediano.","Esa combinación corresponde al nervio radial.","El deslizamiento por un extremo del nervio cubital asocia cervicales neutras, flexión del codo y extensión de la muñeca y de los dedos."]],
  "911": ["¿Qué combinación realiza un deslizamiento por un extremo del nervio radial?",["Cervicales neutras, extensión del codo, flexión de la muñeca y de los dedos","Cervicales neutras, extensión del codo, extensión de la muñeca y de los dedos","Cervicales neutras, flexión del codo, extensión de la muñeca y de los dedos"],["El deslizamiento por un extremo del nervio radial asocia cervicales neutras, extensión del codo y flexión de la muñeca y de los dedos.","Esa combinación corresponde al nervio mediano.","Esa combinación corresponde al nervio cubital."]],
  "912": ["¿Qué combinación realiza una técnica de tensión del nervio radial?",["Inclinación cervical contralateral, flexión del codo, extensión de la muñeca","Inclinación cervical contralateral, extensión del codo, flexión de la muñeca","Inclinación cervical homolateral, extensión del codo, flexión de la muñeca"],["Esa combinación corresponde a la tensión del nervio cubital.","La tensión del nervio radial asocia una inclinación cervical contralateral, una extensión del codo y una flexión de la muñeca y de los dedos.","La inclinación homolateral pertenece al deslizamiento, no a la tensión."]],
  "913": ["¿Cuál es la neuropatía compresiva más frecuente del cuerpo humano?",["El síndrome del túnel carpiano","El síndrome del canal cubital","El síndrome de la salida torácica"],["El síndrome del túnel carpiano es la neuropatía periférica por compresión más frecuente del cuerpo humano.","El canal cubital solo es la segunda neuropatía del miembro superior.","La salida torácica tiene una incidencia mucho menor."]],
  "914": ["¿Cuál es la relación entre sexos del síndrome de la salida torácica?",["Tres a cuatro veces más frecuente en el hombre","Repartido igualmente entre ambos sexos","Tres a cuatro veces más frecuente en la mujer"],["El predominio descrito es femenino.","Se describe un predominio claro.","El síndrome de la salida torácica es 3 a 4 veces más frecuente en la mujer, entre los 20 y los 50 años."]],
  "915": ["¿En qué grupo de edad sobreviene el síndrome de la salida torácica?",["Entre los 20 y los 50 años","Entre los 50 y los 70 años","Entre los 10 y los 20 años"],["El síndrome de la salida torácica sobreviene entre los 20 y los 50 años.","Ese grupo es más tardío que el descrito.","Ese grupo es más precoz que el descrito."]],
  "916": ["¿Qué proporción de las epicondilopatías laterales comporta un síndrome de la arcada de Frohse?",["Cerca del 45 %","Cerca del 19 %","Cerca del 5 %"],["Esa proporción es muy superior a la establecida.","El síndrome de la arcada de Frohse está presente en el 19,4 % de las epicondilopatías laterales.","Esa proporción es inferior a la establecida."]],
  "917": ["¿En quién es más frecuente el síndrome de Wartenberg?",["En el hombre","En el niño en crecimiento","En la mujer"],["El predominio descrito es femenino.","La infancia no es el terreno descrito.","La prevalencia del síndrome de Wartenberg es más elevada en la mujer que en el hombre."]],
  "918": ["¿Cuál es la prevalencia global del síndrome del túnel carpiano?",["Cerca del 5 %","Cerca del 14 %","Cerca del 30 %"],["Esa prevalencia es inferior a la establecida.","La prevalencia global del síndrome del túnel carpiano es del 14,4 %.","Esa prevalencia es superior a la establecida."]],
  "919": ["¿Qué lugar ocupa el síndrome del canal cubital entre las neuropatías del miembro superior?",["El segundo más frecuente","El primero más frecuente","El cuarto más frecuente"],["El síndrome del canal cubital es la segunda neuropatía más frecuente del miembro superior.","El primer lugar corresponde al síndrome del túnel carpiano.","El lugar establecido es mucho más alto."]],
  "920": ["¿Qué población está expuesta a la afectación del canal de Guyon?",["Los atletas lanzadores","Los ciclistas de carretera","Los jugadores de raqueta"],["Los lanzadores están expuestos a la salida torácica.","Los ciclistas están expuestos por compresión repetida de la eminencia hipotenar sobre el manillar.","Los deportes de raqueta exponen al síndrome del pronador redondo."]],
  "921": ["¿Cuál es el mecanismo de acción de las ondas de choque en la necrosis avascular?",["La reducción directa de la presión intraósea","El bloqueo de las señales dolorosas medulares","El aumento de los factores angiogénicos y osteogénicos"],["La descompresión mecánica depende del tratamiento articular.","El bloqueo de las señales corresponde al modo de acción de la corriente analgésica.","Las ondas de choque aumentan la expresión de los factores de crecimiento angiogénicos y osteogénicos."]],
  "922": ["¿Qué posición utiliza la prueba HEC?",["Flexión de cadera a 90° con rotación interna y aducción","Flexión de la rodilla con flexión, abducción y rotación externa de cadera","Extensión de cadera con rotación externa máxima"],["Esa combinación es la de la prueba FADIR.","El paciente en decúbito supino flexiona la rodilla colocando a la vez la cadera en flexión, abducción y rotación externa, y después eleva el pie hacia el techo.","Esa combinación es la de la maniobra de aprehensión."]],
  "923": ["¿En qué fase está indicado el deslizamiento por un extremo en la cadera?",["En las fases intermedias del tratamiento","En las fases más agudas e irritables","En las fases terminales de readaptación deportiva"],["El deslizamiento por un extremo se utiliza en las fases intermedias del tratamiento, con un extremo fijo.","Las fases más afectadas dependen del deslizamiento por dos extremos.","Las fases terminales dependen de la tensión."]],
  "924": ["¿Qué grado articular se busca antes de aplicar un movimiento accesorio?",["El grado máximo, incluso doloroso","El grado límite articular sin dolor","El grado de reposo articular estricto"],["El dolor no se busca en ese enfoque.","Hay que buscar el grado límite articular sin dolor, y después realizar los movimientos accesorios útiles.","La posición de reposo no es el sector buscado aquí."]],
  "925": ["¿Qué hacer si el dolor persiste durante una movilización con movimiento?",["Aumentar el grado de la movilización accesoria","Renunciar al tratamiento articular de la cadera","Buscar otro movimiento accesorio indoloro"],["El aumento del grado no resolvería el dolor.","La renuncia no es la conducta propuesta.","Si el dolor no desaparece, se busca otro movimiento accesorio hasta encontrar uno que no provoque dolor."]],
  "926": ["¿Qué tratamiento del síndrome trocantéreo es el más eficaz a medio plazo?",["El tratamiento con ondas de choque","La inyección de corticosteroides","El ejercicio domiciliario solo"],["A medio plazo, la terapia con ondas de choque resulta más eficaz que las demás opciones.","La inyección de corticosteroides solo mantiene la ventaja a corto plazo.","El ejercicio domiciliario toma la ventaja a largo plazo."]],
  "927": ["¿Qué valor de ángulo de cobertura lateral define un conflicto de tipo pincer?",["Un ángulo superior a 60°","Un ángulo superior a 40°","Un ángulo superior a 20°"],["Ese valor corresponde al umbral del ángulo alfa.","El tipo pincer corresponde a un ángulo de cobertura lateral superior a 40°.","Ese valor es inferior al umbral establecido."]],
  "928": ["¿Qué duración de sesión se recomienda para la terapia manual de los tejidos blandos de la cadera?",["Cerca de cinco minutos","Cerca de una hora","Cerca de veinte minutos"],["Esa duración es demasiado corta respecto a la recomendación.","Esa duración es muy superior a la recomendación.","Se recomienda una sesión de veinte minutos para reducir la rigidez."]],
  "929": ["¿Cuándo se recomienda la terapia manual de los tejidos blandos de la cadera?",["En el estadio posoperatorio inicial o en dolor crónico","Únicamente en la última fase de la recuperación","Únicamente antes de las pruebas complementarias"],["Se recomienda en el estadio inicial del tratamiento posoperatorio o para los dolores crónicos de la cadera.","La última fase corresponde a las movilizaciones en fin de recorrido.","El momento de las pruebas no interviene en esa indicación."]],
  "930": ["¿Por qué tratar los glúteos y el tensor de la fascia lata en la necrosis avascular?",["Para descomprimir mecánicamente la articulación","Para restaurar la perfusión de la cabeza femoral","Para reducir el dolor muscular referido al miembro inferior"],["La descompresión depende del tratamiento articular.","No se les atribuye ninguna acción directa sobre la perfusión.","El tratamiento de los glúteos y del tensor de la fascia lata reduce el dolor muscular referido al miembro inferior."]],
  "931": ["¿Qué parámetros de magnetoterapia se recomiendan en la necrosis avascular?",["Una alta frecuencia y una baja intensidad, en sesiones cortas","Una baja frecuencia y una alta intensidad, durante periodos largos","Una baja frecuencia y una baja intensidad, en sesiones breves"],["Esos parámetros son los inversos de los recomendados.","Se recomiendan parámetros de baja frecuencia y de alta intensidad, durante periodos largos, al menos 4 a 6 horas al día.","La intensidad recomendada es alta, y las duraciones largas."]],
  "932": ["¿Cuál es la aportación de la corriente analgésica en la necrosis avascular de la cadera?",["Un efecto de regresión de la lesión","Un efecto de reducción del edema","Un simple papel de coadyuvante analgésico"],["La regresión de la lesión se atribuye a las ondas de choque.","La reducción del edema se atribuye a la magnetoterapia.","La corriente analgésica convencional o interferencial es un coadyuvante, pero no tiene efecto sobre la patología subyacente."]],
  "933": ["¿Qué carga permite trabajar la hidroterapia en la necrosis avascular?",["Del 10 al 20 % del peso corporal","Del 30 al 50 % del peso corporal","Del 60 al 80 % del peso corporal"],["El principio de Arquímedes permite trabajar movilidad y fuerza con una carga del 10-20 % del peso corporal.","Del treinta al cincuenta por ciento corresponde a la reducción obtenida con los bastones.","Esa carga es muy superior a la establecida."]],
  "934": ["¿Cuándo puede introducirse la cadena cinética cerrada en la necrosis avascular?",["En cuanto desaparece completamente el dolor","Cuando la estabilidad ósea está controlada","En cuanto terminan las sesiones de ondas de choque"],["La desaparición del dolor no es el criterio establecido.","Hay que evitar la cadena cinética cerrada hasta que la estabilidad ósea esté controlada mediante la prueba de imagen.","El final del tratamiento con ondas de choque no es el criterio establecido."]],
  "935": ["¿Cuál es el interés del cicloergómetro en la necrosis avascular de la cadera?",["Fortalecer los abductores contra fuerte resistencia","Restaurar la perfusión de la cabeza femoral","Nutrir el cartílago por imbibición sin impacto vertical"],["La fuerte resistencia no se busca.","No se le atribuye ninguna acción sobre la perfusión.","La bicicleta estática a baja resistencia mantiene la nutrición del cartílago por imbibición, sin impacto vertical."]],
  "936": ["¿Por qué es difícil el diagnóstico de tendinopatía del psoas ilíaco?",["Porque el dolor es poco específico y las asociaciones son frecuentes","Porque el tendón sigue siendo inaccesible a toda palpación directa","Porque no se ha descrito nunca ninguna prueba ortopédica"],["El diagnóstico es difícil debido al carácter no específico del dolor y a la alta prevalencia de otras afecciones intraarticulares asociadas.","La palpación forma parte de la exploración objetiva.","Se describen varias pruebas ortopédicas."]],
  "937": ["¿Cuál de estos cuadros puede explicar un dolor lateral de cadera?",["Un conflicto femoroacetabular de tipo cam","Una necrosis avascular de la cabeza femoral","Una tendinopatía del tensor de la fascia lata"],["El conflicto femoroacetabular da un dolor inguinal, en C.","La necrosis avascular da un dolor profundo de cadera o de ingle.","Las causas de dolor lateral comportan la bursitis trocantérea, la tendinopatía glútea, la cadera en resorte externa, las neuropatías y la tendinopatía del tensor de la fascia lata."]],
  "938": ["¿Qué estructura se desliza sobre el trocánter mayor en la cadera en resorte externa?",["La cintilla iliotibial","El tendón del músculo iliopsoas","El tendón del músculo piramidal"],["La cadera en resorte externa procede del deslizamiento de la cintilla iliotibial sobre el trocánter mayor.","El tendón del iliopsoas está implicado en la cadera en resorte interna.","El piramidal no es la estructura implicada."]],
  "939": ["¿Qué puede revelar la prueba complementaria de una cadera en resorte externa?",["Una protuberancia ósea del cuello femoral","Un engrosamiento de la cintilla iliotibial","Una muerte del tejido óseo subcondral"],["La protuberancia del cuello caracteriza al conflicto de tipo cam.","Las pruebas revelan un engrosamiento anormal de la cintilla iliotibial o del glúteo mayor, y una acumulación de líquido o un edema de los tejidos blandos.","La necrosis del tejido óseo caracteriza a la necrosis avascular."]],
  "940": ["¿Qué tendones encuentra alterados la exploración en la tendinopatía glútea?",["Los del glúteo medio y del glúteo menor","El del glúteo mayor de forma aislada","El del tensor de la fascia lata"],["Las pruebas revelan un engrosamiento, un adelgazamiento o un desgarro del tendón del glúteo medio o del glúteo menor.","El glúteo mayor no es el tendón descrito como alterado.","El tensor de la fascia lata depende de otra tendinopatía."]],
  "941": ["¿Cómo se realiza el signo de Trendelenburg?",["En apoyo sobre la pierna sana, la otra en abducción resistida","En apoyo sobre la pierna afectada, la otra en flexión de cadera y de rodilla","En decúbito lateral, con la pierna afectada en aducción pasiva"],["El apoyo se hace sobre la pierna afectada, no sobre la pierna sana.","El paciente de pie eleva una pierna en flexión de cadera y de rodilla a 90°, en apoyo únicamente sobre la pierna afectada.","Esa maniobra es la de la prueba de Ober."]],
  "942": ["¿Qué se añade a la prueba de tensión para explorar el nervio iliohipogástrico?",["Una rotación externa máxima de la cadera","Una flexión de la rodilla al final del recorrido","Una extensión y una inclinación del tronco"],["La rotación externa máxima pertenece a la maniobra de aprehensión.","La flexión de la rodilla no es el añadido descrito.","A la prueba del nervio femorocutáneo lateral se añade una extensión y una inclinación del tronco."]],
  "943": ["¿Cuál de estos movimientos accesorios se aplica a la cadera?",["El deslizamiento transversal medial","La presión unilateral posteroanterior","El deslizamiento costotransverso mantenido"],["Las movilizaciones accesorias comportan las anteroposteriores y los deslizamientos transversales mediales, laterales y longitudinales.","Esa presión se aplica a las articulaciones vertebrales.","Ese deslizamiento se aplica a la caja torácica."]],
  "944": ["¿Qué posición adopta la cadera en la prueba FADIR?",["Flexión, rotación externa y abducción","Flexión a 90°, rotación interna y aducción","Extensión pasiva y rotación externa máxima"],["Esa combinación es la de la prueba de FABER.","La prueba FADIR asocia una flexión de cadera a 90°, una rotación interna y una aducción, con la pelvis fijada.","Esa combinación es la de la maniobra de aprehensión."]],
  "945": ["¿Cuál de estos grupos musculares fortalece el ejercicio en el conflicto femoroacetabular?",["Únicamente los flexores plantares del tobillo","Únicamente los extensores del raquis cervical","Los rotadores externos y los músculos del tronco"],["El tobillo no está implicado en ese programa.","El raquis cervical no está implicado en ese programa.","El fortalecimiento comprende los abductores, los aductores, los extensores, los rotadores externos y los músculos del tronco."]],
  "946": ["¿Después de qué intervención puede aparecer la tendinopatía del psoas ilíaco?",["Después de una artroplastia total de cadera","Después de una artroscopia de rodilla","Después de una osteotomía tibial de valguización"],["Puede sobrevenir después de una artroplastia total de cadera, en el 2,2-4,4 % de los casos.","La rodilla no es la intervención implicada.","Esa intervención no es la implicada."]],
  "947": ["¿Cuál es el efecto del láser de baja intensidad en el síndrome miofascial?",["Estimula la actividad celular y la reparación tisular","Aumenta la viscoelasticidad muscular","Libera endorfinas por estimulación nerviosa periférica"],["El láser de baja intensidad estimula la actividad celular, favorece la reparación de los tejidos, reduce la inflamación y alivia el dolor.","El aumento de viscoelasticidad es el efecto de la corriente interferencial.","La liberación de endorfinas es el efecto de la corriente analgésica transcutánea."]],
  "948": ["¿Qué músculo puede referir un dolor anterior de muslo?",["El músculo obturador interno","El músculo pectíneo de la ingle","El músculo sóleo de la pierna"],["El obturador interno refiere hacia la cara posterior del muslo.","El dolor anterior de muslo puede venir del cuadrado lumbar, del sartorio, del recto femoral, del vasto intermedio, del iliopsoas, del pectíneo y de los aductores.","El sóleo refiere hacia la cara posterior de la pierna y el talón."]],
  "949": ["¿Qué músculo puede referir un dolor lateral de tobillo?",["El músculo tibial posterior","El músculo flexor largo de los dedos","El músculo peroneo largo"],["El tibial posterior refiere hacia la cara posterior del tobillo y el talón.","El flexor largo de los dedos refiere hacia la cara medial.","El dolor lateral de tobillo puede venir del peroneo largo, del corto y del tercer peroneo."]],
  "950": ["¿Qué gesto intensifica el dolor del síndrome doloroso trocantéreo?",["La abducción resistida de la cadera","La flexión de cadera con rotación interna","La rotación interna forzada de la cadera"],["El dolor se intensifica con la presión sobre el trocánter mayor, en el apoyo o en una abducción resistida.","La flexión con rotación interna reproduce un conflicto femoroacetabular.","La rotación interna forzada limitada evoca una necrosis avascular."]],
  "951": ["¿En qué movimientos se manifiesta la cadera en resorte externa?",["En abducción resistida únicamente","En flexión, extensión y rotaciones de la cadera","En extensión pasiva con rotación externa"],["La abducción resistida despierta una tendinopatía glútea.","El chasquido sobreviene en los movimientos de flexión, de extensión, de rotación externa o interna de la cadera.","Esa combinación es la de la maniobra de aprehensión."]],
  "952": ["¿Qué forma de cadera en resorte es más frecuente en la mujer?",["La forma externa","Las dos formas indistintamente","La forma interna"],["Para la forma externa no se encuentra ninguna diferencia entre los sexos.","La diferencia solo afecta a la forma interna.","La cadera en resorte interna es más frecuente en la mujer, mientras que no hay diferencia entre los sexos para la forma externa."]],
  "953": ["¿Cuál es una de las pruebas clínicas más sensibles en la cadera en resorte?",["La reproducción del chasquido audible","La medida de la distancia entre rodilla y mesa","El mantenimiento del apoyo monopodal treinta segundos"],["El diagnóstico es principalmente clínico y la reproducción del chasquido audible es una de las pruebas más sensibles.","Esa medida pertenece a la prueba de FABER.","El apoyo monopodal pertenece al signo de Trendelenburg."]],
  "954": ["¿Cómo se realiza la prueba del hula hoop?",["En decúbito lateral, mediante una aducción pasiva de la pierna","De pie, mediante una aducción asociada a una circunducción de cadera","En decúbito supino, mediante una flexión y una rotación interna"],["Esa maniobra es la de la prueba de Ober.","El paciente de pie realiza una aducción asociada a una circunducción de la cadera afectada.","Esa maniobra es la de la prueba FADIR."]],
  "955": ["¿Cuál es la posición de partida de la prueba de Ober?",["El decúbito lateral, con el lado afectado arriba","El decúbito supino, con la pelvis fijada","La posición de pie, con los pies en el suelo"],["El paciente está en decúbito lateral, estando el lado afectado situado arriba.","El decúbito supino es la posición de las pruebas FADIR y FABER.","La posición de pie es la de la prueba del hula hoop."]],
  "956": ["¿Qué posición adopta la pierna en la prueba de FABER?",["Flexión, aducción y rotación interna","Extensión, aducción y rotación externa","Flexión, abducción y rotación externa"],["Esa combinación es la de la prueba FADIR.","Esa combinación no es la de la prueba.","La prueba de FABER coloca la cadera en flexión, abducción y rotación externa, con la pelvis fijada."]],
  "957": ["¿Cuál es la principal causa de dolor lateral de cadera?",["La bursitis trocantérea","La cadera en resorte externa","La tendinopatía glútea"],["La bursitis solo concierne a cerca de un paciente de cada cinco.","La cadera en resorte solo afecta al 5-10 % de la población.","La tendinopatía glútea es la principal causa de dolor lateral de cadera, del 15 al 50 % de los casos."]],
  "958": ["¿Qué déficit de fuerza provoca la tendinopatía glútea?",["Una disminución de la fuerza en flexión de cadera","Una disminución de la fuerza en abducción de cadera","Una disminución de la fuerza en extensión de rodilla"],["La debilidad de la flexión evoca una afectación del psoas ilíaco.","La tendinopatía glútea provoca una disminución de la fuerza en el movimiento de abducción de la cadera.","La rodilla no está implicada en esa tendinopatía."]],
  "959": ["¿Cuál es la posición de partida de la prueba de abducción resistida?",["De lado, con la pierna afectada hacia arriba","Sentado al borde de la mesa, con las piernas a 90°","De pie, frente al fisioterapeuta"],["El paciente está tumbado de lado, con la pierna afectada hacia arriba, y realiza una abducción contra resistencia.","Esa posición es la de la flexión resistida de cadera.","Esa posición es la del signo de Trendelenburg."]],
  "960": ["¿Cómo se realiza la prueba de derrotación externa resistida?",["Manteniendo una abducción contra resistencia manual","Realizando una circunducción de la cadera en apoyo","Volviendo activamente de la rotación externa a la posición neutra"],["Esa maniobra es la de la prueba de abducción resistida.","La circunducción pertenece a la prueba del hula hoop.","La cadera se coloca en flexión a 90° y rotación externa, y después el paciente vuelve activamente a la posición neutra contra resistencia."]],
  "961": ["¿Qué se hace si la posición de partida de la prueba de derrotación externa es dolorosa?",["Se reduce la rotación externa hasta la indolencia","Se interrumpe definitivamente la exploración","Se aumenta la flexión más allá de 90°"],["Si la posición provoca dolor, se reduce ligeramente la rotación externa hasta que el dolor desaparece.","La interrupción definitiva no es la conducta propuesta.","El aumento de la flexión no es la corrección propuesta."]],
  "962": ["¿Cómo se comporta el dolor de la bursitis trocantérea en abducción?",["Disminuye durante la abducción del fémur","Aumenta durante la abducción del fémur","Permanece estrictamente inalterado en abducción"],["El dolor disminuye durante la abducción del fémur.","El aumento en abducción evoca una tendinopatía glútea.","Se describe efectivamente una modificación."]],
  "963": ["¿Qué aumenta progresivamente el dolor de la bursitis trocantérea?",["La posición sentada, con las piernas cruzadas","La actividad prolongada y la estabilización pélvica","La extensión del tronco con una inclinación"],["Esa posición agrava el conflicto femoroacetabular.","El dolor aumenta progresivamente con una actividad prolongada y con los movimientos que requieren una estabilización pélvica.","Esa combinación pertenece a la prueba del iliohipogástrico."]],
  "964": ["¿A qué se asocia la bursitis trocantérea con mayor frecuencia?",["A una cadera en resorte externa","A un conflicto femoroacetabular mixto","A una tendinopatía del músculo glúteo"],["La cadera en resorte no es la asociación más frecuente.","El conflicto femoroacetabular no es la asociación descrita.","La mayoría de las bursitis se asocian a una tendinopatía del músculo glúteo."]],
  "965": ["¿Hasta dónde puede extenderse el dolor del nervio femorocutáneo lateral?",["Hasta la planta del pie","Hasta la cara externa de la rodilla","Hasta la región lumbar baja"],["La extensión a la planta del pie no se describe.","En el caso del nervio femorocutáneo lateral, el dolor puede extenderse hasta la cara externa de la rodilla.","La extensión lumbar se describe para la tendinopatía del psoas."]],
  "966": ["¿Cuál de estos factores puede provocar un atrapamiento nervioso en la cadera?",["El porte repetido de cargas por encima de la cabeza","El uso prolongado de bastones de marcha","El uso de ropa apretada"],["Ese gesto concierne al miembro superior.","Los bastones son al contrario un medio de descarga.","El atrapamiento puede ser secundario a la obesidad, a la diabetes, al embarazo, a la ropa apretada o a un hematoma ilíaco subyacente."]],
  "967": ["¿Cuándo aumenta la eficacia de las movilizaciones accesorias coxofemorales?",["En la mitad de la amplitud articular disponible","En los primerísimos grados del movimiento","En el límite del movimiento articular fisiológico"],["La mitad de la amplitud no es el sector más eficaz.","Los primeros grados no son el sector más eficaz.","La eficacia de las movilizaciones accesorias aumenta en el límite del movimiento articular fisiológico."]],
  "968": ["¿En cuántas categorías se divide el tratamiento articular de la cadera?",["Accesorias, con movimiento y en fin de rango","Pasivas, activas y resistidas","Tracciones, compresiones y manipulaciones"],["El tratamiento articular se divide en movilizaciones accesorias, movilizaciones con movimiento y movilizaciones en fin de rango.","La división por modo de contracción no es la establecida.","La división por tipo de fuerza no es la establecida."]],
  "969": ["¿Cuál es la regla de oro de una movilización con movimiento en la cadera?",["La técnica debe reproducir el dolor del paciente","La técnica debe ser indolora","La técnica debe alcanzar la amplitud máxima"],["La reproducción del dolor sería contraria al principio.","El movimiento accesorio se mantiene durante todo el movimiento fisiológico doloroso, y la técnica debe ser indolora.","La amplitud máxima no es la regla enunciada."]],
  "970": ["¿En qué pacientes se utilizan sobre todo las movilizaciones en fin de recorrido?",["En los pacientes deportistas, al final del manejo","En los pacientes mayores y sedentarios","En los pacientes recién operados de la cadera"],["Las movilizaciones en fin de recorrido se utilizan generalmente en los pacientes deportistas.","Esos pacientes toleran mal esas técnicas irritantes.","La fase posoperatoria inmediata no se presta a ello."]],
  "971": ["¿Qué movilizaciones pueden beneficiar a las restricciones de cadera?",["Las compresiones axiales mantenidas en carga prolongada","Las distracciones laterales y los deslizamientos posteriores","Las tracciones longitudinales en posición sentada alta"],["Las compresiones no son la técnica establecida.","Las distracciones laterales a partir de la posición de reposo y los deslizamientos posteriores hasta los límites de la amplitud pueden ser beneficiosos.","La posición sentada no es la descrita."]],
  "972": ["¿Cuál es el tratamiento básico del síndrome doloroso trocantéreo?",["El tratamiento mediante ejercicio","La inyección de corticosteroides","Las ondas de choque extracorpóreas"],["El tratamiento mediante ejercicio se define como el tratamiento básico del síndrome doloroso trocantéreo.","La inyección solo es eficaz a corto plazo.","Las ondas de choque son eficaces, pero no constituyen la base del tratamiento."]],
  "973": ["¿Qué tipo de conflicto femoroacetabular es el más frecuente?",["El tipo cam","El tipo pincer","El tipo mixto"],["El tipo cam aislado es menos frecuente que el tipo mixto.","El tipo pincer aislado es menos frecuente que el tipo mixto.","La mayoría de los pacientes presenta un tipo mixto, en el 87 % de los casos."]],
  "974": ["¿Qué tipo de conflicto femoroacetabular predomina en el hombre?",["El tipo cam","El tipo pincer","El tipo mixto"],["El tipo cam es más frecuente en el hombre, y el tipo pincer en la mujer.","El tipo pincer predomina en la mujer.","El tipo mixto no se describe como ligado al sexo."]],
  "975": ["¿Cómo se realiza la maniobra de aprehensión de la cadera?",["Mediante una extensión pasiva y después una rotación externa","Mediante una flexión a 90° seguida de una rotación interna","Mediante una aducción seguida de una circunducción de pie"],["Se realiza una extensión pasiva de la cadera, aprovechando la gravedad, y después se añade una rotación externa máxima.","Esa maniobra es la de la prueba FADIR.","Esa maniobra es la de la prueba del hula hoop."]],
  "976": ["¿Para qué sirven los grados 1 y 2 de Maitland en el conflicto femoroacetabular?",["Para la mejora de la amplitud de movimiento","Para la modulación del dolor","Para la educación del patrón de movimiento"],["La ganancia de amplitud depende de los grados 3 y 4.","Los grados 1 y 2 sirven para modular el dolor, los grados 3 y 4 para mejorar la amplitud de movimiento.","La educación del patrón no depende de un grado de movilización."]],
  "977": ["¿Qué combinación de movimientos reproduce la posición sentada con las piernas cruzadas?",["Flexión, abducción y rotación externa","Extensión, aducción y rotación externa","Flexión, aducción y rotación interna"],["Esa combinación es la de la prueba de FABER.","Esa combinación es la de la maniobra de aprehensión.","Sentarse con las piernas cruzadas asocia flexión, aducción y rotación interna: la posición del conflicto."]],
  "978": ["¿Qué ventaja ofrece la artroscopia en el conflicto femoroacetabular?",["Una recuperación más rápida, por estancia acortada","Una corrección definitiva sin rehabilitación","Una supresión del riesgo de lesión labral"],["La artroscopia permite una recuperación más rápida gracias a una duración de hospitalización reducida.","No se describe ninguna exención de rehabilitación.","No se plantea la supresión del riesgo labral."]],
  "979": ["¿Cómo comienza la necrosis avascular de la cabeza femoral?",["Comienza con un dolor nocturno intenso","Es generalmente asintomática al inicio","Comienza con un chasquido audible al caminar"],["Un dolor intenso de entrada no corresponde al inicio descrito.","Al inicio, la necrosis avascular de la cabeza femoral es generalmente asintomática.","El chasquido evoca una cadera en resorte."]],
  "980": ["¿Cuál de estos factores etiológicos es el más corriente en la necrosis avascular de la cadera?",["Los trabajos repetitivos en posición de cuclillas","La práctica intensiva de la carrera a pie","El tratamiento con corticosteroides"],["Esa exposición no se cita entre los factores.","La carrera se cita para la tendinopatía glútea.","Los factores más corrientes comportan los corticosteroides, el traumatismo, las fracturas, la luxación y el consumo excesivo de alcohol."]],
  "981": ["¿Qué prueba es la técnica de referencia para diagnosticar una necrosis avascular de la cadera?",["La exploración por resonancia magnética","La exploración radiológica simple","La gammagrafía ósea de cuerpo entero"],["La exploración por resonancia magnética es la técnica de referencia, debido a su alta sensibilidad.","La radiología simple es económica y disponible, pero no es la referencia.","La gammagrafía no es la técnica de referencia aquí."]],
  "982": ["¿En qué estadios son eficaces las ondas de choque focalizadas en la necrosis avascular?",["En los estadios III y IV","En los estadios I y II","En todos los estadios indistintamente"],["Los estadios avanzados no son aquellos en los que se demuestra la eficacia.","Las ondas de choque focalizadas de alta energía son eficaces en los estadios I y II, con regresión de la lesión.","La eficacia se describe en los estadios precoces."]],
  "983": ["¿Cuál es la eficacia de la magnetoterapia en la necrosis avascular de la cadera?",["Superior a la de las ondas de choque","Nula sobre el edema óseo persistente","Moderada, pero inferior a las ondas de choque"],["Queda por debajo de las ondas de choque.","Se describe efectivamente un efecto moderado sobre el edema óseo.","Su eficacia es moderada para el edema óseo y la consolidación, pero inferior a la de las ondas de choque."]],
  "984": ["¿Cuál de estos tendones figura entre las tendinopatías más corrientes del miembro inferior?",["El tendón del tibial posterior","El tendón del peroneo largo lateral","El tendón del músculo poplíteo"],["Las tendinopatías más corrientes conciernen al tendón de Aquiles, al tibial posterior, a la pata de ganso, a la rótula, al psoas ilíaco y a los glúteos.","El peroneo largo no figura en la lista establecida.","El poplíteo no figura en la lista establecida."]],
  "985": ["¿Hasta dónde puede extenderse el dolor de la tendinopatía del psoas ilíaco?",["Hasta la región lumbar","Hasta la cara externa de la rodilla","Hasta la planta del pie"],["El dolor puede extenderse a la región lumbar.","Esa extensión caracteriza al nervio femorocutáneo lateral.","La extensión al pie no se describe."]],
  "986": ["¿Qué prueba ofrece la mejor precisión diagnóstica en la tendinopatía del psoas ilíaco?",["Una ecografía del tendón en carga","Una inyección anestésica peritendinosa","Una exploración por resonancia magnética"],["La ecografía identifica la tendinopatía, pero no ofrece esa precisión.","Una inyección anestésica peritendinosa en el psoas ilíaco ofrece actualmente la mejor precisión diagnóstica.","Esa exploración identifica la tendinopatía, sin igualar esa precisión."]],
  "987": ["¿A partir de qué nivel de dolor se considera positiva la prueba HEC?",["Por encima de 6 en la escala visual analógica","Desde la mínima sensación inhabitual","Por encima de 3 en la escala visual analógica"],["Ese umbral es superior al establecido.","No se establece ningún umbral tan bajo.","La prueba es positiva si reproduce los síntomas del paciente, por encima de 3 en la escala visual analógica."]],
  "988": ["¿Cómo se realiza la flexión resistida de cadera en posición sentada?",["Sentado, piernas a 90°, resistencia en el tercio distal del muslo","Tumbado de lado, resistencia en la cara lateral de la rodilla","De pie, resistencia sobre la cresta ilíaca opuesta"],["El paciente está sentado al borde de la mesa, con las piernas a 90°, y flexiona la cadera contra una resistencia en el tercio distal del muslo.","Esa posición es la de la prueba de abducción resistida.","Esa posición no es la de la prueba."]],
  "989": ["¿Qué explora la prueba de Thomas?",["La fuerza en flexión de cadera","La flexibilidad muscular del psoas","La reproducción de los síntomas"],["La fuerza se evalúa mediante la flexión resistida.","La prueba de Thomas evalúa la flexibilidad muscular; no es eficaz para diagnosticar una tendinopatía del psoas ilíaco.","La reproducción de los síntomas depende de la prueba HEC."]],
  "990": ["¿Permite la prueba de Thomas diagnosticar una tendinopatía del psoas ilíaco?",["Sí, es la prueba de referencia","Sí, con la condición de añadirle una resistencia","No, no es eficaz para ese diagnóstico"],["La prueba de referencia es la prueba HEC.","No se propone ninguna variante resistida para ese diagnóstico.","La prueba de Thomas evalúa la flexibilidad, pero no es una prueba eficaz para diagnosticar una tendinopatía del psoas ilíaco."]],
  "991": ["¿Qué se encuentra a la palpación en un síndrome de dolor miofascial?",["Un nódulo doloroso sobre una banda tensa palpable","Una crepitación articular a la movilización","Un chasquido reproducible en el trocánter mayor"],["La exploración encuentra un nódulo doloroso sobre una banda tensa palpable, con respuesta de espasmo local.","La crepitación evoca una afectación degenerativa.","El chasquido evoca una cadera en resorte."]],
  "992": ["¿Qué se observa en un estiramiento completo en caso de síndrome miofascial?",["Una amplitud conservada y totalmente indolora","Una limitación dolorosa de la amplitud","Una hiperlaxitud del segmento implicado"],["Una amplitud indolora no corresponde a ese cuadro.","Se constata una limitación dolorosa de la amplitud de movilidad en un estiramiento completo.","La hiperlaxitud no pertenece a ese cuadro."]],
  "993": ["¿Cuál es el efecto de la corriente interferencial en el síndrome miofascial?",["Aumenta la viscoelasticidad muscular y la analgesia","Estimula la actividad celular y la reparación","Bloquea las señales dolorosas hacia el cerebro"],["La corriente interferencial aumenta la viscoelasticidad muscular y la analgesia, como complemento del masaje de liberación miofascial.","La estimulación celular es el efecto del láser de baja intensidad.","El bloqueo de las señales es el efecto de la corriente analgésica transcutánea."]],
  "994": ["¿En qué forma de síndrome miofascial se utiliza sobre todo la toxina botulínica?",["En las formas agudas recientes","En las formas crónicas","En las formas asociadas a una fibromialgia"],["Las formas agudas no son la indicación establecida.","La toxina botulínica se utiliza sobre todo en las formas crónicas.","La fibromialgia depende primero del diagnóstico diferencial."]],
  "995": ["¿Qué músculo puede referir un dolor posterior de rodilla?",["El músculo poplíteo","El músculo recto femoral","El músculo tibial anterior"],["El dolor posterior de rodilla puede venir del plantar, de los isquiotibiales, del poplíteo, del gastrocnemio y del sóleo.","El recto femoral refiere hacia la cara anterior de la rodilla.","El tibial anterior refiere hacia la cara anterior de la pierna."]],
  "996": ["¿Qué músculo puede referir un dolor en el talón?",["El músculo peroneo largo lateral","El músculo cuadrado plantar","El músculo extensor corto de los dedos"],["El peroneo largo refiere hacia la cara lateral del tobillo.","El dolor del talón puede venir del tibial posterior, del sóleo, del cuadrado plantar y del abductor del dedo gordo.","El extensor corto de los dedos refiere hacia el dorso del pie."]],
  "997": ["¿Qué parte de los dolores laterales de cadera representa la tendinopatía glútea?",["Del 5 al 10 % de los casos","Del 80 al 90 % de los casos","Del 15 al 50 % de los casos"],["Ese intervalo corresponde a la prevalencia de la cadera en resorte.","Esa parte es superior a la establecida.","La tendinopatía glútea representa el 15-50 % de los dolores laterales de cadera."]],
  "998": ["¿Qué proporción de los síndromes dolorosos trocantéreos comporta una bursitis?",["Cerca del 50 %","Cerca del 5 %","Cerca del 20 %"],["Esa proporción es superior a la establecida.","Esa proporción es inferior a la establecida.","Cerca del 20 % de los pacientes con un síndrome doloroso trocantéreo presenta una bursitis, en la mayoría de los casos asociada a una tendinopatía glútea."]],
  "999": ["¿A qué grupo de edad afectan más las neuropatías de la cadera?",["Entre los 30 y los 40 años","Entre los 40 y los 60 años","Entre los 60 y los 70 años"],["Las neuropatías de la región de la cadera afectan sobre todo al grupo de 30 a 40 años.","Ese grupo corresponde al síndrome doloroso trocantéreo.","Ese grupo es más tardío que el descrito."]],
  "1000": ["¿Qué proporción de la población portadora de un conflicto femoroacetabular permanece asintomática?",["Hasta el 10 %","Hasta el 90 %","Hasta el 50 %"],["Esa proporción es muy inferior a la establecida.","Esa proporción es muy superior a la establecida.","Hasta el 50 % de la población portadora permanece asintomática."]],
  "1001": ["¿Cómo evoluciona la prevalencia de las tendinopatías con la edad?",["Disminuye con la edad","Permanece estable sea cual sea la edad","Aumenta con la edad"],["La tendencia descrita es inversa.","Se describe efectivamente una evolución con la edad.","La prevalencia de las tendinopatías aumenta con la edad, y las mujeres están más afectadas que los hombres."]],
  "1002": ["¿Cuál es la incidencia del síndrome doloroso trocantéreo en atención primaria?",["Cerca de 10 por 1 000 adultos al año","Cerca de 0,1 por 1 000 adultos al año","Cerca de 1,8 por 1 000 adultos al año"],["Esa incidencia es muy superior a la establecida.","Esa incidencia es muy inferior a la establecida.","La incidencia es de 1,8 por 1 000 adultos al año en atención primaria."]],
  "1003": ["¿Cuál es la relación entre sexos del síndrome doloroso trocantéreo?",["Un predominio femenino de 2 a 3 por 1","Un predominio masculino de 2 a 3 por 1","Una distribución idéntica entre ambos sexos"],["El síndrome doloroso trocantéreo presenta un predominio femenino, con una relación de 2 a 3 por 1.","El predominio descrito es femenino.","Se describe un predominio femenino claro."]],
  "1004": ["¿A qué edad se observa con mayor frecuencia el síndrome doloroso trocantéreo?",["Entre los 20 y los 40 años","Entre los 40 y los 60 años","Entre los 30 y los 40 años"],["Ese grupo corresponde al conflicto femoroacetabular.","El síndrome doloroso trocantéreo se observa con mayor frecuencia entre los 40 y los 60 años.","Ese grupo corresponde a las neuropatías de cadera."]],
  "1005": ["¿Cuál es la prevalencia de la cadera en resorte?",["Del 10 al 15 % de la población general","Del 5 al 10 % de la población general","Del 15 al 50 % de la población general"],["Ese intervalo corresponde al conflicto femoroacetabular.","La cadera en resorte afecta al 5-10 % de la población general.","Ese intervalo corresponde a la parte de la tendinopatía glútea en los dolores laterales."]],
  "1006": ["¿Qué proporción de los pacientes con lumbalgia presenta una tendinopatía glútea?",["Cerca del 10 %","Cerca del 35 %","Cerca del 70 %"],["Esa proporción es inferior a la establecida.","Cerca del 35 % de las personas con dolores lumbares presenta una tendinopatía glútea.","Esa proporción es superior a la establecida."]],
  "1007": ["¿Qué proporción de los pacientes con bursitis presenta trastornos del sueño?",["Cerca del 20 %","Cerca del 40 %","Cerca del 70 %"],["El veinte por ciento corresponde a la parte de bursitis en el síndrome trocantéreo.","Cerca del 40 % de los pacientes sufre trastornos del sueño debidos al dolor, con un descenso del rendimiento deportivo.","Esa proporción es superior a la establecida."]],
  "1008": ["¿En quién es más elevada la incidencia de las neuropatías de la cadera?",["En la mujer adulta","En el adolescente","En el hombre adulto"],["El predominio femenino concierne al síndrome doloroso trocantéreo.","La adolescencia no es el terreno descrito.","La incidencia de las neuropatías de la cadera es más elevada en el hombre."]],
  "1009": ["¿En qué proporción de los pacientes predomina el dolor del conflicto femoroacetabular en reposo?",["En cerca de un tercio de ellos","En cerca de la mitad de ellos","En la casi totalidad de ellos"],["En un tercio de los pacientes, el dolor puede ser predominante en reposo.","Esa proporción es superior a la establecida.","El dolor de reposo no es la regla general."]],
  "1010": ["¿Cuál es la prevalencia del conflicto femoroacetabular?",["Del 5 al 10 % de la población general","Del 10 al 15 % de la población general","Del 30 al 40 % de la población general"],["Ese intervalo corresponde a la cadera en resorte.","El conflicto femoroacetabular afecta al 10-15 % de la población general.","Esa prevalencia es superior a la establecida."]],
  "1011": ["¿A qué edad es más elevada la incidencia del conflicto femoroacetabular?",["En el adulto joven de 20 a 40 años","En el adulto de 40 a 60 años","En la persona mayor de 65 años"],["La incidencia es más elevada en el adulto joven de 20 a 40 años.","Ese grupo corresponde al síndrome doloroso trocantéreo.","Ese grupo no corresponde a la afección."]],
  "1012": ["¿A qué población afecta la necrosis avascular de la cabeza femoral?",["A las personas activas de 20 a 40 años","A las personas sedentarias de más de 65 años","A las mujeres de más de 40 años"],["La necrosis avascular de la cabeza femoral afecta a las personas activas de 20 a 40 años.","Esa población no corresponde a la descrita.","Esa población corresponde a la tendinopatía glútea."]],
  "1013": ["¿Qué parte de las lesiones musculoesqueléticas representan las tendinopatías?",["Cerca del 10 %","Cerca del 30 %","Cerca del 60 %"],["Esa parte es inferior a la establecida.","Se estima que el 30 % de las lesiones musculoesqueléticas se relaciona con tendinopatías.","Esa parte es superior a la establecida."]],
  "1014": ["¿Qué parte de las tendinopatías sobreviene en un marco deportivo?",["Del 10 al 20 %","Del 70 al 90 %","Del 30 al 50 %"],["Esa parte es inferior a la establecida.","Esa parte es superior a la establecida.","Del 30 al 50 % de las tendinopatías sobreviene en el marco de una actividad deportiva."]],
  "1015": ["¿Qué lugar ocupa la tendinopatía del psoas ilíaco entre las lesiones inguinales del futbolista?",["El segundo lugar","El primer lugar","El quinto lugar"],["La tendinopatía del psoas ilíaco es la segunda lesión inguinal más frecuente en el fútbol.","No ocupa el primer lugar.","Su lugar es mucho más alto."]],
  "1016": ["¿Cuál es la prevalencia internacional del síndrome de dolor miofascial?",["Del 5 al 10 % de la población","Del 13,5 al 47 % de la población","Del 60 al 80 % de la población"],["Ese intervalo es inferior al establecido.","A nivel internacional, el síndrome de dolor miofascial afecta a entre el 13,5 y el 47 % de la población.","Ese intervalo es superior al establecido."]],
  "1017": ["¿Qué parte de la población tiene un síndrome de dolor miofascial a lo largo de su vida?",["Cerca del 45 %","Cerca del 25 %","Cerca del 85 %"],["Esa parte es inferior a la establecida.","Esa parte es muy inferior a la establecida.","El síndrome de dolor miofascial afecta al 85 % de la población en algún momento de la vida."]],
  "1018": ["¿Qué tipo de ejercicio corrige el valgo dinámico de la rodilla?",["El control neuromuscular en cadena cinética cerrada","El estiramiento pasivo prolongado de los aductores","El fortalecimiento concéntrico máximo del cuádriceps"],["Se establecen ejercicios de control neuromuscular en cadena cinética cerrada, insistiendo en la alineación femoral y tibial.","El estiramiento pasivo aislado no corrige el valgo dinámico.","La fuerza máxima aislada no corrige el valgo dinámico."]],
  "1019": ["¿Cómo gestionar la carga al inicio del tratamiento de una tendinopatía rotuliana?",["Suprimir definitivamente toda actividad deportiva","Mantener la carga habitual sin modificación","Reducir temporalmente los saltos y los impactos"],["La supresión definitiva no es la estrategia establecida.","El mantenimiento de la carga provocadora sería contraproducente.","Hay que reducir temporalmente las actividades provocadoras, saltos e impactos, y sustituirlas por una carga progresiva controlada."]],
  "1020": ["¿Qué busca la fase de almacenamiento de energía en la tendinopatía rotuliana?",["La recuperación de la capacidad reactiva del tendón","Únicamente la analgesia al inicio del manejo","La ganancia de flexibilidad de los isquiotibiales"],["Esa fase recupera la capacidad reactiva del tendón gracias a cargas elásticas.","La analgesia depende de la fase isométrica.","La ganancia de flexibilidad no es el objetivo de esa fase."]],
  "1021": ["¿En cuánto tiempo desaparece el dolor pospunción?",["En 2 a 3 semanas","En 24 a 48 horas","En 12 semanas"],["Dos a tres semanas corresponde a la duración del efecto de un corticoide.","El dolor pospunción desaparece espontáneamente en 24 a 48 horas.","Doce semanas corresponde a la duración mínima de un programa de ejercicio."]],
  "1022": ["¿Qué rango de frecuencia utiliza la electroacupuntura en la condromalacia?",["De 50 a 100 Hz","De 0,5 a 2 Hz","De 5 a 20 Hz"],["Ese rango es superior al establecido.","Ese rango corresponde a las movilizaciones oscilatorias.","La electroacupuntura se aplica a una frecuencia de 5 a 20 Hz."]],
  "1023": ["¿En qué sector es segura la cadena cinética cerrada en la rodilla?",["De 0 a 45° de flexión","De 25 a 90° de flexión","De 90 a 120° de flexión"],["La cadena cerrada, como las sentadillas y la prensa, es segura de 0 a 45° de flexión.","Ese sector es el de la cadena cinética abierta.","Ese sector no es el descrito como seguro."]],
  "1024": ["¿En qué sector es segura la cadena cinética abierta en la rodilla?",["De 0 a 45° de flexión","De 25 a 90° de flexión","De 0 a 25° de flexión"],["Ese sector es el de la cadena cinética cerrada.","La cadena abierta, como la extensión de la rodilla en máquina, es segura de 25 a 90° de flexión.","Ese sector no es el descrito como seguro."]],
  "1025": ["¿Qué consecuencia tienen las desalineaciones pélvicas sobre los isquiotibiales?",["Reducen la vascularización de su inserción","Crean una relación tensión-longitud anormal","Inhiben reflejamente su contracción voluntaria"],["No se describe ninguna acción vascular.","Esas desalineaciones crean una relación tensión-longitud anormal en los isquiotibiales y los aductores, aumentando la carga de inserción.","La inhibición refleja concierne al glúteo mayor en la necrosis de cadera."]],
  "1026": ["¿Qué consecuencia conlleva el valgo dinámico de la rodilla?",["Una descarga del compartimento medial de la rodilla","Una disminución de la actividad de los aductores","Una compresión aumentada del compartimento medial"],["El compartimento medial está al contrario sobrecargado.","La actividad de los aductores aumenta al contrario.","El colapso medial aumenta la compresión y el estrés del compartimento medial, e incrementa la actividad de los aductores."]],
  "1027": ["¿Por qué tratar la rigidez de la cara anterior del muslo en la pata de ganso?",["Porque frena la activación de los isquiotibiales","Porque provoca un valgo dinámico de la rodilla","Porque reduce la estabilidad de la rótula"],["La tensión anterior del muslo aumenta la resistencia durante la activación de los isquiotibiales, lo que aumenta la carga sobre el tendón.","El valgo dinámico tiene otros determinantes.","La estabilidad rotuliana no es el problema descrito."]],
  "1028": ["¿Cuál es el objetivo de la fase isométrica en la pata de ganso?",["La adaptación estructural completa del tendón","La analgesia y un fortalecimiento precoz","La reducción de la longitud de la zancada"],["La adaptación estructural depende de la fase siguiente.","La fase isométrica busca la analgesia y un fortalecimiento precoz, sin provocar síntomas excesivos.","La modificación de la zancada depende de la fase de marcha."]],
  "1029": ["¿Cuándo pasar de la fase isométrica a la fase excéntrica en la pata de ganso?",["Después de doce semanas sea cual sea el estado clínico","Desde la primera sesión, en paralelo a los isométricos","Después de tolerar los isométricos sin dolor residual"],["No se impone ningún plazo fijo de ese tipo.","La progresión es secuencial, no simultánea.","Se progresa después de tolerar los isométricos sin dolor residual."]],
  "1030": ["¿Qué nivel de síntomas hay que evitar tratar en tendinopatía crónica?",["Por encima de 1 a 2 sobre 10","Por encima de 5 a 6 sobre 10","Por encima de 8 a 9 sobre 10"],["En patología crónica, hay que evitar tratar los síntomas superiores a 1 o 2 sobre 10.","Ese umbral es superior al establecido para las formas crónicas.","Ese umbral es muy superior al establecido."]],
  "1031": ["¿Cómo modificar la marcha en la fase 3 del protocolo de la pata de ganso?",["Alargar la zancada para reducir el número de pasos por minuto","Aumentar la cadencia del 5 al 10 % para acortar la zancada","Disminuir la cadencia para limitar los impactos"],["El alargamiento de la zancada aumentaría la solicitación.","Se aumenta la cadencia del 5 al 10 % para disminuir la longitud de la zancada, lo que reduce significativamente la solicitación de los isquiotibiales.","La disminución de la cadencia no es la estrategia descrita."]],
  "1032": ["¿Qué busca la fase isotónica en la tendinopatía rotuliana?",["La adaptación estructural del tendón y la ganancia de fuerza","La analgesia inmediata antes de la puesta en carga","El retorno a la disciplina deportiva específica"],["La fase isotónica busca la adaptación estructural del tendón y la ganancia de fuerza muscular.","La analgesia inmediata depende de la fase isométrica.","El retorno al deporte es la última fase."]],
  "1033": ["¿Cuáles son las principales causas de dolor anterior de la rodilla?",["La tendinopatía de la pata de ganso y la bursitis","La artrosis femorotibial y la lesión meniscal","El síndrome femoropatelar y la condromalacia"],["La pata de ganso da un dolor anteromedial, no anterior puro.","Esas afectaciones no se designan como causas principales.","El síndrome femoropatelar y la condromalacia rotuliana constituyen las principales causas de dolor anterior de la rodilla."]],
  "1034": ["¿Qué sensación subjetiva acompaña a la inestabilidad femoropatelar?",["Una sensación de fallo articular","Una sensación de bloqueo en extensión","Una sensación de quemazón cutánea difusa"],["El paciente describe una sensación subjetiva de fallo articular, o de que la rodilla se le va.","El bloqueo franco no es el signo descrito.","La quemazón cutánea evoca una afectación neural."]],
  "1035": ["¿A partir de qué índice de masa corporal se convierte el sobrepeso en factor de riesgo de artrosis de rodilla?",["Por encima de 25","Por encima de 30","Por encima de 35"],["El umbral establecido por el curso es más alto.","El sobrepeso se establece como factor de riesgo por encima de un índice de masa corporal de 30.","El umbral establecido por el curso es más bajo."]],
  "1036": ["¿Qué sugiere una prueba de extrusión femoropatelar positiva?",["Una irritación condral o sinovial localizada","Un déficit del control neuromuscular dinámico","Una inestabilidad femoropatelar o una hiperlaxitud capsular"],["La irritación localizada se traduce por un dolor a la palpación de las facetas.","El control neuromuscular se evalúa con las pruebas funcionales.","Un resultado positivo sugiere una inestabilidad femoropatelar o una hiperlaxitud capsular."]],
  "1037": ["¿En qué escala se expresa la clasificación de Kellgren y Lawrence?",["De 0 a 4","De 0 a 100","De 1 a 5"],["La clasificación de Kellgren y Lawrence se expresa en grados de 0 a 4.","Cero a cien es la escala del cuestionario VISA-P.","Esa escala no corresponde a la establecida."]],
  "1038": ["¿Existe una intervención única curativa en el síndrome femoropatelar?",["Sí, el ejercicio excéntrico aislado basta","No, el manejo debe ser multimodal","Sí, la artroscopia corrige de forma duradera la lesión"],["El ejercicio aislado no constituye una respuesta única.","El manejo debe seguir siendo multimodal, integrando ejercicios individualizados e intervenciones físicas complementarias.","La artroscopia no aporta ese beneficio."]],
  "1039": ["¿En qué plazo debe volver el dolor a su nivel basal después del ejercicio?",["En las 72 horas","En las 24 horas","En la semana siguiente"],["Ese plazo es superior al establecido.","El dolor debe volver a su nivel basal en las 24 horas; si no, hay que reducir la carga.","Ese plazo es muy superior al establecido."]],
  "1040": ["¿Qué vínculo subraya el enfoque biopsicosocial en la pata de ganso?",["Entre el valgo dinámico y la sobrecarga tendinosa","Entre la obesidad y la progresión radiológica de la artrosis","Entre las creencias inexactas, el miedo-evitación y peores resultados"],["Ese vínculo depende del análisis biomecánico.","Ese vínculo no es el subrayado aquí.","Existe un vínculo entre las creencias inexactas sobre el dolor, las conductas de miedo y evitación, y peores resultados funcionales."]],
  "1041": ["¿Qué trastorno estático del pie favorece la tendinopatía rotuliana?",["El pie pronador","El pie cavo supinador","El pie en valgo calcáneo fijo"],["El pie pronador figura entre los factores de riesgo.","El pie cavo no se cita entre los factores.","Esa deformidad no se cita entre los factores."]],
  "1042": ["¿Cuál es la primera etapa de la exploración física de una tendinopatía rotuliana?",["La sentadilla unilateral en plano inclinado","La palpación de la parte inferior de la rótula","La compresión de la rótula contra el fémur"],["La sentadilla en declive es la prueba funcional, no la primera etapa.","La palpación de la parte inferior de la rótula es la primera etapa; un dolor localizado ahí es característico.","La compresión rotuliana es la prueba de Clarke."]],
  "1043": ["¿En qué escala se expresa el cuestionario VISA-P?",["De 0 a 4 grados","De 0 a 10 puntos","De 0 a 100 puntos"],["Cero a cuatro es la escala de la clasificación radiológica de la artrosis.","Esa escala corresponde a la evaluación del dolor.","La puntuación del cuestionario VISA-P varía entre 0 y 100 puntos."]],
  "1044": ["¿Qué dice la evidencia sobre los ultrasonidos terapéuticos en la tendinopatía rotuliana?",["No corrobora su eficacia","Confirma su eficacia en fase crónica","Los sitúa en primera intención del tratamiento"],["La evidencia actual deja la eficacia de los ultrasonidos terapéuticos sin respaldo en esa patología.","No se aporta ninguna confirmación de eficacia.","No se establecen en primera intención."]],
  "1045": ["¿Cuál es el volumen de la fase isométrica en la tendinopatía rotuliana?",["Diez repeticiones de 10 segundos","Cinco repeticiones de 45 segundos","Tres series de 15 repeticiones"],["Unas repeticiones breves no corresponden al protocolo.","La fase isométrica comporta 5 repeticiones de 45 segundos.","Un formato en series repetidas no corresponde al protocolo."]],
  "1046": ["¿Qué vía quirúrgica es superior en la tendinopatía rotuliana?",["Ninguna, no existe evidencia concluyente","La cirugía abierta, claramente superior","La artroscopia, claramente superior"],["No existe ninguna evidencia concluyente de la superioridad de la cirugía abierta respecto a la artroscopia.","No se establece ninguna superioridad de la vía abierta.","No se establece ninguna superioridad de la artroscopia."]],
  "1047": ["¿Cómo comienza el dolor del síndrome femoropatelar?",["Intenso y súbito, en la cara anteromedial","Sordo y difuso, detrás o alrededor de la rótula","Profundo y localizado en el polo inferior de la rótula"],["Un dolor intenso y súbito anteromedial evoca una pata de ganso.","El dolor es inicialmente sordo y difuso, localizado detrás o alrededor de la rótula, y después se vuelve continuo y más intenso.","El dolor del polo inferior evoca una tendinopatía rotuliana."]],
  "1048": ["¿Qué actividad desencadena típicamente el dolor del síndrome femoropatelar?",["Saltar de forma explosiva y repetida","Flexionar la rodilla contra una resistencia","Subir y bajar escaleras"],["Los saltos explosivos repetidos exponen a la tendinopatía rotuliana.","La flexión resistida despierta una tendinopatía de la pata de ganso.","El dolor se agrava al subir y bajar escaleras, al ponerse en cuclillas, al arrodillarse o al correr."]],
  "1049": ["¿Qué exposición profesional favorece la artrosis de la rodilla?",["Las profesiones que imponen saltos explosivos","Las profesiones que imponen una posición sentada prolongada","Las profesiones que obligan a arrodillarse a menudo"],["Los saltos explosivos exponen a la tendinopatía rotuliana.","La posición sentada prolongada despierta el dolor femoropatelar.","Los factores de riesgo comportan las profesiones que exigen arrodillarse con frecuencia."]],
  "1050": ["¿Cómo se realiza la prueba de compresión de Clarke?",["Presión sobre el polo superior de la rótula, con el cuádriceps contraído","Desplazamiento lateral y después medial de la rótula, con la rodilla flexionada","Palpación de las facetas rotulianas, con la rodilla en extensión completa"],["Se aplica una presión ligera sobre el polo superior de la rótula mientras el paciente contrae isométricamente el cuádriceps.","Ese desplazamiento pertenece a la prueba de extrusión femoropatelar.","La palpación de las facetas es una exploración distinta."]],
  "1051": ["¿En qué posición se palpan las facetas rotulianas?",["Con la rodilla flexionada a 30°","Con la rodilla flexionada a 90°","Con la rodilla en extensión"],["Treinta grados es la posición de la sentadilla de provocación.","Noventa grados no es la posición descrita.","La palpación digital de las facetas medial y lateral se hace con la rodilla en extensión."]],
  "1052": ["¿Cuál de estas pruebas evalúa el control neuromuscular dinámico de la rodilla?",["La prueba de compresión de Clarke","La prueba de bajada de un escalón","La palpación de las facetas rotulianas"],["La prueba de Clarke es una prueba de provocación estática.","La prueba de bajada, la sentadilla unilateral y los saltos sobre una pierna evalúan la capacidad funcional y el control neuromuscular.","La palpación es una exploración estática."]],
  "1053": ["¿Qué intervención constituye la piedra angular del tratamiento conservador de la rodilla?",["La terapia manual articular","La electroterapia analgésica","El ejercicio terapéutico"],["La terapia manual es eficaz, pero no es la piedra angular.","La electroterapia solo es un complemento.","El ejercicio terapéutico es la piedra angular del tratamiento conservador, respaldada por el nivel de evidencia más alto."]],
  "1054": ["¿Qué puede aportar una cuña ortopédica en la artrosis de rodilla desalineada?",["La corrección del eje de carga del miembro","Una retroalimentación propioceptiva inmediata en la rodilla","Una activación selectiva del vasto medial"],["Las cuñas ortopédicas corrigen el eje de carga, redistribuyen las fuerzas de compresión y alivian los compartimentos afectados.","La retroalimentación propioceptiva es la aportación del vendaje.","La activación selectiva depende de la electroestimulación."]],
  "1055": ["¿Cuál es el nivel de evidencia de la punción seca en el síndrome femoropatelar?",["Alto, sobre el dolor a largo plazo","Nulo, no se ha referido ningún efecto","Bajo a moderado, sobre el dolor a corto plazo"],["El nivel de evidencia no es alto y el efecto no es a largo plazo.","Se refiere efectivamente un efecto a corto plazo.","La evidencia es baja a moderada: la punción seca reduce el dolor y la discapacidad a corto plazo."]],
  "1056": ["¿Cuál es el efecto de la punción seca sobre la artrosis de rodilla establecida?",["No se ha demostrado ningún efecto significativo","Un efecto significativo sobre el dolor a corto plazo","Un efecto sobre la progresión radiológica de la enfermedad"],["Los análisis disponibles dejan la punción seca sin efecto significativo sobre la artrosis establecida ni sobre el dolor posoperatorio.","Ese efecto solo se demuestra en el síndrome femoropatelar.","No se describe ninguna acción sobre la progresión."]],
  "1057": ["¿Cómo debe utilizarse la electroterapia en la rodilla?",["Como tratamiento principal de las formas dolorosas","En sustitución del ejercicio en fase aguda","Como complemento de un plan multimodal, nunca aislada"],["Nunca es el tratamiento principal.","No sustituye al ejercicio terapéutico.","La electroterapia debe integrarse en un plan multimodal y nunca utilizarse como intervención aislada."]],
  "1058": ["¿Cuál es el valor de la corriente analgésica y de los ultrasonidos en la rodilla?",["Eficaces asociados al ejercicio, su efecto aislado sigue debatiéndose","Eficaces de forma aislada, sin necesidad de ejercicio asociado","Formalmente contraindicados en las patologías de la rodilla"],["En los protocolos convencionales reducen los síntomas asociados al ejercicio, pero su efecto aislado sigue siendo controvertido.","El efecto aislado es precisamente controvertido.","No se plantea ninguna contraindicación de ese tipo."]],
  "1059": ["¿Cuál es la indicación de la electroestimulación muscular en la rodilla?",["La ganancia de fuerza a largo plazo","La activación del cuádriceps inhibido","La corrección del eje de carga"],["Para la ganancia a largo plazo, el ejercicio voluntario sigue siendo superior.","Es útil para la activación específica del cuádriceps, sobre todo del vasto medial oblicuo, en fase inicial o en caso de inhibición dolorosa.","La corrección del eje depende de las cuñas ortopédicas."]],
  "1060": ["¿Qué sigue siendo superior a la electroestimulación para la ganancia funcional a largo plazo?",["La punción seca de los puntos gatillo","El vendaje neuromuscular de la rodilla","El ejercicio voluntario activo"],["La punción seca solo actúa a corto plazo.","El vendaje solo es útil como complemento.","El ejercicio voluntario activo sigue siendo superior para una ganancia funcional a largo plazo."]],
  "1061": ["¿Qué cadena cinética presenta una ligera ventaja a cinco años en la rodilla?",["La cadena cinética abierta","La cadena cinética cerrada","Ninguna, los resultados son idénticos"],["Las dos cadenas son eficaces, pero la cadena abierta es ligeramente superior en un periodo de cinco años.","La cadena cerrada es eficaz, pero sin esa ventaja a largo plazo.","Se describe efectivamente una ligera ventaja."]],
  "1062": ["¿Cuál es la primera línea farmacológica en las patologías de la rodilla?",["Los antiinflamatorios no esteroideos y el paracetamol","Las inyecciones de corticosteroides intraarticulares","Los fármacos de acción lenta sobre la artrosis"],["Los antiinflamatorios no esteroideos y el paracetamol constituyen la primera línea farmacológica del control sintomático.","Las inyecciones no son la primera línea.","Esos fármacos se dirigen a la progresión, no al control sintomático inicial."]],
  "1063": ["¿Qué pueden aportar los fármacos de acción lenta en la artrosis de rodilla?",["Un alivio sintomático inmediato y potente","Un posible retraso de la progresión radiológica","Una regeneración completa del cartílago lesionado"],["El alivio inmediato depende de los analgésicos.","Los fármacos de acción lenta, como la glucosamina y la condroitina, pueden retrasar la progresión radiológica, con evidencia controvertida.","No se describe ninguna regeneración completa."]],
  "1064": ["¿Qué deformidad axial favorece la tendinopatía de la pata de ganso?",["La rodilla en varo","La rodilla en valgo","El pie pronador"],["El varo no se cita entre los factores de riesgo.","Los factores de riesgo comportan la artrosis de la rodilla, la obesidad, las actividades deportivas y las rodillas en valgo.","El pie pronador es un factor de tendinopatía rotuliana."]],
  "1065": ["¿Qué pruebas de provocación se utilizan en la tendinopatía de la pata de ganso?",["La flexión y la rotación externa resistidas","La sentadilla unilateral en plano inclinado","La compresión de la rótula sobre el fémur"],["Las pruebas de provocación son la flexión de la rodilla resistida y la rotación externa de la rodilla resistida.","Esa prueba pertenece a la tendinopatía rotuliana.","Esa maniobra es la prueba de Clarke."]],
  "1066": ["¿Qué inestabilidad hay que corregir en la tendinopatía de la pata de ganso?",["La retroversión acetabular y la displasia de cadera","La inclinación pélvica y la inclinación torácica","La báscula rotuliana lateral y la hiperlaxitud capsular"],["Esas anomalías conciernen al conflicto femoroacetabular.","Hay que corregir la inclinación pélvica anterior y la inclinación torácica lateral mediante ejercicios de control motor.","Esos elementos conciernen a la inestabilidad femoropatelar."]],
  "1067": ["¿Cuál es la duración de las contracciones isométricas en la fase 1 de la pata de ganso?",["De 5 a 10 segundos","De 30 a 60 segundos","De 2 a 3 minutos"],["Esa duración es demasiado breve respecto al protocolo.","La fase 1 comporta contracciones estáticas de 30 a 60 segundos, desde la rodilla flexionada a 90° hasta la extensión completa según la tolerancia.","Esa duración es superior a la establecida."]],
  "1068": ["¿Qué nivel de dolor es aceptable durante el ejercicio excéntrico de la pata de ganso?",["De 7 a 9 sobre 10","La ausencia estricta de todo dolor","De 3 a 5 sobre 10"],["Ese nivel es demasiado elevado respecto a la indicación.","No se exige la ausencia total de dolor.","Un dolor comprendido entre 3 y 5 sobre 10 es apropiado durante el ejercicio excéntrico."]],
  "1069": ["¿A qué casos se reservan las inyecciones de corticosteroides en la pata de ganso?",["A los casos recientes muy dolorosos de menos de un mes","A los casos recalcitrantes con bursopatía asociada","A los casos asociados a un valgo dinámico marcado"],["Las formas recientes no dependen de esa indicación.","Se reservan a los casos recalcitrantes con bursopatía coexistente.","El valgo dinámico se trata con el control motor."]],
  "1070": ["¿Cuál es el nivel de evidencia del plasma rico en plaquetas en la pata de ganso?",["Alto, con un beneficio duradero demostrado","Nulo, con un agravamiento documentado de las lesiones","Insuficiente, ningún estudio a largo plazo publicado"],["No se demuestra ningún beneficio duradero.","No se refiere ningún agravamiento.","No existe ningún estudio publicado que evalúe los resultados a largo plazo de las inyecciones de plasma rico en plaquetas: la evidencia es insuficiente."]],
  "1071": ["¿En quién da la cirugía de la pata de ganso los mejores resultados?",["En los atletas jóvenes sin artrosis asociada","En los pacientes artrósicos de larga data","En los pacientes con sobrepeso y rodilla en valgo"],["Los resultados son buenos en los atletas jóvenes, y mediocres en los pacientes que presentan una artrosis coexistente de larga data.","En esos pacientes, los resultados son al contrario mediocres.","Esa población no es la descrita como favorable."]],
  "1072": ["¿Cómo comienza el dolor de la tendinopatía rotuliana?",["De forma intensa y súbita, en reposo","De forma progresiva, en las escaleras","De forma insidiosa, solo durante el deporte"],["Un dolor súbito evoca una afectación de la pata de ganso.","El dolor en las escaleras evoca un síndrome femoropatelar.","El dolor aparece a menudo de forma insidiosa y solo está presente, al inicio, durante la práctica deportiva."]],
  "1073": ["¿Qué tipo de solicitación favorece la tendinopatía rotuliana?",["Los saltos explosivos repetidos","La posición de rodillas prolongada y repetida","La flexión resistida repetida de la rodilla"],["La prevalencia es elevada en los deportes con cargas repetitivas, en particular los saltos explosivos.","La posición de rodillas favorece la artrosis de la rodilla.","La flexión resistida despierta una afectación de la pata de ganso."]],
  "1074": ["¿Cuál es la prueba funcional de referencia de la tendinopatía rotuliana?",["La prueba de bajada de un escalón","La prueba de compresión de Clarke","La sentadilla unilateral en plano en declive"],["La prueba de bajada evalúa el control neuromuscular global.","La prueba de Clarke explora la condromalacia.","La sentadilla unilateral en plano en declive es la prueba funcional de referencia de la tendinopatía rotuliana."]],
  "1075": ["¿Con qué inclinación se realiza la sentadilla unilateral en declive de referencia?",["Sobre una tabla inclinada a 25°","Sobre una tabla inclinada a 45°","Sobre un plano estrictamente horizontal"],["La sentadilla unilateral en declive se realiza sobre una tabla inclinada a 25°.","Esa inclinación es superior a la establecida.","El plano en declive es precisamente necesario."]],
  "1076": ["¿Qué flexión de la rodilla utiliza la sentadilla de provocación del tendón rotuliano?",["Una flexión de cerca de 90°, con las dos piernas en el suelo","Una flexión de cerca de 30°, con la otra pierna extendida","Una flexión completa en posición de cuclillas"],["Esa posición no es la de la prueba.","El paciente de pie realiza una sentadilla con una flexión de la rodilla a 30° sobre la pierna afectada, quedando la otra pierna extendida.","La posición de cuclillas completa no es la de la prueba."]],
  "1077": ["¿Qué cambio de puntuación VISA-P se considera clínicamente relevante?",["Un cambio de 13 puntos","Un cambio de 3 puntos","Un cambio de 50 puntos"],["Un cambio de 13 puntos se considera clínicamente relevante para juzgar la eficacia del tratamiento.","Ese cambio es demasiado pequeño para establecerse.","Ese cambio es muy superior al umbral establecido."]],
  "1078": ["¿Qué nivel de dolor puede aceptarse durante el ejercicio en la tendinopatía rotuliana?",["Hasta 7 sobre 10, sea cual sea la evolución","Hasta 3 sobre 10, sin aumento al día siguiente","No puede tolerarse ningún dolor"],["Ese nivel es demasiado elevado respecto a la indicación.","Hay que explicar que un dolor de hasta 3 sobre 10 es aceptable durante el ejercicio, con la condición de que no aumente al día siguiente.","Un dolor moderado se acepta explícitamente."]],
  "1079": ["¿Cuál es el estatus de las técnicas pasivas en la tendinopatía rotuliana?",["El tratamiento principal desde la fase inicial","Técnicas contraindicadas en esa patología","Coadyuvantes, nunca un tratamiento único"],["Nunca constituyen el tratamiento principal.","No están contraindicadas, solo son complementarias.","Las técnicas pasivas deben considerarse siempre coadyuvantes, nunca un tratamiento único o principal."]],
  "1080": ["¿Cuál es el nivel de evidencia de la punción seca asociada a los excéntricos en la tendinopatía rotuliana?",["Moderado, con un beneficio a corto plazo sobre el dolor","Nulo, al no haberse referido ningún beneficio","Alto, con un beneficio duradero más allá de un año"],["Existe evidencia de calidad moderada en favor de la punción seca y de la electrólisis asociadas a los excéntricos, con un beneficio a corto plazo.","Se refiere efectivamente un beneficio.","El nivel de evidencia no es alto y el efecto se mantiene a corto plazo."]],
  "1081": ["¿Son las ondas de choque una primera elección en la tendinopatía rotuliana?",["Sí, desde la fase inicial del tratamiento","Sí, en sustitución del ejercicio excéntrico","No, no se recomiendan como primera elección"],["No se establecen en primera intención.","No sustituyen al ejercicio.","Pese a su popularidad, las ondas de choque no se recomiendan como primera elección."]],
  "1082": ["¿Qué debilidad de cadera sobrecarga el tendón rotuliano?",["La debilidad de los músculos glúteos","La debilidad de los flexores","La debilidad de los aductores"],["La debilidad de los músculos glúteos, en particular del glúteo medio, genera patrones compensatorios que sobrecargan la rodilla.","Los flexores no se citan en ese mecanismo.","Los aductores no se citan en ese mecanismo."]],
  "1083": ["¿Cuál es el enfoque más eficaz en la tendinopatía rotuliana?",["El ejercicio excéntrico aislado","La carga progresiva del tendón","La asociación de las ondas de choque y del vendaje"],["El excéntrico aislado queda superado por la carga progresiva.","La carga progresiva del tendón es el enfoque más eficaz, superior al ejercicio excéntrico aislado a largo plazo.","Esa asociación no es el enfoque más eficaz."]],
  "1084": ["¿Qué velocidad de ejecución impone la fase isotónica del tendón rotuliano?",["Un segundo en cada sentido, con carga ligera","Una ejecución explosiva con carga máxima","Tres segundos en concéntrico y tres en excéntrico"],["Esa cadencia rápida no es la establecida.","La ejecución explosiva depende de la fase pliométrica.","La resistencia lenta e intensa se hace a velocidad controlada, tres segundos en concéntrico y tres segundos en excéntrico."]],
  "1085": ["¿Cuál es el estatus del vendaje rotuliano en la tendinopatía rotuliana?",["No aconsejado, debido al riesgo de rotura tendinosa","Inútil, al no haberse demostrado ningún beneficio","Recomendado, reduce el dolor y mejora la propiocepción"],["El riesgo de rotura concierne a los corticosteroides.","Se describe efectivamente un beneficio inmediato.","Los vendajes rotulianos están recomendados: reducen inmediatamente el dolor, mejoran la propiocepción y facilitan la práctica deportiva."]],
  "1086": ["¿Cuándo pueden ser útiles los parches de nitroglicerina en la tendinopatía rotuliana?",["Desde la primera semana de manejo","Si la progresión en carga fracasa a las 12 semanas","Únicamente después de seis meses de tratamiento"],["No se proponen de entrada.","Pueden ser útiles como complemento si la progresión con carga fracasa después de doce semanas.","Seis meses es el plazo establecido para la cirugía."]],
  "1087": ["¿Cuál es la incidencia anual del síndrome femoropatelar en los sujetos activos?",["Cerca de 22 casos nuevos por 1 000 personas","Cerca de 2 casos nuevos por 1 000 personas","Cerca de 50 casos nuevos por 1 000 personas"],["La incidencia es de 22 casos nuevos por 1 000 personas al año en las poblaciones físicamente activas.","Esa incidencia es muy inferior a la establecida.","Esa incidencia es superior a la establecida."]],
  "1088": ["¿A qué población afecta principalmente la tendinopatía rotuliana?",["A los atletas jóvenes varones","A las mujeres de edad media con sobrepeso","A las personas mayores de 70 años"],["La tendinopatía rotuliana afecta principalmente a los atletas jóvenes varones.","Esa población corresponde a la pata de ganso.","Esa población corresponde a la artrosis."]],
  "1089": ["¿Cómo se denomina el dolor de la rodilla después de una posición sentada prolongada con las rodillas flexionadas?",["El signo del fallo articular","El signo del arco doloroso","El signo del cine"],["La sensación de fallo designa que la rodilla se va.","El arco doloroso concierne al hombro.","Permanecer sentado mucho tiempo con las rodillas flexionadas despierta el dolor: es el signo del cine."]],
  "1090": ["¿Cuál es la prevalencia del síndrome femoropatelar en el adulto de 30 a 40 años?",["Cerca del 36 %","Cerca del 50 %","Cerca del 22 %"],["El treinta y seis por ciento corresponde a la población general.","La prevalencia es de cerca del 36 % en población general y alcanza el 50 % en los pacientes de 30 a 40 años.","Veintidós corresponde a la incidencia por mil personas."]],
  "1091": ["¿Cuál es la relación entre sexos del síndrome femoropatelar?",["Dos veces más hombres que mujeres","Una distribución igual entre los sexos","Dos veces más mujeres que hombres"],["El predominio descrito es femenino.","Se describe un predominio claro.","El síndrome femoropatelar afecta a dos veces más mujeres que hombres."]],
  "1092": ["¿Cuál es la enfermedad articular más corriente en el adulto?",["La condromalacia","La artrosis de la rodilla","La pata de ganso"],["La condromalacia es frecuente, pero no ocupa ese lugar.","La artrosis es la enfermedad articular más corriente en el adulto.","Esa tendinopatía es frecuente, pero no ocupa ese lugar."]]
});
